_DUAL_CLONE_DETECTED_THIS_RUN: bool = False

# Fix 1 (v0.2.13): unix timestamp marking the start of the current install
# run. Populated by _run_install() at entry. Used by
# _refresh_dist_binary_after_rebuild to distinguish "freshly produced this
# run" from "weeks-old stale artifact". Module-level so the helper can
# read it without threading the value through every intermediate call site.
_INSTALL_START_TS: Optional[float] = None


def _install_log_path() -> Path | None:
    """Return path to state/logs/install.jsonl iff the dir exists.

    We deliberately do NOT auto-create state/logs/ here — Step 8 (state
    directory creation) is the single owner of that mkdir. Logging before
    Step 8 buffers in memory; Step 8 flushes the buffer to disk.
    """
    log_dir = PROJECT_ROOT / "state" / "logs"
    if not log_dir.is_dir():
        return None
    return log_dir / "install.jsonl"


def _log_install_event(step: str, phase: str, detail: str = "",
                       data: dict | None = None,
                       actor: str = "install.py") -> None:
    """Append one event to state/logs/install.jsonl. Never raises.

    If the log directory doesn't exist yet (pre-Step-8), the event is
    buffered in `_PENDING_EVENTS` and flushed once Step 8 creates the
    directory. This means events from Steps 1-7 of a FRESH install land
    in the file too, instead of being lost.
    """
    try:
        ts = _utc_iso_now()
        record = {
            "ts": ts,
            "actor": actor,
            "step": step,
            "phase": phase,
            "detail": detail or "",
        }
        if data:
            # Best-effort: drop unserializable values rather than fail.
            try:
                json.dumps(data)
                record["data"] = data
            except (TypeError, ValueError):
                pass
        line = json.dumps(record, ensure_ascii=True) + "\n"

        path = _install_log_path()
        if path is None:
            # Buffer until Step 8 creates the dir. Bounded buffer size
            # (a runaway install would fill memory but not crash).
            if len(_PENDING_EVENTS) < 500:
                _PENDING_EVENTS.append(line)
            return

        # Drain pending events first so they appear in chronological order
        # alongside the current event. This is the normal case once Step 8
        # has run; the buffer is empty so it's a no-op.
        if _PENDING_EVENTS:
            _drain_pending_events(path)

        with path.open("a", encoding="utf-8") as f:
            f.write(line)
            f.flush()

        # v0.2.49 batch 4: optional stdout mirror so the launcher's
        # OrchestratorUpdateProgressModal can surface sub-progress while
        # `install.py --update` is in flight (the modal otherwise sits
        # at 40% "Applying updates..." for the entire re-embedding
        # phase — minutes of apparent freeze).
        #
        # Gated on VCO_PROGRESS_STREAM=1 so terminal users don't see
        # the extra noise. Format: `[VCO-EVENT] <step> <phase> <detail>`
        # — single line, no JSON, the launcher parses it via
        # str-split on whitespace (cheap, no JSON parse cost on the
        # hot path).
        if os.environ.get("VCO_PROGRESS_STREAM") == "1":
            try:
                # Strip newlines from detail — multiline stage messages
                # would break the launcher's line-buffered parser.
                safe_detail = (detail or "").replace("\n", " ").replace("\r", " ")
                sys.stdout.write(
                    f"[VCO-EVENT] {step} {phase} {safe_detail}\n"
                )
                sys.stdout.flush()
            except Exception:
                # Stdout failure (terminal disconnect, pipe closed) is
                # not a reason to break the install. The JSONL log
                # above already succeeded.
                pass
    except Exception:
        # Per the contract: NEVER let a log failure break the install.
        pass


def _drain_pending_events(path: Path) -> None:
    """Write any pre-Step-8 buffered events to the log file.

    Called automatically from `_log_install_event` once the log dir is
    available, AND explicitly from `_create_state_directory` so the
    buffer drains even if the next event happens to fail to log.
    """
    if not _PENDING_EVENTS:
        return
    try:
        with path.open("a", encoding="utf-8") as f:
            for buffered_line in _PENDING_EVENTS:
                f.write(buffered_line)
            f.flush()
        _PENDING_EVENTS.clear()
    except Exception:
        # If draining fails (disk full, perm denied), keep the buffer so
        # a later event has another shot. Bounded above so memory is safe.
        pass


def _utc_iso_now() -> str:
    """ISO-8601 UTC timestamp with second precision, Z suffix."""
    # datetime.now(tz=...) avoids the deprecated utcnow().
    from datetime import datetime, timezone
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# ---------------------------------------------------------------------------
# v0.2.53 DEDUP-3: _make_deferral builder
#
# Replaces 51 inline `DeferralEntry(...)` constructions in install.py.
#
# WHY:
# * The default `kg_node_refs=[]` was an empirical bug source — half the
#   inline constructions forgot to pass it (the dataclass field default
#   factory works, but cleaner to make the keyword explicit + verified).
# * Multi-line `detected` / `why_deferred` strings were copy-pasted as
#   triple-quoted bodies with inconsistent leading-whitespace
#   handling. The helper applies textwrap.dedent + strip uniformly.
# * Test coverage today asserts shape per-callsite; one helper means
#   one set of assertions catches the class.
#
# Per audit install-py-dedup-2026-06-10.md #11 (LoC saved ~150).
# ---------------------------------------------------------------------------


def _make_deferral(
    condition_id: str,
    *,
    title: str,
    detected: str,
    why_deferred: str,
    command_to_apply: str,
    severity: str = "warning",
    kg_node_refs: Optional[list[str]] = None,
) -> DeferralEntry:
    """Build a :class:`DeferralEntry` with shared phrasing patterns.

    Applies :func:`textwrap.dedent` + :func:`str.strip` to the
    multi-line text fields (`detected`, `why_deferred`,
    `command_to_apply`) so callers can use triple-quoted strings with
    arbitrary indentation without leaking whitespace into the
    rendered Markdown of UPDATE_DEFERRED.md.

    Defaults ``kg_node_refs`` to ``[]`` rather than relying on the
    dataclass field_factory — explicit-default catches the missing-kwarg
    typo class that bit the project in past releases (51 callsites,
    several had drifted to forget kg_node_refs entirely).
    """
    import textwrap
    return DeferralEntry(
        condition_id=condition_id,
        title=title.strip(),
        detected=textwrap.dedent(detected).strip(),
        why_deferred=textwrap.dedent(why_deferred).strip(),
        command_to_apply=textwrap.dedent(command_to_apply).strip(),
        severity=severity,
        kg_node_refs=list(kg_node_refs) if kg_node_refs else [],
    )


# ---------------------------------------------------------------------------
# v0.2.53 bootstrap mode (`install.py --bootstrap`)
#
# Implements §3 of docs/INSTALL_ARCHITECTURE_v2.md.
#
# READ-ONLY by default: probes Python, Node, Podman, GPU, paths; emits a
# versioned JSON envelope on stdout (with --json) or a human-readable
# summary table. The envelope's `weaviate_endpoints.health` is the
# canonical SSOT (NEW-4) — Rust + bash consumers MUST read it from here
# rather than re-deriving (which historically diverged: install.py used
# `/v1/.well-known/ready`, installer.rs used `/v1/meta`).
#
# Side-effect policy: NO writes (not even `state/logs/install.jsonl` —
# bootstrap must be safe to run before install has ever happened). NO
# network. NO user prompts. Every probe has timeout ≤ 10s.
#
# The bootstrap dispatch fires at the very top of main() BEFORE
# `_ensure_running_under_mcp_venv()` runs, so bootstrap works on a
# freshly cloned repo with no .venv.
#
# Envelope schema: docs/schemas/install-bootstrap-envelope-v1.json
# ---------------------------------------------------------------------------

BOOTSTRAP_SCHEMA_VERSION = 1
BOOTSTRAP_PROBE_TIMEOUT_S = 10


def _bootstrap_probe_version(
    cmd: list[str], *, timeout: int = BOOTSTRAP_PROBE_TIMEOUT_S
) -> Optional[str]:
    """Run a short version-probe command; return its stdout (stripped) or None.

    Soft-fails on every error: missing binary, non-zero exit, timeout,
    OSError. Used by bootstrap probes which must NEVER throw.
    """
    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=timeout,
        )
    except (subprocess.SubprocessError, OSError, FileNotFoundError):
        return None
    if result.returncode != 0:
        return None
    out = (result.stdout or "").strip()
    if not out:
        # Some tools (e.g. older `node --version`) print version to stderr.
        out = (result.stderr or "").strip()
    return out or None


def _bootstrap_parse_version_tuple(s: str) -> Optional[list[int]]:
    """Extract the first dotted-numeric run from `s`; return as list[int].

    `'Python 3.13.2'` -> `[3, 13, 2]`. `'v20.11.0'` -> `[20, 11, 0]`.
    Returns None when no version is found.
    """
    if not s:
        return None
    m = re.search(r"(\d+)\.(\d+)(?:\.(\d+))?", s)
    if not m:
        return None
    parts = [int(g) for g in m.groups() if g is not None]
    return parts


def _bootstrap_probe_binary(
    name: str,
    *,
    version_argv: Optional[list[str]] = None,
    extra_search_dirs: Optional[list[Path]] = None,
    parser: Optional[Any] = None,
) -> dict:
    """Probe one binary on PATH. Return ToolProbe-shaped dict.

    Soft-fails to `ok=False, cmd=None, version=None` for any error path.
    """
    cmd_path: Optional[str] = shutil.which(name)
    if cmd_path is None and extra_search_dirs:
        for d in extra_search_dirs:
            cand = d / name
            if cand.exists() and os.access(str(cand), os.X_OK):
                cmd_path = str(cand)
                break
    if cmd_path is None:
        return {
            "cmd": None, "version": None, "version_tuple": None, "ok": False,
        }
    argv = [cmd_path] + (version_argv if version_argv is not None else ["--version"])
    raw = _bootstrap_probe_version(argv)
    parsed_version = parser(raw) if (parser and raw) else raw
    vt = _bootstrap_parse_version_tuple(raw or "")
    return {
        "cmd": cmd_path,
        "version": parsed_version,
        "version_tuple": vt,
        "ok": True,
    }


def _bootstrap_python_wheel_support(venv_python_or_self: str) -> Optional[bool]:
    """M-P1-1: detect whether the running Python has wheel coverage for VCO deps.

    Calls ``pip install --dry-run --only-binary=:all:`` against a small
    representative set of pinned deps. If pip reports "Would install",
    wheels are available. If pip falls back to source build, returns False.

    Soft-fails to None if pip is unavailable (e.g. before venv exists);
    callers treat None as "unknown, defer judgement".
    """
    # Representative set: cover ML/native + pure-Python so a false-negative
    # in either family shows up. Kept small (under 10s probe budget).
    probe_pkgs = ["weaviate-client>=4.7", "pydantic>=2", "httpx>=0.27"]
    try:
        result = subprocess.run(
            [venv_python_or_self, "-m", "pip", "install",
             "--dry-run", "--only-binary=:all:",
             "--no-cache-dir", "--quiet",
             *probe_pkgs],
            capture_output=True, text=True, timeout=BOOTSTRAP_PROBE_TIMEOUT_S,
            env={**os.environ, "PIP_DISABLE_PIP_VERSION_CHECK": "1"},
        )
    except (subprocess.SubprocessError, OSError, FileNotFoundError):
        return None
    # Non-zero exit when pip needs to build from source under --only-binary.
    return result.returncode == 0


def _bootstrap_detect_os() -> tuple[str, str]:
    """Return (canonical_os, os_family).

    canonical_os: 'macos' | 'linux' | 'windows' | 'unknown'.
    os_family: lowercased platform.system() variant.
    """
    sysname = (platform.system() or "").strip().lower()
    if sysname == "darwin":
        return ("macos", "darwin")
    if sysname == "linux":
        return ("linux", "linux")
    if sysname.startswith("win"):
        # mingw64 (git-bash) vs msvc (cmd) — both report 'windows' to
        # platform.system(); distinguish via the SHELL env if available.
        shell = (os.environ.get("SHELL") or "").lower()
        fam = "mingw64" if "git" in shell or "msys" in shell else "msvc"
        return ("windows", fam)
    return ("unknown", sysname or "unknown")


def _bootstrap_normalize_arch() -> str:
    """Return normalized arch: arm64 | x86_64 | aarch64 | other."""
    raw = (platform.machine() or "").strip().lower()
    if raw in ("arm64", "aarch64"):
        # macOS reports arm64; Linux reports aarch64. Canonicalise to
        # the value present in launcher/dist subdirs.
        return raw
    if raw in ("x86_64", "amd64"):
        return "x86_64"
    return raw or "unknown"


def _bootstrap_detect_linux_distro() -> Optional[dict]:
    """Parse /etc/os-release. Return None on non-Linux or unreadable file."""
    if (platform.system() or "").lower() != "linux":
        return None
    osr = Path("/etc/os-release")
    if not osr.is_file():
        return None
    try:
        kv: dict[str, str] = {}
        for line in osr.read_text(encoding="utf-8", errors="replace").splitlines():
            if "=" not in line or line.startswith("#"):
                continue
            k, _, v = line.partition("=")
            kv[k.strip()] = v.strip().strip('"').strip("'")
    except OSError:
        return None
    distro_id = (kv.get("ID") or "").lower()
    pkgmgr_map = {
        "ubuntu": "apt", "debian": "apt", "raspbian": "apt", "linuxmint": "apt",
        "fedora": "dnf", "rhel": "dnf", "centos": "dnf", "rocky": "dnf",
        "almalinux": "dnf", "amzn": "dnf",
        "arch": "pacman", "manjaro": "pacman",
        "opensuse": "zypper", "opensuse-leap": "zypper", "opensuse-tumbleweed": "zypper",
        "sles": "zypper",
        "alpine": "apk",
    }
    return {
        "id": distro_id or None,
        "version_id": kv.get("VERSION_ID") or None,
        "codename": kv.get("VERSION_CODENAME") or None,
        "pkg_mgr": pkgmgr_map.get(distro_id),
    }


def _bootstrap_detect_macos_features() -> Optional[dict]:
    """macOS-only features: Homebrew prefix, Apple Silicon, Rosetta."""
    if (platform.system() or "").lower() != "darwin":
        return None
    brew_prefix: Optional[str] = None
    if Path("/opt/homebrew/bin/brew").is_file():
        brew_prefix = "/opt/homebrew"
    elif Path("/usr/local/bin/brew").is_file():
        brew_prefix = "/usr/local"
    is_apple_silicon = _bootstrap_normalize_arch() == "arm64"
    rosetta_present = Path("/Library/Apple/usr/libexec/oah/translate").exists()
    return {
        "homebrew_prefix": brew_prefix,
        "is_apple_silicon": is_apple_silicon,
        "rosetta_present": rosetta_present,
    }


def _bootstrap_detect_windows_features() -> Optional[dict]:
    """Windows-only features: PowerShell version, winget, chocolatey, WSL2."""
    if not (platform.system() or "").lower().startswith("win"):
        return None
    ps_ver = _windows_powershell_version() if "_windows_powershell_version" in globals() else None
    return {
        "powershell_version": list(ps_ver) if ps_ver else None,
        "winget_present": shutil.which("winget") is not None,
        "chocolatey_present": shutil.which("choco") is not None,
        "wsl2_present": shutil.which("wsl") is not None,
    }


def _bootstrap_detect_podman() -> dict:
    """Probe Podman binary and (macOS/Windows only) machine state."""
    base = _bootstrap_probe_binary("podman")
    machine_running: Optional[bool] = None
    canonical_os, _ = _bootstrap_detect_os()
    if base["ok"] and canonical_os in ("macos", "windows"):
        # podman machine list --format json -> parse for any Running=true.
        try:
            result = subprocess.run(
                [base["cmd"], "machine", "list", "--format", "json"],
                capture_output=True, text=True,
                timeout=BOOTSTRAP_PROBE_TIMEOUT_S,
            )
            if result.returncode == 0:
                try:
                    machines = json.loads(result.stdout or "[]")
                    machine_running = any(
                        m.get("Running") is True
                        for m in (machines if isinstance(machines, list) else [])
                    )
                except (json.JSONDecodeError, TypeError):
                    machine_running = False
            else:
                machine_running = False
        except (subprocess.SubprocessError, OSError, FileNotFoundError):
            machine_running = False
    base["machine_running"] = machine_running
    base["ok"] = base["ok"] and (machine_running is not False)
    return base


def _bootstrap_detect_docker() -> dict:
    """Probe Docker binary."""
    return _bootstrap_probe_binary("docker")


def _bootstrap_detect_brew() -> dict:
    """Probe brew binary + prefix."""
    base = _bootstrap_probe_binary("brew")
    prefix: Optional[str] = None
    if base["ok"] and base["cmd"]:
        prefix = _bootstrap_probe_version([base["cmd"], "--prefix"])
    base["prefix"] = prefix
    return base


def _bootstrap_detect_gpu() -> dict:
    """Best-effort GPU detection. Soft-fails to vendor='none' on errors.

    v0.2.68 (Defect Y): shares the SAME device-selection pipeline as
    ``_detect_system`` — ``vco_lib.gpu_device.enumerate_gpus`` +
    ``select_gpu_device`` — so both detect paths agree on the chosen
    discrete card (closes the G5/G7 duplicate-order gap). The bootstrap
    envelope's contract is unchanged: ``vram_gb=None`` means "unknown"
    (mapped from "no chosen device" or "chosen device's VRAM probe
    failed", i.e. ``chosen.vram_gb == 0.0``).
    """
    canonical_os, _ = _bootstrap_detect_os()
    if canonical_os == "macos":
        if _bootstrap_normalize_arch() == "arm64":
            return {
                "vendor": "metal", "model": "Apple Silicon",
                "vram_gb": None, "driver_version": None,
                "container_toolkit_ok": None,
            }
        return {
            "vendor": "none", "model": None, "vram_gb": None,
            "driver_version": None, "container_toolkit_ok": None,
        }

    # Shared enumeration + selection (same as the main install path).
    # Soft-fail: any import/probe failure falls back to vendor='none'.
    try:
        from vco_lib.gpu_device import enumerate_gpus, select_gpu_device
        vendor_pref = _gpu_vendor_preference_from_env()
        chosen = select_gpu_device(enumerate_gpus(), vendor_pref=vendor_pref)
    except Exception:  # noqa: BLE001 — detection must never crash bootstrap
        chosen = None

    if chosen is None:
        return {
            "vendor": "none", "model": None, "vram_gb": None,
            "driver_version": None, "container_toolkit_ok": None,
        }

    # 0.0 (probe failed) maps back to None to keep the envelope contract.
    # Round to 1 decimal to match the pre-v0.2.68 envelope shape (the old
    # NVIDIA arm used `round(vram_mb / 1024.0, 1)`).
    vram_gb = (
        round(chosen.vram_gb, 1)
        if chosen.vram_gb and chosen.vram_gb > 0
        else None
    )

    if chosen.vendor == "nvidia":
        # Enrich with the driver_version field (and a friendlier name) the
        # envelope historically carried for NVIDIA.
        model = chosen.name or None
        driver = None
        if shutil.which("nvidia-smi"):
            out = _bootstrap_probe_version(
                ["nvidia-smi", "--query-gpu=name,memory.total,driver_version",
                 "--format=csv,noheader,nounits"]
            )
            if out:
                first = out.splitlines()[0].split(",")
                if first and first[0].strip():
                    model = first[0].strip()
                if len(first) > 2 and first[2].strip():
                    driver = first[2].strip()
        return {
            "vendor": "nvidia", "model": model, "vram_gb": vram_gb,
            "driver_version": driver, "container_toolkit_ok": None,
        }

    if chosen.vendor == "amd":
        return {
            "vendor": "amd", "model": chosen.name or "AMD GPU (rocm)",
            "vram_gb": vram_gb, "driver_version": None,
            "container_toolkit_ok": None,
        }

    # "unknown" vendor kept-on-uncertainty: report it as a generic GPU so
    # the bootstrap envelope doesn't pretend the box is GPU-less.
    return {
        "vendor": chosen.vendor or "none",
        "model": chosen.name or None, "vram_gb": vram_gb,
        "driver_version": None, "container_toolkit_ok": None,
    }


def _bootstrap_detect_secrets(root: Path) -> dict:
    """Shim over :func:`vco_lib.secrets_bootstrap.detect_secrets_envelope`.

    Kept for backwards compatibility with the existing call-site; new
    callers should import the shared helper directly.
    """
    from vco_lib.secrets_bootstrap import detect_secrets_envelope
    return detect_secrets_envelope(
        root, probe_timeout_s=BOOTSTRAP_PROBE_TIMEOUT_S
    )


def _bootstrap_classify_install_root(root: Path) -> str:
    """Return install_root_kind per §3.4.

    - orchestrator_clone: has install.py + CLAUDE.md + .git, no state/.
    - completed_install: has install.py + CLAUDE.md + (state/ OR .env w/ KG_COLLECTION).
    - git_repo: has .git but no install markers.
    - unknown: none of the above.
    """
    has_install_py = (root / "install.py").is_file()
    has_claude_md = (root / "CLAUDE.md").is_file()
    has_git = (root / ".git").exists()
    has_state = (root / "state").is_dir()
    env_path = root / ".env"
    has_env_kg = False
    if env_path.is_file():
        try:
            has_env_kg = "KG_COLLECTION=" in env_path.read_text(
                encoding="utf-8", errors="replace"
            )
        except OSError:
            has_env_kg = False
    if has_install_py and has_claude_md and (has_state or has_env_kg):
        return "completed_install"
    if has_install_py and has_claude_md and has_git:
        return "orchestrator_clone"
    if has_git:
        return "git_repo"
    return "unknown"


def _bootstrap_launcher_dist_subdir() -> Optional[str]:
    """Return the canonical launcher dist subdir for this OS.

    SSOT for M-P0-2: macOS is `macos-arm64` (NOT `experimental_macOS`).

    v0.2.54 Track C (Intel-Mac fix): arch-aware on macOS. Releases ship
    arm64 only, but a LOCAL cargo build on an Intel Mac lands in
    `macos-x64/` — hardcoding arm64 made every dist-path consumer look
    in the wrong slot on x86_64 hosts.
    """
    canonical_os, _ = _bootstrap_detect_os()
    if canonical_os == "macos":
        machine = platform.machine().lower()
        if machine in ("x86_64", "amd64"):
            return "macos-x64"
        return "macos-arm64"
    if canonical_os == "linux":
        return "linux-x64"
    if canonical_os == "windows":
        return "windows-x64"
    return None


def _bootstrap_resolve_vco_version(root: Path) -> tuple[str, Optional[str]]:
    """Return (vco_version, short_sha).

    Reads VERSION file when present; falls back to git short-sha resolution.
    Soft-fails to ('unknown', None).
    """
    version_file = root / "VERSION"
    vco_version = "unknown"
    if version_file.is_file():
        try:
            vco_version = version_file.read_text(
                encoding="utf-8", errors="replace"
            ).strip() or "unknown"
            if vco_version != "unknown" and not vco_version.startswith("v"):
                vco_version = "v" + vco_version
        except OSError:
            pass
    short_sha: Optional[str] = None
    git_dir = root / ".git"
    if git_dir.exists():
        try:
            r = subprocess.run(
                ["git", "-C", str(root), "rev-parse", "--short", "HEAD"],
                capture_output=True, text=True, timeout=5,
            )
            if r.returncode == 0:
                short_sha = (r.stdout or "").strip() or None
        except (subprocess.SubprocessError, OSError, FileNotFoundError):
            short_sha = None
    return (vco_version, short_sha)


def _bootstrap_resolve_paths(root: Path) -> dict:
    """Build the `paths` envelope block."""
    subdir = _bootstrap_launcher_dist_subdir()
    launcher_bin: Optional[Path] = None
    hub_bin: Optional[Path] = None
    if subdir:
        dist_dir = root / "launcher" / "dist" / subdir
        is_win = subdir.startswith("windows")
        launcher_bin = dist_dir / (
            "vct-launcher.exe" if is_win else "vct-launcher"
        )
        hub_bin = dist_dir / ("vct-hub.exe" if is_win else "vct-hub")
    venv_python = root / ".venv" / (
        "Scripts" if platform.system().lower().startswith("win") else "bin"
    ) / ("python.exe" if platform.system().lower().startswith("win") else "python3")
    mcp_venv_python = root / "claude_mcp_servers" / ".venv" / (
        "Scripts" if platform.system().lower().startswith("win") else "bin"
    ) / ("python.exe" if platform.system().lower().startswith("win") else "python3")
    vct_root = Path(os.environ.get("VCT_STATE_DIR") or (Path.home() / ".vct"))
    return {
        "install_root": str(root),
        "install_root_kind": _bootstrap_classify_install_root(root),
        "venv_python": str(venv_python) if venv_python.parent.exists() else None,
        "mcp_venv_python": (
            str(mcp_venv_python) if mcp_venv_python.parent.exists() else None
        ),
        "launcher_dist_subdir": subdir,
        "launcher_binary": str(launcher_bin) if launcher_bin else None,
        "launcher_binary_exists": bool(launcher_bin and launcher_bin.is_file()),
        "vct_hub_binary": str(hub_bin) if hub_bin else None,
        "vct_hub_binary_exists": bool(hub_bin and hub_bin.is_file()),
        "state_dir": str(root / "state"),
        "state_dir_exists": (root / "state").is_dir(),
        "claude_dir": str(root / ".claude"),
        "vct_root_dir": str(vct_root),
        "launcher_db": str(vct_root / "launcher.db"),
        "hub_port_file": str(vct_root / "hub.port"),
        "hub_token_file": str(vct_root / "hub.token"),
    }


def _bootstrap_package_manager_advice(
    system_block: dict, distro: Optional[dict],
) -> dict:
    """Build the `package_manager_advice` block. L-P0-1 parity-aware."""
    canonical_os = system_block["os"]
    has_brew = system_block["brew"]["ok"]
    has_winget = (
        system_block.get("windows_features") and
        system_block["windows_features"].get("winget_present")
    )
    primary: Optional[str] = None
    if canonical_os == "macos" and has_brew:
        primary = "brew"
    elif canonical_os == "windows" and has_winget:
        primary = "winget"
    elif canonical_os == "linux" and distro and distro.get("pkg_mgr"):
        primary = distro["pkg_mgr"]
    elif canonical_os == "linux" and has_brew:
        primary = "brew"  # Linuxbrew last-resort

    # Build install hints per primary pkgmgr.
    install_python: list[str] = []
    install_node: list[str] = []
    install_podman: list[str] = []
    install_lean_ctx: list[str] = []
    if primary == "brew":
        install_python = ["brew install python@3.13"]
        install_node = ["brew install node"]
        install_podman = ["brew install podman"]
        install_lean_ctx = ["brew install lean-ctx"]
    elif primary == "apt":
        install_python = ["sudo apt-get update",
                          "sudo apt-get install -y python3 python3-venv python3-pip"]
        install_node = ["sudo apt-get install -y nodejs npm"]
        install_podman = ["sudo apt-get install -y podman"]
        install_lean_ctx = []
    elif primary == "dnf":
        install_python = ["sudo dnf install -y python3 python3-pip"]
        install_node = ["sudo dnf install -y nodejs npm"]
        install_podman = ["sudo dnf install -y podman"]
    elif primary == "pacman":
        install_python = ["sudo pacman -S --noconfirm python python-pip"]
        install_node = ["sudo pacman -S --noconfirm nodejs npm"]
        install_podman = ["sudo pacman -S --noconfirm podman"]
    elif primary == "zypper":
        install_python = ["sudo zypper install -y python3 python3-pip"]
        install_node = ["sudo zypper install -y nodejs npm"]
        install_podman = ["sudo zypper install -y podman"]
    elif primary == "apk":
        install_python = ["sudo apk add python3 py3-pip"]
        install_node = ["sudo apk add nodejs npm"]
        install_podman = ["sudo apk add podman"]
    elif primary == "winget":
        install_python = ["winget install --id Python.Python.3.13 --silent"]
        install_node = ["winget install --id OpenJS.NodeJS.LTS --silent"]
        install_podman = ["winget install --id RedHat.Podman --silent"]

    # M-P1-2 — macOS/Windows need podman machine init + start after podman install.
    if (
        canonical_os in ("macos", "windows")
        and install_podman
        and system_block["podman"].get("machine_running") is not True
    ):
        install_podman = install_podman + [
            "podman machine init", "podman machine start",
        ]

    # Tauri deps — Linux-only, distro-aware (L-P0-2)
    tauri_deps: list[str] = []
    if canonical_os == "linux" and distro:
        d_id = (distro.get("id") or "").lower()
        d_ver = distro.get("version_id") or ""
        if d_id in ("ubuntu", "debian", "linuxmint", "raspbian"):
            # Ubuntu 24.04+ ships libwebkit2gtk-4.1; older needs 4.0 fallback.
            tauri_deps = [
                "build-essential", "curl", "wget", "file", "libssl-dev",
                "libgtk-3-dev", "libayatana-appindicator3-dev",
                "librsvg2-dev", "libwebkit2gtk-4.1-dev",
            ]
            try:
                major = int((d_ver or "0").split(".")[0])
                if major < 24:
                    tauri_deps.append("libwebkit2gtk-4.0-dev  # fallback")
            except ValueError:
                tauri_deps.append("libwebkit2gtk-4.0-dev  # fallback")
        elif d_id in ("fedora", "rhel", "centos", "rocky", "almalinux"):
            tauri_deps = [
                "webkit2gtk4.1-devel", "openssl-devel", "curl", "wget",
                "file", "libappindicator-gtk3-devel", "librsvg2-devel",
            ]

    # SELinux Z-flag — Fedora-family + Enforcing
    selinux_z = False
    if (
        canonical_os == "linux" and distro
        and (distro.get("id") or "").lower() in ("fedora", "rhel", "centos", "rocky", "almalinux")
    ):
        try:
            r = subprocess.run(
                ["getenforce"], capture_output=True, text=True,
                timeout=BOOTSTRAP_PROBE_TIMEOUT_S,
            )
            selinux_z = (r.stdout or "").strip().lower() == "enforcing"
        except (subprocess.SubprocessError, OSError, FileNotFoundError):
            selinux_z = False

    # NVIDIA container toolkit install hint (L-P0-7)
    nvidia_toolkit: Optional[str] = None
    if (
        canonical_os == "linux"
        and system_block["gpu"]["vendor"] == "nvidia"
        and not shutil.which("nvidia-ctk")
    ):
        if primary == "apt":
            nvidia_toolkit = (
                "curl -fsSL https://nvidia.github.io/libnvidia-container/gpgkey "
                "| sudo gpg --dearmor -o "
                "/usr/share/keyrings/nvidia-container-toolkit-keyring.gpg && "
                "sudo apt-get update && "
                "sudo apt-get install -y nvidia-container-toolkit"
            )
        elif primary == "dnf":
            nvidia_toolkit = "sudo dnf install -y nvidia-container-toolkit"

    return {
        "primary": primary,
        "install_python": install_python,
        "install_node": install_node,
        "install_podman": install_podman,
        "install_lean_ctx": install_lean_ctx,
        "tauri_deps": tauri_deps,
        "selinux_volume_flag_needed": selinux_z,
        "nvidia_container_toolkit_install": nvidia_toolkit,
        "render_group_remediation": None,
    }


def _bootstrap_compute_missing_prereqs(system_block: dict) -> list[dict]:
    """Build the `missing_prereqs` list. Order matters (UI may show top-N)."""
    out: list[dict] = []

    # Python wheel-support warning (M-P1-1)
    py = system_block["python"]
    if py.get("wheel_support_ok") is False:
        out.append({
            "name": "python_wheel_coverage",
            "human": (
                f"Python {py.get('version')} lacks wheel coverage for "
                "VCO's binary deps; pip would build from source"
            ),
            "severity": "warning",
            "install_hint": (
                "Consider downgrading to Python 3.12 or 3.13 for full "
                "wheel coverage. See docs/TROUBLESHOOTING.md."
            ),
        })

    # Container runtime — at least one of podman/docker must be present.
    if not (system_block["podman"]["ok"] or system_block["docker"]["ok"]):
        # Did podman binary exist but machine wasn't running?
        if system_block["podman"]["cmd"] is not None:
            out.append({
                "name": "podman_machine",
                "human": "Podman is installed but the VM is not running",
                "severity": "blocking",
                "install_hint": "podman machine init && podman machine start",
            })
        else:
            out.append({
                "name": "container_runtime",
                "human": "Podman or Docker is required",
                "severity": "blocking",
                "install_hint": (
                    "Install Podman (recommended) or Docker. "
                    "See docs/GETTING_STARTED.md."
                ),
            })

    # Node/npm — required for Claude Code MCP layer + diagram MCP.
    if not system_block["node"]["ok"]:
        out.append({
            "name": "node",
            "human": "Node.js 20+ is required",
            "severity": "blocking",
            "install_hint": "See package_manager_advice.install_node",
        })

    # Git — needed for orchestrator clone validation
    if not system_block["git"]["ok"]:
        out.append({
            "name": "git",
            "human": "git is required",
            "severity": "blocking",
            "install_hint": "Install git via your system package manager",
        })

    # lean-ctx — optional
    if not system_block["lean_ctx"]["ok"]:
        out.append({
            "name": "lean_ctx",
            "human": "lean-ctx is optional (bash output compression)",
            "severity": "optional",
            "install_hint": "See package_manager_advice.install_lean_ctx",
        })

    return out


def _bootstrap_build_envelope(root: Path) -> dict:
    """Build the full v1 envelope. All sub-probes soft-fail."""
    canonical_os, os_family = _bootstrap_detect_os()
    arch = _bootstrap_normalize_arch()
    vco_version, short_sha = _bootstrap_resolve_vco_version(root)

    # System probes.
    python_self = sys.executable or "python3"
    python_block = {
        "cmd": python_self,
        "version": f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}",
        "version_tuple": [
            sys.version_info.major, sys.version_info.minor, sys.version_info.micro,
        ],
        "min_required": list(MIN_PYTHON),
        "wheel_support_ok": _bootstrap_python_wheel_support(python_self),
        "ok": (sys.version_info.major, sys.version_info.minor) >= MIN_PYTHON,
    }

    node_block = _bootstrap_probe_binary("node")
    if node_block["ok"]:
        node_block["min_required"] = [18, 0, 0]
        # Check 18+ minimum
        vt = node_block.get("version_tuple") or [0]
        node_block["ok"] = vt[0] >= 18

    npm_block = _bootstrap_probe_binary("npm")
    pnpm_block = _bootstrap_probe_binary("pnpm")
    git_block = _bootstrap_probe_binary("git")
    brew_block = _bootstrap_detect_brew()
    lean_ctx_block = _bootstrap_probe_binary("lean-ctx")
    claude_block = _bootstrap_probe_binary("claude")

    podman_block = _bootstrap_detect_podman()
    docker_block = _bootstrap_detect_docker()
    container_runtime_chosen: Optional[str] = None
    if podman_block["ok"]:
        container_runtime_chosen = "podman"
    elif docker_block["ok"]:
        container_runtime_chosen = "docker"

    distro = _bootstrap_detect_linux_distro()
    macos_features = _bootstrap_detect_macos_features()
    windows_features = _bootstrap_detect_windows_features()
    gpu_block = _bootstrap_detect_gpu()

    # RAM probe (soft-fail).
    ram_gb: Optional[float] = None
    try:
        if canonical_os == "linux":
            for line in Path("/proc/meminfo").read_text(
                encoding="utf-8", errors="replace"
            ).splitlines():
                if line.startswith("MemTotal:"):
                    kb = int(line.split()[1])
                    ram_gb = round(kb / 1024.0 / 1024.0, 1)
                    break
        elif canonical_os == "macos":
            r = subprocess.run(
                ["sysctl", "-n", "hw.memsize"], capture_output=True, text=True,
                timeout=5,
            )
            if r.returncode == 0:
                ram_gb = round(int(r.stdout.strip()) / (1024**3), 1)
    except (OSError, ValueError, subprocess.SubprocessError):
        ram_gb = None

    cpu_count = os.cpu_count()

    system_block = {
        "os": canonical_os,
        "os_family": os_family,
        "kernel_release": platform.release() or None,
        "arch": arch,
        "ram_gb": ram_gb,
        "cpu_count": cpu_count,
        "python": python_block,
        "node": node_block,
        "npm": npm_block,
        "pnpm": pnpm_block,
        "podman": podman_block,
        "docker": docker_block,
        "container_runtime_chosen": container_runtime_chosen,
        "git": git_block,
        "brew": brew_block,
        "lean_ctx": lean_ctx_block,
        "claude_cli": claude_block,
        "gpu": gpu_block,
        "linux_distro": distro,
        "windows_features": windows_features,
        "macos_features": macos_features,
    }

    paths_block = _bootstrap_resolve_paths(root)
    pm_advice = _bootstrap_package_manager_advice(system_block, distro)
    secrets_block = _bootstrap_detect_secrets(root)

    # Endpoints — NEW-4 SSOT: weaviate health is `/v1/.well-known/ready`.
    weaviate_endpoints = {
        "base": "http://localhost:8081",
        "health": "http://localhost:8081/v1/.well-known/ready",
        "meta": "http://localhost:8081/v1/meta",
        "schema": "http://localhost:8081/v1/schema",
        "graphql": "http://localhost:8081/v1/graphql",
        "grpc_host": "localhost:50052",
    }
    ollama_endpoints = {
        "base": "http://localhost:11435",
        "tags": "http://localhost:11435/api/tags",
        "pull": "http://localhost:11435/api/pull",
    }
    code_embed_endpoints = {
        "base": "http://localhost:11440",
        "health": "http://localhost:11440/health",
    }
    vct_hub_endpoints = {
        "base": "http://127.0.0.1:7700",
        "health": "http://127.0.0.1:7700/api/v1/health",
    }

    missing = _bootstrap_compute_missing_prereqs(system_block)
    blocker_messages = [m["human"] for m in missing if m["severity"] == "blocking"]
    warnings = [m["human"] for m in missing if m["severity"] == "warning"]
    ready = len(blocker_messages) == 0

    return {
        "schema_version": BOOTSTRAP_SCHEMA_VERSION,
        "vco_version": vco_version,
        "vco_short_sha": short_sha,
        "generated_at": _utc_iso_now(),
        "system": system_block,
        "paths": paths_block,
        "package_manager_advice": pm_advice,
        "secrets": secrets_block,
        "weaviate_endpoints": weaviate_endpoints,
        "ollama_endpoints": ollama_endpoints,
        "code_embed_endpoints": code_embed_endpoints,
        "vct_hub_endpoints": vct_hub_endpoints,
        "missing_prereqs": missing,
        "ready_to_install": ready,
        "blocker_messages": blocker_messages,
        "warnings": warnings,
    }


def _bootstrap_print_human(envelope: dict) -> None:
    """Pretty-print envelope as a human-readable summary table."""
    sys_b = envelope["system"]
    print()
    print(f"VCO Bootstrap Probe  (schema v{envelope['schema_version']}, "
          f"{envelope['vco_version']})")
    print("=" * 72)
    print(f"OS              : {sys_b['os']} ({sys_b['os_family']}, {sys_b['arch']})")
    if sys_b.get("ram_gb") is not None:
        print(f"RAM             : {sys_b['ram_gb']} GB")
    if sys_b.get("cpu_count"):
        print(f"CPU cores       : {sys_b['cpu_count']}")
    print("-" * 72)

    def _row(label: str, probe: dict) -> None:
        status = "ok " if probe.get("ok") else "MISS"
        ver = probe.get("version") or ""
        cmd = probe.get("cmd") or "(not found)"
        print(f"  {label:<14} [{status}]  {ver:<12}  {cmd}")
    _row("python", sys_b["python"])
    _row("node", sys_b["node"])
    _row("npm", sys_b["npm"])
    _row("podman", sys_b["podman"])
    _row("docker", sys_b["docker"])
    _row("git", sys_b["git"])
    _row("brew", sys_b["brew"])
    _row("lean-ctx", sys_b["lean_ctx"])
    _row("claude", sys_b["claude_cli"])
    print("-" * 72)
    if envelope["missing_prereqs"]:
        print(f"Missing prereqs ({len(envelope['missing_prereqs'])}):")
        for m in envelope["missing_prereqs"]:
            sev = m["severity"].upper()
            print(f"  [{sev:<8}] {m['name']}: {m['human']}")
            if m.get("install_hint"):
                print(f"             hint: {m['install_hint']}")
    else:
        print("No missing prereqs detected.")
    print("-" * 72)
    print(f"Ready to install: {'YES' if envelope['ready_to_install'] else 'NO'}")
    if envelope["blocker_messages"]:
        for b in envelope["blocker_messages"]:
            print(f"  BLOCKER: {b}")
    if envelope["warnings"]:
        for w in envelope["warnings"]:
            print(f"  WARN:    {w}")
    print()


def _bootstrap_install_missing(envelope: dict, *, no_prompt: bool) -> int:
    """Implement `--install-missing`. Returns exit code (0 ok, 3 pkgmgr failed).

    Side-effect policy: this IS the side-effect branch. Runs pkgmgr
    install commands from `package_manager_advice` for each blocking
    prereq. macOS/Windows: also runs `podman machine init` + `start`.
    Re-prints the post-install envelope if changes succeed.
    """
    missing = envelope["missing_prereqs"]
    blocking = [m for m in missing if m["severity"] == "blocking"]
    if not blocking:
        print("[--install-missing] No blocking prereqs; nothing to do.")
        return 0
    advice = envelope["package_manager_advice"]
    if not no_prompt and sys.stdin.isatty():
        names = ", ".join(m["name"] for m in blocking)
        ans = input(
            f"Install missing prereqs [{names}]? [Y/n] "
        ).strip().lower()
        if ans and ans not in ("y", "yes"):
            print("[--install-missing] Aborted by user.")
            return 3
    failed: list[str] = []
    for m in blocking:
        name = m["name"]
        # Map prereq name to advice key.
        cmds: list[str] = []
        if name in ("container_runtime", "podman_machine"):
            cmds = advice.get("install_podman", [])
        elif name == "node":
            cmds = advice.get("install_node", [])
        elif name == "python_wheel_coverage":
            print(f"[--install-missing] {name}: no automated remediation; "
                  "see docs/TROUBLESHOOTING.md")
            continue
        if not cmds:
            print(f"[--install-missing] No install advice for {name}; skipping.")
            continue
        print(f"[--install-missing] {name}: running")
        for c in cmds:
            print(f"  $ {c}")
            try:
                r = subprocess.run(c, shell=True, timeout=600)
            except (subprocess.SubprocessError, OSError) as e:
                print(f"    FAIL: {e}")
                failed.append(name)
                break
            if r.returncode != 0:
                print(f"    FAIL (exit {r.returncode})")
                failed.append(name)
                break
    if failed:
        print(f"[--install-missing] Failed: {', '.join(failed)}")
        return 3
    print("[--install-missing] All install commands completed.")
    return 0


def _run_bootstrap(argv: list[str]) -> int:
    """Top-level dispatch for `install.py --bootstrap`.

    Argv parsing is intentionally lightweight (no argparse) because this
    runs BEFORE the main argparse instance is built and BEFORE the MCP
    venv relaunch. We accept ONLY `--bootstrap`, `--json`,
    `--install-missing`, `--no-prompt`, `--verbose`. Any other arg is a
    bad-invocation error.
    """
    # Strip --bootstrap so consumers don't double-parse it later.
    args_set = set(argv)
    bad_combos = {"--update", "--lightweight", "--uninstall"}
    if args_set & bad_combos:
        print(
            "ERROR: --bootstrap cannot be combined with "
            f"{', '.join(sorted(args_set & bad_combos))}",
            file=sys.stderr,
        )
        return 2
    allowed = {
        "--bootstrap", "--json", "--install-missing",
        "--no-prompt", "--verbose",
    }
    unknown = [a for a in argv if a not in allowed and a != "--yes"]
    if unknown:
        print(
            f"ERROR: --bootstrap rejects unknown args: {' '.join(unknown)}",
            file=sys.stderr,
        )
        return 2
    want_json = "--json" in args_set
    want_install_missing = "--install-missing" in args_set
    no_prompt = "--no-prompt" in args_set or "--yes" in args_set

    try:
        envelope = _bootstrap_build_envelope(PROJECT_ROOT)
    except Exception as e:  # noqa: BLE001 — top-level safety net
        # Bootstrap MUST NEVER hang or crash silently. Print traceback to
        # stderr so the user sees it; exit 1 per §3.2.
        import traceback
        print(f"ERROR: bootstrap envelope build failed: {e}", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
        return 1

    if want_install_missing:
        rc = _bootstrap_install_missing(envelope, no_prompt=no_prompt)
        if rc != 0:
            return rc
        # Re-detect after install.
        try:
            envelope = _bootstrap_build_envelope(PROJECT_ROOT)
        except Exception as e:  # noqa: BLE001
            print(f"ERROR: post-install probe failed: {e}", file=sys.stderr)
            return 1

    if want_json:
        # Stable, indented JSON for human-readable debugging + machine consumers.
        json.dump(envelope, sys.stdout, indent=2, sort_keys=False)
        sys.stdout.write("\n")
        sys.stdout.flush()
    else:
        _bootstrap_print_human(envelope)
    return 0


def _load_resume_state() -> dict[str, str]:
    """Parse state/logs/install.jsonl and return {step: last_phase} for the
    most-recent install session that's no older than 24 hours.

    A "session" begins with `actor=install.py, step=1/10, phase=start`.
    Only events from the *latest* session are considered. Sessions older
    than 24h are treated as stale and ignored entirely. Any later "error"
    on a step within the same session demotes that step out of the
    skip-eligible set (we set its last_phase = "error" so the caller will
    re-run it).
    """
    path = _install_log_path()
    if path is None or not path.is_file():
        return {}
    try:
        raw = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}

    events: list[dict] = []
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except (ValueError, TypeError):
            continue
        if isinstance(obj, dict):
            events.append(obj)

    if not events:
        return {}

    # Find the index of the most-recent session start.
    last_session_start = -1
    for i, ev in enumerate(events):
        if (ev.get("actor") == "install.py"
                and ev.get("step") == "1/10"
                and ev.get("phase") == "start"):
            last_session_start = i
    if last_session_start < 0:
        return {}

    session_events = events[last_session_start:]

    # Stale-session check (>24h).
    start_ts = session_events[0].get("ts", "")
    if start_ts:
        from datetime import datetime, timezone, timedelta
        try:
            # Strip trailing 'Z' for fromisoformat (3.11 supports Z; we
            # accept both for portability with older ts strings).
            ts_clean = start_ts.replace("Z", "+00:00")
            start_dt = datetime.fromisoformat(ts_clean)
            now = datetime.now(timezone.utc)
            if now - start_dt > timedelta(hours=24):
                return {}
        except (ValueError, TypeError):
            # Unparseable timestamp → treat as stale (safer than resuming
            # on a malformed log).
            return {}

    # Reduce session events to {step: last_phase}. "ok" / "skip" only count
    # if no later "error" appears for the same step.
    state: dict[str, str] = {}
    for ev in session_events:
        step = ev.get("step")
        phase = ev.get("phase")
        if not isinstance(step, str) or not isinstance(phase, str):
            continue
        if ev.get("actor") != "install.py":
            # Cross-actor events (post-install-launcher.sh, launcher) are
            # not consulted by install.py's resume — they describe phases
            # install.py doesn't own.
            continue
        # Latest phase wins.
        state[step] = phase
    return state


def _should_skip_step(step: str) -> bool:
    """Return True iff resume is enabled AND the log says this step
    completed (ok/skip) in the current session.

    NOTE: This is a HINT — callers MUST still verify the actual side
    effect (venv exists, .env exists, collection has the schema we expect)
    before declaring the step a no-op. The log is necessary but not
    sufficient — Weaviate may have been wiped between runs, the user may
    have deleted .venv, etc.
    """
    if not _RESUME_ENABLED:
        return False
    return _RESUME_STATE.get(step) in ("ok", "skip")


# ---------------------------------------------------------------------------
# Deliverable 2 (2026-04-28): persist install choices + state hashes so
# re-installs can replay them instead of re-prompting / re-detecting.
#
# Two new event step IDs in install.jsonl:
#   - "choices"      → one record per major decision point (embedding
#                      mode, container runtime). The record
#                      holds enough info that a second install run can
#                      re-make the same decision without prompting.
#   - "state-hashes" → MD5 of requirements.txt / Cargo.lock / package.json /
#                      knowledge dir, written at the END of a successful
#                      install. `_compute_drift` compares these against
#                      current files to flag what changed and needs
#                      re-syncing.
#
# Stale-session rule: choices older than 24h are NOT replayed (matches
# the existing `_load_resume_state` rule — same reasoning: a long-stale
# choice is more likely wrong than right).
# ---------------------------------------------------------------------------

# Files whose content hashes are tracked across installs. Tuple form so
# we can iterate stably and return a deterministic dict shape.
STATE_HASH_TARGETS: tuple[tuple[str, str], ...] = (
    ("requirements_txt_md5", "requirements.txt"),
    ("cargo_lock_md5", "launcher/src-tauri/Cargo.lock"),
    ("package_json_md5", "launcher/package.json"),
)

# Knowledge dir is hashed differently — md5 of the sorted file-name
# listing rather than file content. Catches additions/removals; cheap.
STATE_HASH_KNOWLEDGE_DIR = "knowledge"


def _record_install_choice(name: str, value, extra: dict | None = None) -> None:
    """Persist one install-time decision so re-runs can replay it.

    Wraps `_log_install_event` with a fixed step="choices" so all
    decisions appear in a single audit category. Best-effort: never
    raises (matches the install-log contract).

    Args:
        name: Stable choice ID (e.g. "embedding_mode",
            "container_runtime"). The replay loader keys on this.
        value: The chosen value, JSON-serialisable. Bool / str / dict
            are all fine.
        extra: Optional structured payload (model versions, reason,
            etc.) — useful for forensics, ignored by the replay loader.
    """
    payload: dict = {"value": value}
    if extra:
        payload.update(extra)
    _log_install_event("choices", "ok", name, data=payload)


def _load_previous_choices() -> dict[str, dict]:
    """Read install.jsonl and return {choice_name: {value, ...extra}}
    for the most-recent install.py session.

    Returns an empty dict when:
      - The log file doesn't exist yet (first install).
      - The most-recent session is older than 24h (stale-session rule).
      - No "choices" events were recorded that session.

    Reuses the session-detection logic from `_load_resume_state`
    (session = events between consecutive `step="1/10", phase="start"`
    markers from `actor=install.py`). The choice with the latest
    timestamp wins if a name was recorded twice in one session.
    """
    path = _install_log_path()
    if path is None or not path.is_file():
        return {}

    try:
        raw = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}

    events: list[dict] = []
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except (ValueError, TypeError):
            continue
        if isinstance(obj, dict):
            events.append(obj)

    if not events:
        return {}

    last_session_start = -1
    for i, ev in enumerate(events):
        if (ev.get("actor") == "install.py"
                and ev.get("step") == "1/10"
                and ev.get("phase") == "start"):
            last_session_start = i
    if last_session_start < 0:
        return {}

    session_events = events[last_session_start:]

    # Stale check (>24h).
    start_ts = session_events[0].get("ts", "")
    if start_ts:
        from datetime import datetime, timezone, timedelta
        try:
            ts_clean = start_ts.replace("Z", "+00:00")
            start_dt = datetime.fromisoformat(ts_clean)
            now = datetime.now(timezone.utc)
            if now - start_dt > timedelta(hours=24):
                return {}
        except (ValueError, TypeError):
            return {}

    out: dict[str, dict] = {}
    for ev in session_events:
        if ev.get("step") != "choices" or ev.get("phase") != "ok":
            continue
        name = ev.get("detail")
        data = ev.get("data") or {}
        if not isinstance(name, str) or not name:
            continue
        if not isinstance(data, dict):
            continue
        out[name] = data
    return out


def _md5_file(path: Path) -> str | None:
    """Return MD5 hex digest of a file's bytes, or None on read error
    (file missing, permission denied, etc.). MD5 chosen over SHA-256
    purely for size (32-char vs 64-char) — drift detection is not
    security-critical.
    """
    if not path.is_file():
        return None
    import hashlib
    h = hashlib.md5()
    try:
        with path.open("rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
    except OSError:
        return None
    return h.hexdigest()


def _md5_knowledge_dir(root: Path) -> str | None:
    """MD5 of the sorted relative-path listing under `root/knowledge/`.

    Catches additions / removals / renames; doesn't compare file
    contents (would be expensive on every install run, and content
    drift on knowledge nodes is normal — they're meant to be edited).

    Used to flag when the bundled knowledge dir has changed and needs
    re-seeding into Weaviate. Returns None when knowledge/ is missing.
    """
    kd = root / STATE_HASH_KNOWLEDGE_DIR
    if not kd.is_dir():
        return None
    import hashlib
    paths: list[str] = []
    for p in kd.rglob("*"):
        if p.is_file():
            try:
                rel = p.relative_to(kd).as_posix()
            except ValueError:
                continue
            paths.append(rel)
    paths.sort()
    h = hashlib.md5()
    for s in paths:
        h.update(s.encode("utf-8"))
        h.update(b"\n")
    return h.hexdigest()


def _compute_state_hashes(install_path: Path) -> dict[str, str | None]:
    """Compute MD5s of every tracked artifact under `install_path`.

    Returns a dict with one key per `STATE_HASH_TARGETS` entry plus
    `knowledge_md5`. Missing files map to None (NOT to the empty-string
    hash) so the caller can distinguish "file gone" from "file empty".
    """
    out: dict[str, str | None] = {}
    for slot, rel in STATE_HASH_TARGETS:
        out[slot] = _md5_file(install_path / rel)
    out["knowledge_md5"] = _md5_knowledge_dir(install_path)
    return out


def _record_state_hashes(install_path: Path) -> None:
    """Snapshot the post-install state-hash set into install.jsonl.

    Call this at the END of a successful install (after Step 9b /
    Step 10) so the next run has a known-good baseline to diff against.
    """
    hashes = _compute_state_hashes(install_path)
    _log_install_event(
        "state-hashes", "ok",
        "post-install snapshot",
        data=hashes,
    )


def _load_previous_state_hashes() -> dict[str, str | None]:
    """Return the most-recent state-hash snapshot from install.jsonl,
    or {} if none. Like `_load_previous_choices`, only reads from the
    most-recent session and honours the 24h stale-session rule.
    """
    path = _install_log_path()
    if path is None or not path.is_file():
        return {}

    try:
        raw = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}

    events: list[dict] = []
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except (ValueError, TypeError):
            continue
        if isinstance(obj, dict):
            events.append(obj)

    if not events:
        return {}

    # Find latest "state-hashes" event globally — these are written
    # exactly once per successful install at the very end, so the
    # latest one is always the "last good install" baseline. We do NOT
    # apply the 24h stale rule here: a state-hash baseline from 3
    # months ago is still a perfectly valid drift reference (the user
    # hasn't reinstalled since then; we want to know what changed).
    for ev in reversed(events):
        if ev.get("step") == "state-hashes" and ev.get("phase") == "ok":
            data = ev.get("data") or {}
            if isinstance(data, dict):
                return {k: v for k, v in data.items()
                        if isinstance(k, str)}
    return {}


def _compute_drift(install_path: Path) -> dict[str, bool]:
    """Compare current state hashes against the last-recorded snapshot.

    Returns a bool-per-slot dict where True = "this artifact has
    changed since the last successful install". When no previous
    snapshot exists, returns all True (treat as fully-drifted, since
    we have no baseline).

    Used by the lightweight re-install path (Deliverable 3) to decide:
      - requirements_txt_md5 changed → run `pip install -r ... --upgrade`
      - cargo_lock_md5 / package_json_md5 changed → caller may want to
        rebuild the launcher
      - knowledge_md5 changed → (legacy signal, no longer used directly)
        v0.2.42 CI-10 replaced single-tree md5 with per-file content-hash
        diff via ``_seed_weaviate``'s diff gate; see CI-10 implementation in
        ``_seed_weaviate`` for the "pay once, never again" design.
    """
    current = _compute_state_hashes(install_path)
    previous = _load_previous_state_hashes()
    if not previous:
        # No baseline — nothing to compare against. Return True for
        # every slot so the caller falls back to full processing.
        return {k: True for k in current}
    out: dict[str, bool] = {}
    for slot, cur_hash in current.items():
        prev_hash = previous.get(slot)
        # Two-sided None is "no change" (both absent).
        if cur_hash is None and prev_hash is None:
            out[slot] = False
        else:
            out[slot] = cur_hash != prev_hash
    return out


# ---------------------------------------------------------------------------
# Re-install file-conflict resolution
#
# Mirror of the Rust implementation in
#   launcher/src-tauri/src/commands/installer.rs
# (apply_conflict_strategy + DEFAULT_PRESERVE_LIST + MERGE_BLOCK_*).
# Keep both sides in lockstep — see docs/INSTALL_RECOVERY.md → "Conflict
# Resolution" for the user-facing description and the Claude self-merge
# contract.
#
# This Python path is only exercised when install.py is invoked directly
# with --conflict-strategy (CLI users). The launcher's own install_orchestrator
# does the conflict-resolution step in Rust BEFORE spawning install.py, so
# the wizard flow doesn't go through here.
# ---------------------------------------------------------------------------

# Default preserve list — keep in sync with DEFAULT_PRESERVE_LIST in
# launcher/src-tauri/src/commands/installer.rs and OnboardingWizard.svelte.
#
# MEMORY.md is intentionally NOT here — lives at
# ~/.claude/projects/<id>/memory/MEMORY.md, not in the install dir. The
# notification block mentions it so the user can manually run a merge
# if their MEMORY.md has diverged.
DEFAULT_PRESERVE_LIST: tuple[str, ...] = (
    "CLAUDE.md",
    ".claude/CONTEXT_STATE.md",
    ".claude/PROJECT_REGISTRY.md",
    ".env",
)

# Notification block markers in .claude/CONTEXT_STATE.md. Re-runs of the
# install REPLACE the block in-place rather than accumulating stale copies.
MERGE_BLOCK_START = "<!-- vct-merge-pending -->"
MERGE_BLOCK_END = "<!-- /vct-merge-pending -->"

# Hard whitelist of paths the orchestrator install is allowed to copy
# from `source` into `install_path`. Anything else at the source is
# left behind; anything else at the install_path is left untouched.
#
# Source of truth: ``orchestrator-managed-paths.txt`` at the repo root
# (sibling of this file). Edit there ONLY — both Rust
# (``installer.rs`` via ``include_str!``) and Python (here, at import
# time) parse the same file with the same rules. A cross-language
# consistency test (``tests/test_managed_paths_consistency.py``) pins
# the two languages to the file contents.
#
# The .txt file lists itself, so ``update_orchestrator_at`` propagates
# freshly-edited editions of the list into every existing install.
#
# Note (PR-31 / v0.2.12): ``CLAUDE.md`` was removed from this whitelist.
# The root CLAUDE.md is orchestrator-self development docs, not a user-
# project scaffold. User projects render their CLAUDE.md from
# ``templates/CLAUDE.md.template`` via the project-bootstrapper. The
# ``DEFAULT_PRESERVE_LIST`` constant above still includes ``CLAUDE.md``
# — that is the existing-user-CLAUDE.md preservation concern on
# update, separate from the whitelist concern this section governs.

# Path resolution: __file__ → install.py at repo root → the .txt is
# its sibling. We use Path(__file__).resolve() so the lookup is robust
# even when install.py is invoked via a relative path or symlink.
_MANAGED_PATHS_FILE: Path = (
    Path(__file__).resolve().parent / "orchestrator-managed-paths.txt"
)


def _parse_managed_paths_text(text: str) -> tuple[str, ...]:
    """Parse ``orchestrator-managed-paths.txt`` content into an allowlist.

    Parse rules (must match ``parse_managed_paths_text`` in
    ``launcher/src-tauri/src/commands/installer.rs``):

      * A leading UTF-8 BOM (``\\ufeff``) on the first line is
        stripped. Saved-from-Windows-Notepad files routinely carry one
        and ``str.strip()`` does NOT remove BOM characters; without
        this, the first allowlist entry silently fails to match and
        the file gets treated as if its first line were missing.
      * Lines are stripped of leading/trailing whitespace.
      * Empty lines are skipped.
      * Lines whose first non-whitespace character is ``#`` are
        comments and are skipped entirely (no inline comments — ``#``
        is only a line prefix).

    Order is preserved so the resulting tuple has the same shape as
    the file, which makes diff output legible when entries change.
    """
    if text.startswith("﻿"):
        text = text[1:]
    out: list[str] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        out.append(stripped)
    return tuple(out)


def _load_orchestrator_managed_paths() -> tuple[str, ...]:
    """Read + parse the source-of-truth .txt file at import time.

    Read errors are fatal: if the file is missing or unreadable, the
    install logic has no allowlist to enforce and silently falling
    back to a hard-coded default would re-introduce the drift bug
    PR-5 was written to fix. We surface a clear error pointing the
    user at the file path and the upstream repo so they can recover.
    """
    try:
        text = _MANAGED_PATHS_FILE.read_text(encoding="utf-8")
    except OSError as e:
        raise RuntimeError(
            f"Could not read orchestrator allowlist file at "
            f"{_MANAGED_PATHS_FILE}: {e}. This file is the source of "
            f"truth for ORCHESTRATOR_MANAGED_PATHS and is required by "
            f"install.py. If you cloned the orchestrator repo "
            f"correctly the file should be present; otherwise re-fetch "
            f"from https://github.com/hotak92/vibecoded-orchestrator."
        ) from e
    return _parse_managed_paths_text(text)


ORCHESTRATOR_MANAGED_PATHS: tuple[str, ...] = _load_orchestrator_managed_paths()


def _normalize_conflict_strategy(s: str) -> str:
    """CLI uses kebab-case; internal handler uses snake_case (matches Rust)."""
    return {
        "delete-claude": "delete_claude_and_reinstall",
        "overwrite-all": "overwrite_all",
        "overwrite-preserve": "overwrite_preserve",
        "adopt-as-is": "adopt_as_is",
    }[s]


def _parse_preserve_paths(raw: str | None) -> list[str]:
    """Parse `--preserve-paths a,b,c`. Empty/None → default list."""
    if not raw:
        return list(DEFAULT_PRESERVE_LIST)
    return [p.strip() for p in raw.split(",") if p.strip()]


def _new_sibling_path(p: Path) -> Path:
    """Insert `.new` before the file's extension. Mirrors `new_sibling_path`
    in installer.rs.

    Examples:
      - CLAUDE.md → CLAUDE.new.md
      - .env → .env.new (no extension to split on)
      - archive.tar.gz → archive.tar.new.gz (split on LAST dot)
    """
    name = p.name
    # Filename starting with `.` and no other `.` (e.g. `.env`) → treat
    # the leading dot as part of the stem so we don't write `.new.env`.
    if "." not in name or (name.startswith(".") and name.count(".") == 1):
        return p.with_name(f"{name}.new")
    stem, _, ext = name.rpartition(".")
    return p.with_name(f"{stem}.new.{ext}")


def _build_merge_notification_block(preserved_files: list[str]) -> str:
    """Render the notification block. Idempotency note: the prose inside
    must NOT contain the literal MERGE_BLOCK_START/END strings, otherwise
    the marker-counting check breaks. Reference them obliquely as "the
    HTML-comment markers".
    """
    if preserved_files:
        list_lines = "\n".join(
            f"- `{p}` (upstream-new at `{_new_sibling_path(Path(p))}`)"
            for p in preserved_files
        )
    else:
        list_lines = "_(none — strategy ran with an empty preserve list)_"

    return (
        f"{MERGE_BLOCK_START}\n"
        "## Pending merge — read this on session start\n"
        "\n"
        "The orchestrator was just upgraded. Several user-curated files have an\n"
        "upstream-new version sitting next to them (`*.new.md` / `*.new.<ext>`).\n"
        "For each pair:\n"
        "\n"
        "1. Read both the existing file AND the upstream-new sibling.\n"
        "2. Reconcile: keep the user's project-specific content, but adopt new\n"
        "   structure / guidance / sections from the upstream version. Use your\n"
        "   judgment for ambiguous merges; ask the user if a conflict is\n"
        "   irreconcilable.\n"
        "3. After successfully merging a file, **delete its upstream-new\n"
        "   sibling**.\n"
        "4. When ALL `.new.*` siblings under the install path are gone, you'll\n"
        "   know the merge is complete — at that point, **delete this entire\n"
        "   notification block** (the HTML-comment markers wrapping this section\n"
        "   plus all text between them) from this CONTEXT_STATE.md. That removes\n"
        "   the prompt for the next session.\n"
        "\n"
        "Files awaiting merge:\n"
        f"{list_lines}\n"
        "\n"
        "Note: `MEMORY.md` lives at `~/.claude/projects/<id>/memory/MEMORY.md`,\n"
        "not in the install dir, so v1.0 of the conflict resolver does NOT write\n"
        "an upstream-new sibling for it. If you suspect your MEMORY.md is\n"
        "divergent from the upstream template, run a manual diff and merge by\n"
        "hand.\n"
        "\n"
        "(Do NOT delete user content. Preserve any session-specific state in\n"
        "CONTEXT_STATE.md, your existing CLAUDE.md customisations, etc. The\n"
        "upstream version is a reference for new structure, not a wholesale\n"
        "replacement.)\n"
        f"{MERGE_BLOCK_END}\n"
    )


def _replace_or_append_block(existing: str, block: str) -> str:
    """If `existing` contains a `<!-- vct-merge-pending -->` ...
    `<!-- /vct-merge-pending -->` block, replace it with `block`. Otherwise
    append `block` (separated by a single newline) to the end."""
    start = existing.find(MERGE_BLOCK_START)
    if start != -1:
        end_rel = existing[start:].find(MERGE_BLOCK_END)
        if end_rel != -1:
            end = start + end_rel + len(MERGE_BLOCK_END)
            after = existing[end:]
            # Strip a single leading newline so we don't accumulate blank
            # lines on every refresh.
            if after.startswith("\n"):
                after = after[1:]
            return existing[:start] + block + after
    sep = "" if (existing.endswith("\n") or not existing) else "\n"
    return f"{existing}{sep}\n{block}"


def update_merge_notification_block(
    context_state_path: Path, preserved_files: list[str],
    deferral_report: "DeferralReport | None" = None,
) -> bool:
    """Append (or refresh) the merge-notification block in
    `.claude/CONTEXT_STATE.md`. Returns True iff the file was written.

    v0.2.46 V47-B (Gap B): if `context_state_path` is a symlink, VCO
    writes the notification block to a sibling ``.vco-new`` path and
    emits a deferral entry. The original symlink is never touched.
    """
    block = _build_merge_notification_block(preserved_files)

    # v0.2.46 V47-B: symlink at CONTEXT_STATE.md → write to sibling.
    if is_symlink_blocking(context_state_path):
        vco_new = compute_vco_new_path(context_state_path)
        if deferral_report is not None:
            emit_symlink_deferral(deferral_report, context_state_path, vco_new)
        vco_new.parent.mkdir(parents=True, exist_ok=True)
        vco_new.write_text(block)
        return True

    # v0.2.46 V47-B: use lexists so a dangling symlink isn't treated
    # as "file doesn't exist".
    if not os.path.lexists(os.fspath(context_state_path)):
        context_state_path.parent.mkdir(parents=True, exist_ok=True)
        context_state_path.write_text(block)
        return True
    existing = context_state_path.read_text()
    updated = _replace_or_append_block(existing, block)
    if updated == existing:
        return False
    context_state_path.write_text(updated)
    return True


def _copy_recursive(src: Path, dst: Path) -> int:
    """Plain recursive copy. Symlinks are resolved (file content follows).
    Returns the number of files copied."""
    if src.is_dir():
        dst.mkdir(parents=True, exist_ok=True)
        total = 0
        for entry in src.iterdir():
            total += _copy_recursive(entry, dst / entry.name)
        return total
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)
    return 1


def _copy_recursive_preserve(
    src: Path,
    dst: Path,
    install_root: Path,
    preserve: list[str],
    preserved_present: list[str],
    deferral_report: "DeferralReport | None" = None,
) -> tuple[int, int]:
    """Preserve-aware recursive copy. For each FILE encountered:
      - If its install-relative path is in `preserve` AND a file already
        exists at `dst`, copy to `<dst>.new.<ext>` instead and append the
        relative path to `preserved_present`.
      - Otherwise, plain overwrite copy.

    Returns `(files_visited, new_files_written)`.

    v0.2.46 V47-B (Gap B): if `dst` is itself a symlink, OR if its parent
    directory is a symlink, VCO does NOT touch it. The intended content
    is written to `<dst>.vco-new` instead and a deferral entry is added
    (when `deferral_report` is provided). The original symlink is
    preserved bit-for-bit. Symlinked DIRECTORIES are not recursed into
    for writes — recursion stops at the symlink boundary.
    """
    # v0.2.46 V47-B: if dst is a symlinked directory, don't recurse in
    # for writes. Compute the sibling and land everything under it.
    if src.is_dir() and is_symlink_blocking(dst):
        vco_new = compute_vco_new_path(dst)
        if deferral_report is not None:
            emit_symlink_deferral(
                deferral_report, dst, vco_new, install_root=install_root
            )
        # Mirror the source tree into the sibling instead of through
        # the symlink. Use the same preserve-aware copy so user-
        # modifications under the .vco-new tree still produce .new
        # siblings (extremely unlikely on a fresh sibling, but safe).
        return _copy_recursive_preserve(
            src, vco_new, install_root, preserve, preserved_present,
            deferral_report=deferral_report,
        )

    if src.is_dir():
        # v0.2.46 V47-B: use lexists-equivalent guard on the parent
        # before mkdir. `mkdir(exist_ok=True)` on a symlink-to-dir
        # would silently succeed and route subsequent writes through
        # the symlink — exactly what we are forbidding.
        if not dst.exists() and not os.path.lexists(os.fspath(dst)):
            dst.mkdir(parents=True, exist_ok=True)
        elif not is_symlink_blocking(dst):
            # Real directory already exists — no-op.
            pass
        files_visited = 0
        new_files = 0
        for entry in src.iterdir():
            v, n = _copy_recursive_preserve(
                entry, dst / entry.name, install_root, preserve, preserved_present,
                deferral_report=deferral_report,
            )
            files_visited += v
            new_files += n
        return files_visited, new_files

    rel = str(dst.relative_to(install_root))

    # v0.2.46 V47-B: dst is a symlink (file or dangling). Refuse to
    # overwrite the symlink; write VCO's content to the sibling.
    if is_symlink_blocking(dst):
        vco_new = compute_vco_new_path(dst)
        vco_new.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, vco_new)
        if deferral_report is not None:
            emit_symlink_deferral(
                deferral_report, dst, vco_new, install_root=install_root
            )
        return 1, 1

    # v0.2.46 V47-B: use lexists (not exists) to detect prior content,
    # so a dangling symlink at dst is NOT treated as "nothing here".
    # (Caught above by is_symlink_blocking, but kept for defense-in-
    # depth in case any future refactor drops the islink check.)
    if rel in preserve and os.path.lexists(os.fspath(dst)):
        sibling = _new_sibling_path(dst)
        sibling.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, sibling)
        preserved_present.append(rel)
        return 1, 1

    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)
    return 1, 0


def apply_conflict_strategy(
    source: Path, install_path: Path, strategy: str, preserve_paths: list[str]
) -> dict:
    """Apply a `ConflictStrategy` at `install_path`, copying from `source`.

    `strategy` is the snake_case name (matches the Rust `ConflictStrategy`
    enum). Returns a report dict with the same shape as the Rust
    `ConflictApplyReport` so callers can log it as JSON-serializable
    metadata.

    Defense: for `delete_claude_and_reinstall` we resolve and verify the
    path we're about to remove is exactly `<install_path>/.claude` before
    calling shutil.rmtree. Refuses to follow symlinks out of the install
    path.
    """
    report: dict = {
        "strategy": strategy,
        "preserved_count": 0,
        "new_md_count": 0,
        "notification_written": False,
        "copied_count": 0,
    }
    if not (source / "vct-module.json").exists():
        raise ValueError(
            f"source {source} is not an orchestrator repo (no vct-module.json)"
        )
    install_path.mkdir(parents=True, exist_ok=True)

    if strategy == "adopt_as_is":
        return report

    if strategy == "delete_claude_and_reinstall":
        claude_dir = install_path / ".claude"
        # v0.2.46 V47-B (Gap B): explicit symlink guard. The resolve()
        # check below already mitigates symlink-escape attacks, but a
        # symlinked .claude/ ROOT (e.g., .claude → ~/.claude/shared)
        # would still be rmtree'd by reaching its target. Hard rule:
        # never touch a symlink at the install path; refuse the
        # destructive op and let the caller decide.
        if is_symlink_blocking(claude_dir):
            raise ValueError(
                f"refusing to delete: {claude_dir} is a symlink "
                f"(VCO never replaces symlinks under the install path; "
                f"remove the symlink manually before re-running with "
                f"delete_claude_and_reinstall)"
            )
        if claude_dir.exists():
            canon_install = install_path.resolve()
            canon_claude = claude_dir.resolve()
            expected = canon_install / ".claude"
            if canon_claude != expected:
                raise ValueError(
                    f"refusing to delete: {claude_dir} resolves to "
                    f"{canon_claude} (expected {expected})"
                )
            shutil.rmtree(claude_dir)
        # Fresh copy.
        for managed in ORCHESTRATOR_MANAGED_PATHS:
            s = source / managed
            d = install_path / managed
            if not s.exists():
                continue
            report["copied_count"] += _copy_recursive(s, d)
        return report

    if strategy == "overwrite_all":
        for managed in ORCHESTRATOR_MANAGED_PATHS:
            s = source / managed
            d = install_path / managed
            if not s.exists():
                continue
            report["copied_count"] += _copy_recursive(s, d)
        return report

    if strategy == "overwrite_preserve":
        # Dedup the preserve list (callers may pass repeats).
        preserve = sorted(set(preserve_paths))
        preserved_present: list[str] = []
        new_files_written = 0
        copied = 0
        for managed in ORCHESTRATOR_MANAGED_PATHS:
            s = source / managed
            d = install_path / managed
            if not s.exists():
                continue
            v, n = _copy_recursive_preserve(
                s, d, install_path, preserve, preserved_present
            )
            copied += v
            new_files_written += n
        report["copied_count"] = copied
        report["preserved_count"] = len(preserved_present)
        report["new_md_count"] = new_files_written

        ctx = install_path / ".claude" / "CONTEXT_STATE.md"
        report["notification_written"] = update_merge_notification_block(
            ctx, preserved_present
        )
        return report

    raise ValueError(f"unknown conflict strategy: {strategy}")


# ---------------------------------------------------------------------------
# Deliverable 3 (2026-04-28): lightweight re-install
#
# Used by the launcher when a Strategy-3 (overwrite-preserve) re-install
# runs against an already-installed project that has a healthy `.venv/`,
# unchanged Python deps, and matching state hashes. The full install.py
# path takes ~1-2min on a hot system; the lightweight path skips model
# pulls + Weaviate seed (both idempotent already) and only redoes:
#
#   1. Path rewrite in .env / .claude/settings.json (when the install
#      moved or was bundled at a different path).
#   2. Venv triage — recreate only on Python version mismatch or
#      requirements.txt drift; otherwise leave alone.
#   3. Container ensure (no model pull — those are shared volumes,
#      already present).
#
# The lightweight mode is gated on `--lightweight`; the full path is
# unchanged when the flag isn't passed.
# ---------------------------------------------------------------------------

# Files we rewrite paths in. Conservative — only those that commonly
# embed an absolute install_path. Hooks under .claude/hooks/ use
# `$(dirname "$0")` and don't need rewriting.
LIGHTWEIGHT_PATH_REWRITE_TARGETS: tuple[str, ...] = (
    ".env",
    ".claude/settings.json",
)


def _rewrite_paths_in_file(path: Path, old_str: str, new_str: str) -> bool:
    """Replace every literal occurrence of `old_str` with `new_str` in
    a single text file. Returns True iff at least one replacement was
    made. No-op if the file is missing or doesn't contain old_str.

    We use literal substring replace (not regex) because the strings
    we're rewriting are absolute filesystem paths. They may contain
    regex metacharacters, but no user-controlled regex syntax is
    expected.
    """
    if not path.is_file() or not old_str:
        return False
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return False
    if old_str not in text:
        return False
    new_text = text.replace(old_str, new_str)
    try:
        path.write_text(new_text, encoding="utf-8")
    except OSError:
        return False
    return True


def _lightweight_rewrite_paths(install_path: Path,
                              old_path: str) -> dict[str, bool]:
    """Rewrite occurrences of `old_path` (absolute) → str(install_path)
    in every target file under `install_path`.

    Returns {relative_target: rewrote_at_least_one_occurrence}. Used
    when a project moved on disk (e.g. user renamed the parent folder).

    Idempotent: a no-op when old_path == install_path or when no target
    file embeds the old path.
    """
    results: dict[str, bool] = {}
    new_str = str(install_path)
    if not old_path or old_path == new_str:
        # Nothing to do; record a clean no-op for every target.
        for rel in LIGHTWEIGHT_PATH_REWRITE_TARGETS:
            results[rel] = False
        return results
    for rel in LIGHTWEIGHT_PATH_REWRITE_TARGETS:
        results[rel] = _rewrite_paths_in_file(
            install_path / rel, old_path, new_str,
        )
    return results


# ---------------------------------------------------------------------------
# v0.2.46 V47-G-final: detection heuristic + interactive prompt
# ---------------------------------------------------------------------------
#
# Replaces V47-G-stub's None / placeholder branches. Three pieces:
#
#   1. ``_detect_third_party_project(install_path)`` — heuristic scan that
#      returns None when there's no signal (= proceed with fresh install),
#      or a dict describing detected signals.
#
#   2. ``_prompt_adopt_decision(detection, args)`` — modal-style interactive
#      prompt offering Adopt / Cancel / Show details. Safe defaults: non-TTY
#      or --yes / --quiet → "no-adopt" (NEVER auto-adopt without explicit
#      consent; CI must opt in via --adopt-project explicitly).
#
#   3. ``_print_adopt_dry_run_manifest(install_path)`` — real dry-run output
#      replacing V47-G-stub's placeholder. Prints a section per Gap A-F.
#
# Plus:
#   4. ``_resolve_adopt_project_mode(args, install_path=None)`` — extended
#      signature. When ``install_path`` is provided AND no explicit flag is
#      set, runs detection + prompt. When ``install_path`` is None (the
#      V47-G-stub contract surface), behaves identically to the stub
#      (returns None for no-flag case). Backward-compat is critical: the
#      V47-G-stub contract tests must keep passing.

# Names that look like a Python virtualenv directory. Tested in priority
# order — the first hit wins for the signal label.
_V47G_VENV_DIR_NAMES = (".venv", "venv", "env", ".env-py")


def _v47g_is_venv_dir(path: Path) -> bool:
    """True iff ``path`` is a directory that looks like a Python venv.

    Signal: contains ``pyvenv.cfg`` (Python 3.3+ standard marker). Avoids
    false positives like ``.venv/`` being an empty folder.
    """
    try:
        if not path.is_dir():
            return False
        return (path / "pyvenv.cfg").is_file()
    except OSError:
        return False


def _v47g_describe_venv(path: Path) -> str:
    """Return a one-line summary of a venv (py version + rough pkg count).

    Both pieces are best-effort: missing pyvenv.cfg / unreadable
    site-packages → degrade to a generic label.
    """
    py_label = "Python ?"
    pkg_label = "~? packages"
    try:
        cfg = (path / "pyvenv.cfg").read_text(encoding="utf-8", errors="replace")
        for line in cfg.splitlines():
            if line.lower().startswith("version"):
                # Format: "version = 3.12.3"
                _, _, ver = line.partition("=")
                ver = ver.strip()
                if ver:
                    py_label = f"Python {ver}"
                    break
    except OSError:
        pass
    # Rough pkg count by enumerating dist-info dirs in lib/.../site-packages.
    try:
        site_pkgs_candidates = list(path.glob("lib/python*/site-packages"))
        if site_pkgs_candidates:
            n = sum(
                1 for p in site_pkgs_candidates[0].iterdir()
                if p.name.endswith(".dist-info")
            )
            pkg_label = f"~{n} packages"
    except OSError:
        pass
    return f"{py_label}, {pkg_label}"


def _v47g_count_env_secrets(env_path: Path) -> int:
    """Count secret-shaped keys in ``.env`` (best-effort, soft-fail to 0).

    Reuses ``vco_lib.secrets_audit.audit_env_secrets`` for consistency with
    V47-C's actual detection. Cheap on small ``.env`` files; degraded path
    returns 0 (signal still reads "with content" via byte size).
    """
    try:
        return len(_secrets_audit.audit_env_secrets(env_path))
    except Exception:  # noqa: BLE001 — soft-fail
        return 0


# Expected top-level keys in a well-formed ``.vco-manifest.json``. The
# manifest writer (install.py:6886+) emits ``schema_version``,
# ``vco_version``, ``installed_at``, ``updated_at``, ``files``,
# ``preserved_files``. Any of the version/files keys is enough to
# treat the JSON object as a real manifest — we're not validating
# the whole schema here, just sanity-checking that the file isn't
# empty / garbage / unrelated JSON.
_V47G_MANIFEST_EXPECTED_KEYS: tuple[str, ...] = (
    "vco_version",
    "schema_version",
    "files",
    "bundled_files",  # legacy alias retained for back-compat reads
)


def _v47g_classify_manifest(manifest_path: Path) -> str:
    """Classify ``.claude/.vco-manifest.json`` into one of three states.

    Returns one of:
      - ``"absent"`` — file does not exist (= truly 3rd-party project).
      - ``"valid"``  — file exists, is non-empty, parses as a JSON object,
        and contains at least one expected top-level key.
      - ``"broken"`` — file exists but is empty / unparseable / shape-
        unrecognized. Treated as a SIGNAL by detection so the user is
        explicitly told the manifest is bad rather than silently
        falling through.

    v0.2.46 post-adversarial L2: closes the cosmetic finding from S2 of
    the Part 2 adversarial review — "Empty/unparseable
    .vco-manifest.json suppresses adopt prompt." By design, but better
    to flag the broken state than silently treat as VCO-managed.

    Soft-fail: any OSError during read returns ``"broken"`` (the file
    exists but we can't tell what it says — same triage as a malformed
    file from the user's perspective).
    """
    if not manifest_path.is_file():
        return "absent"
    try:
        # Empty file is a common manifest-broken state (a partially-failed
        # write left a zero-byte file behind). json.loads('') raises, so
        # this is handled below — but checking size first lets us produce
        # a cleaner branch path in tests.
        raw = manifest_path.read_text(encoding="utf-8")
    except OSError:
        return "broken"
    if not raw.strip():
        return "broken"
    try:
        data = json.loads(raw)
    except (json.JSONDecodeError, ValueError):
        return "broken"
    if not isinstance(data, dict):
        return "broken"
    # Sanity check: at least one expected top-level key must be present.
    if not any(k in data for k in _V47G_MANIFEST_EXPECTED_KEYS):
        return "broken"
    return "valid"


def _detect_third_party_project(install_path: Path) -> dict | None:
    """Heuristic: is this an existing 3rd-party project being adopted by VCO?

    Returns ``None`` when there's no signal (= proceed with normal
    install / fresh project flow). Returns a dict with structure::

        {
          "signals": [<one-line description per detected signal>, ...],
          "summary": "<short summary string>",
          "manifest_present": False,
          "details": {<signal_key>: <verbose detail string>, ...},
        }

    when at least one signal is present.

    ``manifest_present=True`` short-circuit: if ``.claude/.vco-manifest.json``
    exists the project is already VCO-managed → NEVER treat as 3rd-party,
    NEVER prompt. Returns None unconditionally in that case (we don't
    second-guess existing VCO installs — the regular update flow runs).

    Soft-fails to None on any I/O error so detection never blocks install.
    """
    try:
        if install_path is None or not install_path.is_dir():
            return None

        # v0.2.46 post-adversarial L4 (orchestrator-clone exclusion):
        # The VCO orchestrator clone itself has CLAUDE.md + .env + .venv
        # + .claude/ + knowledge/ — every signal the heuristic looks for
        # — but it does NOT carry a .vco-manifest.json (the manifest is
        # written into PROJECTS VCO installs into, not into the VCO clone
        # which is bootstrapped from the upstream tarball). Without this
        # exclusion, every `install.py --update` on the orchestrator
        # clone fires the adopt prompt + non-interactively defaults to
        # "no-adopt" (per V47-G-final's safer-default rule) + EXITS
        # without applying the update.
        #
        # The discriminator matches `validate_source_repo` in install.py
        # (both `install.py` AND `first-install.sh` at install_path) —
        # the same pair the venv-resolver helper uses to identify a real
        # VCO clone. Add `vct-module.json` as a tertiary check so a 3rd-
        # party project that happens to have both install.py and
        # first-install.sh in its root (extremely unlikely combo) still
        # gets the adopt prompt.
        install_py_marker = install_path / "install.py"
        first_install_marker = install_path / "first-install.sh"
        vct_module_marker = install_path / "vct-module.json"
        if (install_py_marker.is_file()
                and first_install_marker.is_file()
                and vct_module_marker.is_file()):
            # This IS the VCO orchestrator clone — never prompt for
            # adopt mode on it. The update flow proceeds normally.
            return None

        manifest_path = install_path / ".claude" / ".vco-manifest.json"
        manifest_status = _v47g_classify_manifest(manifest_path)
        if manifest_status == "valid":
            # Existing well-formed VCO project — never prompt.
            return None
        # When the manifest is absent OR broken, we DO continue with
        # detection. `broken` is treated as an extra signal below so the
        # user sees that state explicitly rather than silently dropping
        # into either "prompt with no context" or "skip without warning".
        # (v0.2.46 post-adversarial L2.)

        signals: list[str] = []
        details: dict[str, str] = {}

        if manifest_status == "broken":
            signals.append(
                ".claude/.vco-manifest.json (present but unparseable / "
                "malformed — VCO state may need repair)"
            )
            details["manifest_broken"] = (
                "`.claude/.vco-manifest.json` exists but is empty, "
                "non-JSON, or missing every expected top-level key "
                "(`vco_version`, `schema_version`, `bundled_files`, "
                "`files`). VCO's normal manifest-driven update flow "
                "cannot rely on it. Options: (a) restore from backup; "
                "(b) treat as a 3rd-party project being re-adopted "
                "(--adopt-project); (c) run --update --force to accept "
                "VCO's bundled defaults over whatever the manifest "
                "tracked."
            )

        # Signal 1: .claude/ exists with at least one file.
        claude_dir = install_path / ".claude"
        if claude_dir.is_dir():
            try:
                n_entries = sum(1 for _ in claude_dir.iterdir())
            except OSError:
                n_entries = 0
            if n_entries > 0:
                # Try to give a rough idea of what's inside.
                parts: list[str] = []
                for sub in ("agents", "skills", "hooks", "scripts"):
                    p = claude_dir / sub
                    if p.is_dir():
                        try:
                            count = sum(1 for _ in p.iterdir())
                            if count > 0:
                                parts.append(f"{sub}={count}")
                        except OSError:
                            pass
                inv = ", ".join(parts) if parts else f"{n_entries} entries"
                signals.append(f".claude/ (existing orchestrator artifacts: {inv})")
                details["claude_dir"] = (
                    f"Directory '.claude/' contains {n_entries} top-level entries. "
                    f"VCO will land its agents/skills/hooks/scripts beside these; "
                    f"any pre-existing files matching VCO names will be preserved "
                    f"as .vco-new siblings (see V47-A managed-block).\n"
                    f"  Inventory: {inv}"
                )

        # Signal 2: CLAUDE.md exists with non-empty content.
        claude_md = install_path / "CLAUDE.md"
        if claude_md.is_file():
            try:
                size = claude_md.stat().st_size
            except OSError:
                size = 0
            if size > 0:
                signals.append(f"CLAUDE.md (existing project instructions, {size} bytes)")
                details["claude_md"] = (
                    f"CLAUDE.md exists ({size} bytes). VCO will append its "
                    f"orchestrator-instruction block to the END of the file "
                    f"(preserving everything above), or land a CLAUDE.md.vco-new "
                    f"sibling in --adopt-project mode."
                )

        # Signal 3: .env exists with non-empty content.
        env_path = install_path / ".env"
        if env_path.is_file():
            try:
                size = env_path.stat().st_size
            except OSError:
                size = 0
            if size > 0:
                n_secrets = _v47g_count_env_secrets(env_path)
                if n_secrets > 0:
                    sig_line = f".env (with {n_secrets} secret-shaped key{'s' if n_secrets != 1 else ''})"
                else:
                    sig_line = f".env (with content, {size} bytes)"
                signals.append(sig_line)
                if n_secrets > 0:
                    # Pull key names for the verbose details view.
                    try:
                        candidates = _secrets_audit.audit_env_secrets(env_path)
                        keys = sorted({c.key for c in candidates})
                        details["env"] = (
                            f".env contains {n_secrets} key{'s' if n_secrets != 1 else ''} "
                            f"matching the secret-shape heuristic. V47-C will offer "
                            f"to migrate to the OS keychain (Y/n/details prompt). "
                            f"Keys: {', '.join(keys)}"
                        )
                    except Exception:  # noqa: BLE001
                        details["env"] = (
                            f".env contains content matching secret-shape heuristic. "
                            f"V47-C will offer to migrate to the OS keychain."
                        )
                else:
                    details["env"] = (
                        f".env exists ({size} bytes) but none of its keys look "
                        f"secret-shaped — VCO's V47-C audit will be a no-op."
                    )

        # Signal 4: .venv (or similar) is a Python venv directory.
        for venv_name in _V47G_VENV_DIR_NAMES:
            candidate = install_path / venv_name
            if _v47g_is_venv_dir(candidate):
                desc = _v47g_describe_venv(candidate)
                signals.append(f"{venv_name}/ ({desc})")
                details["venv"] = (
                    f"Found Python venv at '{venv_name}/' ({desc}). V47-D will "
                    f"preserve this venv (action='skip-no-manifest'); use "
                    f"--rebuild-venv if you want VCO's default venv instead."
                )
                break

        # Signal 5: knowledge/ exists with .md files.
        knowledge_dir = install_path / "knowledge"
        if knowledge_dir.is_dir():
            try:
                md_count = sum(
                    1 for p in knowledge_dir.rglob("*.md")
                    # Soft-cap to keep this fast on huge trees.
                    if p.is_file()
                )
                if md_count > 100:
                    md_count = 100  # cap labelled below
                    cap_label = "100+"
                else:
                    cap_label = str(md_count)
            except OSError:
                md_count = 0
                cap_label = "0"
            if md_count > 0:
                signals.append(f"knowledge/ (with {cap_label} .md file{'s' if md_count != 1 else ''})")
                details["knowledge"] = (
                    f"knowledge/ directory exists with {cap_label} markdown file(s). "
                    f"VCO's knowledge graph layer will index these alongside its own "
                    f"shipped KG nodes; nothing is overwritten."
                )

        if not signals:
            return None

        return {
            "signals": signals,
            "summary": f"{len(signals)} signal{'s' if len(signals) != 1 else ''} detected",
            # `manifest_present` is the legacy boolean (Wave-2 consumers use it).
            # `manifest_status` is the L2 three-way classifier
            # ("absent" / "valid" / "broken"). When status is "valid" we'd
            # have returned None above; here we're either "absent" or
            # "broken". The boolean stays False for back-compat with consumers
            # that haven't migrated to the status string.
            "manifest_present": False,
            "manifest_status": manifest_status,
            "details": details,
        }
    except Exception:  # noqa: BLE001 — soft-fail
        return None


def _v47g_render_modal(install_path: Path, detection: dict) -> str:
    """Render the ASCII modal-style header for the adopt prompt."""
    lines: list[str] = []
    border = "+" + "-" * 67 + "+"
    lines.append("")
    lines.append(border)
    lines.append("| Existing project detected                                          |")
    lines.append("|                                                                    |")
    # Install path (may be long; we just print it, ascii box gives up on
    # word-wrapping for long paths — this is fine for a one-shot CLI).
    lines.append(f"| {str(install_path)}")
    lines.append("| contains:")
    for sig in detection.get("signals", []):
        # Truncate visually long signals so the modal stays readable.
        lines.append(f"|   * {sig}")
    lines.append("|")
    lines.append("| Adopt this project under VCO?")
    lines.append("|")
    lines.append("| Adopt mode: maximally protective. Existing files preserved;")
    lines.append("| VCO defaults landed as .vco-new siblings; deferral entries")
    lines.append("| generated for everything that needs your review.")
    lines.append(border)
    return "\n".join(lines)


def _v47g_render_details(detection: dict) -> str:
    """Render the expanded details view (one block per detected signal)."""
    lines: list[str] = []
    lines.append("")
    lines.append("--- Detection details ---")
    details = detection.get("details", {}) or {}
    if not details:
        lines.append("(no detailed information available)")
    else:
        for key, text in details.items():
            lines.append(f"\n[{key}]")
            for ln in text.splitlines():
                lines.append(f"  {ln}")
    lines.append("")
    return "\n".join(lines)


def _prompt_adopt_decision(detection: dict, args) -> str:
    """Interactive adopt-decision prompt.

    Returns one of:
      - ``"adopt"``    — user picked Adopt (recommended path)
      - ``"no-adopt"`` — user picked Cancel, or non-interactive default

    Safety defaults (return ``"no-adopt"`` unconditionally):
      - Non-TTY stdin (CI / scripted install)
      - ``--yes`` flag (no consent → don't surprise the user)
      - ``--quiet`` flag (no UI possible)

    Rationale: adopting a 3rd-party tree is a load-bearing decision (V47-A
    rewrites .claude/settings.json managed keys, V47-C may migrate secrets
    to the keychain, V47-D protects the user's venv, etc.). Even though
    adopt-mode is "maximally protective", the user should explicitly opt
    in. CI that needs adopt-mode should pass ``--adopt-project`` explicitly.
    """
    # Safety defaults — never auto-adopt without explicit user consent.
    non_interactive = (
        bool(getattr(args, "yes", False))
        or bool(getattr(args, "quiet", False))
        or not sys.stdin.isatty()
    )
    if non_interactive:
        print(
            "\n[adopt-project] Detection found existing-project signals but "
            "this install is running non-interactively (--yes / --quiet / "
            "no TTY)."
        )
        print(
            "  Defaulting to 'no-adopt' — pass --adopt-project explicitly "
            "to adopt this tree."
        )
        return "no-adopt"

    # Compute install_path from the args attribute commonly available
    # (we want it for the modal header). If unavailable, derive from
    # the global PROJECT_ROOT.
    try:
        install_path = PROJECT_ROOT
    except NameError:
        install_path = Path(".").resolve()

    # Render the modal header. Subsequent re-renders (after "show details")
    # repeat the header so the user sees the choices again.
    modal = _v47g_render_modal(install_path, detection)

    print(modal)
    while True:
        print("  1) Adopt (recommended)")
        print("  2) Cancel")
        print("  3) Show details")
        try:
            ans = input("  Choice [1-3]: ").strip()
        except EOFError:
            # Stdin closed mid-prompt → safe default.
            print("  (stdin closed — defaulting to 'no-adopt')")
            return "no-adopt"
        if ans == "1":
            return "adopt"
        if ans == "2":
            return "no-adopt"
        if ans == "3":
            print(_v47g_render_details(detection))
            # Re-render the modal so the user can re-decide.
            print(modal)
            continue
        print(f"  Please pick 1, 2, or 3 (got: {ans!r}).")


def _print_adopt_dry_run_manifest(install_path: Path) -> None:
    """Print the V47-G-final dry-run action manifest (one section per gap).

    Replaces V47-G-stub's placeholder ``print("...V47-G-stub placeholder...")``.
    For each of the v0.2.46 gaps (A-F), describes the action that WOULD be
    taken if adopt-project ran. Never writes anything; this is purely
    informational.

    Soft-fails on any sub-section's I/O — the manifest must always complete.
    """
    print()
    print("=" * 70)
    print("V47-G-final dry-run manifest")
    print("=" * 70)
    print(f"Install path: {install_path}")

    # Detection summary at the top.
    detection = _detect_third_party_project(install_path)
    if detection is None:
        print("\nDetection: no third-party-project signals.")
        print("           Adopt-project flow would be a no-op here (fresh install).")
    else:
        print(f"\nDetection: {detection.get('summary', 'signals detected')}")
        for sig in detection.get("signals", []):
            print(f"  * {sig}")

    # Gap A — .claude/settings.json managed-block merge.
    print()
    print("[Gap A] .claude/settings.json managed-block merge")
    settings_path = install_path / ".claude" / "settings.json"
    try:
        if settings_path.is_file():
            print(f"  Would refresh managed keys in: {settings_path}")
            print("  (User-set non-VCO keys preserved verbatim. See V47-A.)")
        else:
            print("  No existing .claude/settings.json — VCO would create one fresh.")
    except OSError as e:
        print(f"  (Could not inspect settings.json: {e})")

    # Gap B — Symlinks under install path.
    print()
    print("[Gap B] Symlinks (V47-B: never touched, .vco-new sibling instead)")
    sym_count = 0
    try:
        if install_path.is_dir():
            for p in install_path.rglob("*"):
                # Hard cap to keep dry-run fast on big trees.
                if sym_count >= 20:
                    print("  (... more symlinks omitted ...)")
                    break
                try:
                    if p.is_symlink():
                        sym_count += 1
                        print(f"  - {p.relative_to(install_path)} → would emit .vco-new sibling")
                except OSError:
                    continue
    except OSError as e:
        print(f"  (Could not scan symlinks: {e})")
    if sym_count == 0:
        print("  (No symlinks detected — Gap B is a no-op for this tree.)")

    # Gap C — .env secret-shaped keys.
    print()
    print("[Gap C] .env secrets (V47-C: offered for keychain migration)")
    env_path = install_path / ".env"
    if env_path.is_file():
        try:
            candidates = _secrets_audit.audit_env_secrets(env_path)
        except Exception as e:  # noqa: BLE001
            candidates = []
            print(f"  (Audit failed: {e})")
        if candidates:
            keys = sorted({c.key for c in candidates})
            print(f"  Would offer to migrate {len(keys)} key(s) to the OS keychain:")
            for k in keys:
                print(f"    * {k}")
        else:
            print("  .env exists but no secret-shaped keys detected — nothing to migrate.")
    else:
        print("  No .env file — Gap C is a no-op.")

    # Gap D — venv triage.
    print()
    print("[Gap D] venv triage (V47-D: protect 3rd-party venvs)")
    venv_found = False
    for venv_name in _V47G_VENV_DIR_NAMES:
        candidate = install_path / venv_name
        if _v47g_is_venv_dir(candidate):
            venv_found = True
            desc = _v47g_describe_venv(candidate)
            print(f"  Found: {venv_name}/ ({desc})")
            manifest_path = install_path / ".claude" / ".vco-manifest.json"
            if not manifest_path.is_file():
                print("  Action: skip-no-manifest (preserve existing venv).")
                print("          Use --rebuild-venv to override.")
            else:
                print("  Action: standard triage (manifest present).")
            break
    if not venv_found:
        print("  No Python venv detected — VCO would create one fresh.")

    # Gap E — foreign compose files (informational scan).
    print()
    print("[Gap E] Foreign compose files (V47-E: informational scan)")
    compose_candidates = [
        install_path / "docker-compose.yml",
        install_path / "docker-compose.yaml",
        install_path / "compose.yml",
        install_path / "compose.yaml",
        install_path / "podman-compose.yml",
        install_path / "podman-compose.yaml",
    ]
    found_compose = [p for p in compose_candidates if p.is_file()]
    if found_compose:
        print(f"  Would log {len(found_compose)} foreign compose file(s):")
        for p in found_compose:
            print(f"    * {p.relative_to(install_path)}")
        print("  (Informational only — VCO's compose work happens in its own dir.)")
    else:
        print("  No foreign compose files found.")

    # Gap F — PROJECT_NAME resolution.
    print()
    print("[Gap F] PROJECT_NAME resolution (V47-F: precedence chain)")
    print("  Resolution order:")
    print("    1. --project-name CLI flag")
    print("    2. .vscode/settings.json (claude-code.env.PROJECT_NAME)")
    print("    3. .claude/env PROJECT_NAME=")
    print("    4. .env PROJECT_NAME=")
    print("    5. interactive prompt (or sanitized directory name fallback)")
    # Try the actual resolver chain (read-only — won't write anything).
    vscode_name = _read_project_name_from_vscode_settings(install_path)
    if vscode_name:
        print(f"  Active via .vscode: {vscode_name}")
    claude_env = install_path / ".claude" / "env"
    if claude_env.is_file():
        claude_env_name = _read_project_name_from_envfile(claude_env)
        if claude_env_name:
            print(f"  Active via .claude/env: {claude_env_name}")
    dotenv = install_path / ".env"
    if dotenv.is_file():
        env_name = _read_project_name_from_envfile(dotenv)
        if env_name:
            print(f"  Active via .env: {env_name}")
    if not (vscode_name
            or (claude_env.is_file() and _read_project_name_from_envfile(claude_env))
            or (dotenv.is_file() and _read_project_name_from_envfile(dotenv))):
        # Fallback would be the directory name.
        print(f"  Fallback: sanitized directory name '{install_path.name}'")

    print()
    print("=" * 70)
    print("Dry-run complete. No files modified.")
    print("=" * 70)


def _resolve_adopt_project_mode(args, install_path: Path | None = None) -> str | None:
    """v0.2.46 V47-G-final: resolve --adopt-project-* flags + detection into a mode.

    Returns one of:
      - "adopt"        — explicit --adopt-project flag, OR detection prompt → adopt
      - "no-adopt"     — explicit --no-adopt-project flag, OR detection prompt → cancel,
                         OR detection signal in non-interactive context (safe default)
      - "replace-all"  — explicit --adopt-project-replace-all flag set
      - "dry-run"      — explicit --adopt-project-dry-run flag set
      - None           — no explicit flag AND no detection signal (= proceed normally)

    Explicit flags take precedence (we never override the user). Only when no
    explicit flag is set AND ``install_path`` is provided does the helper run
    the V47-G-final detection heuristic + interactive prompt.

    Backward-compat: when ``install_path`` is None (the V47-G-stub contract
    surface used by the contract test suite and any pre-V47-G-final caller),
    behaves identically to the stub — no detection, returns None for the
    no-flag case. This preserves the V47-G-stub contract.
    """
    if getattr(args, "adopt_project_dry_run", False):
        return "dry-run"
    if getattr(args, "adopt_project_replace_all", False):
        return "replace-all"
    if getattr(args, "adopt_project", False):
        return "adopt"
    if getattr(args, "no_adopt_project", False):
        return "no-adopt"
    # No explicit flag — V47-G-final detection branch (only if install_path
    # was provided by the caller). Stub-contract callers (no install_path)
    # still get None here.
    if install_path is not None:
        try:
            detection = _detect_third_party_project(install_path)
        except Exception:  # noqa: BLE001 — soft-fail
            detection = None
        if detection is not None:
            try:
                return _prompt_adopt_decision(detection, args)
            except Exception as e:  # noqa: BLE001 — soft-fail
                # Prompt machinery broke (very unlikely) — safe default.
                print(f"[adopt-project] Prompt failed ({e}); defaulting to 'no-adopt'.")
                return "no-adopt"
    return None


# ---------------------------------------------------------------------------
# v0.2.46 V47-F (Gap F): PROJECT_NAME precedence resolver for NEW adopt.
# ---------------------------------------------------------------------------

def _read_project_name_from_vscode_settings(install_path: Path) -> str | None:
    """Read `claude-code.env.PROJECT_NAME` from `.vscode/settings.json`.

    Returns the string value if present and non-empty, else None. Soft-fails
    to None on any parse / read error so the precedence chain falls through
    to the next layer.

    Looks at two layouts to be robust against editor variations:
      1. `claude-code.env.PROJECT_NAME` (the canonical workspace key the
         Claude Code VS Code extension uses)
      2. `env.PROJECT_NAME` (a degenerate layout some users hand-write)
    """
    settings = install_path / ".vscode" / "settings.json"
    if not settings.is_file():
        return None
    try:
        text = settings.read_text(encoding="utf-8")
        data = json.loads(text)
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(data, dict):
        return None
    # Layout 1: claude-code.env.PROJECT_NAME (canonical).
    cc_env = data.get("claude-code.env")
    if isinstance(cc_env, dict):
        val = cc_env.get("PROJECT_NAME")
        if isinstance(val, str) and val.strip():
            return val.strip()
    # Layout 2: env.PROJECT_NAME (degenerate).
    env_block = data.get("env")
    if isinstance(env_block, dict):
        val = env_block.get("PROJECT_NAME")
        if isinstance(val, str) and val.strip():
            return val.strip()
    return None


def _read_project_name_from_envfile(env_path: Path) -> str | None:
    """Read PROJECT_NAME=<val> from a .env-format file (.claude/env or .env).

    Returns the string value if present and non-empty, else None. Skips
    commented-out lines (leading ``#``) — we want a USER-SET active value,
    not a placeholder. Soft-fails to None on any read error.

    Strips surrounding single/double quotes if the value is wrapped in
    them (common in env-file convention: PROJECT_NAME="My Project").
    """
    if not env_path.is_file():
        return None
    try:
        text = env_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    for raw in text.splitlines():
        s = raw.lstrip()
        # Skip blank lines + comments. A line beginning with "#" is NOT
        # an active assignment — the V47-F resolver must not pick up a
        # disabled placeholder.
        if not s or s.startswith("#"):
            continue
        eq = s.find("=")
        if eq <= 0:
            continue
        key = s[:eq].strip()
        if key != "PROJECT_NAME":
            continue
        val = s[eq + 1:].strip()
        # Strip surrounding quotes if any.
        if len(val) >= 2 and val[0] == val[-1] and val[0] in ('"', "'"):
            val = val[1:-1]
        if val:
            return val
        return None
    return None


def _resolve_project_name_for_adopt(
    install_path: Path,
    args,
    interactive: bool | None = None,
) -> str:
    """v0.2.46 V47-F: resolve PROJECT_NAME for a NEW adopt operation.

    Precedence (highest → lowest):
      1. ``args.project_name`` — explicit ``--project-name`` CLI flag
      2. ``.vscode/settings.json claude-code.env.PROJECT_NAME``
      3. ``.claude/env PROJECT_NAME=`` (active, uncommented)
      4. ``.env PROJECT_NAME=`` (active, uncommented)
      5. Interactive prompt (TTY + not ``--yes``)
      6. Folder name (sanitized fallback — matches pre-V47-F derivation)

    Used ONLY in the NEW adopt path (when ``.vco-manifest.json`` is
    absent — i.e. the caller has decided this is a fresh / 3rd-party tree
    being adopted). Existing VCO projects already have a resolved
    PROJECT_NAME at install time, threaded through ``_reconcile_env_keys``
    which is additive-only — those installs MUST NOT call this helper or
    they risk re-deriving + overwriting a user-pinned name. This contract
    is critical to the V47-F non-destructiveness rule (see the dedicated
    pre-ship gate test ``test_existing_project_name_preserved_on_update``).

    Args:
        install_path: The target directory being adopted. NOT necessarily
            the orchestrator-clone PROJECT_ROOT — adopt targets are
            arbitrary user directories.
        args: ``argparse.Namespace`` (or any object with ``getattr``
            attribute access) carrying ``project_name`` (optional) and
            ``yes`` (optional). Missing attributes default to None / False.
        interactive: Force the interactive-prompt path on/off (testing
            override). ``None`` (default) auto-detects ``sys.stdin.isatty()``
            and ``not args.yes``.

    Returns:
        The resolved PROJECT_NAME as a raw string (NOT sanitized — callers
        sanitize when they need a Weaviate class basename). Never empty —
        falls back to folder name if everything else returns None.
    """
    # 1. CLI flag wins.
    cli_name = getattr(args, "project_name", None)
    if isinstance(cli_name, str) and cli_name.strip():
        return cli_name.strip()

    # 2. .vscode/settings.json claude-code.env.PROJECT_NAME
    vscode_name = _read_project_name_from_vscode_settings(install_path)
    if vscode_name:
        return vscode_name

    # 3. .claude/env PROJECT_NAME=
    claude_env_name = _read_project_name_from_envfile(
        install_path / ".claude" / "env"
    )
    if claude_env_name:
        return claude_env_name

    # 4. .env PROJECT_NAME=
    dotenv_name = _read_project_name_from_envfile(install_path / ".env")
    if dotenv_name:
        return dotenv_name

    # 5. Interactive prompt (TTY + not --yes).
    folder_default = install_path.name or "Project"
    if interactive is None:
        is_tty = bool(getattr(sys.stdin, "isatty", lambda: False)())
        suppressed = bool(getattr(args, "yes", False))
        interactive = is_tty and not suppressed
    if interactive:
        try:
            print(
                "\n[adopt-project] No PROJECT_NAME found via CLI flag, "
                ".vscode/settings.json, .claude/env, or .env."
            )
            prompt = f"  Project name? [default: {folder_default}]: "
            entered = input(prompt).strip()
            if entered:
                return entered
        except (EOFError, KeyboardInterrupt):
            # Fall through to folder-name default on input failure.
            pass

    # 6. Folder name fallback.
    return folder_default


def _log_project_name_pin_diff(
    install_path: Path,
    resolved_name: str,
) -> None:
    """v0.2.46 V47-F: emit an informational log when launcher.db / .env
    PROJECT_NAME differs from what folder-name derivation WOULD produce.

    Pure informational — no action taken, just visibility. Helps surface
    pre-V47-F installs that pinned a non-canonical project name while
    sitting in a folder like ``python/``. Soft-fails to no-op if either side can't
    be read.

    Called from the update path (existing-project branch) to confirm the
    non-destructiveness rule held: whatever the existing project has, it
    keeps. The log line lets the user see WHY their PROJECT_NAME isn't
    matching the folder name.
    """
    folder_derived = install_path.name or ""
    if not folder_derived:
        return

    # Try the launcher.db first — it's the authoritative source of truth
    # for a registered VCO project.
    pinned: str | None = None
    pinned_source: str = ""
    try:
        from vco_lib.launcher_db_reader import (  # noqa: F401
            _discover_db_path,
        )
        # Best-effort DB lookup. Soft-fail to .env fallback below.
        try:
            from vco_lib.config_projection import project_env_from_db
            # Resolve project_id via folder match (cheap helper that
            # install.py already uses elsewhere).
            pid = _resolve_project_id_by_folder(install_path)
            if pid is not None:
                bundle = project_env_from_db(pid)
                # Bundle's env carries the canonical PROJECT_NAME.
                env_block = getattr(bundle, "env", None) or {}
                if isinstance(env_block, dict):
                    db_name = env_block.get("PROJECT_NAME")
                    if isinstance(db_name, str) and db_name.strip():
                        pinned = db_name.strip()
                        pinned_source = "launcher.db"
        except Exception:
            pass
    except Exception:
        pass

    # Fall back to the .env file if the DB didn't yield a value.
    if pinned is None:
        env_name = _read_project_name_from_envfile(install_path / ".env")
        if env_name:
            pinned = env_name
            pinned_source = ".env"

    if pinned is None:
        return

    # Sanitize both sides to a Weaviate-class basename for the comparison.
    # If the pinned name SANITIZES to the same value as the folder name,
    # there's no surprise to surface — just nothing to log.
    try:
        from vco_lib.project_init import sanitize_for_weaviate_class
        pinned_sanitized = sanitize_for_weaviate_class(pinned)
        folder_sanitized = sanitize_for_weaviate_class(folder_derived)
    except Exception:
        return
    if pinned_sanitized == folder_sanitized:
        return

    msg = (
        f"  PROJECT_NAME pinned to {pinned!r} (source: {pinned_source}) "
        f"— folder-name derivation would have produced "
        f"{folder_sanitized!r} (from folder {folder_derived!r})."
    )
    print(msg)
    _log_install_event(
        "project-name", "info",
        "PROJECT_NAME pinned differs from folder-derivation",
        data={
            "pinned": pinned,
            "pinned_sanitized": pinned_sanitized,
            "folder": folder_derived,
            "folder_sanitized": folder_sanitized,
            "source": pinned_source,
        },
    )


def _venv_triage(install_path: Path,
                 adopt_project_mode: str | None = None,
                 force_rebuild: bool = False) -> dict:
    """Decide what to do with `<install_path>/.venv` on a lightweight
    re-install.

    v0.2.46 V47-G-stub: accepts optional `adopt_project_mode` for downstream
    Wave-2 (Gap D) to mode-gate destructive venv-recreation.

    v0.2.46 V47-D (Gap D, this commit): wire the actual guard logic.
    When `.venv` exists but `.vco-manifest.json` does NOT — i.e. VCO has
    no manifest record proving it owns this venv — the venv is treated
    as a 3rd-party environment (e.g. projects with 9+ GB scientific
    Python stacks). In that case:

      * A would-be "recreate" (Python-version mismatch) is downgraded
        to "skip-no-manifest" UNLESS adopt_project_mode == "replace-all"
        (explicit user opt-in to overwrite everything) OR
        `force_rebuild=True` (CLI flag `--rebuild-venv`).
      * A would-be "upgrade" path with no requirements.txt on disk AND
        no manifest is also downgraded to "skip-no-manifest" — VCO has
        no way to know what to install.

    Caller (`_run_lightweight`) handles "skip-no-manifest" as a no-op
    plus an UPDATE_DEFERRED.md entry explaining how to force-rebuild.

    Cases:
      1. .venv missing       → action="create", recreate fully
      2. .venv exists, no manifest, no requirements.txt, no force →
         action="skip-no-manifest" (NEW; 3rd-party venv VCO can't manage)
      3. .venv exists, Python version mismatch:
         - manifest present OR replace-all OR force_rebuild →
           action="recreate"
         - else → action="skip-no-manifest" (NEW; preserve 3rd-party venv)
      4. .venv exists, Python OK, requirements.txt drift →
         action="upgrade", pip install -r ... --upgrade in place
      5. .venv exists, all matches  → action="skip"

    Returns {"action": one_of(...), "reason": str, "venv_python": Path|None}.
    The caller (`_run_lightweight`) executes the action.
    """
    venv = install_path / ".venv"
    if platform.system() == "Windows":
        venv_python = venv / "Scripts" / "python.exe"
    else:
        venv_python = venv / "bin" / "python"

    if not venv.is_dir() or not venv_python.exists():
        return {"action": "create", "reason": ".venv missing",
                "venv_python": None}

    # v0.2.46 V47-D: figure out whether VCO has a manifest record proving
    # it owns this venv. Absence of .vco-manifest.json is the load-bearing
    # signal that this is a 3rd-party environment we must not destroy.
    manifest_path = install_path / ".claude" / ".vco-manifest.json"
    has_manifest = manifest_path.is_file()
    requirements_path = install_path / "requirements.txt"
    has_requirements = requirements_path.is_file()

    # Hard guard for the "VCO has no clue what's in this venv" case:
    # neither manifest nor requirements.txt → don't recreate, don't
    # upgrade, just inform the caller via deferral.
    if (not has_manifest and not has_requirements
            and not force_rebuild
            and adopt_project_mode != "replace-all"):
        return {
            "action": "skip-no-manifest",
            "reason": (
                "no .vco-manifest.json + no requirements.txt — "
                "this is a 3rd-party venv VCO does not manage; "
                "pass --rebuild-venv to force a rebuild"
            ),
            "venv_python": venv_python,
        }

    # Python version check.
    try:
        result = subprocess.run(
            [str(venv_python), "-c",
             "import sys; print(f'{sys.version_info.major}.{sys.version_info.minor}')"],
            capture_output=True, text=True, timeout=10,
        )
        venv_pyver = (result.stdout.strip()
                      if result.returncode == 0 else "")
    except (subprocess.SubprocessError, OSError):
        venv_pyver = ""

    expected = f"{sys.version_info.major}.{sys.version_info.minor}"
    if not venv_pyver or venv_pyver != expected:
        # v0.2.46 V47-D: ONLY recreate when (a) we have a manifest
        # proving VCO owns this venv, OR (b) the user has explicitly
        # opted in via --adopt-project-replace-all or --rebuild-venv.
        # Otherwise this would silently destroy a user's 3rd-party
        # environment (e.g. a large 3rd-party scientific stack) on a
        # Python-version-drift adopt — the HIGH finding from the
        # venv-architecture audit (2026-06-03).
        if not has_manifest and adopt_project_mode != "replace-all" \
                and not force_rebuild:
            return {
                "action": "skip-no-manifest",
                "reason": (
                    f"Python version mismatch (.venv={venv_pyver!r}, "
                    f"launcher={expected!r}) but no .vco-manifest.json — "
                    "refusing to destroy a 3rd-party venv; pass "
                    "--rebuild-venv to force a rebuild"
                ),
                "venv_python": venv_python,
            }
        return {"action": "recreate",
                "reason": f"Python version mismatch (.venv={venv_pyver!r}, "
                          f"launcher={expected!r})",
                "venv_python": None}

    # Requirements drift check (uses state-hashes from Deliverable 2).
    drift = _compute_drift(install_path)
    if drift.get("requirements_txt_md5", True):
        return {"action": "upgrade",
                "reason": "requirements.txt content changed since last install",
                "venv_python": venv_python}

    return {"action": "skip", "reason": "venv healthy, no drift",
            "venv_python": venv_python}


def _run_lightweight(args: argparse.Namespace) -> int:
    """Execute the lightweight re-install path.

    Skips: model pulls, Weaviate seed, lean-ctx detection,
    full GPU detection. Runs: path rewrite, venv triage, container
    ensure (without seed), state-hash snapshot.

    Returns the exit code (0 on success, non-zero on failure).
    """
    print("=" * 62)
    print("  VibeCoded Tools — Orchestrator Lightweight Re-install")
    print("=" * 62)
    print(f"  install path: {PROJECT_ROOT}")
    if args.lightweight_old_path:
        print(f"  previous path: {args.lightweight_old_path}")
    print()
    _log_install_event(
        "lightweight", "start",
        "lightweight re-install begin",
        data={"install_path": str(PROJECT_ROOT),
              "old_path": args.lightweight_old_path},
    )

    # Step 1: state directory must exist before logging will hit disk.
    _create_state_directory()

    # Step 2: path rewrite in .env / .claude/settings.json
    if args.lightweight_old_path:
        rewrite_report = _lightweight_rewrite_paths(
            PROJECT_ROOT, args.lightweight_old_path,
        )
        rewritten = [k for k, v in rewrite_report.items() if v]
        print(f"[1/4] Path rewrite: {len(rewritten)} file(s) updated")
        for k in rewritten:
            print(f"        {k}")
        _log_install_event(
            "lightweight", "ok",
            "path-rewrite complete",
            data={"rewrote_files": rewritten,
                  "all_targets": list(rewrite_report.keys())},
        )
    else:
        print("[1/4] Path rewrite: skipped (no --lightweight-old-path)")
        _log_install_event(
            "lightweight", "skip",
            "path-rewrite (no old path provided)",
        )

    # Step 3: venv triage
    # v0.2.46 V47-G-final: thread adopt_project_mode through to _venv_triage
    # so Wave-2 V47-D can mode-gate destructive "recreate" actions when the
    # tree is being adopted (don't wipe a user's 3rd-party .venv).
    # v0.2.46 V47-D: also thread force_rebuild=args.rebuild_venv so the
    # `--rebuild-venv` CLI flag overrides the adopt-guard when the user
    # explicitly opts in to a rebuild.
    # NOTE: lightweight installs intentionally do NOT run the V47-G-final
    # detection prompt — lightweight is the launcher's "I already know this
    # is a VCO project, just refresh it" path, so adopt-detection would be
    # noise. We pass install_path=None to skip detection here.
    adopt_project_mode = _resolve_adopt_project_mode(args, install_path=None)
    force_rebuild = getattr(args, "rebuild_venv", False)
    triage = _venv_triage(PROJECT_ROOT,
                          adopt_project_mode=adopt_project_mode,
                          force_rebuild=force_rebuild)
    print(f"[2/4] Venv triage: action={triage['action']} ({triage['reason']})")
    _log_install_event(
        "lightweight", "ok",
        f"venv triage: {triage['action']}",
        data={"action": triage["action"], "reason": triage["reason"]},
    )

    if triage["action"] == "create":
        _create_venv(PROJECT_ROOT)
        venv_python = (PROJECT_ROOT / ".venv" /
                       ("Scripts/python.exe" if platform.system() == "Windows"
                        else "bin/python"))
        _install_requirements(venv_python, dev=args.dev)
    elif triage["action"] == "recreate":
        # Drop the old venv first.
        venv = PROJECT_ROOT / ".venv"
        if venv.is_dir():
            shutil.rmtree(venv, ignore_errors=True)
        _create_venv(PROJECT_ROOT)
        venv_python = (PROJECT_ROOT / ".venv" /
                       ("Scripts/python.exe" if platform.system() == "Windows"
                        else "bin/python"))
        _install_requirements(venv_python, dev=args.dev)
    elif triage["action"] == "upgrade":
        _install_requirements(triage["venv_python"], dev=args.dev)
    elif triage["action"] == "skip-no-manifest":
        # v0.2.46 V47-D (Gap D): the venv exists but VCO has no manifest
        # record proving it owns it. Refuse to destroy it. Emit a
        # deferral entry so the user sees "VCO didn't touch your venv,
        # run install.py --rebuild-venv if you want VCO to rebuild it."
        # The deferral is appended via _lightweight_deferral further
        # down (the report-writer runs at the end of _run_lightweight).
        # We attach the entry here so the venv-skip rationale is
        # contiguous with the triage decision in the log timeline.
        _venv_path = PROJECT_ROOT / ".venv"
        _manifest_path = PROJECT_ROOT / ".claude" / ".vco-manifest.json"
        # We can't add to the deferral report until it's instantiated
        # later; stash the entry payload on the args namespace so the
        # later block can pick it up. The args namespace is the only
        # mutable cross-step carrier inside _run_lightweight without
        # threading another argument through.
        # v0.2.53 DEDUP-3: routed through _make_deferral. Text fields
        # use single-line concatenation (matching original behavior
        # byte-for-byte); the helper's textwrap.dedent passes them
        # through unchanged since there's no leading whitespace.
        args._venv_skip_no_manifest_entry = _make_deferral(
            "venv_skip_no_manifest",
            title="Venv preserved (no VCO manifest detected)",
            detected=(
                f"Found `.venv` at {_venv_path} but no "
                f".vco-manifest.json at {_manifest_path}. VCO treats this "
                "as a 3rd-party environment it does not manage, and will "
                "NOT recreate it. Reason: " + triage["reason"]
            ),
            why_deferred=(
                "Recreating a venv that VCO did not install could "
                "destroy a user-curated environment (e.g. a "
                "9+ GB scientific stack from an upstream project). "
                "The orchestrator refuses to do this silently. If VCO "
                "is in fact correct to rebuild the venv (the launcher's "
                "Python is intentionally different from what created "
                "it), re-run with the explicit `--rebuild-venv` flag."
            ),
            command_to_apply="python install.py --lightweight --rebuild-venv",
            severity="warning",
            kg_node_refs=[
                "knowledge/concepts/venv-adopt-guard-v0246.md",
            ],
        )
    else:
        # action == "skip"
        pass

    # Gap E (v0.2.46): inform the user about project-owned compose files so
    # they know VCO detected — and will not touch — their containers.
    if foreign := _scan_foreign_compose_files(PROJECT_ROOT):
        print(f"[i] Detected {len(foreign)} non-VCO compose file(s) — leaving alone:")
        for p in foreign:
            print(f"    {p}")
        print()
        _log_install_event(
            "foreign_compose_scan", "info",
            f"detected {len(foreign)} non-VCO compose file(s): "
            + ", ".join(str(p) for p in foreign),
        )

    # Step 4: container ensure (skip model pulls + seed; both
    # idempotent and unchanged on lightweight path).
    if args.no_containers:
        print("[3/4] Containers: skipped (--no-containers)")
    else:
        # Ensure the runtime is available, but do not pull models or
        # reseed Weaviate. The shared-container volume already has
        # everything; a re-install is purely about wiring this project
        # up to point at it.
        if sys.platform == "linux":
            print("[3/4] Containers: assumed running (lightweight path "
                  "doesn't probe / start them)")
        else:
            print("[3/4] Containers: assumed running (lightweight)")
    _log_install_event(
        "lightweight", "ok",
        "containers: assume-running",
    )

    # Step 5: snapshot fresh state hashes so future drift detection
    # has the right baseline.
    _record_state_hashes(PROJECT_ROOT)
    print("[4/4] State-hashes snapshot: written")

    # Bug G (v0.2.8): refresh install-manifest.json on lightweight too.
    # Previously the manifest was written only on the full install path,
    # so an install that was set up at v0.1.x and lightweight-reinstalled
    # at v0.2.x kept reporting v0.1.x forever. sysinfo=None — the
    # manifest writer falls back to prior values for the affected fields.
    _write_install_manifest(None, args, install_method="lightweight")

    # v0.2.10 (Bug L2): re-materialize boot service on lightweight too —
    # the wrapper path may have changed if the install was relocated
    # (--lightweight-old-path). Idempotent for unchanged paths.
    #
    # PR-12 Bug C: lightweight reinstall is the EXACT path users hit when
    # upgrading via the launcher's "Update orchestrator" button — pass a
    # fresh DeferralReport so any stale-unit auto-repair surfaces in
    # UPDATE_DEFERRED.md the user reads at next session.
    _lightweight_deferral = DeferralReport()

    # v0.2.46 V47-D (Gap D): if the venv-triage step earlier hit the
    # "skip-no-manifest" branch, attach its deferral entry to the report
    # so it lands in UPDATE_DEFERRED.md alongside any other lightweight
    # deferrals. The triage step itself can't write to the report (the
    # report is instantiated here); it stashes the payload on args.
    _venv_skip_entry = getattr(args, "_venv_skip_no_manifest_entry", None)
    if _venv_skip_entry is not None:
        _lightweight_deferral.add_entry(_venv_skip_entry)

    # PR-14b (v0.2.11 MCP simplification): SearXNG no longer ships in the
    # default compose stack; Ollama MCP is dropped from the default install;
    # SEARXNG_URL + GITHUB_TOKEN are no longer needed in the search MCP env.
    # Surface deferral notices so existing users know to clean up manually.
    if not getattr(args, "suppress_mcp_deprecation_warnings", False):
        _check_searxng_remnants(PROJECT_ROOT, _lightweight_deferral)
        _check_ollama_mcp_remnants(_lightweight_deferral)
        _check_search_mcp_env_obsolete(_lightweight_deferral)
    _materialize_boot_service(PROJECT_ROOT, None, args,
                              deferral_report=_lightweight_deferral)
    # v0.2.37: seed the launcher's install_path resolver on lightweight
    # too — the lightweight path is exactly what `--lightweight-old-path`
    # uses to relocate an install, so this is the canonical moment to
    # refresh the seed. See `_seed_launcher_install_path` for the
    # full rationale.
    _seed_launcher_install_path(PROJECT_ROOT, _lightweight_deferral)
    # Best-effort: persist the deferral report. Mirrors the folder
    # resolution used by the full install path (line ~2169).
    try:
        _lightweight_folder = (
            Path(args.project_folder)
            if getattr(args, "project_folder", None)
            else PROJECT_ROOT
        )
        _lightweight_deferral.write(_lightweight_folder)
    except Exception as _exc:  # noqa: BLE001 — soft-fail
        _log_install_event(
            "lightweight", "warn",
            f"could not write lightweight-mode deferral report: {_exc}",
        )

    _log_install_event(
        "lightweight", "ok",
        "lightweight re-install complete",
    )

    print()
    print("=" * 62)
    print("  Lightweight re-install complete!")
    print("=" * 62)
    return 0


# ---------------------------------------------------------------------------
# PR-28 (Group G, v0.2.12) — install-time storage-location prompt
# ---------------------------------------------------------------------------
#
# Users running install.py from the CLI (without the launcher GUI) previously
# got NO chance to point the orchestrator at pre-existing volume data on the
# host. Default behaviour creates fresh named volumes; a user with 110 GB of
# Ollama models at ~/podman_volumes/ollama/models would see their containers
# come up empty and only notice when `ollama list` returns nothing from
# inside the new container.
#
# The prompt is gated by:
#   - --quiet / --yes / non-TTY stdin → silent default (mode='deferred').
#   - EOF on stdin during the prompt → treated as 'deferred' (don't abort).
#   - No legacy paths detected → silent default ('named').
#
# The persistence call shells out to `vct-launcher --set-storage-config ...`
# when the bundled launcher binary is locatable. Falls through to a direct
# Python write of `~/.vct/storage.toml` otherwise (sufficient for fresh
# installs where the launcher hasn't been built / extracted yet).

# Logical-service → list of candidate host paths to probe. Order matters:
# the first existing path wins. Mirrors the surface area covered by
# launcher/src-tauri/src/commands/storage_ux.rs::detect_legacy_volumes_inner
# but operates on the FILESYSTEM rather than `podman volume ls`, because at
# install time we don't necessarily have a runtime up yet AND the user may
# have data sitting in a bind-mount directory that no current container
# references.
#
# The per-service-suffix probes are derived from
# `vco_lib.containers.HISTORICAL_ALIASES` so the maintainer-machine leak
# (the literal `weaviate_claude` / `ollama_claude` paths that lived here
# pre-v0.2.15) cannot reappear — see vco_lib/containers.py for the
# centralised registry + the rationale.
def _build_legacy_volume_probes() -> dict[str, tuple[str, ...]]:
    """Build the per-service probe list from the central container-name
    registry. Replaces the v0.2.14-and-earlier hardcoded
    ``weaviate_claude`` / ``ollama_claude`` paths (maintainer-machine
    leak — see vco_lib/containers.py).

    Probe path forms (all routed through ``Path.expanduser()`` /
    ``%LOCALAPPDATA%`` / ``%USERPROFILE%`` expansion so they work on
    Linux + macOS + Windows):
      * ``~/podman_volumes/<full-container-name>`` (POSIX) /
        ``%USERPROFILE%\\podman_volumes\\<full-container-name>``
        (Windows) — recovers bind-mount layouts using the literal
        container name as the directory. Only generated for full
        container names that would naturally form a bind-mount root
        (i.e. the ``_claude``-suffixed legacy and the
        ``vct_code_embed`` transitional name); NOT for bare
        service-token aliases like ``weaviate`` / ``ollama`` /
        ``code_embed`` because those conventionally bind-mount one
        level deeper (e.g. ``~/podman_volumes/ollama/models``).
      * ``~/.local/share/containers/storage/volumes/<alias>/_data`` —
        rootless POSIX named-volume mountpoint pattern. Generated for
        every alias.
      * ``%LOCALAPPDATA%\\containers\\storage\\volumes\\<alias>\\_data`` —
        rootful Windows Podman Desktop / Podman-on-Windows volume
        mountpoint pattern. Generated for every alias.
      * ``%USERPROFILE%\\AppData\\Roaming\\Docker\\volumes\\<alias>\\_data`` —
        Docker Desktop volume root on Windows.
      * Service-specific shared bind paths kept explicit per service
        (most-used layouts).

    Returns tuples of path strings with shell-style ``~/``-relative
    POSIX heads OR Windows ``%VAR%``-style heads. Callers are expected
    to pass them through ``_expand_path_token()`` (defined below) which
    handles both forms transparently.
    """
    from vco_lib.containers import HISTORICAL_ALIASES, canonical_name

    # Service-specific "well-known shared paths" the user may have set
    # up out-of-band (NOT derived from container names). Kept explicit
    # so they're easy to audit / extend. POSIX paths first, then
    # Windows analogues — both forms are tried by the probe loop.
    shared_paths: dict[str, tuple[str, ...]] = {
        "ollama": (
            "~/podman_volumes/ollama/models",
            "%USERPROFILE%\\podman_volumes\\ollama\\models",
            "%USERPROFILE%\\.ollama\\models",  # Ollama-on-Windows default
        ),
        "code_embed": (
            "~/podman_volumes/code_embed_cache",
            "%USERPROFILE%\\podman_volumes\\code_embed_cache",
        ),
        "weaviate": (
            # No bare host shared path historically — only named volumes.
        ),
    }

    # Aliases that look like distinct container names (vs. bare service
    # tokens that conventionally bind-mount one level deeper).
    def _alias_is_container_shape(alias: str) -> bool:
        return alias.endswith("_claude") or alias.startswith(("vct_", "vco_"))

    # Mountpoint root templates per OS family. Use a single `{alias}`
    # placeholder; the loop below substitutes.
    posix_named_volume_root = "~/.local/share/containers/storage/volumes/{alias}/_data"
    windows_podman_volume_root = (
        "%LOCALAPPDATA%\\containers\\storage\\volumes\\{alias}\\_data"
    )
    # Docker Desktop on Windows materialises named volumes inside its
    # Hyper-V VHD; the bind-mountable path under the user profile is
    # available only when "Use the WSL 2 based engine" is on AND
    # "Use containerd for pulling and storing images" is OFF. Probing
    # is cheap: missing dirs just fall through.
    windows_docker_volume_root = (
        "%USERPROFILE%\\AppData\\Local\\Docker\\wsl\\data\\volumes\\{alias}\\_data"
    )

    out: dict[str, tuple[str, ...]] = {}
    for service in ("ollama", "code_embed", "weaviate"):
        paths: list[str] = list(shared_paths.get(service, ()))
        for alias in HISTORICAL_ALIASES[service]:
            if _alias_is_container_shape(alias):
                # Bind-mount-root forms — POSIX + Windows.
                paths.append(f"~/podman_volumes/{alias}")
                paths.append(f"%USERPROFILE%\\podman_volumes\\{alias}")
            # Named-volume mountpoints for every alias on every OS.
            paths.append(posix_named_volume_root.format(alias=alias))
            paths.append(windows_podman_volume_root.format(alias=alias))
            paths.append(windows_docker_volume_root.format(alias=alias))
        # Always probe the canonical compose volume mountpoint last
        # (named volumes the current compose creates).
        canon_volume = {
            "ollama": "ollama_data",
            "code_embed": "code_embed_cache",
            "weaviate": "weaviate_data",
        }[service]
        paths.append(posix_named_volume_root.format(alias=canon_volume))
        paths.append(windows_podman_volume_root.format(alias=canon_volume))
        paths.append(windows_docker_volume_root.format(alias=canon_volume))
        # canonical_name() imported above only to surface a hard error
        # if the registry is malformed at import time.
        _ = canonical_name(service)
        # Deduplicate preserving order.
        seen: set[str] = set()
        deduped: list[str] = []
        for p in paths:
            if p in seen:
                continue
            seen.add(p)
            deduped.append(p)
        out[service] = tuple(deduped)
    return out


def _expand_path_token(raw: str) -> Optional[Path]:
    """Expand a probe-path token to an absolute ``Path``, handling both
    POSIX ``~/...`` heads and Windows ``%VAR%`` heads.

    Returns ``None`` if expansion can't produce a usable path
    (e.g. a Windows-style token on POSIX with no matching env var, or
    vice versa). The caller treats ``None`` as "not applicable on this
    host", same as a missing directory.
    """
    if not raw:
        return None
    # Windows-style %VAR% expansion first — os.path.expandvars is a
    # no-op on POSIX for unknown vars (it leaves the literal in place),
    # which would then fail Path.is_dir() naturally.
    expanded = os.path.expandvars(raw)
    if "%" in expanded:
        # Unresolved %VAR% means this token is Windows-specific and we're
        # not on Windows (or the variable simply isn't set). Skip.
        return None
    # POSIX tilde expansion. Path.expanduser handles "~/..." but NOT
    # mid-string "~user/..." with raw backslashes; we only generate the
    # leading-tilde form so we're safe.
    try:
        return Path(expanded).expanduser()
    except (RuntimeError, OSError):
        return None


_LEGACY_VOLUME_PROBES: dict[str, tuple[str, ...]] = _build_legacy_volume_probes()


def _detect_legacy_volume_paths() -> dict[str, str]:
    """Probe well-known host-side paths for pre-existing service data.

    Returns a `{service: absolute_path}` map for every probe that resolves
    to an existing non-empty directory. Empty map when nothing is found.

    Cross-OS: probes include both POSIX (``~/...``,
    ``~/.local/share/containers/...``) and Windows
    (``%LOCALAPPDATA%\\containers\\...``,
    ``%USERPROFILE%\\AppData\\Local\\Docker\\wsl\\data\\volumes\\...``)
    forms. `_expand_path_token` skips Windows-style tokens on POSIX (and
    vice versa) so non-applicable probes silently fall through.
    """
    detected: dict[str, str] = {}
    for service, candidates in _LEGACY_VOLUME_PROBES.items():
        for raw in candidates:
            resolved = _expand_path_token(raw)
            if resolved is None:
                # Token not applicable on this OS (Windows-style on POSIX
                # or vice versa) — skip silently.
                continue
            if not resolved.is_dir():
                continue
            # Skip empty directories: they were probably created by a prior
            # install attempt that never landed any data. We only want to
            # surface volumes the user actually has STUFF in.
            try:
                first = next(resolved.iterdir(), None)
            except (PermissionError, OSError):
                continue
            if first is None:
                continue
            detected[service] = str(resolved)
            break
    return detected


def _dir_size_human(path: str) -> str:
    """Best-effort human-readable directory size. Soft-fail on permission
    errors; the user just sees "(size unavailable)" next to the path."""
    try:
        root = Path(path)
        if not root.is_dir():
            return "(not a directory)"
        total = 0
        for child in root.rglob("*"):
            try:
                if child.is_file() and not child.is_symlink():
                    total += child.stat().st_size
            except (PermissionError, OSError):
                continue
            # Cap at ~50K files to keep the prompt snappy on huge model
            # caches; the human-readable label is just a hint, not an
            # exact accounting.
        if total <= 0:
            return "(empty)"
        units = ["B", "KB", "MB", "GB", "TB"]
        idx = 0
        scaled = float(total)
        while scaled >= 1024.0 and idx < len(units) - 1:
            scaled /= 1024.0
            idx += 1
        return f"{scaled:.1f} {units[idx]}"
    except (PermissionError, OSError):
        return "(size unavailable)"


def _vct_state_dir() -> Path:
    """Resolve `~/.vct/` honouring VCT_STATE_DIR (mirrors the Rust path
    resolver in `launcher/src-tauri/src/paths.rs::vct_root_dir`). The
    Python fallback writes storage.toml directly into this directory.

    Thin wrapper around :func:`vco_lib.paths.vct_root_dir` — kept as a
    module-local symbol so existing call sites (`_write_storage_toml_direct`)
    don't have to import the helper. v0.2.40 F5 consolidation pointed all
    inline ``~/.vct`` reconstructions at the canonical resolver so future
    cross-OS convention changes (macOS / Windows) need a single fix-point.
    """
    from vco_lib.paths import vct_root_dir
    return vct_root_dir()


# ---------------------------------------------------------------------------
# v0.2.44 V44-I: cross-OS advisory lock for the install-state mutation block.
#
# Background: install.py is not concurrency-safe across processes. Two
# simultaneous `python install.py --update` invocations (e.g. an IDE
# post-pull hook racing a manual run) can interleave writes to
# `.claude/settings.json` and `.claude/env` — each write is atomic per
# surface but not across surfaces. The two surfaces then disagree, which
# breaks the Phase 0.B config-projection contract.
#
# V44-H surfaced this as a known-issue ("Concurrent install.py --update
# from two terminals can split-brain env surfaces"). V44-I closes it
# in-tag per the "no deferred fixes" discipline (CLAUDE.md 2026-05-31).
#
# Lock path: `<vct_root_dir>/install.py.lock` (honours VCT_STATE_DIR so
# tests can scope the lock per-tmpdir). Soft-fails to WARNING when the
# file can't be opened or locked — never blocks install.
# ---------------------------------------------------------------------------
import contextlib as _contextlib


# ---------------------------------------------------------------------------
# v0.2.49: main()-entry single-instance lock for `install.py --update`.
#
# Background: V44-I's `_install_advisory_lock` is called from EXACTLY ONE
# narrow site (the orchestrator-root rebind path at ~line 11193). The
# broader `install.py --update` run is not protected. A bug reported
# 2026-06-05 (a contributor's machine) showed two concurrent `install.py --update`
# invocations deadlocking for 13 minutes — one held partial state, the
# other spun in retry-with-backoff loops until timeout.
#
# This module-level pair coordinates the main()-entry guard and the V44-I
# narrow-block guard on the SAME lock file. On POSIX `fcntl.flock` is
# reentrant on a single fd held by the same process; on Windows
# `msvcrt.locking` is NOT reentrant. The flag short-circuits cleanly
# cross-OS: once main() holds the lock, V44-I yields immediately without
# trying to re-take the OS lock.
# ---------------------------------------------------------------------------
_MAIN_ENTRY_LOCK_HELD: bool = False
_MAIN_ENTRY_LOCK_HANDLE = None  # kept alive for process lifetime


def _release_main_entry_lock_atexit() -> None:
    """v0.2.51 Bug F: close the singleton-lock file cleanly at exit.

    Without this, Python emits a noisy ``ResourceWarning: unclosed file
    <_io.BufferedRandom name='/.../install.py.lock'>`` to stderr every
    time install.py exits — the lock handle is intentionally kept open
    for the process lifetime, but the interpreter's GC-on-shutdown sees
    an unreleased file and warns.

    Behaviour:
      - Releases the OS-level lock (fcntl.LOCK_UN on POSIX,
        msvcrt.LK_UNLCK on Windows). The process is about to exit so the
        OS would do this anyway, but doing it explicitly silences any
        late-stage warnings from the lock subsystem.
      - Closes the file handle. Suppresses every conceivable error —
        atexit handlers MUST NOT raise; raising here would mask the
        actual reason the process is exiting (could be normal exit, SIGINT,
        unhandled exception during install).
      - Idempotent: safe to call even if the handle is None or already
        closed (the lock was never acquired, or it was released earlier).

    Registered once at module import via :func:`atexit.register`. Pairs
    with :func:`_install_singleton_lock_or_die` which opens the handle
    and stores it in ``_MAIN_ENTRY_LOCK_HANDLE``.
    """
    global _MAIN_ENTRY_LOCK_HANDLE
    fp = _MAIN_ENTRY_LOCK_HANDLE
    if fp is None:
        return
    try:
        if sys.platform == "win32":
            import msvcrt
            try:
                fp.seek(0)
                msvcrt.locking(fp.fileno(), msvcrt.LK_UNLCK, 1)
            except OSError:
                pass
        else:
            import fcntl
            try:
                fcntl.flock(fp.fileno(), fcntl.LOCK_UN)
            except OSError:
                pass
    except Exception:
        # Soft-fail by design. atexit handlers must not raise.
        pass
    try:
        fp.close()
    except Exception:
        pass
    _MAIN_ENTRY_LOCK_HANDLE = None


import atexit as _atexit
_atexit.register(_release_main_entry_lock_atexit)


# A-6 (v0.2.73) deadline refresh + V52-AI initial lockfile write: extracted
# to vco_lib.install_update_gate.InstallUpdateGate (P2c-a, v0.2.75) — main()
# holds thin gate.begin()/gate.refresh(phase) call sites. The P3a rider
# (absent-lockfile RE-CREATE during --update) lives there too.


def _install_singleton_lock_or_die(timeout_seconds: float = 15.0):
    """v0.2.49: acquire the install.py main-entry single-instance lock.

    Closes the 13-minute-deadlock pattern reported 2026-06-05 from
    a contributor's machine where two concurrent `install.py --update`
    invocations interleaved on shared state.

    Behaviour:
      - On success: returns an open file handle. Caller MUST assign it
        to a module-level variable (_MAIN_ENTRY_LOCK_HANDLE) so the lock
        is held for the process lifetime; the OS releases it
        automatically when the process exits and the handle closes.
        Also sets the module-level flag `_MAIN_ENTRY_LOCK_HELD = True`
        so the V44-I narrow-block lock yields without re-attempting.
      - On contention timeout: sys.exit(1) with a clear error to stderr
        naming the holding PID + when it started + a hint to wait or
        kill the other process.
      - Soft-fail (lock file can't be opened — permission error,
        readonly fs): emits WARNING to stderr, returns None, PROCEEDS
        without lock. The lock is defense-in-depth, not a hard gate.

    Cross-OS:
      - POSIX (Linux/macOS): fcntl.flock with LOCK_EX | LOCK_NB; retry
        with exponential backoff up to timeout_seconds.
      - Windows: msvcrt.locking(LK_NBLCK, 1) on a 1-byte region at
        offset 0 of the same lock file; same retry pattern.

    Coordinates with `_install_advisory_lock` (V44-I) by using the
    same lock file path (vct_root_dir() / "install.py.lock") AND by
    setting `_MAIN_ENTRY_LOCK_HELD = True` so V44-I's reentrant
    re-take is a noop on this process. Required because msvcrt.locking
    on Windows is NOT reentrant — without the flag, V44-I would
    deadlock against the lock we already hold.

    Writes "<pid>\\n<unix_timestamp>\\n" to the lock file after
    acquiring so concurrent attempts can name the holding PID in their
    error messages. Truncates first so stale PIDs from
    crashed-without-cleanup runs are overwritten.
    """
    global _MAIN_ENTRY_LOCK_HELD

    # Resolve lock path via the canonical resolver (mirrors V44-I).
    try:
        from vco_lib.paths import vct_root_dir as _vct_root_dir
        lock_path = _vct_root_dir() / "install.py.lock"
    except Exception as e:
        print(
            f"  WARNING: could not resolve install lock path: {e} "
            f"(proceeding without main-entry singleton guard)",
            file=sys.stderr,
        )
        return None

    fp = None
    try:
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        # a+b creates the file if missing and lets us seek+read+write.
        fp = open(str(lock_path), "a+b")
    except Exception as e:
        print(
            f"  WARNING: could not open install lock {lock_path}: {e} "
            f"(proceeding without main-entry singleton guard)",
            file=sys.stderr,
        )
        return None

    deadline = time.monotonic() + timeout_seconds
    backoff = 0.25
    acquired = False
    while time.monotonic() < deadline:
        try:
            if sys.platform == "win32":
                import msvcrt
                msvcrt.locking(fp.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(fp.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            acquired = True
            break
        except (BlockingIOError, OSError):
            time.sleep(backoff)
            backoff = min(backoff * 1.5, 2.0)

    if not acquired:
        # Read the holding PID + start-time from the lock file for the
        # diagnostic. May be empty (race: holder hasn't written yet) or
        # stale (crashed without releasing); surface whatever's there.
        holder_info = "unknown PID"
        try:
            fp.seek(0)
            raw = fp.read(256).decode("utf-8", errors="replace").strip()
            lines = raw.splitlines()
            holder_pid = lines[0].strip() if lines else "?"
            holder_ts = lines[1].strip() if len(lines) > 1 else "?"
            try:
                ts_int = int(float(holder_ts))
                import datetime as _dt
                started = _dt.datetime.fromtimestamp(ts_int).isoformat(
                    timespec="seconds"
                )
                holder_info = f"PID {holder_pid} (started {started})"
            except (ValueError, OSError):
                holder_info = f"PID {holder_pid}"
        except Exception:
            pass
        try:
            fp.close()
        except Exception:
            pass
        print(
            f"ERROR: install.py is already running ({holder_info}) on "
            f"lock {lock_path}; waited {timeout_seconds}s. Wait for the "
            f"other run to finish, or kill it and retry.",
            file=sys.stderr,
        )
        sys.exit(1)

    # Write holding PID + start timestamp so concurrent attempts can name
    # the conflict. Truncate first so a stale PID from a crashed-without-
    # cleanup prior run gets overwritten. seek+truncate within the same
    # open fd preserves the OS-level advisory lock we just acquired.
    try:
        import time as _time
        fp.seek(0)
        fp.truncate(0)
        payload = f"{os.getpid()}\n{int(_time.time())}\n".encode("utf-8")
        fp.write(payload)
        fp.flush()
    except Exception:
        # Diagnostic-only data; lock is already acquired. Don't fail.
        pass

    _MAIN_ENTRY_LOCK_HELD = True
    return fp


@_contextlib.contextmanager
def _install_advisory_lock(timeout_seconds: float = 60.0):
    """v0.2.44 V44-I: cross-OS advisory lock for the duration of the
    install-state mutation block.

    Prevents the split-brain hazard where two install.py processes
    interleave writes to .claude/settings.json and .claude/env.

    Cross-OS:
      - POSIX (Linux/macOS): fcntl.flock with LOCK_EX | LOCK_NB; retry
        with exponential backoff up to timeout_seconds. Lock file under
        vco_lib.paths.vct_root_dir() / "install.py.lock".
      - Windows: msvcrt.locking(LK_NBLCK, 1) on a 1-byte region at
        offset 0 of the same lock file; same retry pattern.

    Soft-fail: if the lock file cannot be created or locked at all
    (permission errors, filesystem quirks), emit a WARNING and continue
    without the lock. The lock is a defensive measure, not a hard gate.

    v0.2.49: if main() already holds the entry-lock on the SAME file
    (`_MAIN_ENTRY_LOCK_HELD == True`), this re-take is unnecessary AND
    would deadlock on Windows (msvcrt.locking is not reentrant). Yield
    immediately — the process-level entry lock already provides the
    same exclusion guarantee.
    """
    # v0.2.49: short-circuit when main() already holds the lock. POSIX
    # fcntl.flock is reentrant for the same fd in the same process,
    # but Windows msvcrt.locking is not — re-attempting the lock would
    # deadlock. The module-level flag is the canonical cross-OS guard.
    if _MAIN_ENTRY_LOCK_HELD:
        yield None
        return
    # Resolve lock path via the canonical resolver (mirrors the Rust
    # `paths::vct_root_dir`). install.py imports vco_lib at module load
    # so this should always succeed; if it doesn't, the unrecoverable
    # import error has already prevented this code path from running.
    from vco_lib.paths import vct_root_dir as _vct_root_dir
    lock_path = _vct_root_dir() / "install.py.lock"

    fp = None
    try:
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        fp = open(str(lock_path), "a+b")
    except Exception as e:
        print(
            f"  WARNING: could not open install lock {lock_path}: {e} "
            f"(proceeding without concurrency protection)"
        )
        yield None
        return

    deadline = time.monotonic() + timeout_seconds
    backoff = 0.25
    acquired = False
    try:
        while time.monotonic() < deadline:
            try:
                if sys.platform == "win32":
                    import msvcrt
                    msvcrt.locking(fp.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(fp.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                acquired = True
                break
            except (BlockingIOError, OSError):
                time.sleep(backoff)
                backoff = min(backoff * 1.5, 2.0)

        if not acquired:
            print(
                f"  WARNING: install lock {lock_path} held by another "
                f"process for >{timeout_seconds}s; proceeding without "
                f"concurrency protection"
            )

        yield fp if acquired else None
    finally:
        if acquired:
            try:
                if sys.platform == "win32":
                    import msvcrt
                    fp.seek(0)
                    msvcrt.locking(fp.fileno(), msvcrt.LK_UNLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(fp.fileno(), fcntl.LOCK_UN)
            except Exception:
                pass
        try:
            if fp is not None:
                fp.close()
        except Exception:
            pass


def _write_storage_toml_direct(choice: dict) -> Path:
    """Python fallback when no launcher binary is on disk.

    Schema mirrors `launcher/src-tauri/src/commands/storage_ux.rs::StorageConfig`:
        mode = "named" | "bind"
        bind_root = ""
        [per_service_paths]
        ollama = "/abs/path"
        ...
        [external_aliases]
    Atomic write (write to .tmp + rename) so a SIGTERM mid-write doesn't
    leave a half-formed TOML.
    """
    mode = choice.get("mode", "named")
    bind_paths: dict[str, str] = choice.get("bind_paths", {}) or {}
    state_dir = _vct_state_dir()
    state_dir.mkdir(parents=True, exist_ok=True)
    target = state_dir / "storage.toml"

    lines: list[str] = []
    lines.append(f'mode = "{mode}"')
    lines.append('bind_root = ""')
    lines.append("")
    lines.append("[per_service_paths]")
    if mode == "bind" and bind_paths:
        # Sort for stable output (matches the Rust BTreeMap renderer).
        for service in sorted(bind_paths):
            path_norm = bind_paths[service].replace("\\", "/")
            # Escape embedded quotes; TOML basic strings reject them.
            path_safe = path_norm.replace('"', '\\"')
            lines.append(f'{service} = "{path_safe}"')
    lines.append("")
    lines.append("[external_aliases]")
    body = "\n".join(lines) + "\n"

    tmp = target.with_suffix(".toml.tmp")
    tmp.write_text(body, encoding="utf-8")
    tmp.replace(target)
    return target


def _prompt_storage_location(
    install_root: Path,
    args: argparse.Namespace,
    *,
    input_fn=input,
    stdin_isatty=None,
    detect_fn=None,
) -> dict:
    """Prompt for storage layout at install time.

    Returns a dict shaped like:
        {"mode": "named" | "bind" | "deferred", "bind_paths": {...}}

    - "deferred" → install.py should leave `~/.vct/storage.toml` untouched
      and let the user configure storage via the launcher GUI later.
    - "named"   → fresh named volumes (the legacy default behaviour).
    - "bind"    → bind-mount the auto-detected legacy paths.

    Non-interactive contracts:
      - `--quiet`, `--yes`, or non-TTY stdin → return 'deferred' silently.
      - EOF on stdin during the prompt → return 'deferred'.
      - Detected nothing → return 'named' silently (no legacy data to
        surface; the default is the right answer).

    `input_fn`, `stdin_isatty`, and `detect_fn` are test seams; production
    callers pass the defaults.
    """
    is_quiet = bool(getattr(args, "quiet", False))
    is_yes = bool(getattr(args, "yes", False))
    if stdin_isatty is None:
        try:
            tty = sys.stdin.isatty()
        except (ValueError, OSError):
            tty = False
    else:
        tty = bool(stdin_isatty)

    if is_quiet or is_yes or not tty:
        return {"mode": "deferred", "bind_paths": {}}

    legacy_paths = (detect_fn or _detect_legacy_volume_paths)()
    if not legacy_paths:
        # No legacy data to worry about — silently default to named volumes.
        return {"mode": "named", "bind_paths": {}}

    print()
    print("=== Storage configuration ===")
    print("Detected pre-existing volume data on this machine:")
    for service in sorted(legacy_paths):
        path = legacy_paths[service]
        size = _dir_size_human(path)
        print(f"  - {service}: {path} ({size})")
    print()
    print("How should the orchestrator use this data?")
    print("  (1) Bind-mount the existing paths (recommended if you have models/data)")
    print("  (2) Use fresh named volumes (start clean; existing data preserved on disk)")
    print("  (3) Configure later via the launcher GUI's Storage Settings")
    print()
    try:
        raw = input_fn("Choice [1/2/3, default=3]: ")
    except (EOFError, KeyboardInterrupt):
        # User Ctrl+D / Ctrl+C'd — treat as deferred. Do NOT abort the
        # install; the prompt is opt-in UX, not a blocker.
        print("\n  (no answer — deferring storage configuration to the launcher)")
        return {"mode": "deferred", "bind_paths": {}}
    choice = (raw or "").strip() or "3"

    if choice == "1":
        return {"mode": "bind", "bind_paths": legacy_paths}
    if choice == "2":
        return {"mode": "named", "bind_paths": {}}
    return {"mode": "deferred", "bind_paths": {}}


def _persist_storage_choice(choice: dict, install_root: Path) -> str:
    """Persist the user's storage choice. Returns a short description of
    which path was used ('launcher-cli' or 'python-fallback' or 'deferred').
    Soft-fail throughout — never abort install over a missed write."""
    if choice.get("mode") == "deferred":
        return "deferred"

    # Storage-config is an interactive prompt context: skip tiers 2-3
    # (GitHub download, cargo rebuild) so we never block the user mid-
    # prompt. Falls back to _write_storage_toml_direct when no bundled
    # binary is on disk. PR-36 unified this with the MCP-registration
    # resolver — see `_ensure_launcher_binary`.
    binary = _ensure_launcher_binary(install_root, prefer_only_bundled=True)
    if binary is not None:
        cmd: list[str] = [str(binary), "--set-storage-config", choice["mode"]]
        for service, path in (choice.get("bind_paths") or {}).items():
            cmd.extend(["--bind-path", f"{service}={path}"])
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.returncode == 0:
                return "launcher-cli"
            print(
                f"  [storage] warning: launcher CLI exited {result.returncode}: "
                f"{(result.stderr or '').strip()}"
            )
            # Fall through to Python fallback so we still record the user's
            # decision even if the launcher binary is broken.
        except (subprocess.SubprocessError, OSError) as e:
            print(f"  [storage] warning: launcher CLI failed: {e}")

    try:
        target = _write_storage_toml_direct(choice)
        print(f"  [storage] wrote {target}")
        return "python-fallback"
    except (OSError, ValueError) as e:
        print(f"  [storage] warning: could not write storage.toml: {e}")
        return "failed"


