def _ensure_running_under_mcp_venv() -> None:
    """v0.2.45 V45-A: relaunch under MCP venv if weaviate import is missing.

    Why: the launcher's update_orchestrator Tauri command (installer.rs)
    spawns install.py under detect_python() — typically /usr/bin/python3.12
    on Linux, NOT claude_mcp_servers/.venv/bin/python. install.py step 7d
    (_migrate_kg_named_vector_slots) does an in-process `import weaviate`
    via vco_lib.project_init._connect_v4_client. weaviate-client only lives
    in the MCP venv. Without this relaunch, every launcher-driven update
    deferred 4 entries to UPDATE_DEFERRED.md with ModuleNotFoundError.

    No-op when:
      - weaviate is already importable (CLI users with venv activated)
      - we're already running under the resolved MCP venv (re-entry guard
        via VCT_INSTALL_RELAUNCHED env)
      - the resolved interpreter doesn't exist / can't be resolved
        (soft-fail; install proceeds with system Python and step 7d will
        still raise — but at least UPDATE_DEFERRED captures the error
        and we have not introduced a new failure mode)
    """
    import importlib.util
    if importlib.util.find_spec("weaviate") is not None:
        return  # already importable — nothing to do
    # Re-entry guard: avoid exec loops if the relaunch points back at us
    if os.environ.get("VCT_INSTALL_RELAUNCHED") == "1":
        return
    # v0.2.46 Part-1.5 H1: when any soft-fail path below short-circuits the
    # relaunch (no MCP venv resolvable, target non-existent, etc.), print a
    # breadcrumb so step 7d's eventual ModuleNotFoundError on `import weaviate`
    # points the user at the venv-resolution cause rather than appearing as
    # an unrelated traceback. Audit finding 2026-06-03 (venv-architecture).
    def _warn_silent_fallback(reason: str) -> None:
        print(
            "[v0.2.45 V45-A] could not relaunch under MCP venv "
            f"({reason}) — proceeding with system Python; "
            "step 7d (_migrate_kg_named_vector_slots) may fail with "
            "ModuleNotFoundError: weaviate."
        )
        sys.stdout.flush()
    try:
        target = _resolve_venv_python_for_install(PROJECT_ROOT)
    except Exception as _resolve_exc:
        _warn_silent_fallback(f"_resolve_venv_python_for_install raised: {_resolve_exc}")
        return
    if not target:
        _warn_silent_fallback("_resolve_venv_python_for_install returned None")
        return
    # Compare resolved interpreter against sys.executable; skip if same
    try:
        if Path(target).resolve() == Path(sys.executable).resolve():
            return
    except Exception:
        # Fallback: string-compare
        if str(target) == sys.executable:
            return
    if not Path(target).is_file():
        _warn_silent_fallback(f"resolved interpreter does not exist: {target}")
        return
    env = os.environ.copy()
    env["VCT_INSTALL_RELAUNCHED"] = "1"
    print(f"[v0.2.45 V45-A] relaunching install.py under MCP venv: {target}")
    sys.stdout.flush()
    os.execve(str(target), [str(target), *sys.argv], env)


# ---------------------------------------------------------------------------
# V47-C (v0.2.46 Part 2 Gap C): .env secret detection + keychain migration.
#
# Detects secret-shaped keys (TOKEN, SECRET, PAT, PASSWORD, AUTH, *_KEY)
# in the project's `.env`, offers to migrate them to the OS keychain via
# the vct-hub `/api/v1/secrets/migrate` endpoint. The keychain is the
# launcher's authoritative store for credentials post-Phase-5 of the
# secrets-consolidation plan; until V47-C, project `.env` files at
# adopt-time stayed plaintext-on-disk indefinitely because the wizard
# never offered a one-shot migration step. Asymmetric with
# `~/.claude.json` (which has had `_is_secret_shaped_env_key` filtering
# since PR-23 / v0.2.12) — this closes the gap on the per-project surface.
#
# Migration semantics (matches commands/secrets_import.rs):
#   * Scope:    Shared { project_id: SENTINEL_SHARED }  (one slot per user)
#   * Module:   "user"
#   * Key:      original env var name (e.g. "OPENAI_API_KEY")
#
# Post-migration the `.env` value is replaced with `__vco_keychain__`;
# the bundled secrets-resolver helper at
# `templates/scripts/vct_secrets_resolve.sh` treats that sentinel as
# "ask the hub".
# ---------------------------------------------------------------------------

def _post_secrets_to_hub(
    secrets_payload: list[dict],
) -> tuple[list[str], list[dict]]:
    """POST to ``/api/v1/secrets/migrate`` and return ``(migrated, failed)``.

    ``secrets_payload`` is ``[{"key": str, "value": str}, ...]``. The hub
    routes each pair into the user-shared keychain bucket (same slot the
    SecretsPanel's "Shared (this user)" tab writes to).

    Returns:
      * ``migrated`` — list of keys the hub confirmed it wrote.
      * ``failed`` — list of ``{"key": str, "error": str}`` for entries
        the hub could not write (transient keyring errors, permission
        denied, etc.).

    Raises ``RuntimeError`` only when the hub itself is unreachable or
    returns a non-2xx response — those are install-blocking failures
    that the caller should surface as a deferral.

    Discovery: uses ``vco_lib.project_config._discover_hub`` so the
    install path picks up the same port + token the resolver clients
    use (no duplicated env-var probing).
    """
    # Lazy imports: keep install.py's import surface stable when V47-C
    # isn't exercised on this run (most installs).
    import json
    try:
        import requests
    except ImportError as exc:
        raise RuntimeError(
            "V47-C: cannot migrate secrets — `requests` not importable; "
            "is the MCP venv active?"
        ) from exc

    from vco_lib.project_config import _discover_hub, HubUnreachable

    try:
        port, token = _discover_hub()
    except HubUnreachable as exc:
        raise RuntimeError(f"V47-C: hub unreachable: {exc}") from exc

    url = f"http://127.0.0.1:{port}/api/v1/secrets/migrate"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    body = json.dumps({"secrets": secrets_payload}).encode("utf-8")
    try:
        resp = requests.post(url, data=body, headers=headers, timeout=(2.0, 30.0))
    except requests.RequestException as exc:
        raise RuntimeError(f"V47-C: POST {url} failed: {exc}") from exc

    if resp.status_code >= 400:
        raise RuntimeError(
            f"V47-C: hub returned HTTP {resp.status_code}: "
            f"{resp.text[:300]!r}"
        )

    try:
        data = resp.json()
    except ValueError as exc:
        raise RuntimeError(
            f"V47-C: hub response not JSON: {resp.text[:300]!r}"
        ) from exc

    migrated = list(data.get("migrated") or [])
    failed = list(data.get("failed") or [])
    return migrated, failed


def _print_secrets_migration_details() -> None:
    """Print the long-form explanation shown on the ``details`` prompt option."""
    print()
    print("  What this does:")
    print("    1. Reads each secret-shaped key/value from your `.env`")
    print("    2. POSTs the values to your local vct-hub on 127.0.0.1")
    print("    3. The hub writes them to the OS keychain (libsecret on")
    print("       Linux, Keychain on macOS, Credential Manager on Windows)")
    print("    4. The .env values are replaced with `__vco_keychain__`")
    print("       so bundled tooling knows to ask the hub at runtime")
    print()
    print("  What this does NOT do:")
    print("    * No values leave your machine. The hub binds 127.0.0.1.")
    print("    * Your `.env` file is NOT deleted — the keys stay there")
    print("      with a sentinel value so .env-aware tools keep working.")
    print("    * Already-migrated entries (value == `__vco_keychain__`)")
    print("      are silently skipped.")
    print()
    print("  Why migrate:")
    print("    * Keychain encrypts secrets at rest (libsecret/Keychain).")
    print("    * Plaintext .env is readable by ANY process running as you,")
    print("      including a rogue `pip install` or browser extension.")
    print("    * Launcher GUI can rotate/pause/revoke keys without you")
    print("      having to grep through .env files.")
    print()


def _audit_and_offer_env_secret_migration(
    project_root: Path,
    deferral_report: DeferralReport,
    adopt_project_mode: str | None,
    args,
) -> None:
    """V47-C entry point. Audit ``.env`` and (interactively) migrate.

    Behaviour matrix:

    +-----------------+------------+--------------------------------+
    | env candidates  | TTY + !yes | action                         |
    +=================+============+================================+
    | none            | n/a        | silent no-op                   |
    +-----------------+------------+--------------------------------+
    | >=1             | interactive | prompt Y / n / details         |
    +-----------------+------------+--------------------------------+
    | >=1             | --yes / CI  | KEEP-IN-ENV + deferral entry   |
    +-----------------+------------+--------------------------------+

    `adopt_project_mode`:
      * ``"replace-all"`` → still prompt (secrets are sacrosanct; don't
        auto-migrate without consent even in aggressive mode).
      * ``"adopt"`` / ``None`` → standard interactive flow.
      * ``"no-adopt"`` / ``"dry-run"`` → already short-circuited upstream
        in ``main()``; we never reach this code path for them.

    Called from ``main()`` after the dry-run early-exit, before the actual
    install starts. Soft-fails on any exception — secrets handling must
    never block the install (the user can re-run with secrets later).
    """
    try:
        env_path = project_root / ".env"
        candidates = _secrets_audit.audit_env_secrets(env_path)
        if not candidates:
            return  # silent no-op — no secret-shaped keys with real values

        non_interactive = (
            bool(getattr(args, "yes", False))
            or bool(getattr(args, "quiet", False))
            or not sys.stdin.isatty()
        )

        sorted_keys = sorted({c.key for c in candidates})
        n = len(sorted_keys)
        plural = "" if n == 1 else "s"

        _log_install_event(
            "v47c_env_secrets_audit", "ok",
            f"detected {n} secret-shaped key{plural} in .env",
            data={"keys": sorted_keys, "interactive": not non_interactive},
        )

        print()
        print(f"  Detected {n} secret-shaped key{plural} in `.env`:")
        for k in sorted_keys:
            print(f"    * {k}")
        print()

        if non_interactive:
            # Headless / scripted install: don't surprise the user by
            # writing to their keychain. Default to keep-in-env, emit
            # a deferral so a follow-up `--update --apply-deferred`
            # surfaces the choice interactively next time.
            print(
                "  Running non-interactively (--yes / --quiet / no TTY) — "
                "keeping secrets in .env."
            )
            deferral_report.add_entry(
                DeferralEntry(
                    condition_id="env_secrets_retained_in_plaintext",
                    title=(
                        f"{n} secret-shaped key{plural} retained in plaintext "
                        f"in .env"
                    ),
                    detected=(
                        f"V47-C audit detected secret-shaped key{plural} in "
                        f"`{env_path}`: {', '.join(f'`{k}`' for k in sorted_keys)}. "
                        f"The install ran non-interactively so no migration "
                        f"was performed."
                    ),
                    why_deferred=(
                        "Migrating credentials to the OS keychain requires "
                        "explicit user consent (writes to the keychain are "
                        "irreversible from this process — the keychain becomes "
                        "the source of truth). The install ran with --yes / "
                        "--quiet / a non-TTY stdin so no consent could be "
                        "collected."
                    ),
                    command_to_apply=(
                        "# Re-run install.py interactively (no --yes / --quiet):\n"
                        "#   python install.py --update --apply-deferred\n"
                        "# At the prompt, answer 'Y' to migrate to the OS keychain.\n"
                        "# Or migrate one-by-one from the launcher GUI's per-project\n"
                        "# Secrets tab (V47-G-final)."
                    ),
                    severity="warning",
                    kg_node_refs=[
                        "knowledge/concepts/secret-management.md",
                    ],
                )
            )
            return

        # Interactive: prompt with Y / n / details.
        if adopt_project_mode == "replace-all":
            print(
                "  Note: --adopt-project-replace-all is set, but secrets "
                "still require explicit consent."
            )

        while True:
            try:
                answer = input(
                    "  Migrate these to the OS keychain? [Y/n/details] "
                ).strip().lower()
            except EOFError:
                # stdin closed mid-prompt → degrade to non-interactive path.
                print("  (stdin closed — keeping secrets in .env)")
                return
            if answer in ("", "y", "yes"):
                choice = "migrate"
                break
            if answer in ("n", "no"):
                choice = "keep"
                break
            if answer in ("d", "details"):
                _print_secrets_migration_details()
                continue
            print("  Please answer Y, n, or details.")

        if choice == "keep":
            print("  Keeping secrets in .env (no keychain writes).")
            _log_install_event(
                "v47c_env_secrets_audit", "ok",
                "user declined keychain migration",
                data={"keys": sorted_keys, "choice": "keep"},
            )
            deferral_report.add_entry(
                DeferralEntry(
                    condition_id="env_secrets_retained_in_plaintext",
                    title=(
                        f"{n} secret-shaped key{plural} retained in plaintext "
                        f"in .env (user choice)"
                    ),
                    detected=(
                        f"User declined the V47-C keychain-migration offer for "
                        f"`{env_path}`: {', '.join(f'`{k}`' for k in sorted_keys)}."
                    ),
                    why_deferred=(
                        "User declined the offer. The .env file remains the "
                        "authoritative source for these secrets. Re-running "
                        "install.py will re-offer the migration."
                    ),
                    command_to_apply=(
                        "# To accept the offer on a future run:\n"
                        "#   python install.py --update --apply-deferred\n"
                        "# Or migrate one key at a time from the launcher GUI's\n"
                        "# per-project Secrets tab (V47-G-final)."
                    ),
                    severity="info",
                    kg_node_refs=[
                        "knowledge/concepts/secret-management.md",
                    ],
                )
            )
            return

        # User said Y — POST to hub, rewrite .env on success.
        secrets_payload = [
            {"key": c.key, "value": c.value} for c in candidates
        ]
        try:
            migrated, failed = _post_secrets_to_hub(secrets_payload)
        except RuntimeError as exc:
            print(f"  Migration failed: {exc}")
            print("  Keeping secrets in .env (no changes made).")
            _log_install_event(
                "v47c_env_secrets_audit", "warn",
                f"hub-migrate failed: {exc}",
                data={"keys": sorted_keys, "error": str(exc)},
            )
            deferral_report.add_entry(
                DeferralEntry(
                    condition_id="env_secrets_hub_migration_failed",
                    title=(
                        f"V47-C: keychain migration failed for {n} "
                        f"secret{plural}"
                    ),
                    detected=(
                        f"User accepted the V47-C migration offer but the hub "
                        f"call failed: {exc}. .env was NOT modified; the "
                        f"keychain was NOT written to. Keys queued for retry: "
                        f"{', '.join(f'`{k}`' for k in sorted_keys)}."
                    ),
                    why_deferred=(
                        "The hub round-trip failed. Most common cause: the "
                        "launcher / vct-hub is not running, or the user's "
                        "keychain backend (libsecret on Linux, Keychain on "
                        "macOS, Credential Manager on Windows) is unavailable. "
                        "Auto-retry on the next install run isn't safe — the "
                        "values may have changed in .env between runs."
                    ),
                    command_to_apply=(
                        "# 1. Verify the launcher is running:\n"
                        "#      vct-hub --status\n"
                        "# 2. Re-run the migration:\n"
                        "#      python install.py --update --apply-deferred"
                    ),
                    severity="warning",
                    kg_node_refs=[
                        "knowledge/concepts/secret-management.md",
                    ],
                )
            )
            return

        # Rewrite .env: only the keys the hub confirmed.
        if migrated:
            try:
                replaced, missed = _secrets_audit.rewrite_env_with_sentinels(
                    env_path, migrated,
                )
            except Exception as exc:  # noqa: BLE001 — soft-fail
                # Migration succeeded keychain-side but the rewrite failed.
                # This is recoverable — re-run will detect "already in
                # keychain" and offer to rewrite again.
                print(
                    f"  Migrated {len(migrated)} key{plural} to keychain, "
                    f"but rewriting .env failed: {exc}"
                )
                _log_install_event(
                    "v47c_env_secrets_audit", "warn",
                    f"rewrite failed after successful hub-migrate: {exc}",
                    data={"migrated": migrated, "error": str(exc)},
                )
            else:
                print(
                    f"  Migrated {replaced} key{plural} to the OS keychain. "
                    f"`.env` values replaced with `__vco_keychain__`."
                )
                if missed:
                    print(
                        f"  Note: {len(missed)} key(s) not found in `.env` "
                        f"at rewrite time: {', '.join(missed)}"
                    )
                _log_install_event(
                    "v47c_env_secrets_audit", "ok",
                    f"migrated {len(migrated)} key{plural}; replaced {replaced} in .env",
                    data={"migrated": migrated, "missed": missed},
                )

        if failed:
            failed_keys = [f.get("key", "?") for f in failed]
            print(
                f"  Failed to migrate {len(failed)} key{plural}: "
                f"{', '.join(failed_keys)}"
            )
            for f in failed:
                print(f"    {f.get('key', '?')}: {f.get('error', '?')}")
            deferral_report.add_entry(
                DeferralEntry(
                    condition_id="env_secrets_hub_migration_partial",
                    title=(
                        f"V47-C: {len(failed)} of {n} secret{plural} failed to "
                        f"migrate to keychain"
                    ),
                    detected=(
                        f"Partial migration: {len(migrated)} succeeded, "
                        f"{len(failed)} failed. Failed keys: "
                        f"{', '.join(f'`{k}`' for k in failed_keys)}. "
                        f"The succeeded keys' .env values were replaced with "
                        f"`__vco_keychain__`; the failed keys' values remain "
                        f"plaintext."
                    ),
                    why_deferred=(
                        "The hub rejected some entries (transient keychain "
                        "error, permission denied, etc.). The remaining "
                        "plaintext values are flagged here so the user can "
                        "retry after the underlying cause is fixed."
                    ),
                    command_to_apply=(
                        "# Inspect the failures (check libsecret / Keychain / "
                        "Credential Manager state),\n"
                        "# then re-run:\n"
                        "#   python install.py --update --apply-deferred"
                    ),
                    severity="warning",
                    kg_node_refs=[
                        "knowledge/concepts/secret-management.md",
                    ],
                )
            )

        # Best-effort perm hardening on Unix.
        changed, msg = _secrets_audit.harden_env_perms(env_path)
        if msg:
            _log_install_event(
                "v47c_env_perms", "ok" if changed else "info", msg,
            )
            if changed:
                print(f"  Hardened .env file permissions ({msg}).")

    except Exception as exc:  # noqa: BLE001 — V47-C is best-effort
        # Never let secrets-audit block an install. Log + move on.
        _log_install_event(
            "v47c_env_secrets_audit", "warn",
            f"audit raised unexpectedly: {exc}",
        )


def main() -> int:
    # v0.2.53 bootstrap mode (Track B / docs/INSTALL_ARCHITECTURE_v2.md §3):
    # short-circuit BEFORE _ensure_running_under_mcp_venv() so the bootstrap
    # probe is usable on a freshly cloned repo with no .venv. The bootstrap
    # dispatch reads sys.argv directly (no argparse) because argparse
    # construction happens further down and we don't want to defer the
    # short-circuit through there.
    #
    # Bootstrap is READ-ONLY by default. With --install-missing it runs
    # pkgmgr install commands for blocking prereqs. Never writes JSONL,
    # never spawns daemons (except `podman machine init` when explicitly
    # requested), never mutates ~/.claude.json. See §3.5 side-effect policy.
    if "--bootstrap" in sys.argv:
        # Defer --help to the full argparse so the user sees the
        # standard help envelope rather than a bootstrap-only error.
        if "--help" in sys.argv or "-h" in sys.argv:
            pass
        else:
            # Forward only flags after the script name; --bootstrap is
            # consumed inside _run_bootstrap.
            return _run_bootstrap(sys.argv[1:])

    # v0.2.46 Part-1.5 H3: DO NOT call _log_install_event or any code that
    # buffers state into module-level variables BEFORE this line. When
    # _ensure_running_under_mcp_venv() execve's into the MCP venv, the new
    # process re-imports install.py from scratch — any module-level state
    # accumulated in the pre-relaunch process (incl. _PENDING_EVENTS) is
    # lost. Today the discipline is naturally preserved because nothing
    # logs before main() runs; this comment exists to keep that invariant
    # explicit when future refactors are tempted to log earlier.
    # Audit finding 2026-06-03 (venv-runtime-adversarial S5).
    _ensure_running_under_mcp_venv()
    # 2026-04-29 fix (wizard install-path lockdown): defensive
    # source-repo check — install.py operates on PROJECT_ROOT which is
    # the directory it was launched from. If someone has copied
    # install.py somewhere without first-install.sh next to it, fail
    # loudly with a clear message instead of half-installing.
    validate_source_repo(PROJECT_ROOT)

    # v0.2.49: main()-entry single-instance lock for --update runs.
    # Closes the 13-minute-deadlock pattern reported 2026-06-05 from
    # a contributor's machine where two concurrent `install.py --update`
    # invocations interleaved on shared state. Wait-then-die with a
    # 15s timeout — fast enough for accidental double-clicks to
    # succeed (first instance finishes), but bounded so a genuine
    # concurrent run gets a clear error.
    #
    # The V44-I narrow-block lock at install.py:~11193 coordinates on
    # the same lockfile via the module-level `_MAIN_ENTRY_LOCK_HELD`
    # flag (set inside `_install_singleton_lock_or_die` on success).
    # Without that flag V44-I would re-take the same OS lock and
    # deadlock on Windows (msvcrt.locking is not reentrant; POSIX
    # fcntl.flock IS reentrant, so on Linux/macOS it would be a noop
    # but the flag short-circuits cleanly on both surfaces).
    #
    # Gated on "--update" in sys.argv (peeked BEFORE argparse) so the
    # guard fires only for the deadlock-prone code path. Fresh installs
    # on a clean dir don't have the same shared-state mutation contention.
    # Soft-fails to WARNING if the lock file can't be opened
    # (permission/readonly fs) — same discipline as V44-I.
    global _MAIN_ENTRY_LOCK_HANDLE
    if "--update" in sys.argv:
        _MAIN_ENTRY_LOCK_HANDLE = _install_singleton_lock_or_die(
            timeout_seconds=15.0
        )

    parser = argparse.ArgumentParser(
        description="VibeCoded Tools — Orchestrator Installer",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("--no-containers", action="store_true",
                        help="Skip Docker/Podman service setup")
    parser.add_argument("--gpu", action="store_true",
                        help="Enable GPU support for Ollama + code embeddings")
    parser.add_argument("--cpu-only", action="store_true",
                        help="Force CPU-only mode (skip GPU detection)")
    parser.add_argument("--no-gpu-check", action="store_true",
                        help="Skip GPU driver probing entirely (for environments where nvidia-smi/rocm-smi hangs)")
    parser.add_argument("--low-resource", action="store_true",
                        help="Lightest mode: Jina V2 (768d) via Ollama. For low-RAM/low-VRAM machines.")
    # v0.2.9 (Bug K): VRAM threshold for auto GPU vs CPU mode pick.
    # Default 8.0 GB — see `_DEFAULT_GPU_VRAM_THRESHOLD_GB` rationale.
    parser.add_argument("--gpu-vram-threshold-gb", type=float,
                        default=_DEFAULT_GPU_VRAM_THRESHOLD_GB,
                        help=(f"VRAM threshold (GB) for auto GPU mode "
                              f"selection. Below this, the install falls "
                              f"back to CPU-only even with a discrete GPU "
                              f"present. Default: "
                              f"{_DEFAULT_GPU_VRAM_THRESHOLD_GB}."))
    parser.add_argument("--openai-key", type=str, default="",
                        help="Use OpenAI embeddings (provide API key)")
    parser.add_argument("--container", type=str, choices=["docker", "podman"],
                        help="Force a specific container runtime")
    parser.add_argument("--dev", action="store_true",
                        help="Install development dependencies")
    parser.add_argument("--skip-models", action="store_true",
                        help="Skip pulling Ollama models")
    parser.add_argument("--update", action="store_true",
                        help="Update mode: skip clone, re-install deps + restart services. "
                             "Always writes .claude/context/UPDATE_DEFERRED.md at the end — "
                             "either with actionable deferral entries OR a stub confirming "
                             "the run completed cleanly (Fix 6, v0.2.13).")
    # v0.2.53: bootstrap mode is short-circuited at top of main() BEFORE
    # argparse runs (so it works on a freshly cloned repo with no .venv).
    # The argparse entries here exist only so `install.py --help` shows
    # the flags. The actual dispatch reads sys.argv directly — argparse
    # never sees these in bootstrap runs. See _run_bootstrap().
    parser.add_argument("--bootstrap", action="store_true",
                        help="(v0.2.53) Bootstrap probe mode: detect system "
                             "prereqs and emit a versioned JSON envelope "
                             "(with --json) or human-readable summary "
                             "(default). READ-ONLY; safe to run before "
                             "first install. Implements §3 of "
                             "docs/INSTALL_ARCHITECTURE_v2.md. Schema: "
                             "docs/schemas/install-bootstrap-envelope-v1.json.")
    parser.add_argument("--json", action="store_true",
                        help="With --bootstrap: emit JSON envelope on stdout "
                             "for machine consumers (Rust + bash). Without "
                             "--bootstrap: no effect (reserved).")
    parser.add_argument("--install-missing", action="store_true",
                        help="With --bootstrap: run package-manager install "
                             "commands for missing prereqs. Side-effectful. "
                             "Prompts for consent on TTY; --no-prompt skips "
                             "the prompt.")
    parser.add_argument("--no-prompt", action="store_true",
                        help="With --bootstrap --install-missing: skip the "
                             "interactive consent prompt (assume yes).")
    parser.add_argument("--rebuild-collections", action="store_true", default=False,
                        help="Drop and re-ingest Weaviate collections (KG + dev). "
                             "Required when the schema invariants change "
                             "(named-vector slots, index_null_state, etc.) and "
                             "Weaviate ≤1.30 doesn't allow Reconfigure for those. "
                             "ONLY touches Weaviate state — your .md sources, "
                             ".env, .vscode/settings.json, .claude/settings.json "
                             "are NOT modified. Auto-detected and prompted on "
                             "--update when the running collection lacks "
                             "today's invariants.")
    parser.add_argument("--skip-rebuild-prompt", action="store_true", default=False,
                        help="During --update, skip the schema-rebuild prompt "
                             "even if the running collection is on an older "
                             "schema. Use to defer the rebuild for a later "
                             "session (search may misbehave until rebuilt).")
    parser.add_argument("--migrate-dry-run", "--dry-run-migrate",
                        dest="migrate_dry_run", action="store_true", default=False,
                        help="With --rebuild-collections: report the migration "
                             "plan only, do NOT mutate Weaviate. Useful to "
                             "preview which collections will be patched in "
                             "place vs copied vs rebuilt.")
    parser.add_argument("--force-rebuild", action="store_true", default=False,
                        help="With --rebuild-collections: bypass smart "
                             "copy-with-vectors path and always drop + "
                             "re-embed (the OLD behaviour, escape hatch). "
                             "Use when the source has legacy single-vector "
                             "format or you suspect vector corruption.")
    parser.add_argument("--migrate-uuid-scheme", action="store_true", default=False,
                        help="Stub placeholder (v0.2.16): mark the install "
                             "manifest's code-graph uuid_scheme key for migration "
                             "tooling. The actual migration runs as a follow-up in "
                             "a later release. Currently a no-op beyond the "
                             "manifest marker that --update already writes "
                             "(uuid_scheme=\"v2\"); installs predating v0.2.16 "
                             "have no marker, which a future migrator will read "
                             "as \"v1\" and suggest code-graph --force-recreate.")
    parser.add_argument("--apply-deferred", action="store_true", default=False,
                        help="During --update, attempt to apply each pending entry "
                             "in .claude/context/UPDATE_DEFERRED.md. Resolved entries "
                             "are removed; the file is deleted when zero entries remain.")
    parser.add_argument("--apply-orphan-deletes", action="store_true", default=False,
                        help="During --update --apply-deferred, additionally consent "
                             "to DELETE Weaviate collections marked by the "
                             "`orphan_*_collection` deferral entries (the deferrals "
                             "name 0-row legacy collections from older install.py "
                             "versions). Destructive on the Weaviate side; the script "
                             "still re-verifies the collection is empty + still "
                             "exists before issuing the DELETE.")
    parser.add_argument("--force-pin-reset", action="store_true", default=False,
                        help="On --update, REINSTALL any globally-installed npm "
                             "package whose version drifted from "
                             "bundled_mcp_versions.toml back to the pinned "
                             "version. Without this flag, drift is detected and "
                             "reported via UPDATE_DEFERRED.md (Phase 0 of "
                             "the diagrams-integration plan, 2026-05-24) but "
                             "the user's installed version is left untouched. "
                             "Use this when you intentionally want VCO to "
                             "overwrite an out-of-band `npm install -g` your "
                             "shell history shows you ran.")
    parser.add_argument("--rewrite-stale-mcps", action="store_true", default=False,
                        help="On --update, prompt for consent to rewrite any "
                             "~/.claude.json mcpServers entries whose paths point "
                             "outside the current install_root. Without this flag, "
                             "stale entries are only detected + reported via deferral "
                             "(PR-23 behavior). With this flag, each stale entry is "
                             "prompted individually (y/n/all/skip-all). --quiet "
                             "bypasses the prompt and emits a clarifying deferral "
                             "(no rewrite). Set VCT_REWRITE_STALE_MCPS=all in the "
                             "env to auto-accept all entries (CI / scripted). PR-33.")
    parser.add_argument("--remove-deprecated-mcps", action="store_true", default=False,
                        help="On --update, prompt for consent to REMOVE ~/.claude.json "
                             "mcpServers entries that belong to deprecated default MCPs "
                             "(e.g. `ollama`, removed in v0.2.11). Without this flag, "
                             "deprecated entries are only detected + reported via deferral "
                             "(PR-34 detection-only behavior). With this flag, each "
                             "matching entry whose command path is inside the current "
                             "install_root is prompted individually (y/n/all/skip-all). "
                             "--quiet bypasses the prompt and emits a clarifying deferral "
                             "(no removal). User-customised entries whose command path is "
                             "OUTSIDE install_root are never touched. "
                             "Set VCT_REMOVE_DEPRECATED_MCPS=all in the env to "
                             "auto-accept all entries (CI / scripted). PR-34.")
    # Fix 1 (v0.2.13): post-cargo-rebuild dist-binary refresh.
    parser.add_argument("--no-binary-swap", dest="no_binary_swap",
                        action="store_true", default=False,
                        help="Skip the v0.2.13 post-rebuild dist-binary refresh. "
                             "Normally, when a fresh launcher binary is detected at "
                             "launcher/src-tauri/target/release/vct-launcher-temp "
                             "(produced during this install run, or newer than the "
                             "version recorded in tauri.conf.json), install.py copies "
                             "it into launcher/dist/<os>-<arch>/ so the next "
                             "_ensure_launcher_binary() returns the fresh artifact. "
                             "Pass --no-binary-swap to opt out (the dist binary stays "
                             "untouched even if a fresher build exists).")
    # Fix 5 (v0.2.13): control the Path A tier-3 retry inside _register_mcps.
    parser.add_argument("--prefer-only-bundled", dest="prefer_only_bundled",
                        action="store_true", default=False,
                        help="MCP registration: restrict launcher-binary resolution "
                             "to the bundled tier-1 path only — skip tier-2 (download) "
                             "and tier-3 (cargo rebuild) AND the v0.2.13 Fix-5 retry. "
                             "Used by latency-sensitive contexts that can't afford a "
                             "15-25 min cargo build (e.g. mid-prompt registration).")
    parser.add_argument("--no-rebuild-on-stale", dest="no_rebuild_on_stale",
                        action="store_true", default=False,
                        help="MCP registration: skip the v0.2.13 Fix-5 tier-3 retry "
                             "even when the launcher CLI times out / exits non-zero "
                             "against a tier-1 (potentially stale) binary. Useful for "
                             "CI / scripted runs that explicitly opt out of cargo "
                             "fallback. Tier-1/2/3 binary RESOLUTION itself is "
                             "unaffected — this only gates the post-failure retry.")
    parser.add_argument("--project-folder", type=str, default=None,
                        help="Folder where .claude/context/UPDATE_DEFERRED.md should "
                             "land. Defaults to the orchestrator's PROJECT_ROOT "
                             "(self-update behavior). End-user managed projects pass "
                             "their own project root so deferral entries are visible "
                             "in their workspace, not the orchestrator clone.")
    parser.add_argument("--quiet", action="store_true",
                        help="Minimal output")
    parser.add_argument("--no-lean-ctx", action="store_true", default=False,
                        help="Skip lean-ctx detection / install / hints (optional CLI-output compression tool).")
    parser.add_argument("--with-agents", action="store_true", default=True,
                        help="Install bundled Claude agents (default: on)")
    parser.add_argument("--no-agents", dest="with_agents", action="store_false",
                        help="Skip installing Claude agents")
    parser.add_argument("--with-skills", action="store_true", default=True,
                        help="Install Claude skills (default: on)")
    parser.add_argument("--no-skills", dest="with_skills", action="store_false",
                        help="Skip installing Claude skills")
    parser.add_argument("--with-hooks", action="store_true", default=True,
                        help="Install Claude Code hooks + merge .claude/settings.json (default: on)")
    parser.add_argument("--no-hooks", dest="with_hooks", action="store_false",
                        help="Skip installing hooks and the settings.json template")
    parser.add_argument("--no-compile", dest="compile_pyc", action="store_false", default=True,
                        help="Skip the bytecode-compile step (Step 11b). First import of "
                             "orchestrator modules will be ~50-200ms slower; useful for "
                             "dev/CI runs where the speedup doesn't matter.")
    parser.add_argument("--telemetry", choices=["on", "off"], default=None,
                        help="Anonymous telemetry consent. Default: prompt; "
                             "non-interactive runs default to 'off'.")
    parser.add_argument("--yes", action="store_true",
                        help="Non-interactive: accept defaults for all prompts (telemetry=off).")
    parser.add_argument("--uninstall", action="store_true", default=False,
                        help="Uninstall the orchestrator. Lists what will be removed (dry-run by "
                             "default), then prompts for confirmation per category.")
    parser.add_argument("--keep-data", action="store_true", default=False,
                        help="Uninstall: keep container volumes (Weaviate / Ollama / code embeddings).")
    parser.add_argument("--remove-projects", action="store_true", default=False,
                        help="Uninstall: also remove orchestrator-managed .claude/ folders in "
                             "registered projects (default: off — leave user code alone).")
    parser.add_argument("--dry-run", action="store_true", default=False,
                        help="Uninstall: print what would be removed without removing anything.")
    parser.add_argument("--skip-seed", action="store_true", default=False,
                        help="Skip the Weaviate seed step (bundled knowledge/ + docs/). "
                             "Also skips collection creation — when there's no content "
                             "to seed, the MCP server creates collections lazily on first "
                             "write. Useful in CI / test runs. Re-run later with "
                             "`kg-sync --all` (handles both knowledge/ and docs/ since 2026-04-30).")
    # PR-39 (v0.2.12, 2026-05-16): the orchestrator-self's runtime .claude/
    # is now rendered from templates/ at install time. This flag skips that
    # step for tests / installs targeting a pre-populated .claude/.
    parser.add_argument("--skip-materialize-claude-dir", action="store_true",
                        default=False,
                        help="Skip rendering .claude/{hooks,scripts,settings.json} "
                             "from templates/ (PR-39, v0.2.12). Useful in tests or "
                             "when targeting a pre-populated .claude/ directory.")
    # v0.2.54 Track D (Theme 5): the orchestrator-self materialize now
    # hash-compares against .claude/.vco-self-manifest.json and PRESERVES
    # user-modified hook/script copies (emitting an
    # orchestrator_self_user_modified_preserved deferral) instead of
    # silently overwriting them. This flag accepts the template versions
    # for every preserved file.
    parser.add_argument("--force-materialize-claude-dir", action="store_true",
                        default=False,
                        help="Overwrite user-modified .claude/{hooks,scripts} "
                             "files with the current template versions (the "
                             "default since v0.2.54 is to preserve them and "
                             "emit a deferral entry).")
    parser.add_argument("--no-resume", action="store_true", default=False,
                        help="Disable resume-from-log. Forces every step to run "
                             "even if state/logs/install.jsonl says a previous "
                             "session already completed it. Default: resume "
                             "enabled (verifies side effects regardless).")
    parser.add_argument("--skip-collections", action="store_true", default=False,
                        help="Skip Weaviate collection bootstrap (Step 7b) but still seed. "
                             "Implied by --skip-seed. Useful when the user wants the MCP "
                             "server to create collections lazily.")
    # Safe-by-default service handling. When a foreign Weaviate / Ollama is
    # detected on the canonical port, the installer prompts the user. These
    # flags resolve the prompt non-interactively for CI / scripting.
    parser.add_argument("--on-conflict",
                        choices=["alt-port", "adopt", "abort"],
                        default=None,
                        help="Non-interactive resolution when a foreign service is "
                             "detected on a canonical port. 'alt-port' (default for "
                             "foreign): pick a free port and write compose.override.yaml. "
                             "'adopt' (advanced): reuse the foreign service in place — "
                             "WILL write our collections into it. 'abort': stop install.")
    # Re-install file-conflict resolution. Mirrors the 4-option modal in
    # the launcher's OnboardingWizard. CLI users running install.py
    # directly against a populated install path get explicit flags
    # instead of the wizard prompt. Default unset = keep current behaviour
    # (no copy step in install.py — those flags are a no-op unless
    # --conflict-source-path is also passed). See
    # docs/INSTALL_RECOVERY.md → "Conflict Resolution".
    parser.add_argument("--conflict-strategy",
                        choices=["delete-claude", "overwrite-all",
                                 "overwrite-preserve", "adopt-as-is"],
                        default=None,
                        help="File-conflict resolution when re-installing over an "
                             "existing install. Pairs with --conflict-source-path "
                             "(the bundled repo to copy FROM). Mirrors the "
                             "OnboardingWizard's 4-option modal.")
    parser.add_argument("--conflict-source-path",
                        type=str, default=None,
                        help="Source path for the conflict-resolution copy step "
                             "(should be a bundled vct-orchestrator repo with "
                             "vct-module.json). Required when --conflict-strategy "
                             "is set.")
    parser.add_argument("--lightweight", action="store_true", default=False,
                        help="Lightweight re-install. Skips model pulls + Weaviate "
                             "seed (idempotent upserts already done), preserves an "
                             "existing healthy .venv (recreates only on Python "
                             "version mismatch or requirements.txt drift), and "
                             "runs path-rewrite on .env / .claude/settings.json. "
                             "Used by the launcher's per-project re-install path "
                             "(Deliverable 3 from launch-blocker spec 2026-04-28).")
    parser.add_argument("--lightweight-old-path", type=str, default=None,
                        help="Used with --lightweight. The previous install path "
                             "whose absolute occurrences in .env / settings.json "
                             "should be rewritten to the current PROJECT_ROOT.")
    # v0.2.46 V47-D (Gap D): explicit override for the new venv-adopt guard.
    # By default, `_venv_triage` refuses to recreate a `.venv` when no
    # `.vco-manifest.json` is present (= "VCO doesn't own this venv —
    # could be a user's 3rd-party scientific stack"). When the user
    # KNOWS the recreate is correct, `--rebuild-venv` opts in.
    parser.add_argument("--rebuild-venv", action="store_true", default=False,
                        help="v0.2.46: force-rebuild the project's .venv even "
                             "when VCO can't prove it owns it (no "
                             ".vco-manifest.json). By default, the lightweight "
                             "re-install path refuses to destroy a 3rd-party "
                             "venv on Python-version drift or when no "
                             "requirements.txt is present. Pass this flag when "
                             "you know VCO is correct to rebuild — e.g. you "
                             "intentionally changed the launcher's Python "
                             "version and the project's venv needs to follow.")
    # v0.2.10 (Bug L2 — cross-OS boot-service materialization). The
    # compose-project working directory may not match the install path
    # (the canonical example: install at ~/code/orch but compose lives
    # at ~/code/claude/claude_mcp_servers). When set, this is the highest-
    # priority signal for _resolve_compose_working_dir; otherwise we
    # probe a running container's working_dir label, then fall back to
    # install-path probes.
    parser.add_argument("--compose-working-dir", type=str, default=None,
                        help="Absolute path to the directory containing "
                             "compose.yaml for the Claude MCP stack. Used by "
                             "the boot-service materialization step to record "
                             "WorkingDirectory= in the systemd unit / launchd "
                             "plist / Task Scheduler XML. When unset, the "
                             "installer probes a running container's label, "
                             "then falls back to <install>/claude_mcp_servers/ "
                             "or <install>/infrastructure/.")
    parser.add_argument("--preserve-paths",
                        type=str, default=None,
                        help="Comma-separated list of install-relative paths to "
                             "preserve under --conflict-strategy=overwrite-preserve. "
                             "Default: CLAUDE.md,.claude/CONTEXT_STATE.md,"
                             ".claude/PROJECT_REGISTRY.md,.env")
    # v0.2.6 (Bug C1): desktop-icon lifecycle. Direct `python install.py`
    # runs (without first-install.sh wrapping) previously skipped the
    # icon-creation step entirely. The orchestrator now invokes
    # `scripts/post-install-launcher.sh` (or .ps1 on Windows when present)
    # at the end of a successful full install — UNLESS opted out via
    # `--no-desktop-icon` / `VCT_NO_DESKTOP_ICON=1`. `--desktop-icon-only`
    # skips the actual install steps and runs ONLY the icon step (for
    # users who declined the first time and changed their mind).
    parser.add_argument("--no-desktop-icon", action="store_true", default=False,
                        help="Skip the desktop-icon creation step at end of install. "
                             "Equivalent to VCT_NO_DESKTOP_ICON=1.")
    parser.add_argument("--desktop-icon-only", action="store_true", default=False,
                        help="Run ONLY the desktop-icon step (post-install-launcher.sh) "
                             "and exit. Useful when you skipped the icon during the "
                             "initial install and want to add it later.")
    # PR-11: global lean-ctx hook detection warning suppression.
    # Users who've reviewed the global lean-ctx hooks and decided to keep
    # them (e.g. for lean-ctx development) can silence the warning.
    parser.add_argument("--suppress-lean-ctx-warning", action="store_true",
                        default=False,
                        help="Suppress the global lean-ctx hooks detection warning. "
                             "Use when you've reviewed the hooks and intentionally "
                             "keep them (e.g. lean-ctx development).")
    # PR-14b: MCP-simplification deprecation notices. Power users / CI that
    # have already acted on the notices can silence the three checks.
    parser.add_argument("--suppress-mcp-deprecation-warnings", action="store_true",
                        default=False,
                        help="Suppress v0.2.11 MCP-simplification deprecation notices "
                             "(SearXNG removed from default stack, Ollama MCP removed, "
                             "search MCP env simplified). Use after you have manually "
                             "cleaned up these remnants.")
    parser.add_argument("--skip-mcp-registration", action="store_true",
                        default=False,
                        help="Skip PR-23 (v0.2.12) MCP-server registration to "
                             "~/.claude.json. Use only for advanced cases where "
                             "you manage ~/.claude.json mcpServers entries "
                             "outside the installer (multi-stack adoption, "
                             "containerised deployment, etc.).")
    # v0.2.42 CI-3-nohub: skip Step 8 (vct-hub deploy + start).
    # Verified auto-start fallback: templates/hooks/session-start-ensure-hub.sh
    # (and its .ps1 sibling) run on every Claude Code SessionStart and invoke
    # `vct-hub --start-if-not-running`, so the hub comes up on the user's next
    # Claude Code session even when skipped here.
    parser.add_argument("--no-hub", action="store_true", default=False,
                        help="v0.2.42: skip Step 8 (vct-hub deployment + start). "
                             "Useful in CI environments without a vct-hub binary "
                             "on PATH (no GitHub release download, no cargo build). "
                             "With --update + --no-hub: any already-running hub is "
                             "left untouched; only the launch step is skipped. "
                             "Hub auto-starts on next launcher open or first Claude "
                             "Code session start (session-start-ensure-hub hook).")

    # ----------------------------------------------------------------------
    # v0.2.46 Part 2 (V47-G-stub): third-party-project adoption mode flags.
    #
    # Distinct from --on-conflict {adopt,...} (service-level adoption of a
    # foreign Weaviate/Ollama/code_embed) and from --conflict-strategy
    # adopt-as-is (file-level keep-on-disk-as-is). Those operate on
    # individual surfaces inside an existing VCO project. THIS group decides
    # what to do with the ENTIRE PROJECT when install.py is run against a
    # directory that already has substantial pre-existing user content (a
    # populated .claude/, an existing .env with secrets, a .venv with
    # project-specific deps, a custom CLAUDE.md, etc.) but no .vco-manifest.
    #
    # V47-G-stub ships only the CLI surface + dispatch contract. Detection
    # heuristic + interactive prompt land in V47-G-final.
    # ----------------------------------------------------------------------
    # v0.2.46 V47-F (Gap F): explicit PROJECT_NAME override.
    # Highest-precedence layer of _resolve_project_name_for_adopt — beats
    # .vscode/settings.json, .claude/env, .env, and the interactive prompt.
    # Used ONLY in the NEW adopt path (when .vco-manifest.json is absent);
    # existing-project updates keep their existing PROJECT_NAME (additive-
    # only contract in _reconcile_env_keys).
    parser.add_argument(
        "--project-name", type=str, default=None,
        help="v0.2.46 (adopt mode): explicit PROJECT_NAME override for "
             "the new adopt path. Pinned as the canonical project name "
             "for KG / Development collection derivation. Beats "
             ".vscode/settings.json claude-code.env.PROJECT_NAME, "
             ".claude/env, .env, and the interactive prompt. Existing "
             "VCO projects (with .vco-manifest.json) are NEVER re-derived "
             "by this flag — they keep whatever PROJECT_NAME they have at "
             "update time.")

    _adopt_project_group = parser.add_mutually_exclusive_group()
    _adopt_project_group.add_argument(
        "--adopt-project", action="store_true", default=False,
        help="v0.2.46 (adopt mode): treat this directory as an existing "
             "3rd-party project being adopted by VCO. Preserve pre-existing "
             "files (CLAUDE.md, .env, .claude/settings.json, .venv) by hash "
             "and land VCO defaults as .vco-new siblings + UPDATE_DEFERRED "
             "entries. Skip the interactive detection prompt.")
    _adopt_project_group.add_argument(
        "--no-adopt-project", action="store_true", default=False,
        help="v0.2.46 (adopt mode): explicitly refuse adopt mode. If "
             "detection heuristic would otherwise prompt, exit non-zero "
             "instead. Useful for CI that must never adopt unknown trees.")
    _adopt_project_group.add_argument(
        "--adopt-project-replace-all", action="store_true", default=False,
        help="v0.2.46 (adopt mode, advanced): aggressive variant of "
             "--adopt-project — overwrite pre-existing whitelist files "
             "instead of preserving them. Use only when you want VCO's "
             "defaults to land identically to a fresh install.")
    _adopt_project_group.add_argument(
        "--adopt-project-dry-run", action="store_true", default=False,
        help="v0.2.46 (adopt mode): print intended adopt actions and exit "
             "without touching any file. Useful to preview what adopt mode "
             "would do before committing to it.")

    args = parser.parse_args()

    # VCT_NON_INTERACTIVE env var: install.ps1 (line ~97) documents that
    # this env var should trigger non-interactive mode, but install.py
    # never honored it — only --yes / --quiet / non-TTY did. The .bat ->
    # .ps1 -> .py chain sets the env var as a fallback when args don't
    # propagate cleanly; lift it into args.yes here so all downstream
    # gates (args.yes checks) see a consistent state.
    if not args.yes and os.environ.get("VCT_NON_INTERACTIVE"):
        args.yes = True

    # v0.2.6 Bug C1 — `--desktop-icon-only` short-circuits: run JUST the
    # icon step (post-install-launcher.sh) and exit. Skips Python version
    # checks, venv creation, etc. because the user already has a working
    # install and just wants the icon now.
    if getattr(args, "desktop_icon_only", False):
        _run_desktop_icon_step(args)
        return 0

    # Deferral report — accumulates non-auto-resolvable conditions detected
    # during this run; written to .claude/context/UPDATE_DEFERRED.md at end.
    # Using a distinct name to avoid shadowing the conflict-resolve `report`
    # local below.
    _deferral_report = DeferralReport()

    # HIGH-2 fix (2026-05-01): deferral file lands in the user-project folder
    # when --project-folder is passed. Default = PROJECT_ROOT preserves the
    # orchestrator self-update behaviour. Resolved HERE (not just before the
    # final write) because the A-2 seed below needs it.
    _deferral_folder = (
        Path(args.project_folder)
        if getattr(args, "project_folder", None)
        else PROJECT_ROOT
    )

    # A-2 (v0.2.73): seed the run's report FROM DISK so the end-of-run write
    # cannot clobber entries other writer families persisted (project_init,
    # Rust emitters, background resync children). Only FOREIGN entries are
    # merged — condition IDs install.py OWNS (re-detects every run) keep
    # their drop-when-absent self-cleaning semantics. Soft-fail: a seed
    # failure degrades to the pre-A-2 behaviour, never blocks the install.
    try:
        _seeded = _deferral_report.merge_from_disk(
            _deferral_folder,
            exclude_ids=_INSTALL_OWNED_CONDITION_IDS,
            exclude_prefixes=_INSTALL_OWNED_CONDITION_PREFIXES,
        )
        if _seeded:
            _log_install_event(
                "deferral_report", "ok",
                f"preserved {_seeded} foreign deferral entr"
                f"{'y' if _seeded == 1 else 'ies'} from disk (A-2 seed)",
            )
    except Exception as exc:  # noqa: BLE001 — seeding is best-effort
        _log_install_event(
            "deferral_report", "warn",
            f"A-2 disk seed failed: {exc}",
        )

    # PR-11: warn early when global lean-ctx hooks are present in
    # ~/.claude/settings.json or ~/.claude/hooks/. These caused two
    # fork-bomb incidents (2026-04-30, 2026-05-15) before VCO 0.2.11.
    # Run BEFORE any compose-up or hook installation so the user sees
    # the warning even if other parts of install fail.
    if not getattr(args, "suppress_lean_ctx_warning", False):
        _check_global_lean_ctx_hooks(_deferral_report)

    # Windows install gate: refuse install when PowerShell 5.1+ isn't on
    # PATH (the .ps1 hooks would have nothing to run them). Non-Windows
    # hosts are a silent no-op. See audit F1 (P0).
    _check_windows_shell_prereqs()

    # Run conflict-resolution copy step BEFORE the rest of install.py so
    # subsequent steps see the post-resolution file tree. Best-effort
    # logging — the install log dir may not exist yet, in which case
    # _log_install_event() silently skips (matches Rust contract).
    if args.conflict_strategy:
        if not args.conflict_source_path:
            print("ERROR: --conflict-strategy requires --conflict-source-path")
            return 2
        try:
            report = apply_conflict_strategy(
                source=Path(args.conflict_source_path),
                install_path=PROJECT_ROOT,
                strategy=_normalize_conflict_strategy(args.conflict_strategy),
                preserve_paths=_parse_preserve_paths(args.preserve_paths),
            )
        except Exception as e:
            print(f"ERROR: conflict-resolve failed: {e}")
            _log_install_event(
                "conflict-resolve", "error",
                f"strategy={args.conflict_strategy}: {e}",
                data={"strategy": args.conflict_strategy},
            )
            return 1
        _log_install_event(
            "conflict-resolve", "ok",
            f"strategy={args.conflict_strategy}",
            data=report,
        )

    if args.uninstall:
        return _run_uninstall(args)

    # Deliverable 3 (2026-04-28): lightweight re-install path. The
    # launcher passes --lightweight when re-running over a healthy
    # install (matching state hashes, present .venv). Skips model
    # pulls, Weaviate seed, full GPU detection — completes in seconds
    # instead of minutes.
    if args.lightweight:
        return _run_lightweight(args)

    mode = "update" if args.update else "install"

    # v0.2.46 Part 2 (V47-G-final): resolve --adopt-project-* mode and dispatch
    # the early-exit cases (no-adopt / dry-run) before any work runs.
    # Wave-2 agents (V47-A through V47-F) read this same value from `args`
    # via `_resolve_adopt_project_mode(args)` inside their gap-specific
    # functions. V47-G-final's detection heuristic + interactive prompt fires
    # here when no explicit flag is set AND PROJECT_ROOT shows existing-
    # project signals (CLAUDE.md, .env, .venv/, .claude/, knowledge/).
    adopt_project_mode = _resolve_adopt_project_mode(args, install_path=PROJECT_ROOT)
    if adopt_project_mode == "no-adopt":
        print(
            "Adopt-project mode explicitly refused via --no-adopt-project. "
            "Exiting without making changes."
        )
        return 1
    if adopt_project_mode == "dry-run":
        # V47-G-final: print the full intended action manifest (which files
        # would be preserved, what symlinks would be skipped, which secrets
        # would be flagged, etc.). One section per Gap A-F.
        _print_adopt_dry_run_manifest(PROJECT_ROOT)
        return 0

    # v0.2.46 V47-C (Gap C): detect secret-shaped keys in `.env` and
    # offer to migrate them to the OS keychain. Runs BEFORE the install
    # work starts so the deferral entries land in the same UPDATE_DEFERRED
    # write the rest of main() emits. Soft-fail by design — never blocks
    # the install. See _audit_and_offer_env_secret_migration's docstring
    # for the behaviour matrix.
    _audit_and_offer_env_secret_migration(
        PROJECT_ROOT, _deferral_report, adopt_project_mode, args,
    )

    # Fix 1 (v0.2.13): mark this run's start timestamp so
    # _refresh_dist_binary_after_rebuild can tell "produced this run" apart
    # from "stale from weeks ago".
    global _INSTALL_START_TS
    _INSTALL_START_TS = time.time()

    # Configure resume-from-log behaviour. Loaded BEFORE any step runs so
    # individual step functions can consult _should_skip_step(). The log
    # is at state/logs/install.jsonl — only present once Step 8 has run
    # at least once (i.e. on second+ install attempts on this checkout).
    global _RESUME_ENABLED, _RESUME_STATE
    _RESUME_ENABLED = not args.no_resume
    _RESUME_STATE = _load_resume_state() if _RESUME_ENABLED else {}

    print()
    print("=" * 62)
    if mode == "update":
        print("  VibeCoded Tools — Orchestrator Updater")
    else:
        print("  VibeCoded Tools — Orchestrator Installer")
    print("=" * 62)
    print()

    # V52-AI (v0.2.52) MCP fork-bomb mitigation + A-6 deadline refreshes.
    # Choreography lives in vco_lib.install_update_gate (P2c-a, v0.2.75):
    # begin() writes the lockfile + arms the atexit delete on --update
    # (no-op on fresh installs); the gate.refresh(phase) call sites below
    # re-extend the 15-min deadline at each long phase boundary and
    # RE-CREATE an absent lockfile mid-update (P3a rider).
    _update_gate_flow = InstallUpdateGate(mode)
    _update_gate_flow.begin()

    # Mark the start of this install session in the durable log. Subsequent
    # events from install.py + post-install-launcher.sh share the same log.
    # On a first-ever install the log dir doesn't exist yet (Step 8 creates
    # it) so this is a no-op until later — fine: 1/10 is also re-emitted
    # as part of _check_python_version().
    _log_install_event(
        "session", "start",
        f"install.py {mode} mode",
        data={"mode": mode, "resume_enabled": _RESUME_ENABLED,
              "argv": sys.argv[1:]},
    )

    # Step 1: Check Python
    _check_python_version()
    _check_prerequisites()

    # Step 2: Detect system
    sysinfo = _detect_system(args)
    _print_system_info(sysinfo)

    # Step 2b: Optional companion tools (lean-ctx for context compression)
    _detect_optional_companions(args)

    # Step 3: Determine embedding configuration
    embed_config = _choose_embedding_config(sysinfo, args)
    # v0.2.50 portability fix (audit F1, 2026-06-08): stash the resolved
    # GPU vendor on embed_config so `_write_env_config` can pick the right
    # CODE_EMBED_DOCKERFILE variant for the code-embed image build.
    # NVIDIA hosts → Dockerfile.cuda. Anyone else (AMD ROCm / Apple
    # Silicon / CPU-only / unknown) → default Dockerfile (CPU multi-arch).
    embed_config["gpu_vendor"] = sysinfo.gpu_vendor or ""
    # v0.2.61 (stale-embedding reconcile): if a stale ACTIVE_EMBEDDING=qwen3
    # was inherited from the env / an OLD settings.json on hardware whose
    # selector picked arctic (and no deliberate user choice exists), rewrite
    # os.environ so every downstream reader (the seed-subprocess resolver +
    # the .env / settings.json / env-template writers) uses the hardware
    # model instead of re-cementing the value that times out KG sync on CPU.
    _reconcile_install_active_embedding(embed_config, args)
    print(f"\n  Embedding mode: {embed_config['description']}")

    # Step 3b (PR-28, Group G, v0.2.12): storage-location prompt. Runs
    # BEFORE the container-runtime detection so a user with 110 GB of
    # legacy Ollama models doesn't end up with empty named volumes after
    # `_start_services`. Silently skipped on --quiet / --yes / non-TTY
    # stdin / when no legacy data is detected. Result persisted via the
    # launcher binary CLI (preferred) or a direct Python write of
    # ~/.vct/storage.toml (fallback). See
    # `.claude/context/volume-binding-fix-2026-05-16.md` for the silent-
    # data-loss footgun this closes.
    _storage_choice = _prompt_storage_location(PROJECT_ROOT, args)
    if _storage_choice.get("mode") != "deferred":
        _persist_storage_choice(_storage_choice, PROJECT_ROOT)
        _record_install_choice(
            "storage_mode", _storage_choice["mode"],
            {"bind_paths": list((_storage_choice.get("bind_paths") or {}).keys())},
        )

    # Step 4: Create virtual environment
    venv_python = _create_venv(PROJECT_ROOT)

    # Step 5: Install/update Python dependencies
    _install_requirements(venv_python, dev=args.dev)

    # Step 5b: Materialize orchestrator-self .claude/ from templates.
    # PR-39 (v0.2.12): the public repo no longer ships .claude/{hooks,
    # scripts,settings.json}; install.py renders them from templates/ at
    # install time (and on every --update). Runs AFTER _install_requirements
    # so any Python scripts can use the venv, and BEFORE _seed_weaviate so
    # the orchestrator's KG-sync hooks are in place when seeding runs.
    if not getattr(args, "skip_materialize_claude_dir", False):
        _materialize_orchestrator_self_claude_dir(
            PROJECT_ROOT,
            deferral_report=_deferral_report,
            force_overwrite=getattr(
                args, "force_materialize_claude_dir", False,
            ),
        )
    else:
        _log_install_event(
            "4b/10", "skip",
            "--skip-materialize-claude-dir set; .claude/ left untouched",
        )

    # Step 5c (v0.2.54 S-3): agent-facing secrets-schema doc. Only-if-
    # missing, so user edits survive every --update.
    _materialize_vct_secrets_shared_readme(PROJECT_ROOT)

    # V0243-5: emit VCT_ORCHESTRATOR_ROOT + VCT_INFRASTRUCTURE_DIR + KG_BASE_DIR
    # to .claude/env managed block. Done unconditionally on orchestrator-root
    # installs so the 3 portability keys are always present regardless of
    # whether launcher.db exists yet (pre-first-boot fresh installs).
    if _is_orchestrator_root_install():
        _emit_orchestrator_root_env_keys(PROJECT_ROOT)

    # Gap E (v0.2.46): inform the user about project-owned compose files so
    # they know VCO detected — and will not touch — their containers.
    if foreign := _scan_foreign_compose_files(PROJECT_ROOT):
        print(f"[i] Detected {len(foreign)} non-VCO compose file(s) — leaving alone:")
        for p in foreign:
            print(f"    {p}")
        print()
        _log_install_event(
            "foreign_compose_scan", "info",
            f"detected {len(foreign)} non-VCO compose file(s): "
            + ", ".join(str(p) for p in foreign),
        )

    # Step 6: Container services (restart on update to pick up config changes)
    if not args.no_containers:
        if not sysinfo.container_cmd:
            # OS-aware prompt: Linux can auto-install via apt/dnf/pacman;
            # macOS/Windows print URLs only (Homebrew/winget+WSL2 require
            # user-driven setup we won't shoulder).
            installed = _prompt_install_container_runtime(args)
            if installed:
                # Re-detect after user-confirmed install. PATH may already
                # contain the new binary in this Python process.
                sysinfo = sysinfo._replace(container_cmd=_detect_container_runtime())
                # v0.2.10 (Bug L3): the post-prompt-install path now refreshes
                # runtime.txt immediately so a single install run captures
                # the new runtime for the wrapper script (don't wait for the
                # later _write_install_manifest call — boot services
                # materialized later in the same run may read it before then).
                _persist_runtime_txt(sysinfo.container_cmd)
            if not sysinfo.container_cmd:
                # Either the user declined, the package manager failed,
                # or we're on macOS/Windows (URL-only path). Fall through
                # to a clear exit with --no-containers escape hatch.
                print("\n    Or re-run with --no-containers to skip.")
                return 1

        # Deliverable 2 (2026-04-28): persist the resolved runtime so
        # re-installs don't re-prompt. This fires AFTER any optional
        # install prompt so we capture the final value.
        _record_install_choice(
            "container_runtime", sysinfo.container_cmd or "none",
            {"reason": "post-detection (incl. prompt-install if any)"},
        )

        # Step 5b: probe BEFORE compose up. Honors content-based detection
        # and persists the resolution in ~/.vct/services.toml. Foreign
        # services on the canonical port either get an alt-port (default)
        # or, with explicit consent, are adopted in place. We never POST
        # collections into a service we didn't start.
        decisions = _resolve_service_safety(args)
        if any(d["action"] == ACTION_ABORT for d in decisions.values()):
            for name, d in decisions.items():
                if d["action"] == ACTION_ABORT:
                    print(f"  [{name}] aborted: {d['evidence']}")
            return 1

        _start_services(sysinfo, args, embed_config, decisions,
                        deferral_report=_deferral_report)
        if not args.skip_models:
            _wait_for_ollama()
            # v0.2.49 Bug I: pass the canonical embedding-model set so
            # _pull_ollama_models can fail-fast on load-bearing pulls
            # rather than silently continuing with a broken KG.
            _embedding_models_set: set[str] = {
                m for m in (embed_config.get("embedding_models") or [])
                if isinstance(m, str) and m
            }
            _pull_ollama_models(
                _build_ollama_pull_list(embed_config, sysinfo),
                embedding_models=_embedding_models_set,
            )
            # v0.2.49 Bug J: probe for dual Ollama instances now that
            # the launcher-managed one is known to be up; emit an
            # UPDATE_DEFERRED warning if a personal instance is also
            # responding so the user sees the divergence post-install.
            _emit_dual_ollama_deferral(_deferral_report)

        # A-6 rider (P3a, v0.2.75): venv/container/model-pull phase done —
        # re-extend the update-gate deadline before the collections/seed
        # phase. Pre-rider the FIRST refresh only fired after the seed, so
        # the initial 15-min window had to cover venv rebuild + container
        # start + multi-GB Ollama pulls + the seed in one stretch.
        _update_gate_flow.refresh("install_py")

        # Bug 29: with shared-container reuse, multiple installs hit the same
        # Weaviate. Bootstrap any of THIS project's KG/Development collections
        # that aren't there yet — leave existing ones alone.
        #
        # Pollution guarantee: collection writes only happen when the user
        # consented. The matrix:
        #   - ACTION_START / ACTION_ALT_PORT (we run our own Weaviate)
        #     ⇒ writes to our instance
        #   - ACTION_ADOPT vct-managed (prior install of ours)
        #     ⇒ writes to a Weaviate we already populated
        #   - ACTION_ADOPT foreign (user typed "2" / passed
        #     --on-conflict adopt)
        #     ⇒ writes to user-owned Weaviate WITH EXPLICIT CONSENT
        # No path writes without consent. The default for foreign is
        # alt-port, so the no-consent case never hits ACTION_ADOPT.
        # Schema-rebuild gate (--update only): if the running KG
        # collection is on an older schema lacking today's invariants
        # (named-vector slots, index_null_state, etc.), prompt to drop
        # + recreate. User-driven decision; defaults to deferring on
        # non-interactive shells without --yes. ONLY touches Weaviate
        # state — sources, env, settings stay intact. After drop,
        # _ensure_collections recreates with the fresh schema and
        # _seed_weaviate re-ingests from sources.
        # Track whether migrate_collections performed a "rebuild" action this
        # run. If so AND a later step (ensure/seed) crashes, the deferral
        # entry must signal "rebuild_pending_seed" so the operator knows the
        # collection was dropped and is awaiting re-seed (HIGH-4).
        _rebuild_was_performed = False

        if _maybe_prompt_rebuild_collections(args, deferral_report=_deferral_report):
            # PR 3: smart per-collection dispatch (copy-with-vectors etc.)
            # replaces the old drop-and-re-embed default. --force-rebuild
            # is the escape hatch back to today's behaviour.
            if getattr(args, "force_rebuild", False):
                _rebuild_collections(args)
                _rebuild_was_performed = True
            else:
                # HIGH-1 fix (2026-05-01): capture migrate_collections result
                # and emit a per-collection deferral entry for every entry in
                # result["errors"]. Previously the dict was discarded silently.
                _migrate_result = _project_init.migrate_collections(
                    args,
                    dry_run=getattr(args, "migrate_dry_run", False),
                    log_event=_log_install_event,
                )
                if _migrate_result and not _migrate_result.get("dry_run", False):
                    if any(
                        entry.get("action") == "rebuild"
                        for entry in _migrate_result.get("plan", [])
                    ):
                        _rebuild_was_performed = True
                    for err in _migrate_result.get("errors", []) or []:
                        _err_collection = err.get("collection") or "unknown"
                        _err_action = err.get("action") or "unknown"
                        _err_msg = err.get("error") or "(no error message)"
                        # condition_id includes the collection name so multiple
                        # failures across collections do NOT deduplicate.
                        _deferral_report.add_entry(
                            DeferralEntry(
                                condition_id=(
                                    f"migrate_collections_partial_failure_"
                                    f"{_err_collection}"
                                ),
                                title=(
                                    f"Schema migration failed for "
                                    f"`{_err_collection}`"
                                ),
                                detected=(
                                    f"Action `{_err_action}` raised: {_err_msg}"
                                ),
                                why_deferred=(
                                    "Migration partial failure leaves the "
                                    "collection in an inconsistent state; "
                                    "manual recovery required."
                                ),
                                command_to_apply=(
                                    "python install.py --update "
                                    "--rebuild-collections --force-rebuild "
                                    "(last-resort drop+re-embed) OR see logs at "
                                    "state/logs/install.jsonl stage 7b.<action>"
                                ),
                                severity="critical",
                                kg_node_refs=[
                                    ".claude/context/"
                                    "weaviate-schema-port-research-2026-05-01.md",
                                ],
                            )
                        )

        # v0.2.18 Commit 10: seed the launcher's app_state with the
        # default text/code embedding-model IDs derived from this
        # install's preset. Idempotent (INSERT OR IGNORE-style ON
        # CONFLICT DO NOTHING) — preserves any user selections from
        # prior launcher sessions. Soft-fails when launcher.db is
        # absent (fresh first-install, launcher never booted) or the
        # app_state table hasn't been migrated yet. Runs BEFORE
        # _seed_weaviate so a Weaviate-down condition does not also
        # block the GUI dropdowns from being pre-populated; runs
        # OUTSIDE the seed try/except for the same reason.
        try:
            _write_preset_defaults_to_app_state(
                embed_config,
                openai_set_as_default=bool(embed_config.get("openai_key")),
            )
        except Exception as _preset_err:  # noqa: BLE001 — never block install
            # Defense-in-depth: the helper already soft-fails on every
            # known sqlite error, but if something else explodes
            # (network filesystem flake, ENOSPC, etc.) we still must
            # not crash the install.
            _log_install_event(
                "preset_defaults", "warn",
                f"unexpected error writing preset defaults: {_preset_err}",
            )

        # v0.2.52 V52-AD — seed the host-wide RL reranker disable row
        # when no training data has accumulated yet. Soft-fails on every
        # known sqlite error (missing DB, missing table, pre-034 schema,
        # existing user choice). Idempotent across re-runs.
        try:
            _seed_rl_reranker_default_disabled()
        except Exception as _rl_default_err:  # noqa: BLE001
            _log_install_event(
                "rl_reranker_default", "warn",
                f"unexpected error seeding RL reranker default: "
                f"{_rl_default_err}",
            )

        # PR 6 + MEDIUM-9 + HIGH-4 fix (2026-05-01): wrap _ensure_collections
        # AND _seed_weaviate in the same try/except so Weaviate-down conditions
        # emit a deferral entry instead of crashing the install. Includes a
        # podman-restart soft-recovery attempt. If a rebuild action dropped a
        # collection earlier this run AND seed/ensure later crashes, the
        # deferral entry includes `rebuild_pending_seed` so the operator knows
        # what was lost.
        _seed_succeeded = False
        try:
            _ensure_collections(embed_config, decisions=decisions, args=args)
            # Seed Weaviate with bundled knowledge/ + docs/. Idempotent;
            # safe to re-run on update.
            _seed_weaviate(args)
            _seed_succeeded = True
        except Exception as _weaviate_err:
            # PR 6: Weaviate is unreachable (or refused connection) after the
            # containers were started. Attempt a soft-recovery restart
            # via podman before emitting a deferral.
            _weaviate_down_msg = str(_weaviate_err)
            _restarted = False
            # Discover the actual Weaviate container name + runtime on
            # this host. v0.2.15: stopped hardcoding `weaviate_claude`
            # (maintainer-machine leak) AND stopped hardcoding `podman`
            # in the recovery hints (docker-only users got useless
            # advice). Runtime honors VCT_CONTAINER_RUNTIME with
            # podman→docker fallback per the install.py contract.
            from vco_lib.containers import (
                all_known_names as _all_known_names,
                find_existing_container as _find_existing_container,
            )
            _self_heal_runtime = (
                _detect_container_runtime()
                or _runtime_preference_from_env()
                or "podman"  # last-resort label when neither is on PATH
            )
            _weaviate_container = (
                _find_existing_container("weaviate", runtime=_self_heal_runtime)
                or "vco_weaviate"  # nothing on host yet — name the canonical
            )
            try:
                subprocess.run(
                    [_self_heal_runtime, "start", _weaviate_container],
                    capture_output=True, timeout=30,
                )
                import time as _time
                _time.sleep(3)  # brief settle
                _ensure_collections(embed_config, decisions=decisions, args=args)
                _seed_weaviate(args)
                _restarted = True
                _seed_succeeded = True
            except Exception:
                pass
            if not _restarted:
                # Build a user-facing "which name to use" hint. If we
                # found one on the host, name it. Otherwise list all the
                # candidates so the user can try whichever they have.
                _candidates_hint = (
                    _weaviate_container
                    if _find_existing_container("weaviate", runtime=_self_heal_runtime)
                    else " | ".join(_all_known_names("weaviate"))
                )
                print(
                    f"WARNING: Weaviate unreachable after restart attempt "
                    f"({_weaviate_down_msg}). Collections not bootstrapped. "
                    "Deferral entry written."
                )
                _deferral_report.add_entry(
                    DeferralEntry(
                        condition_id="weaviate_unreachable_at_update",
                        title="Weaviate unreachable at update",
                        detected=(
                            f"Weaviate refused connection during --update "
                            f"({_weaviate_down_msg}). Auto-restart via "
                            f"`{_self_heal_runtime} start {_weaviate_container}` also failed."
                        ),
                        why_deferred=(
                            "Collection bootstrap and schema migration require "
                            "a live Weaviate. Cannot proceed without it."
                        ),
                        command_to_apply=(
                            f"{_self_heal_runtime} start {_candidates_hint} && "
                            "python install.py --update --skip-rebuild-prompt"
                        ),
                        severity="critical",
                        kg_node_refs=[],
                    )
                )
                # HIGH-4: if a rebuild action dropped collections this run,
                # warn the operator that the collection is GONE and needs
                # re-seed once Weaviate is back.
                if _rebuild_was_performed:
                    _deferral_report.add_entry(
                        DeferralEntry(
                            condition_id="rebuild_pending_seed",
                            title="Rebuild dropped collections; seed pending",
                            detected=(
                                "A `rebuild` action dropped one or more "
                                "collections during this run, and a "
                                "subsequent ensure/seed step crashed before "
                                "the collections could be recreated and "
                                "re-ingested. See `state/logs/install.jsonl` "
                                "stage `7b.rebuild snapshot` for the per-"
                                "collection object count + sample UUIDs that "
                                "were present immediately before the drop."
                            ),
                            why_deferred=(
                                "Cannot recreate + re-ingest without a live "
                                "Weaviate. The .md sources in knowledge/ + "
                                "docs/ are intact and will be re-ingested by "
                                "the next install.py --update run."
                            ),
                            command_to_apply=(
                                f"{_self_heal_runtime} start {_candidates_hint} && "
                                "python install.py --update "
                                "--skip-rebuild-prompt"
                            ),
                            severity="critical",
                            kg_node_refs=[
                                ".claude/context/"
                                "weaviate-schema-port-research-2026-05-01.md",
                            ],
                        )
                    )

        # A-6: seed/collections phase done — re-extend the update-gate
        # deadline before the schema-migration + resync + binary-refresh
        # tail (Ollama pulls during seed are a common 15-min-blower).
        _update_gate_flow.refresh("install_py")

        # PR-24 (v0.2.12, 2026-05-16): schema-correctness migrations.
        # Run AFTER _seed_weaviate so the collections exist before we
        # attempt additive patches. Both scripts are idempotent and
        # soft-fail; failures convert to deferral entries.
        if _seed_succeeded:
            _run_schema_migration_scripts(_deferral_report)

        # v0.2.72 (P7): revision-gated code-graph resync. After the additive
        # `embed_revision` schema migration ran (above, inside
        # analyze_code_graph's create_collections on the next analyze), trigger a
        # BACKGROUND full re-analyze so the ~7-9% of over-budget Function/Class
        # rows that P3 chunking invalidated get re-embedded into chunks. The
        # revision gate makes this LIGHT (rows already at the current revision
        # hash-skip). Non-blocking (background Popen), no global timeout, and it
        # degrades to a deferral when the code-embed service (:11440) is down.
        # Only on --update: a fresh install analyzes at the current revision
        # already, so there are no stale rows to resync. Thin shim → the logic
        # lives in vco_lib.codegraph_resync (install.py is a mega-file).
        # R-6 (v0.2.73): inside the helper, the trigger is additionally gated
        # on the owed-probe (count of rows at a stale/NULL embed revision) —
        # it fires only when work is actually owed, and a POSITIVE zero
        # resolves the pending resync deferral instead of spawning.
        if _seed_succeeded and getattr(args, "update", False):
            _trigger_codegraph_embed_resync(_deferral_report)

        # PR-34 (v0.2.12, Group M): detect the pre-rename shared-KG class
        # left over from a pre-v0.2.12 install. Emit a deferral pointing
        # at the launcher's "Manage shared KG collection" picker — we
        # NEVER auto-rename or auto-drop the class (destructive; picker
        # is the consent mechanism).
        if mode == "update":
            _detect_legacy_shared_kg_class(_deferral_report)
            # v0.2.23 B1 (2026-05-21): case-mismatch self-heal for
            # `project_kg_bindings` rows. Auto-applied (safe — only
            # rewrites a binding row whose target class ALREADY EXISTS
            # in Weaviate by a different casing). Emits an informational
            # deferral entry per heal so the user sees what we changed.
            _self_heal_kg_bindings_on_update(_deferral_report)
            # V0243-13: on orchestrator-root, emit deferred-action entries
            # for known schema drift that requires explicit consent to fix.
            if _is_orchestrator_root_install():
                _emit_orchestrator_root_schema_deferrals(_deferral_report)
    else:
        print("\n[skip] Container services (--no-containers)")
        print("[skip] Weaviate seeding (--no-containers)")

    # Step 7: Create state directory
    _create_state_directory()

    # Step 8: Write .env configuration (skip on update — don't overwrite user changes)
    if mode == "install":
        _write_env_config(embed_config, args)
    else:
        print("[skip] .env configuration (preserved during update)")
        # v0.2.46 V47-F (Gap F): informational log when PROJECT_NAME differs
        # from folder-name derivation. Pure visibility — the existing project
        # KEEPS whatever PROJECT_NAME it already has (non-destructive rule).
        # Helps surface pre-V47-F installs that pinned a non-canonical
        # project name while sitting in a folder like "python/".
        _log_project_name_pin_diff(PROJECT_ROOT, "")
        # A3 (2026-05-28): reconcile any canonical env keys added since the
        # user's original install. Additive-only: user-set values preserved,
        # only missing keys are appended.
        _env_file = PROJECT_ROOT / ".env"
        _reconcile_result = _reconcile_env_keys(_env_file)
        if _reconcile_result["action"] == "appended":
            _added_keys = _reconcile_result["added"]
            print(
                f"  .env: added {len(_added_keys)} new env key(s): "
                + ", ".join(_added_keys)
            )
            _log_install_event(
                "9/10", "info",
                f"_reconcile_env_keys: added {len(_added_keys)} key(s)",
                data={"added": _added_keys, "env_file": str(_env_file)},
            )
        elif _reconcile_result["action"] == "noop":
            _log_install_event(
                "9/10", "info",
                "_reconcile_env_keys: no missing keys (noop)",
                data={"env_file": str(_env_file)},
            )

    # Step 9: Configure Claude Code settings (skip on update)
    if mode == "install":
        # v0.2.46 V47-A (Gap A): thread the run-scoped DeferralReport so the
        # managed-block merge can emit `claude_settings_user_modified_preserved`
        # and `claude_settings_unparseable` entries when it leaves the file
        # alone.
        _configure_claude_settings(embed_config,
                                   adopt_project_mode=adopt_project_mode,
                                   deferral_report=_deferral_report)
    else:
        print("[skip] Claude settings (preserved during update)")
        # 0.2.11 / PR-1: pre-0.2.11 installs wired BASH_ENV in
        # .claude/settings.json to the lean-ctx shim, which became
        # fork-bomb-prone on lean-ctx 3.x. Idempotently strip that key +
        # disable the shim file so an upgraded orchestrator clone
        # doesn't carry the legacy fuse alive. Fresh installs never see
        # this code path (`mode == "install"` above).
        _cleanup_legacy_bash_env_shim(args)

        # Phase 0.B Part 2 (2026-05-25): a single call to
        # `_backfill_code_graph_project_env` (now backed by the Python
        # `vco_lib.config_projection.apply_project_env` contract) projects
        # the FULL canonical env (KG_COLLECTION, DEVELOPMENT_COLLECTION,
        # SHARED_KG_COLLECTION, PROJECT_NAME, CODE_GRAPH_PROJECT,
        # ACTIVE_EMBEDDING, service URLs/ports, access lists) — replacing
        # the historical two-step (PR-7 PROJECT_NAME+CODE_GRAPH backfill
        # plus v0.2.28 KG_COLLECTION+SHARED+DEV backfill). The contract
        # reads launcher.db directly; any per-key drift between disk and
        # DB is corrected on every `--update` pass.
        _backfill_result = _backfill_code_graph_project_env()
        if _backfill_result["action"] == "applied":
            print(
                f"  Claude settings: projected {len(_backfill_result['added_keys'])} "
                f"canonical env key(s) from launcher.db: "
                f"{', '.join(_backfill_result['added_keys'])}"
            )
        elif _backfill_result["action"] == "db_unreachable":
            # Fresh install, pre-launcher-boot: launcher.db doesn't exist
            # yet. The first `vct add-project` will create it + project
            # rows; subsequent --update runs will project the env then.
            pass
        elif _backfill_result["action"] == "orchestrator_not_registered":
            # Launcher running, but the orchestrator-root row isn't in
            # `projects` yet (race with launcher startup). The launcher's
            # auto-register-orchestrator-root path will catch up.
            pass
        _log_install_event(
            "9/10", "info",
            f"_backfill_code_graph_project_env action={_backfill_result['action']}",
            data=_backfill_result,
        )

        # PR-22 (v0.2.12, 2026-05-16): rename legacy
        # `docker-compose.override.yml` to `compose.override.yaml` so
        # podman-compose's auto-loader recognizes it. PR-10A (v0.2.11)
        # shipped writing the wrong filename; on `--update` from
        # v0.2.11 we migrate the file in place + emit a deferral entry.
        # No-op on fresh installs and on already-migrated trees. Soft-fail:
        # surfaces failures via deferral entries, never raises.
        try:
            from vco_lib.project_init import _detect_and_rename_legacy_compose_override
            _override_rename = _detect_and_rename_legacy_compose_override(PROJECT_ROOT)
            if _override_rename is not None:
                print(
                    f"  compose override rename: action="
                    f"{_override_rename['action']}, "
                    f"renamed={len(_override_rename['renamed'])}, "
                    f"conflicts={len(_override_rename['conflicts'])}, "
                    f"errors={len(_override_rename['errors'])}"
                )
            _log_install_event(
                "9/10", "info",
                "_detect_and_rename_legacy_compose_override "
                f"result={_override_rename!r}",
                data=_override_rename or {"action": "noop"},
            )
        except Exception as _override_exc:  # pragma: no cover — defensive
            # Soft-fail: don't let this stop the install.
            _override_err = f"{type(_override_exc).__name__}: {_override_exc}"
            print(
                f"  compose override rename: skipped due to error "
                f"({_override_err})"
            )
            _log_install_event(
                "9/10", "warn",
                f"_detect_and_rename_legacy_compose_override failed: "
                f"{_override_err}",
                data={"error": _override_err},
            )

    # PR-7 / addendum-4 (v0.2.11): .vscode/settings.json watcher/search/
    # Pylance exclude backfill. Runs on BOTH install and update paths:
    #   - Fresh install: creates `.vscode/settings.json` with the canonical
    #     exclude block (the existing `.vscode/settings.json.example` is
    #     templated for the `claude-code.env` block, which the launcher
    #     writes on registration — the excludes are an orthogonal concern).
    #   - Update: adds missing exclude keys only; user-set values
    #     preserved verbatim (user-wins).
    _vscode_excludes_result = _backfill_vscode_excludes()
    if _vscode_excludes_result["action"] in ("created", "backfilled"):
        print(
            f"  VS Code excludes: {_vscode_excludes_result['action']} "
            f"({len(_vscode_excludes_result['added_keys'])} key(s))"
        )
    _log_install_event(
        "9/10", "info",
        f"_backfill_vscode_excludes action={_vscode_excludes_result['action']}",
        data=_vscode_excludes_result,
    )

    # Step 9b: Install agents and skills from templates/
    # v0.2.70 FIX-3 (secondary): thread the live deferral report so symlinked
    # .claude/agents | .claude/skills targets emit a deferral (previously this
    # call passed no report -> the 5 emit_symlink_deferral calls were
    # guarded-out and a symlinked agents/skills dir redirected SILENTLY).
    _install_agents_and_skills(args, deferral_report=_deferral_report)

    # Step 10: Check Claude CLI
    _check_claude_cli()

    # Cache Playwright MCP + Chromium so the default-enabled `playwright`
    # MCP entry doesn't stall on first browser-launch with a 150 MB
    # download. Non-fatal: failures here only warn, since the MCP can
    # still lazy-install on first call.
    _install_playwright_browsers()

    # Phase 1.2 (diagrams plan): pre-pin the `claude-mermaid` npm
    # package at the version declared in `bundled_mcp_versions.toml`
    # so the first Mermaid invocation doesn't pay the cold-install
    # cost. Default-disabled per project (see BUNDLED_MCP_DEFAULT_
    # DISABLED in vct-launcher-core); pre-installing here means
    # opt-in is one click in the launcher, not a 30 s wait.
    # Opt-out: VCT_SKIP_MERMAID=1.
    # Non-fatal: returns False on skip / npm missing / pin mismatch;
    # the wrapper MCP still lazy-installs via `npx -y` when first
    # invoked, so the path is graceful.
    _install_pinned_npm("mermaid_mcp", skip_env_var="VCT_SKIP_MERMAID")

    # Phase 2 (diagrams plan): pre-pin the vendored Excalidraw MCP
    # (see `bundled_mcp_versions.toml::[npm.excalidraw_mcp]`). The pin
    # is a `file:` URL pointing at
    # `vco_lib/excalidraw_mcp_fork/` (moved from
    # `claude_mcp_servers/excalidraw_mcp_fork/` in v0.2.34 so the
    # vendored tree ships in the Python wheel); the install branch in
    # `_install_pinned_npm` calls `npm install -g <vendor-dir>` rather
    # than fetching from the registry. Default-disabled per project
    # (same posture as Mermaid). Opt-out: VCT_SKIP_EXCALIDRAW=1.
    # Non-fatal: returns False on skip / npm missing / vendor missing;
    # the wrapper still works at runtime via `node <vendor-entry>`
    # because the wrapper spawns Node directly on the vendored path,
    # bypassing the global install entirely if it didn't land.
    _install_pinned_npm("excalidraw_mcp", skip_env_var="VCT_SKIP_EXCALIDRAW")

    # Step 11: Initial code graph analysis (if repo has code)
    # Skipped on first install — user runs manually after setup

    # Step 11b: Bytecode compilation. Pre-compile installed Python
    # modules to .pyc so first import doesn't pay per-module compile
    # cost (~50-200ms savings per cold module). Cross-OS: stdlib
    # `compileall` is identical on Linux/macOS/Windows.
    if args.compile_pyc:
        _compile_python_modules(venv_python)
    else:
        print("[skip] Bytecode compilation (--no-compile)")

    # Deliverable 2 (2026-04-28): snapshot the post-install state-hash
    # set (requirements.txt / Cargo.lock / package.json / knowledge/).
    # The next install run uses these to detect drift and choose
    # between full reinstall vs lightweight reinstall (Deliverable 3).
    _record_state_hashes(PROJECT_ROOT)

    # Done — mark the session complete in the durable log so the
    # launcher/Claude Code can tell at a glance that install.py reached
    # the end. (post-install-launcher.sh appends its own build/spawn
    # events after this returns.)
    # Note: 10/10 is logged inside _check_claude_cli() — the per-step
    # event captures the actual outcome. This event marks the *session*
    # closed cleanly, which is a separate signal the launcher uses to
    # decide whether the install completed start-to-end.
    _log_install_event("session", "ok", f"{mode} finished cleanly")

    # (_deferral_folder is resolved at the top of main(), next to the A-2
    # disk seed — see the HIGH-2 comment there.)

    # Apply pending deferrals if requested (--update --apply-deferred).
    if args.update and getattr(args, "apply_deferred", False):
        _apply_deferred_entries(_deferral_report, _deferral_folder, args=args)

    # A-11 (v0.2.73): the mid-run `_deferral_report.write()` that used to sit
    # here was REMOVED. With an empty in-memory report it unlinked the on-disk
    # file (and stripped the CLAUDE.md reminder) minutes before the final
    # write — a hard kill in that window lost every foreign entry with not
    # even a stub. Nothing between here and the final write reads the file
    # back (only `--apply-deferred` does, and it runs above), so the final
    # write at the end of main() is the ONLY writer. Fix 6 (v0.2.13) already
    # established the final write as the authoritative one.

    # Drop the install-manifest at state/install-manifest.json so the launcher
    # (and operators auditing an install) can verify install actually finished.
    # Earlier the launcher inferred "installed" from .venv/ presence, which
    # produced false positives on developer source checkouts that had a venv
    # but no install.py run (false-positive observed in wizard 2026-05-06).
    _write_install_manifest(sysinfo, args, install_method="install.py")

    # PR-14b (v0.2.11 MCP simplification): SearXNG no longer ships in the
    # default compose stack; Ollama MCP is dropped from the default install;
    # SEARXNG_URL + GITHUB_TOKEN are no longer needed in the search MCP env.
    # Surface deferral notices so existing users know to clean up manually.
    # Soft-fail: each helper catches its own errors; install completes even
    # if all three checks fail.
    if not getattr(args, "suppress_mcp_deprecation_warnings", False):
        _check_searxng_remnants(PROJECT_ROOT, _deferral_report)
        _check_ollama_mcp_remnants(_deferral_report)
        _check_search_mcp_env_obsolete(_deferral_report)

    # PR-23 (v0.2.12, 2026-05-16): register bundled MCP entries into
    # ~/.claude.json. Pre-PR-23 install.py performed ZERO MCP registration,
    # so fresh v0.2.11 installs left Claude Code with no orchestrator MCPs
    # wired at all. Soft-fail throughout — install must complete even when
    # MCP registration fully fails. See module docstring of `_register_mcps`
    # for the 4-tier launcher-binary resolution strategy and the
    # security-boundary rationale for the env-key allowlist.
    if not getattr(args, "skip_mcp_registration", False):
        # Fix 1 (v0.2.13): if a pipeline step earlier in this run produced
        # a fresh launcher binary at target/release/vct-launcher-temp,
        # copy it into launcher/dist/<os>-<arch>/ BEFORE _register_mcps
        # resolves a binary. This closes the gap where --update finds a
        # stale dist binary (tier-1 success) and never invokes tier-3 to
        # refresh it. Gated by --no-binary-swap.
        # A-6: entering the binary-refresh phase — re-extend the update-gate
        # deadline so a slow prior phase (venv/seed) hasn't already let it
        # expire while the binary swap is still ahead.
        _update_gate_flow.refresh("binary_refresh")
        try:
            _refresh_dist_binary_after_rebuild(
                PROJECT_ROOT,
                no_swap=bool(getattr(args, "no_binary_swap", False)),
                install_start_ts=globals().get("_INSTALL_START_TS"),
                deferral_report=_deferral_report,
            )
        except Exception as exc:  # noqa: BLE001 — soft-fail by design
            _log_install_event(
                "refresh_dist_binary", "error",
                f"unexpected exception: {exc}",
            )

        try:
            _register_mcps(
                PROJECT_ROOT,
                _deferral_report,
                prefer_only_bundled=bool(getattr(args, "prefer_only_bundled", False)),
                no_rebuild_on_stale=bool(getattr(args, "no_rebuild_on_stale", False)),
            )
        except Exception as exc:  # noqa: BLE001 — soft-fail by design
            print(
                f"  MCP registration raised unexpectedly: {exc}. "
                "Install will complete; re-run `python install.py --update` to retry.",
                file=sys.stderr,
            )
            _log_install_event(
                "register_mcps", "error",
                f"unexpected exception: {exc}",
            )

        # PR-33 (v0.2.12, 2026-05-16): consent-prompted rewrite path.
        # PR-23's _detect_stale_mcp_entries (invoked inside _register_mcps)
        # has already emitted the report-only deferral. When the user
        # passes --rewrite-stale-mcps we additionally walk each stale
        # entry, prompt for consent, and hand off to the same writer.
        # Soft-fail: any exception is caught and downgraded to a warning
        # so the install completes.
        if getattr(args, "rewrite_stale_mcps", False):
            try:
                _rewrite_stale_mcp_entries(
                    PROJECT_ROOT,
                    _deferral_report,
                    quiet=bool(getattr(args, "quiet", False)),
                )
            except Exception as exc:  # noqa: BLE001 — soft-fail by design
                print(
                    f"  --rewrite-stale-mcps raised unexpectedly: {exc}. "
                    "Install will complete; re-run to retry.",
                    file=sys.stderr,
                )
                _log_install_event(
                    "rewrite_stale_mcps", "error",
                    f"unexpected exception: {exc}",
                )

        # PR-34 (v0.2.13, 2026-05-16): consent-prompted deprecated-MCP
        # removal.  _detect_deprecated_mcp_entries (invoked inside
        # _register_mcps) has already emitted the report-only deferral.
        # When the user passes --remove-deprecated-mcps we additionally
        # prompt per entry and remove the accepted ones from ~/.claude.json.
        # --rewrite-stale-mcps also triggers deprecated-MCP detection
        # (deprecation is a form of staleness), but removal still requires
        # the explicit --remove-deprecated-mcps flag.
        # Soft-fail throughout.
        if getattr(args, "remove_deprecated_mcps", False):
            try:
                _remove_deprecated_mcp_entries(
                    PROJECT_ROOT,
                    _deferral_report,
                    quiet=bool(getattr(args, "quiet", False)),
                )
            except Exception as exc:  # noqa: BLE001 — soft-fail by design
                print(
                    f"  --remove-deprecated-mcps raised unexpectedly: {exc}. "
                    "Install will complete; re-run to retry.",
                    file=sys.stderr,
                )
                _log_install_event(
                    "remove_deprecated_mcps", "error",
                    f"unexpected exception: {exc}",
                )

    # v0.2.21 Step 8: deploy vct-hub binary alongside vct-launcher and
    # start it idempotently. The launcher binary has already been
    # placed by _refresh_dist_binary_after_rebuild / _register_mcps
    # above; vct-hub ships in the same `launcher/dist/<arch>/` slot
    # and shares the same release ZIP. Soft-fail throughout: a missing
    # binary or non-responsive /health degrades to "hub-unavailable
    # mode" which the v0.2.21 launcher handles gracefully (resolver
    # falls back to env vars; GUI still comes up).
    #
    # Cutover sentinel (W2 fix): written BEFORE the hub starts so the
    # v0.2.21 launcher's lib.rs setup() can skip its embedded
    # services::watcher::spawn during the overlap with a still-
    # running v0.2.20 launcher's old watcher. Deleted after /health
    # responds.
    #
    # Boot auto-start (8d): NOT registered here — user opts in via
    # launcher GUI Preferences (Step 13). install-time default is
    # conservative.
    #
    # --no-hub (v0.2.42 CI-3-nohub): skip Step 8 entirely when requested.
    # Intended for CI environments (no vct-hub binary on PATH, no network
    # download, no cargo) and headless installs where spawning a background
    # service is undesirable. With --update + --no-hub: any already-running
    # hub is left untouched; only the launch step is skipped (no kill, no
    # sentinel manipulation). Auto-start fallback verified: the hook at
    # templates/hooks/session-start-ensure-hub.sh (and its .ps1 sibling)
    # fires on every Claude Code SessionStart and invokes
    # `vct-hub --start-if-not-running`, so the hub comes up on the user's
    # next Claude Code session without manual intervention.
    if getattr(args, "no_hub", False):
        print("[8/10] Skipping vct-hub start (--no-hub). "
              "Hub will auto-start when the launcher is next opened, "
              "or when the first Claude Code session starts in any "
              "installed project (via session-start-ensure-hub hook).")
    elif not getattr(args, "skip_mcp_registration", False):
        try:
            _deploy_and_start_vct_hub(
                PROJECT_ROOT,
                deferral_report=_deferral_report,
                # v0.2.69 hub-staleness home #2: on a manual --update the
                # GUI did not stop the hub first, so stop the running hub
                # before the binary swap. A fresh install has no prior
                # hub to swap → leave the idempotent start untouched.
                stop_running_first=bool(getattr(args, "update", False)),
            )
        except Exception as exc:  # noqa: BLE001 — soft-fail by design
            _log_install_event(
                "deploy_vct_hub", "error",
                f"unexpected exception: {exc}",
            )

    # v0.2.10 (Bug L2): auto-materialize the boot service so containers
    # come back up after a reboot without manual intervention. Cross-OS:
    # systemd user unit on Linux, LaunchAgent on macOS, Task Scheduler
    # on Windows. Soft-fail throughout — failure here never blocks
    # install completion.
    #
    # PR-12 Bug C: pass the run-scoped _deferral_report so any stale
    # WorkingDirectory= auto-repair surfaces in UPDATE_DEFERRED.md (the
    # final write happens at line ~2181 below).
    _materialize_boot_service(PROJECT_ROOT, sysinfo, args,
                              deferral_report=_deferral_report)

    # v0.2.37 (2026-05-27): seed the launcher's install_path resolver
    # before next boot. The launcher's canonical
    # `resolve_orchestrator_root` resolver reads
    # `app_state['launcher.install_path']` first, then falls back to
    # walking up from `current_exe()`. The walk-up FAILS when the
    # launcher binary lives outside the clone (e.g. `~/bin/`,
    # PATH-installed wrapper, etc.), which historically caused
    # `ProjectEnvSettings::populate` to omit `VCT_ORCHESTRATOR_ROOT`
    # from `.claude/env` — see the user_project_x incident.
    #
    # Approach: write the install_path to a seed file at
    # `<install>/.vct/install_path_seed.txt`. On first launcher boot
    # the launcher's setup hook reads the seed (if present),
    # writes it to `app_state['launcher.install_path']`, and deletes
    # the seed file. This avoids Python-side SQLite schema knowledge
    # (the launcher.db schema is owned by the Rust launcher; we don't
    # want install.py touching it directly).
    #
    # Soft-fail by design: a failed seed write leaves the launcher to
    # fall back to its walk-up resolver, which still works in the
    # common case (binary lives inside the clone). The seed is purely
    # an out-of-band hint for the binary-outside-clone case.
    _seed_launcher_install_path(PROJECT_ROOT, _deferral_report)

    # v0.2.49 access-matrix Phase 1 (item #2): persist the orchestrator-
    # root KG collection canonical name from
    # `VCT_ORCHESTRATOR_ROOT_KG_COLLECTION` env (if set). When unset,
    # migration 028's default is authoritative — this call is a no-op.
    # See `_persist_orchestrator_root_kg_collection` docstring for the
    # resolution priority + soft-fail semantics.
    _persist_orchestrator_root_kg_collection(_deferral_report)

    # v0.2.6 Bug C1: invoke the desktop-icon step so direct `python install.py`
    # runs get an icon too. first-install.sh-wrapped runs already trigger
    # this script independently; the helper is idempotent so the second
    # invocation is a no-op (writes the same .desktop body).
    _run_desktop_icon_step(args)

    # v0.2.54 Track C (C-6): a successful --update run supersedes any
    # pending "merge resolved but install.py not run" state — clear the
    # launcher's resume sentinel so the purple "Continue Update" badge
    # doesn't persist (and re-run a redundant cycle) after the very
    # install.py run its deferral told the user to execute. Guarded:
    # no-op when absent, refused while a merge/rebase is in progress.
    if args.update:
        _clear_update_resume_sentinel_after_success(PROJECT_ROOT)

    # Fix 6 (v0.2.13) + A-11 (v0.2.73): this is the ONLY deferral write of the
    # run. It happens AFTER all deferral-adding steps complete
    # (_check_searxng_remnants, _check_ollama_mcp_remnants,
    # _check_search_mcp_env_obsolete, _register_mcps,
    # _materialize_boot_service, _rewrite_stale_mcp_entries). The historical
    # mid-run write (pre-A-11) was removed — with an empty in-memory report it
    # unlinked foreign entries mid-run. A-2: the report was seeded from disk
    # at the top of main(), so foreign writer families' entries survive this
    # rebuild-from-memory write.
    #
    # P1 (v0.2.75) TOCTOU close: the A-2 seed snapshots the disk at t0, but a
    # detached child (e.g. the P7 resync driver failing fast) can read-merge-
    # write a NEW foreign entry to disk minutes later — the rebuild-from-
    # memory write below would clobber it. Re-merge from disk NOW, at the
    # last moment before the single final write: owned IDs stay excluded
    # (drop-when-absent semantics intact) and merge_from_disk's per-run
    # mark_resolved tombstones prevent resurrecting entries this run
    # explicitly settled (the R-6 not_owed probe clears
    # codegraph_embed_resync_pending from MEMORY only; its on-disk copy is
    # still present here and must NOT be re-imported). Soft-fail like the
    # seed. This is a merge, not a write — A-11's single-write invariant
    # (tests/test_deferral_foreign_preservation_v0273.py) holds.
    try:
        _late_merged = _deferral_report.merge_from_disk(
            _deferral_folder,
            exclude_ids=_INSTALL_OWNED_CONDITION_IDS,
            exclude_prefixes=_INSTALL_OWNED_CONDITION_PREFIXES,
        )
        if _late_merged:
            _log_install_event(
                "deferral_report", "ok",
                f"pre-write disk re-merge preserved {_late_merged} mid-run "
                f"foreign deferral entr{'y' if _late_merged == 1 else 'ies'} "
                "(P1 TOCTOU close)",
            )
    except Exception as exc:  # noqa: BLE001 — re-merge is best-effort
        _log_install_event(
            "deferral_report", "warn",
            f"P1 pre-write disk re-merge failed: {exc}",
        )

    # Additionally, on --update runs that ended with ZERO entries, write a
    # stub UPDATE_DEFERRED.md so the user has a paper trail confirming the
    # update completed cleanly (was previously: NO file at all, indistinguishable
    # from "no --update run happened").
    try:
        wrote_entries = _deferral_report.write(_deferral_folder)
        if not wrote_entries and args.update:
            _write_update_deferred_stub(_deferral_folder, mode=mode)
    except Exception as exc:  # noqa: BLE001 — soft-fail by design
        _log_install_event(
            "deferral_report", "warn",
            f"final write failed: {exc}",
        )

    print()
    print("=" * 62)
    print("  Installation complete!")
    print("=" * 62)
    print()
    _print_next_steps(sysinfo, args)
    return 0


def _write_update_deferred_stub(folder: Path, *, mode: str) -> None:
    """Fix 6 (v0.2.13): write a stub ``UPDATE_DEFERRED.md`` for paper-trail.

    Called at end of ``--update`` runs that produced ZERO actionable
    deferral entries. The stub records the timestamp and mode so users
    grepping ``.claude/context/`` know an update ran cleanly. Previous
    behaviour was to write NO file in this case, which made successful
    updates indistinguishable from "no update happened at all".

    Soft-fail throughout: any OSError is swallowed and logged. The install
    must complete even when this stub write fails.

    Schema: a single-frontmatter Markdown file with no entries. The
    :class:`DeferralReport` reader treats unknown / empty payloads as an
    empty report — so reading this file back via ``DeferralReport.read()``
    yields ``[]`` and apply-deferred is a no-op. Idempotent: overwrites
    any prior stub.
    """
    from datetime import datetime, timezone

    target = folder / ".claude" / "context" / "UPDATE_DEFERRED.md"
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        _log_install_event(
            "deferral_report_stub", "warn",
            f"could not create parent {target.parent}: {exc}",
        )
        return

    ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    content = (
        "---\n"
        "schema_version: 1\n"
        "generated_by: install.py\n"
        f"generated_at: {ts}\n"
        "entries: 0\n"
        "stub: true\n"
        "---\n\n"
        f"# No deferrals from update at {ts}\n\n"
        f"This file is a stub: `install.py --{mode}` completed cleanly "
        "with zero actionable deferral conditions.\n\n"
        "If you expected deferral entries (e.g. you re-ran after fixing "
        "a known issue), they were resolved during this run. Otherwise "
        "this file confirms the update ran end-to-end without surfacing "
        "any conditions requiring follow-up.\n\n"
        "Safe to delete; install.py re-creates it on the next --update.\n"
    )

    try:
        target.write_text(content, encoding="utf-8")
    except OSError as exc:
        _log_install_event(
            "deferral_report_stub", "warn",
            f"could not write {target}: {exc}",
        )
        return
    _log_install_event(
        "deferral_report_stub", "ok",
        f"wrote stub UPDATE_DEFERRED.md at {target} (zero entries)",
    )


# ---------------------------------------------------------------------------
# Deferral-apply helper
# ---------------------------------------------------------------------------

def _pid_is_alive_for_deferral(pid: int) -> bool:
    """Cross-OS "is this PID still running" probe for deferral re-checks.

    v0.2.54 Track D: used by the ``launcher_restart_required`` handler.
    On Windows, ``os.kill(pid, 0)`` is NOT a probe — any non-CTRL signal
    value unconditionally TerminateProcess-es the target — so we go via
    OpenProcess + GetExitCodeProcess (STILL_ACTIVE == 259) instead.
    POSIX uses the conventional ``kill(pid, 0)`` errno dance.

    Conservative on uncertainty: unknown → True (treat the process as
    alive, so the deferral entry is KEPT rather than cleared on a
    guess).
    """
    if pid <= 0:
        return True  # unparseable / sentinel value — keep the entry
    if sys.platform == "win32":
        try:
            import ctypes

            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            STILL_ACTIVE = 259
            kernel32 = ctypes.windll.kernel32  # type: ignore[attr-defined]
            handle = kernel32.OpenProcess(
                PROCESS_QUERY_LIMITED_INFORMATION, False, pid,
            )
            if not handle:
                return False  # no such process (or no access → likely gone)
            try:
                exit_code = ctypes.c_ulong()
                ok = kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(exit_code),
                )
                return bool(ok) and exit_code.value == STILL_ACTIVE
            finally:
                kernel32.CloseHandle(handle)
        except Exception:  # noqa: BLE001 — conservative fallback
            return True
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True  # exists, owned by someone else
    except OSError:
        return True  # uncertain → conservative


def _apply_deferred_entries(
    current_run_report: DeferralReport,
    project_root: Path,
    *,
    args: "argparse.Namespace | None" = None,
) -> None:
    """Attempt to apply each entry in the persisted deferral report.

    Reads the on-disk ``UPDATE_DEFERRED.md``, attempts a best-effort
    resolution for each known condition, and marks successful ones resolved.
    The merged result (on-disk resolved entries removed + any new entries from
    the current run) is written back by the caller (``_deferral_report.write()``
    at end of ``main()``).

    Conditions handled:
      - ``schema_drift_rebuild_required``: never auto-applies the rebuild
        (that stays behind explicit ``--rebuild-collections`` consent), but
        RE-PROBES the current drift state (v0.2.54 Track D): when the
        drift is gone (e.g. the rebuild ran earlier in this same
        invocation) the entry is cleared instead of resurrected.
      - ``update_resume_required``: re-probes the launcher's resume
        sentinel (``.claude/state/orchestrator-update-resume-needed.json``
        in the install root); sentinel gone → resolved (v0.2.54 Track D).
      - ``launcher_restart_required``: consumes
        ``.claude/context/launcher-restart-marker`` (written by the
        restarted launcher) or, failing that, verifies the recorded old
        launcher PID has exited (v0.2.54 Track D).
      - ``weaviate_unreachable_at_update``: try ``podman start <name>``
        (name discovered via ``vco_lib.containers.find_existing_container``;
        falls back to the canonical ``vco_weaviate`` if no container is
        on the host yet) then check reachability; mark resolved if now
        reachable.
      - ``compose_overlay_ambiguous``: cannot auto-resolve (requires human
        decision); emit informational note.
    """
    persisted = DeferralReport.read(project_root)
    if not persisted:
        return

    print()
    print("[apply-deferred] Processing pending deferral entries ...")

    for entry in persisted.entries:
        cid = entry.condition_id

        if cid == "schema_drift_rebuild_required":
            # v0.2.54 Track D (Theme 5): re-probe instead of blind-skip.
            #
            # Pre-fix this branch unconditionally [skip]-ed and re-added
            # the persisted entry, while the docstring claimed "if the
            # user passed --rebuild-collections the drift is already
            # resolved before we arrive". Run order made that a lie:
            # the rebuild executes earlier in main(), then THIS code
            # re-read the on-disk file and resurrected the entry — so
            # `--update --apply-deferred --rebuild-collections` (the
            # entry's own command_to_apply combined with the documented
            # apply flow) performed the rebuild AND kept the deferral
            # alive forever.
            #
            # Same re-probe discipline as the orphan-collection handler
            # below (v0.2.46): probe the CURRENT drift state; clear only
            # when the premise no longer holds; keep on drift or on
            # probe failure. The rebuild itself is still never
            # auto-applied here — that stays behind explicit
            # --rebuild-collections consent.
            kg_collection = os.environ.get("KG_COLLECTION", "")
            if not kg_collection:
                print(
                    f"  [skip] {cid}: KG_COLLECTION not set — cannot "
                    "re-probe drift. Keeping entry."
                )
                current_run_report.add_entry(entry)
            else:
                weaviate_url = os.environ.get(
                    "WEAVIATE_URL",
                    f"http://localhost:{DEFAULT_WEAVIATE_PORT}",
                )
                print(f"  [try]  {cid}: re-probing schema drift on "
                      f"`{kg_collection}` ...")
                try:
                    drift, missing = _detect_kg_schema_drift(
                        weaviate_url, kg_collection,
                    )
                    if not drift:
                        print(
                            f"  [ok]   {cid}: no schema drift detected — "
                            "rebuild already applied (or schema healed). "
                            "Marking resolved."
                        )
                        # Resolved: clear any in-memory copy (the A-2 seed
                        # may have imported the on-disk entry) + tombstone
                        # against the P1 pre-write re-merge (v0.2.75).
                        current_run_report.mark_resolved(cid)
                    else:
                        print(
                            f"  [skip] {cid}: drift persists "
                            f"(missing: {', '.join(missing) or 'unknown'}). "
                            "Requires --rebuild-collections (manual "
                            "consent). Keeping entry."
                        )
                        current_run_report.add_entry(entry)
                except Exception as exc:  # noqa: BLE001 — soft-fail
                    print(f"  [fail] {cid}: drift re-probe failed ({exc}). "
                          "Keeping entry.")
                    current_run_report.add_entry(entry)

        elif cid == "update_resume_required":
            # v0.2.54 Track D (Theme 5): both sides of this entry's
            # lifecycle used to defer to code that didn't exist —
            # installer.rs pointed at install.py `mark_resolved` calls
            # (zero call sites) and install.py's emitter docstring
            # claimed a handler here (there was none), so after a
            # successful resume the "update halted at a conflict" entry
            # survived every --apply-deferred run forever whenever any
            # other deferral coexisted.
            #
            # Re-probe: the sentinel
            # `.claude/state/orchestrator-update-resume-needed.json`
            # (written by the launcher's update commands, deleted by
            # `resume_orchestrator_update` on success) is the source of
            # truth. Gone → the resume completed → resolved. Present →
            # the resume is still pending → keep. NOTE: the sentinel
            # lives in the INSTALL ROOT (= project_root for
            # orchestrator-self runs, where this entry is emitted).
            sentinel = (
                project_root / ".claude" / "state"
                / "orchestrator-update-resume-needed.json"
            )
            if sentinel.is_file():
                print(
                    f"  [skip] {cid}: resume sentinel still present at "
                    f"{sentinel} — the interrupted update has not been "
                    "resumed yet. Click `Continue Update` in the "
                    "launcher's MenuBar badge (or finish `python "
                    "install.py --update` from the install root). "
                    "Keeping entry."
                )
                current_run_report.add_entry(entry)
            else:
                print(
                    f"  [ok]   {cid}: resume sentinel is gone — the "
                    "update was resumed (or this very run completed "
                    "it). Marking resolved."
                )
                # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                current_run_report.mark_resolved(cid)

        elif cid == "launcher_restart_required":
            # v0.2.54 Track D (Theme 5): the documented self-clear
            # protocol (".claude/context/launcher-restart-marker"
            # written by the restarted launcher, consumed here) was
            # never implemented on either side — the marker string
            # existed only in a docstring and a Rust comment, and this
            # function had no handler, so the entry fell into the
            # [unknown] branch and survived forever unless the user
            # clicked the banner button (whose Rust path strips the
            # entry directly).
            #
            # Two-step re-probe, conservative on uncertainty:
            #   1. Marker file present → a post-swap launcher booted →
            #      consume the marker + resolve.
            #   2. Else, parse the old launcher PID from the entry's
            #      Detected text ("running launcher PID: <N>"); PID no
            #      longer alive → the old process exited, so the next/
            #      current launcher start loads the new binary →
            #      resolve. PID alive or unparseable → keep.
            marker = (
                project_root / ".claude" / "context"
                / "launcher-restart-marker"
            )
            if marker.is_file():
                try:
                    marker.unlink()
                except OSError as exc:
                    print(
                        f"  [warn] {cid}: marker consumed but unlink "
                        f"failed ({exc}) — will retry next run."
                    )
                print(
                    f"  [ok]   {cid}: launcher-restart-marker found — "
                    "the launcher restarted on the new binary. "
                    "Marking resolved."
                )
                # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                current_run_report.mark_resolved(cid)
            else:
                pid_match = re.search(
                    r"running launcher PID:\s*(\d+)", entry.detected or "",
                )
                old_pid = int(pid_match.group(1)) if pid_match else -1
                if pid_match and not _pid_is_alive_for_deferral(old_pid):
                    print(
                        f"  [ok]   {cid}: old launcher PID {old_pid} has "
                        "exited — the stale in-memory code is gone. "
                        "Marking resolved."
                    )
                    # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                    current_run_report.mark_resolved(cid)
                else:
                    detail = (
                        f"old launcher PID {old_pid} is still running"
                        if pid_match
                        else "no restart marker and no PID recorded"
                    )
                    print(
                        f"  [skip] {cid}: {detail} — restart still "
                        "pending. Keeping entry."
                    )
                    current_run_report.add_entry(entry)

        elif cid == "weaviate_unreachable_at_update":
            # v0.2.15: discover the actual container name + runtime on
            # this host instead of hardcoding `weaviate_claude` +
            # `podman` (both maintainer-machine assumptions). See
            # vco_lib/containers.py for the rename rationale + the
            # _detect_container_runtime / _runtime_preference_from_env
            # helpers above for the runtime contract.
            from vco_lib.containers import (
                find_existing_container as _find_existing_container,
            )
            _apply_runtime = (
                _detect_container_runtime()
                or _runtime_preference_from_env()
                or "podman"
            )
            _weav_container = (
                _find_existing_container("weaviate", runtime=_apply_runtime)
                or "vco_weaviate"
            )
            print(
                f"  [try]  {cid}: attempting {_apply_runtime} start "
                f"{_weav_container} ..."
            )
            try:
                subprocess.run(
                    [_apply_runtime, "start", _weav_container],
                    capture_output=True, timeout=30,
                )
                import time as _t
                _t.sleep(3)
                weaviate_url = os.environ.get(
                    "WEAVIATE_URL",
                    f"http://localhost:{DEFAULT_WEAVIATE_PORT}",
                )
                urllib.request.urlopen(
                    f"{weaviate_url}/v1/.well-known/ready", timeout=5
                )
                print(f"  [ok]   {cid}: Weaviate is now reachable. Marking resolved.")
                # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                current_run_report.mark_resolved(cid)
            except Exception as exc:
                print(f"  [fail] {cid}: still unreachable ({exc}). Keeping entry.")
                current_run_report.add_entry(entry)

        elif cid == "compose_overlay_ambiguous":
            # Cannot auto-resolve — needs human GPU vendor selection.
            print(
                f"  [skip] {cid}: ambiguous GPU overlay requires user decision. "
                "Pass --gpu or set VCT_GPU_VENDOR and re-run."
            )
            current_run_report.add_entry(entry)

        elif cid.startswith("kg_named_vector_slot_error_"):
            # v0.2.46 post-adversarial L4 (handler): named-vector slot
            # migrations historically failed when install.py step 7d ran
            # without `weaviate` importable (pre-V45-A self-relaunch).
            # The Part 1.5 H1 venv-fallback warning + the venv-resolver
            # helper close the underlying cause; this handler verifies
            # the slot is now present in Weaviate's schema and clears
            # the entry if so. The user is no longer asked to run
            # `vco_lib.project_init migrate-collections` manually when
            # the next `--update --apply-deferred` would do it.
            print(f"  [try]  {cid}: verifying slot via Weaviate schema ...")
            # Condition ID shape: kg_named_vector_slot_error_<Collection>_<slot>
            # e.g. kg_named_vector_slot_error_VCODev_KnowledgeGraph_arctic2_embed
            #      kg_named_vector_slot_error_VCODev_Development_openai_text_embed
            #
            # Both the COLLECTION name and the SLOT name can contain
            # underscores, so a positional split (.rsplit / .partition)
            # can't disambiguate. Instead we suffix-match against the
            # known slot vocabulary; the remainder is the collection.
            # The slot list mirrors `_KG_NAMED_VECTOR_SLOTS` in
            # vco_lib/project_init.py — kept in sync by hand.
            _KNOWN_SLOTS = (
                "qwen3_embed",
                "ollama_embed",
                "openai_embed",
                "arctic2_embed",
                "openai_text_embed",
            )
            try:
                payload = cid[len("kg_named_vector_slot_error_"):]
                slot_name: str | None = None
                for known in _KNOWN_SLOTS:
                    if payload.endswith("_" + known):
                        slot_name = known
                        collection_name = payload[: -(len(known) + 1)]
                        break
                if slot_name is None:
                    raise ValueError(
                        f"unknown slot suffix in condition_id {cid!r}; "
                        f"known slots: {_KNOWN_SLOTS}"
                    )
                weaviate_url = os.environ.get(
                    "WEAVIATE_URL",
                    f"http://localhost:{DEFAULT_WEAVIATE_PORT}",
                )
                schema_url = f"{weaviate_url}/v1/schema/{collection_name}"
                with urllib.request.urlopen(schema_url, timeout=10) as resp:
                    schema = json.loads(resp.read())
                vector_configs = schema.get("vectorConfig") or {}
                if slot_name in vector_configs:
                    print(
                        f"  [ok]   {cid}: slot `{slot_name}` is present in "
                        f"`{collection_name}`. Marking resolved."
                    )
                    # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                    current_run_report.mark_resolved(cid)
                else:
                    print(
                        f"  [fail] {cid}: slot `{slot_name}` still missing "
                        f"from `{collection_name}`. Keeping entry."
                    )
                    current_run_report.add_entry(entry)
            except Exception as exc:  # noqa: BLE001 — soft-fail
                print(f"  [fail] {cid}: probe failed ({exc}). Keeping entry.")
                current_run_report.add_entry(entry)

        elif cid == "orphan_orchestrator_development_collection":
            # v0.2.46 post-adversarial L4 (handler): a 0-row legacy
            # `VibeCodedOrchestrator_Development` Weaviate collection that
            # older install.py versions created. Deleting it is destructive
            # (Weaviate DROP can't be undone), but the deferral itself
            # documents "Dropping is safe" — the collection has no callers
            # and no rows. Gate auto-delete behind explicit user opt-in
            # (`--apply-orphan-deletes` flag) so the default
            # `--apply-deferred` flow remains non-destructive.
            if getattr(args, "apply_orphan_deletes", False):
                print(f"  [try]  {cid}: DELETE legacy orphan collection ...")
                try:
                    weaviate_url = os.environ.get(
                        "WEAVIATE_URL",
                        f"http://localhost:{DEFAULT_WEAVIATE_PORT}",
                    )
                    # Re-verify still-orphaned (0 rows + still exists)
                    # before destruction. A future install that
                    # repopulated the collection should NOT see its rows
                    # vanish because of a stale deferral.
                    schema_url = (
                        f"{weaviate_url}/v1/schema/"
                        f"VibeCodedOrchestrator_Development"
                    )
                    try:
                        with urllib.request.urlopen(schema_url, timeout=5) as resp:
                            resp.read()  # exists
                    except urllib.error.HTTPError as e:
                        if e.code == 404:
                            print(
                                f"  [ok]   {cid}: collection already absent. "
                                "Marking resolved."
                            )
                            # Resolved: clear seeded copy + tombstone
                            # (P1, v0.2.75).
                            current_run_report.mark_resolved(cid)
                            continue
                        raise
                    # Sanity-check row count via aggregate (GraphQL):
                    count_gql = (
                        '{"query":"{ Aggregate { '
                        'VibeCodedOrchestrator_Development { meta { count } } } }"}'
                    )
                    req = urllib.request.Request(
                        f"{weaviate_url}/v1/graphql",
                        data=count_gql.encode("utf-8"),
                        method="POST",
                        headers={"Content-Type": "application/json"},
                    )
                    with urllib.request.urlopen(req, timeout=10) as resp:
                        body = json.loads(resp.read())
                    count = (body.get("data", {})
                                 .get("Aggregate", {})
                                 .get("VibeCodedOrchestrator_Development", [{}])
                                 [0].get("meta", {}).get("count"))
                    if count is None or count > 0:
                        print(
                            f"  [skip] {cid}: collection has {count} rows "
                            f"(not 0). Refusing to delete a non-orphan. "
                            f"Keeping entry."
                        )
                        current_run_report.add_entry(entry)
                        continue
                    # Confirmed empty + still exists. Safe to drop.
                    del_req = urllib.request.Request(schema_url, method="DELETE")
                    urllib.request.urlopen(del_req, timeout=10)
                    print(f"  [ok]   {cid}: collection dropped. Marking resolved.")
                    # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                    current_run_report.mark_resolved(cid)
                except Exception as exc:  # noqa: BLE001
                    print(
                        f"  [fail] {cid}: delete failed ({exc}). Keeping entry."
                    )
                    current_run_report.add_entry(entry)
            else:
                print(
                    f"  [skip] {cid}: destructive — pass "
                    f"--apply-orphan-deletes to consent."
                )
                current_run_report.add_entry(entry)

        elif cid == "launcher_update_diverged":
            # v0.2.55 (durable-logging fix, re-probe handler): the launcher
            # writes this entry when a GUI update could not fast-forward
            # (non-FF divergence) OR `WaitForBinaryRefresh` timed out
            # before the on-disk launcher binary reached the source target.
            # All three kinds share this condition_id (see
            # installer.rs::write_launcher_update_diverged_deferral).
            #
            # Re-probe (mirrors WaitForBinaryRefresh's own exit condition):
            # the source-of-truth is whether the on-disk launcher binary
            # version now meets/exceeds the source version. install.py
            # reaching THIS point already means the pull + --update
            # succeeded (otherwise we wouldn't be running), so the
            # divergence is resolved; we additionally confirm the binary
            # caught up. on_disk >= source → resolved; else keep (the
            # binary-refresh commit may still be landing).
            try:
                source_version = _read_launcher_version(project_root)
                # On-disk binary version lives in the dist sidecar
                # `<binary>.metadata.json::launcher_version` (written by
                # scripts/build-bundled-launcher.sh; read by the Rust
                # read_on_disk_binary_version). Parse it directly here.
                subdir, fname = _launcher_binary_relative_path()
                dist_dir = project_root / "launcher" / "dist" / subdir

                def _read_dist_meta_version(meta_name: str) -> "str | None":
                    p = dist_dir / meta_name
                    if not p.is_file():
                        return None
                    try:
                        m = json.loads(p.read_text(encoding="utf-8"))
                    except Exception:
                        return None
                    raw = m.get("launcher_version")
                    return raw.strip() if isinstance(raw, str) and raw.strip() else None

                on_disk_version = _read_dist_meta_version(f"{fname}.metadata.json")
                # Symmetric with the Rust WaitForBinaryRefresh hub-gate
                # (v0.2.55): also re-probe the hub binary so a launcher that
                # caught up but a still-stale hub doesn't clear the entry
                # prematurely (the C2 asymmetry the review flagged). Absent
                # hub sidecar → treated as "hub OK" (same as the Rust gate).
                hub_meta_name = (
                    "vct-hub.exe.metadata.json"
                    if fname.endswith(".exe")
                    else "vct-hub.metadata.json"
                )
                on_disk_hub_version = _read_dist_meta_version(hub_meta_name)

                def _vparts(v: str) -> list[int]:
                    out: list[int] = []
                    for p in v.split("."):
                        digits = ""
                        for ch in p:
                            if ch.isdigit():
                                digits += ch
                            else:
                                break
                        out.append(int(digits) if digits else 0)
                    return out

                def _ge(a_str: str, b_str: str) -> bool:
                    a, b = _vparts(a_str), _vparts(b_str)
                    n = max(len(a), len(b))
                    a += [0] * (n - len(a))
                    b += [0] * (n - len(b))
                    return a >= b

                launcher_ok = bool(
                    source_version and on_disk_version
                    and _ge(on_disk_version, source_version)
                )
                # Hub: absent sidecar → don't block on it (degrade to
                # launcher-only, matching the Rust gate's caveat).
                hub_ok = (
                    on_disk_hub_version is None
                    or (source_version is not None
                        and _ge(on_disk_hub_version, source_version))
                )
                resolved = launcher_ok and hub_ok

                if resolved:
                    print(
                        f"  [ok]   {cid}: on-disk launcher v{on_disk_version} "
                        f"(hub v{on_disk_hub_version or 'n/a'}) >= source "
                        f"v{source_version} — the update reached target. "
                        "Marking resolved."
                    )
                    # Resolved: clear seeded copy + tombstone (P1, v0.2.75).
                    # This cid is FOREIGN (Rust-emitted,
                    # git_user_editable_merge.rs — NOT in the owned set), so
                    # the A-2 seed already imported the on-disk copy into
                    # current_run_report and the P1 pre-write re-merge would
                    # re-import it again: without mark_resolved here the
                    # 'do NOT re-add' resolution was inert since v0.2.73.
                    current_run_report.mark_resolved(cid)
                else:
                    blocker = "launcher" if not launcher_ok else "hub"
                    print(
                        f"  [skip] {cid}: {blocker} binary has not reached "
                        f"source v{source_version or '<unknown>'} yet "
                        f"(launcher v{on_disk_version or '<unknown>'}, hub "
                        f"v{on_disk_hub_version or '<none>'}; binary-refresh "
                        "commit may still be landing, or divergence unresolved). "
                        "Keeping entry."
                    )
                    current_run_report.add_entry(entry)
            except Exception as exc:  # noqa: BLE001 — soft-fail
                print(
                    f"  [fail] {cid}: version re-probe failed ({exc}). "
                    "Keeping entry."
                )
                current_run_report.add_entry(entry)

        else:
            # Unknown condition: preserve it to avoid silently losing info.
            print(f"  [unknown] {cid}: no handler. Preserving entry.")
            current_run_report.add_entry(entry)


# ---------------------------------------------------------------------------
# Step 1: Python version
# ---------------------------------------------------------------------------

def _check_python_version() -> None:
    print("[1/10] Checking Python version ... ", end="", flush=True)
    _log_install_event("1/10", "start", "checking Python version")
    v = sys.version_info
    if (v.major, v.minor) < MIN_PYTHON:
        print("FAIL")
        print(f"  Python {MIN_PYTHON[0]}.{MIN_PYTHON[1]}+ required, "
              f"found {v.major}.{v.minor}.{v.micro}")
        _print_python_install_hint()
        _log_install_event(
            "1/10", "error",
            f"Python {v.major}.{v.minor}.{v.micro} below required "
            f"{MIN_PYTHON[0]}.{MIN_PYTHON[1]}",
            data={"found": f"{v.major}.{v.minor}.{v.micro}",
                  "required": f"{MIN_PYTHON[0]}.{MIN_PYTHON[1]}"},
        )
        sys.exit(1)

    # v0.2.53 M-P1-1: wheel-coverage detection.
    # Replaces a hard MAX_PYTHON constant. We probe via `pip install
    # --dry-run --only-binary=:all:` against a small set of pinned deps
    # representative of VCO's binary-heavy stack (Pydantic, weaviate-client,
    # httpx). If pip would fall back to source build, the install will
    # almost certainly fail later in step 4/10 with a confusing C-compiler
    # error from setup.py — print a clear hint NOW so the user can
    # downgrade Python before wasting 10 minutes.
    if (v.major, v.minor) >= (3, 14):
        wheel_ok = _check_wheel_support_for_python(sys.executable)
        if wheel_ok is False:
            print("FAIL")
            print(f"  Python {v.major}.{v.minor}.{v.micro} is too new — "
                  "wheels are not yet published for VCO's binary deps.")
            print("  pip would try to build from source, which typically "
                  "fails without a C/C++ toolchain installed.")
            print()
            print("  Workaround: install Python 3.12 or 3.13 and re-run "
                  "first-install with that interpreter:")
            print("    # macOS / Homebrew:")
            print("    brew install python@3.13")
            print("    /opt/homebrew/bin/python3.13 install.py")
            print("    # Linux / apt:")
            print("    sudo apt install python3.13")
            print("    python3.13 install.py")
            print("    # Windows / py launcher:")
            print("    py -3.13 install.py")
            _log_install_event(
                "1/10", "error",
                f"Python {v.major}.{v.minor}.{v.micro} lacks wheel coverage",
                data={
                    "found": f"{v.major}.{v.minor}.{v.micro}",
                    "wheel_support_ok": False,
                    "workaround": "downgrade to 3.12 or 3.13",
                },
            )
            sys.exit(1)

    print(f"OK ({v.major}.{v.minor}.{v.micro})")
    _log_install_event(
        "1/10", "ok",
        f"Python {v.major}.{v.minor}.{v.micro}",
        data={"version": f"{v.major}.{v.minor}.{v.micro}"},
    )


def _check_wheel_support_for_python(python_cmd: str) -> Optional[bool]:
    """v0.2.53 M-P1-1: probe wheel coverage via pip --dry-run.

    Calls ``pip install --dry-run --only-binary=:all: <key-deps>``
    against the given Python interpreter. Returns True iff pip
    reports it CAN install without source build; False if it would
    need to compile; None on probe error (network down, pip absent,
    timeout) — callers treat None as "unknown, defer judgement".

    Kept separate from the bootstrap envelope's
    `_bootstrap_python_wheel_support` because:
    1. This is called from _check_python_version at install step 1/10
       (pre-venv-creation) — it must work against the host Python.
    2. The bootstrap envelope's variant runs READ-ONLY at bootstrap
       time; this one runs during the actual install path.

    Both implementations probe the same canonical key deps.
    """
    probe_pkgs = ["weaviate-client>=4.7", "pydantic>=2", "httpx>=0.27"]
    try:
        result = subprocess.run(
            [python_cmd, "-m", "pip", "install",
             "--dry-run", "--only-binary=:all:",
             "--no-cache-dir", "--quiet",
             *probe_pkgs],
            capture_output=True, text=True, timeout=30,
            env={**os.environ, "PIP_DISABLE_PIP_VERSION_CHECK": "1"},
        )
    except (subprocess.SubprocessError, OSError, FileNotFoundError):
        return None
    return result.returncode == 0


def _print_python_install_hint() -> None:
    os_name = platform.system()
    if os_name == "Linux":
        print("  Install: sudo apt install python3.12  (Ubuntu/Debian)")
        print("           sudo dnf install python3.12  (Fedora)")
    elif os_name == "Darwin":
        print("  Install: brew install python@3.12")
    elif os_name == "Windows":
        print("  Install: winget install Python.Python.3.12")
        print("       Or: https://python.org/downloads/")
    print("  Download: https://python.org")


def _check_prerequisites() -> None:
    """Warn (don't block) about optional prerequisites.

    Hard requirements (Python, container runtime) are checked elsewhere.
    This function surfaces *soft* prereqs that the rest of the install
    expects to be available later, so the user can install them now rather
    than discover them mid-run.
    """
    os_name = platform.system()
    missing: list[tuple[str, str]] = []  # (tool, install hint)

    # The python venv module is built-in on most distros, but Debian/Ubuntu
    # ships it as a separate package. Detect early.
    if os_name == "Linux":
        try:
            r = subprocess.run(
                [sys.executable, "-c", "import venv"],
                capture_output=True, text=True, timeout=10,
            )
            if r.returncode != 0:
                missing.append(("python3-venv", "sudo apt install python3-venv  # Debian/Ubuntu"))
        except (subprocess.TimeoutExpired, OSError):
            pass

    # ensurepip / pip availability inside the soon-to-be-created venv.
    try:
        r = subprocess.run(
            [sys.executable, "-c", "import ensurepip"],
            capture_output=True, text=True, timeout=10,
        )
        if r.returncode != 0:
            if os_name == "Linux":
                missing.append(("python3-pip / ensurepip",
                                "sudo apt install python3-pip  # Debian/Ubuntu"))
            else:
                missing.append(("ensurepip",
                                "Reinstall Python from python.org or your package manager"))
    except (subprocess.TimeoutExpired, OSError):
        pass

    if missing:
        print()
        print("  WARNING: missing optional prerequisites:")
        for tool, hint in missing:
            print(f"    - {tool}: {hint}")
        print("  Continuing — these are needed only for specific install paths.")
        print()


# ---------------------------------------------------------------------------
# Step 2: System detection
# ---------------------------------------------------------------------------

def _gpu_vendor_preference_from_env() -> Optional[str]:
    """Shim over :func:`vco_lib.gpu_profile.gpu_vendor_preference_from_env`.

    v0.2.54 gpu-audit C-3 (see shared helper for full rationale).
    """
    from vco_lib.gpu_profile import gpu_vendor_preference_from_env
    return gpu_vendor_preference_from_env()


def _detect_system(args: argparse.Namespace) -> SystemInfo:
    print("[2/10] Detecting system ... ", flush=True)
    _log_install_event("2/10", "start", "detecting system")
    os_name = platform.system()
    has_gpu = False
    has_metal = False
    gpu_name = ""
    gpu_vendor = ""
    vram_gb = 0.0
    container_cmd = ""
    ram_gb = _probe_system_ram_gb()

    # GPU detection
    if args.cpu_only:
        print("  GPU: skipped (--cpu-only)")
    elif args.openai_key:
        print("  GPU: not needed (using OpenAI embeddings)")
    elif getattr(args, "no_gpu_check", False):
        print("  GPU: skipped (--no-gpu-check)")
    else:
        # v0.2.68 (Defect Y): multi-GPU / iGPU-aware device selection.
        #
        # Pre-v0.2.68 this block did first-vendor / first-card detection
        # (probe nvidia-smi, then rocm-smi, then Metal; read device-0's
        # VRAM only). That under-tiered multi-GPU hosts and — on an
        # AMD-iGPU + AMD-discrete box — could read the iGPU's small UMA
        # "VRAM" and demote a CodeSage-capable discrete card to Jina,
        # violating the "AMD-capable → qwen3, NEVER Jina" invariant.
        #
        # Now we enumerate ALL GPUs once (vco_lib.gpu_device.enumerate_gpus)
        # and pick the most-capable usable discrete card
        # (select_gpu_device: drop Intel + drop iGPUs → max-VRAM discrete).
        # The chosen device's vendor/VRAM flow UNCHANGED into _decide_gpu_mode
        # and the three embedding selectors — single-GPU hosts get a
        # byte-identical result to the old probe (one candidate in, same
        # card out). Metal stays special-cased AFTER select_gpu_device
        # returns None: Apple unified memory has no discrete-VRAM concept,
        # so it must not go through the VRAM picker.
        #
        # We do NOT auto-install GPU drivers — they're large (~3 GB), may
        # need a reboot, and the canonical install path is vendor-specific.
        # Detection-only here; the launcher GUI offers opt-in install.
        #
        # VCT_GPU_VENDOR is honored as vendor_pref into select_gpu_device
        # (lenient: if the preferred vendor has no usable card, fall through
        # to the full usable set rather than stranding the install). The
        # "metal" preference is handled separately (Apple has no discrete
        # VRAM to rank).
        from vco_lib.gpu_device import enumerate_gpus, select_gpu_device

        vendor_pref = _gpu_vendor_preference_from_env()

        if vendor_pref == "metal":
            if os_name == "Darwin" and _detect_apple_silicon():
                has_metal = True
                gpu_vendor = "metal"
                print("  GPU: Apple Silicon (Metal — VCT_GPU_VENDOR=metal)")
            else:
                print(
                    "  VCT_GPU_VENDOR=metal set but this host is not "
                    "Apple Silicon; falling through to auto-detect.",
                    file=sys.stderr,
                )

        if not gpu_vendor and not has_metal:
            candidates = enumerate_gpus()
            chosen = select_gpu_device(candidates, vendor_pref=vendor_pref)
            # Surface the full enumeration on the system-info banner /
            # event log so multi-GPU selection is observable.
            usable_discrete = [
                c for c in candidates
                if c.vendor != "intel" and not c.is_integrated
            ]
            ignored = [c for c in candidates if c not in usable_discrete]

            if chosen is not None:
                has_gpu = True
                gpu_vendor = chosen.vendor
                vram_gb = chosen.vram_gb
                # Enrich the display name with the vendor-specific probe
                # when it gives a friendlier string than the enumerator's
                # generic label (AMD rocm-smi product, NVIDIA driver/CUDA).
                gpu_name = chosen.name
                extra = ""
                if chosen.vendor == "nvidia":
                    nv_present, nv_name = _detect_nvidia_gpu()
                    if nv_present and nv_name:
                        gpu_name = nv_name
                    extra = _probe_nvidia_versions()
                elif chosen.vendor == "amd":
                    rocm_present, rocm_info = _detect_amd_rocm()
                    if rocm_present and rocm_info:
                        gpu_name = rocm_info
                vram_label = f", {vram_gb:.1f} GB VRAM" if vram_gb > 0 else ""
                pref_label = (
                    f" (VCT_GPU_VENDOR={vendor_pref})"
                    if vendor_pref in ("nvidia", "amd")
                    else ""
                )
                if extra:
                    print(f"  GPU: {gpu_name} ({extra}{vram_label}){pref_label}")
                else:
                    label = f"  GPU: {gpu_name}{vram_label}{pref_label}"
                    print(label.replace(": ,", ": "))
                # When more than one usable discrete card was found, tell
                # the user which we picked + how to override.
                if len(usable_discrete) > 1:
                    others = ", ".join(
                        f"{c.name or c.vendor} ({c.vram_gb:.1f} GB)"
                        for c in usable_discrete if c is not chosen
                    )
                    print(
                        f"       selected most-capable GPU; also found: "
                        f"{others} — pass VCT_GPU_VENDOR to override."
                    )
                # When we deliberately ignored an iGPU / Intel GPU, say so —
                # otherwise an iGPU+discrete user might think detection is
                # wrong ("I have 2 GPUs, why does it show one?").
                if ignored:
                    ign = ", ".join(
                        f"{c.name or c.vendor}"
                        f"{' [Intel, unsupported]' if c.vendor == 'intel' else ' [integrated]'}"
                        for c in ignored
                    )
                    print(f"       ignored (not a usable accelerator): {ign}")
            elif os_name == "Darwin" and _detect_apple_silicon():
                has_metal = True
                gpu_vendor = "metal"
                print("  GPU: Apple Silicon (Metal — built-in, no driver install needed)")
            else:
                _print_gpu_hint(os_name)
                # If we saw Intel / integrated GPUs but no usable discrete
                # one, make the "→ CPU" reason explicit (closes the old
                # "Intel falls to CPU by accident" gap).
                if ignored:
                    ign = ", ".join(
                        f"{c.name or c.vendor}"
                        f"{' [Intel, unsupported]' if c.vendor == 'intel' else ' [integrated]'}"
                        for c in ignored
                    )
                    print(f"       (saw {ign} — not usable accelerators; using CPU)")

            # Stash the enumeration for the manifest writer / event log so
            # downstream tools (doctor, GUI snapshot) can reflect "found N,
            # using <chosen>" without re-running detection.
            args._gpu_candidates = [  # type: ignore[attr-defined]
                {
                    "vendor": c.vendor, "name": c.name,
                    "vram_gb": c.vram_gb, "is_integrated": c.is_integrated,
                }
                for c in candidates
            ]

    # v0.2.53 L-P0-8: when a GPU IS detected on Linux, surface the
    # render/video group remediation if missing. The webkit_preflight
    # silently skips when the user lacks `render` (and sometimes `video`)
    # group membership; without this hint the user has no idea why GPU
    # acceleration didn't engage.
    if os_name == "Linux" and (has_gpu or has_metal):
        _print_render_video_group_hint()

    # v0.2.53 L-P0-3: surface the SELinux `:Z` bind-mount hint when
    # SELinux is enforcing AND we're going to set up containers. We
    # check enforcement here (cheap) so the user sees the hint during
    # the system-detection summary, before any container start that
    # would silently fail to access bind-mount data.
    if (
        os_name == "Linux"
        and not getattr(args, "no_containers", False)
        and _detect_selinux_enforcing()
    ):
        _print_selinux_bind_mount_hint()

    # Container runtime
    if args.container:
        container_cmd = args.container
        print(f"  Container: {container_cmd} (forced)")
    else:
        container_cmd = _detect_container_runtime()
        if container_cmd:
            print(f"  Container: {container_cmd}")
        elif not args.no_containers:
            print("  Container: none found")

    print(f"  OS: {os_name} ({platform.machine()})")

    # If --gpu was forced and no vendor detected, default to "nvidia" so
    # the existing GPU overlay still applies (back-compat: prior behaviour
    # was NVIDIA-only).
    final_has_gpu = has_gpu or args.gpu
    final_vendor = gpu_vendor or ("nvidia" if args.gpu else "")

    # v0.2.9 (Bug K): resolve user override → tri-state.
    #   --gpu       => override=True
    #   --cpu-only  => override=False
    #   neither     => override=None (auto)
    # When --openai-key is set, treat as override=False (we don't need
    # local GPU at all — embeddings come from OpenAI). --no-gpu-check is
    # ALSO override=False — the user explicitly suppressed the probe.
    user_override: "bool | None" = None
    if args.gpu:
        user_override = True
    elif args.cpu_only or args.openai_key or getattr(args, "no_gpu_check", False):
        user_override = False
    threshold_gb = float(getattr(
        args, "gpu_vram_threshold_gb", _DEFAULT_GPU_VRAM_THRESHOLD_GB,
    ))
    gpu_mode = _decide_gpu_mode(
        vram_gb=vram_gb,
        vendor=final_vendor,
        user_override=user_override,
        threshold_gb=threshold_gb,
    )
    # If the threshold demoted a discrete GPU to CPU, tell the user
    # explicitly — they may want to override or change the threshold.
    if (
        user_override is None
        and final_vendor in ("nvidia", "amd")
        and vram_gb > 0
        and gpu_mode == "cpu"
    ):
        print(
            f"  GPU mode: CPU (VRAM {vram_gb:.1f} GB < threshold "
            f"{threshold_gb:.1f} GB — pass "
            f"--gpu-vram-threshold-gb to override, or --gpu to force GPU)"
        )

    if ram_gb > 0:
        print(f"  RAM: {ram_gb:.1f} GB")
    info = SystemInfo(
        os_name=os_name,
        has_gpu=final_has_gpu,
        has_metal=has_metal,
        container_cmd=container_cmd,
        gpu_name=gpu_name,
        vram_gb=vram_gb,
        ram_gb=ram_gb,
        gpu_vendor=final_vendor,
    )
    # v0.2.9 (Bug K): stash the resolved mode on args so the manifest
    # writer can record it without re-running detection.
    args._gpu_mode = gpu_mode  # type: ignore[attr-defined]
    args._vram_gb_resolved = vram_gb  # type: ignore[attr-defined]
    args._gpu_vram_threshold_resolved = threshold_gb  # type: ignore[attr-defined]

    _log_install_event(
        "2/10", "ok",
        f"system detected: {os_name}",
        data={
            "os": os_name,
            "arch": platform.machine(),
            "has_gpu": info.has_gpu,
            "has_metal": info.has_metal,
            "container_cmd": container_cmd,
            "gpu_name": gpu_name,
            "gpu_vendor": final_vendor,
            "vram_gb": vram_gb,
            "ram_gb": ram_gb,
            "gpu_mode": gpu_mode,
            "gpu_vram_threshold_gb": threshold_gb,
            # v0.2.68 (Defect Y): record the full GPU enumeration so the
            # event log reflects multi-GPU / iGPU-aware selection.
            "gpu_candidates": getattr(args, "_gpu_candidates", []),
        },
    )
    return info


def _gpu_tool_reports_live(tool: str, probe_args: list[str], timeout: int = 10) -> bool:
    """Return True iff ``tool`` is on PATH AND ``tool probe_args`` exits 0.

    A GPU CLI that isn't installed (e.g. ``rocm-smi`` on a pure-NVIDIA box, or
    either tool on a non-GPU machine) or that hangs past ``timeout`` counts as
    "not live" — never a crash. Mirrors the ``shutil.which()`` + try/except
    guard the detection probes (``_detect_nvidia_gpu``, the rocm-smi probes)
    already use.

    v0.2.62: the compose-overlay ambiguity check in ``_start_services``
    previously invoked ``subprocess.run(["rocm-smi", ...])`` /
    ``(["nvidia-smi", ...])`` unguarded, so any machine missing one tool raised
    ``FileNotFoundError`` ("No such file or directory: 'rocm-smi'") and aborted
    the entire install/update; a hanging tool would have raised
    ``TimeoutExpired``. Centralising the guard here keeps both probes safe.
    """
    if not shutil.which(tool):
        return False
    try:
        return subprocess.run(
            [tool, *probe_args], capture_output=True, timeout=timeout,
        ).returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False


def _detect_nvidia_gpu() -> tuple[bool, str]:
    """Check for NVIDIA GPU via nvidia-smi."""
    try:
        result = subprocess.run(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader,nounits"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0 and result.stdout.strip():
            return True, result.stdout.strip().splitlines()[0]
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    return False, ""


def _detect_apple_silicon() -> bool:
    """Check if running on Apple Silicon."""
    return platform.system() == "Darwin" and platform.machine() == "arm64"


def _probe_nvidia_versions() -> str:
    """Best-effort fetch of NVIDIA driver + CUDA version strings.

    Returns a `"driver X.Y, CUDA Z.W"` summary on success, or an empty
    string on any failure. Purely cosmetic — used to enrich the system-
    info banner. NEVER raises.

    nvidia-smi output format (csv,noheader): `545.23.06, 12.3` per GPU.
    We just take the first row.
    """
    try:
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=driver_version,cuda_version",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0:
            line = result.stdout.strip().splitlines()
            if line:
                parts = [p.strip() for p in line[0].split(",")]
                if len(parts) >= 2:
                    return f"driver {parts[0]}, CUDA {parts[1]}"
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        pass
    return ""


def _detect_amd_rocm() -> tuple[bool, str]:
    """Detect AMD GPU via ROCm tooling.

    Returns (present, summary). `summary` is human-readable, e.g.
    "AMD Radeon Pro VII (ROCm 6.0)". Empty string when absent.

    rocm-smi is part of ROCm; if it runs and returns 0, the kernel
    driver is loaded and at least one supported GPU is visible. We
    also try `rocm-smi --showdriverversion` for the version string;
    failure on the version sub-probe is non-fatal — we still return
    True with a generic summary.
    """
    if not shutil.which("rocm-smi"):
        return False, ""
    try:
        # `rocm-smi --showproductname --json` would be cleaner but
        # JSON output isn't universal across rocm-smi versions. The
        # plain `--showproductname` text output is a stable fallback.
        result = subprocess.run(
            ["rocm-smi", "--showproductname"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode != 0:
            return False, ""
        # Parse a "Card Series: Radeon RX 6800" / "Card model: ..." line
        # if present; otherwise fall back to a generic label.
        product = ""
        for line in result.stdout.splitlines():
            stripped = line.strip()
            if "Card Series:" in stripped or "Card Model:" in stripped:
                product = stripped.split(":", 1)[1].strip()
                break
        # Driver version (best effort).
        driver = ""
        try:
            v = subprocess.run(
                ["rocm-smi", "--showdriverversion"],
                capture_output=True, text=True, timeout=10,
            )
            if v.returncode == 0:
                for line in v.stdout.splitlines():
                    if "Driver" in line and ":" in line:
                        driver = line.split(":", 1)[1].strip()
                        break
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass
        if product and driver:
            return True, f"{product} (ROCm driver {driver})"
        if product:
            return True, f"{product} (ROCm)"
        return True, "AMD GPU (ROCm detected)"
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return False, ""


# v0.2.9 (Bug K): VRAM-threshold gating for GPU mode.
#
# Default threshold (GB) below which we degrade to CPU-only even if a
# discrete GPU is present. Tuned for the default model stack:
#
#   qwen3-embedding:0.6b  ~1.2 GB
#   CodeSage-Large-v2     ~2.6 GB
#   qwen3.5:9b (Q4)       ~6.0 GB
#
# An 8 GB card can hold the inference model OR the embedders, but
# thrashes when both are loaded — degrading to CPU is faster than
# partial offload. Configurable via `--gpu-vram-threshold-gb` for users
# running a different model selection. Keep in sync with the Rust side
# (`launcher::commands::gpu_policy::DEFAULT_GPU_VRAM_THRESHOLD_GB`).
_DEFAULT_GPU_VRAM_THRESHOLD_GB = 8.0


def _decide_gpu_mode(
    vram_gb: float,
    vendor: str,
    user_override: "bool | None" = None,
    threshold_gb: float = _DEFAULT_GPU_VRAM_THRESHOLD_GB,
) -> str:
    """Pure decision function: pick `"cuda"`, `"rocm"`, `"metal"`, or `"cpu"`.

    Precedence:
      1. `user_override` (when not None) wins.
         - override=True:  vendor=="metal" → "metal"; vendor=="amd" → "rocm";
           everyone else → "cuda" (default fallback — user accepted the tradeoff).
         - override=False: "cpu".
      2. vendor=="metal" → "metal" (no threshold — unified memory).
      3. vendor=="nvidia" AND vram_gb >= threshold → "cuda".
      4. vendor=="amd" AND vram_gb >= threshold → "rocm".
      5. Else → "cpu".

    Mirrors the Rust `decide_gpu_mode` in
    `launcher::commands::gpu_policy`. v0.2.20 split the legacy "gpu"
    return value into "cuda" + "rocm" so the install-time overlay
    picker can route correctly per vendor. Pure (no side effects);
    tested from `tests/test_install_gpu_mode_decision.py`.

    Args:
      vram_gb:        Probed VRAM in GB. 0.0 means "no GPU" OR "probe
                      failed". Conservative path: probe-failed → cpu.
      vendor:         "nvidia" | "amd" | "metal" | "" (from
                      `_detect_*` probes).
      user_override:  `True` for `--gpu`, `False` for `--cpu-only`,
                      `None` for "auto".
      threshold_gb:   VRAM threshold in GB (inclusive). Default 8.0.

    Returns:
      One of: `"cuda"`, `"rocm"`, `"metal"`, `"cpu"`. Matches the
      lowercase serde of Rust's `GpuMode` enum.
    """
    if user_override is not None:
        if user_override:
            # User-forced GPU mode. Route to the matching vendor:
            # - Apple Silicon → metal (no CUDA/ROCm on M-series).
            # - AMD          → rocm.
            # - Everyone else (NVIDIA, or empty vendor when the probe
            #   missed a card the user knows is there) → cuda. CUDA is
            #   the safer default fallback (more mature tooling).
            if vendor == "metal":
                return "metal"
            if vendor == "amd":
                return "rocm"
            return "cuda"
        return "cpu"

    if vendor == "metal":
        return "metal"

    if vendor == "nvidia" and vram_gb >= threshold_gb:
        return "cuda"

    if vendor == "amd" and vram_gb >= threshold_gb:
        return "rocm"

    return "cpu"


def _probe_system_ram_gb() -> float:
    """Best-effort system RAM probe across Linux/macOS/Windows.

    Uses `psutil` if available (fastest and most portable). Falls back
    to /proc/meminfo on Linux, `sysctl hw.memsize` on macOS, and `wmic`
    on Windows. Returns 0.0 on any failure — caller handles gracefully.
    """
    try:
        import psutil  # type: ignore
        return round(psutil.virtual_memory().total / (1024.0 ** 3), 2)
    except ImportError:
        pass
    except Exception:
        return 0.0

    system = platform.system()
    try:
        if system == "Linux":
            with open("/proc/meminfo", "r", encoding="utf-8") as f:
                for line in f:
                    if line.startswith("MemTotal:"):
                        kb = int(line.split()[1])
                        return round(kb / (1024.0 ** 2), 2)
        elif system == "Darwin":
            result = subprocess.run(
                ["sysctl", "-n", "hw.memsize"],
                capture_output=True, text=True, timeout=5,
            )
            if result.returncode == 0 and result.stdout.strip():
                return round(int(result.stdout.strip()) / (1024.0 ** 3), 2)
        elif system == "Windows":
            result = subprocess.run(
                ["wmic", "ComputerSystem", "get", "TotalPhysicalMemory"],
                capture_output=True, text=True, timeout=10,
            )
            if result.returncode == 0:
                for line in result.stdout.splitlines():
                    s = line.strip()
                    if s.isdigit():
                        return round(int(s) / (1024.0 ** 3), 2)
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError, ValueError):
        pass
    return 0.0


# Inference model pull list for install-time.
#
# v0.2.23 C10 consolidation (2026-05-21): this function now DERIVES its
# pull list from `select_summary_backend()` rather than maintaining its
# own VRAM/RAM ladder. Pre-consolidation, two separate ladders drifted
# (this one used `vram >= 7.5/5.0/1.0` and `ram >= 24/12`; the runtime
# summary selector used `vram >= 16/6` and `ram >= 12 AND cores >= 6`)
# meaning some hosts pulled qwen3.5:9b at 8 GB VRAM but the runtime
# selector picked gemma — wasted bandwidth + disk.
#
# Now the pull list ALWAYS matches what `select_summary_backend()` would
# pick locally, with `qwen3.5:0.8b` as the universal floor for any
# inference need. The legacy ollama_mcp/server.py was removed in v0.2.11;
# the runtime selector now lives in `templates/scripts/generate-kg-summary.py`
# (which also calls `select_summary_backend` via the consolidated path).
def _inference_models_for_capability(sysinfo: SystemInfo) -> list[str]:
    """Return inference models to pull given detected capability.

    v0.2.23 C10 consolidation: this function used to maintain its OWN
    VRAM/RAM thresholds (vram >= 7.5 / 5.0 / 1.0; ram >= 24.0 / 12.0)
    that DIVERGED from `select_summary_backend`'s thresholds (vram >=
    16.0 / 6.0; ram >= 12.0 AND cores >= 6). The drift meant some hosts
    pulled models they'd never use (qwen3.5:9b pulled at 8 GB VRAM but
    runtime selector picks gemma) — wasted bandwidth + disk. The pull
    list now derives from the SAME selector that runtime uses, so the
    set of pulled models always matches the set runtime can pick.

    Returns at minimum ["qwen3.5:0.8b"] — the floor model that fits down
    to 4 GB RAM and is the universal fallback for any inference need.
    The summary-backend's pick is added when it's a local Ollama model
    (qwen3.5:9b / gemma4:e4b). For "cli" / "openai" / None picks, only
    the floor is pulled — no local-summary model needed.
    """
    floor = "qwen3.5:0.8b"
    cores = _probe_cpu_cores()
    summary_pick = select_summary_backend(
        gpu_vram_gb=float(sysinfo.vram_gb or 0.0),
        ram_gb=float(sysinfo.ram_gb or 0.0),
        cores=cores,
        # `claude_cli_available=False` for the pull-list derivation:
        # even when the CLI is available, the runtime falls back to
        # local models if the CLI fails mid-summary, so we still want
        # the highest-tier local model available on disk as a safety
        # net. Passing False here gives us the local-model pick that
        # runtime WOULD use if CLI fell through.
        claude_cli_available=False,
        # `openai_consent=False` / `openai_key_available=False`: the
        # same reasoning — when local hardware is the fallback, we
        # need it pulled regardless of OpenAI availability.
        openai_consent=False,
        openai_key_available=False,
    )
    # Map the summary-backend ID back to its Ollama tag. CLI / OpenAI /
    # None don't add to the pull list.
    if summary_pick == _SUMMARY_BACKEND_QWEN35_9B:
        return ["qwen3.5:9b", "gemma4:e4b", floor]
    if summary_pick == _SUMMARY_BACKEND_GEMMA:
        return ["gemma4:e4b", floor]
    # summary_pick is None (no local viable) OR "cli" / "openai" (no
    # local needed for the primary path; floor still pulled as the
    # safety net for any other inference need).
    return [floor]


# ---------------------------------------------------------------------------
# v0.2.23 C10 — hardware-aware backend selectors
#
# The three pure decision functions (`select_code_embedding_backend`,
# `select_kg_embedding_backend`, `select_summary_backend`), their shared
# CPU-capability predicate (`_cpu_meets`), and the backend-ID constants
# they return were EXTRACTED to `vco_lib/embedding_selection.py` in
# v0.2.68 (behaviour-preserving move — same logic, same thresholds, same
# docstrings; pure leaf module). They are re-imported at the top of this
# file (near the other `vco_lib` imports) so:
#   - in-module callers (`_inference_models_for_capability`,
#     `_choose_embedding_config`, the AMD GPU-vendor swap, the
#     `_KG_BACKEND_ACTIVE_EMBEDDING` map) keep referencing the names
#     unqualified, exactly as before;
#   - external callers that import them from `install` (the regression
#     tests `tests/test_hardware_auto_selection.py` +
#     `tests/test_inference_pull_list_matches_summary_backend.py`, the
#     KG-summary generator) keep working unchanged — `install.<name>`
#     resolves to the re-export.
# The canonical home is now `vco_lib.embedding_selection`; see that
# module + `knowledge/concepts/hardware-tiered-backend-selection.md` for
# the per-tier rationale.
# ---------------------------------------------------------------------------


def _probe_cpu_cores() -> int:
    """Best-effort PHYSICAL CPU-core count, cross-OS.

    v0.2.49: switched from logical=True (counts SMT threads) to
    logical=False (counts physical cores) after post-update validation on a
    contributor's Windows box showed the embedding-model auto-selector tier-up'd to
    qwen3 on a host where the logical count (16) crossed the >=8
    threshold even though the actual physical cores (8) were exactly at
    the boundary — qwen3-embedding on CPU-only Ollama takes ~30s per
    embedding, so the selector should require margin, not just count
    HyperThreads. Embedding throughput on CPU is gated by physical
    arithmetic units, not thread count.

    Prefers `psutil.cpu_count(logical=False)` (returns the PHYSICAL
    core count; cross-OS, handles cgroup limits on Linux containers,
    docs explicitly: "the number of physical cores only"). Falls back to
    `os.cpu_count() // 2` (a conservative estimate assuming SMT, which
    is true on most modern Intel/AMD desktops + Apple Silicon's
    performance/efficiency split where logical count overstates
    embedding-capable cores). Returns 0 on any probe failure — the
    selectors treat 0 as "low-end CPU" (drops to the smaller-model
    tier), which is the conservative direction (better to under-spec
    than over-promise).
    """
    try:
        import psutil  # type: ignore
        n = psutil.cpu_count(logical=False)
        if n and n > 0:
            return int(n)
        # psutil returns None on some hypervisors / containers when
        # physical-core probing isn't supported. Fall through to
        # os.cpu_count() // 2 as a conservative estimate.
    except ImportError:
        pass
    except Exception:
        return 0
    try:
        n = os.cpu_count()
        if n and n > 0:
            # Conservative: assume SMT/HT, halve the logical count.
            # On non-SMT hardware this under-counts by 2x, which is the
            # safer direction (we drop to a smaller model tier).
            return max(1, int(n) // 2)
        return 0
    except Exception:
        return 0


def _lspci_has_vendor(vendor_substr: str) -> bool:
    """Linux-only: check `lspci` output for a substring (e.g. "NVIDIA",
    "AMD/ATI"). Returns False on non-Linux or any probe failure.

    Used to detect "hardware present but driver missing" — when there's
    NVIDIA silicon in the box but no nvidia-smi, the user almost
    certainly forgot to install the proprietary driver.
    """
    if platform.system() != "Linux" or not shutil.which("lspci"):
        return False
    try:
        result = subprocess.run(
            ["lspci"], capture_output=True, text=True, timeout=10,
        )
        if result.returncode != 0:
            return False
        return vendor_substr.lower() in result.stdout.lower()
    except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
        return False


def _print_gpu_hint(os_name: str) -> None:
    """Print a CPU-only fallback notice + GPU-driver install URLs when
    we couldn't find a working GPU stack. Best-effort: detects
    "hardware present but no driver" via lspci on Linux, and prints
    OS-appropriate URLs everywhere else.

    No auto-install: GPU drivers are vendor-specific, multi-step, often
    require a reboot, and add gigabytes of disk usage. We surface the
    canonical install URLs and let the user decide. The launcher GUI
    can offer an opt-in install button later.

    Reference URLs (canonical only):
      - NVIDIA Linux:    https://docs.nvidia.com/cuda/cuda-installation-guide-linux/
      - NVIDIA Windows:  https://developer.nvidia.com/cuda-downloads
      - AMD ROCm Linux:  https://rocm.docs.amd.com/projects/install-on-linux/en/latest/
    """
    print("  GPU: none detected (will use CPU)")

    has_nvidia_hw = _lspci_has_vendor("NVIDIA")
    has_amd_hw = _lspci_has_vendor("AMD/ATI") or _lspci_has_vendor("ATI Technologies")

    if has_nvidia_hw:
        print("       NVIDIA hardware detected via lspci, but nvidia-smi is missing.")
        if os_name == "Linux":
            print("       Install CUDA toolkit + driver:")
            print("         Ubuntu:   sudo apt install nvidia-driver-545 nvidia-cuda-toolkit")
            print("         Fedora:   sudo dnf install xorg-x11-drv-nvidia-cuda")
            print("         Docs:     https://docs.nvidia.com/cuda/cuda-installation-guide-linux/")
            print("       Re-run install.py after the driver is installed.")
        else:
            print("       https://developer.nvidia.com/cuda-downloads")

    if has_amd_hw:
        print("       AMD hardware detected via lspci. ROCm is optional but")
        print("       enables GPU embeddings on supported cards. Install:")
        print("         https://rocm.docs.amd.com/projects/install-on-linux/en/latest/")

    if os_name == "Windows" and not has_nvidia_hw:
        # On Windows we can't do the lspci probe; print a softer hint.
        print("       If you have an NVIDIA GPU, install drivers + CUDA:")
        print("         https://developer.nvidia.com/cuda-downloads")


def _runtime_preference_from_env() -> Optional[str]:
    """Return the user's explicit `VCT_CONTAINER_RUNTIME` preference, or
    None if unset / set to "auto".

    Canonical contract (v0.2.14, consolidated across install.py,
    launcher Rust, hooks, and the boot wrapper): values are
    case-insensitive, trimmed, and "auto" is treated as "no preference".
    Unknown values log to stderr and are ignored (fall through to
    auto-detect).

    Callers should check this BEFORE running auto-detection so the
    user's choice wins over PATH order. Audit Bug #3 (cross-OS audit,
    2026-05-17).
    """
    raw = os.environ.get("VCT_CONTAINER_RUNTIME", "").strip().lower()
    if not raw or raw == "auto":
        return None
    if raw in ("podman", "docker"):
        return raw
    print(
        f"  VCT_CONTAINER_RUNTIME={raw!r} unrecognized (expected "
        "'podman' / 'docker' / 'auto'); falling through to auto-detect.",
        file=sys.stderr,
    )
    return None


def _detect_container_runtime() -> str:
    """Detect Docker or Podman. Prefer Podman everywhere — no commercial
    license required, increasingly native on macOS/Windows.

    Honors `VCT_CONTAINER_RUNTIME=podman|docker|auto` env var as the
    user's explicit preference (v0.2.14 Bug #3 fix). If set to a
    recognized value, returns that runtime IF it's reachable; else
    falls through to auto-detect (we don't want a misconfigured env
    var to silently leave the user with no runtime — auto-detect
    finds whatever IS working).

    Returns:
      - "podman" or "docker" if a runtime is present AND its daemon
        responds to `version`/`info` (i.e. it can actually run containers).
      - "" if neither runtime is on PATH OR the daemon isn't responding.
        Caller distinguishes the two cases via `_detect_installed_runtime()`.
    """
    pref = _runtime_preference_from_env()
    if pref is not None:
        # User explicitly chose. Try ONLY that one; if it works, honor.
        # If not, fall through to auto-detect (lenient: don't strand the
        # user on a misconfigured env var). Stderr explains the fallthrough.
        if shutil.which(pref):
            try:
                result = subprocess.run(
                    [pref, "version"], capture_output=True, text=True, timeout=15,
                )
                if result.returncode == 0:
                    return pref
            except (subprocess.TimeoutExpired, OSError):
                pass
        print(
            f"  VCT_CONTAINER_RUNTIME={pref!r} not reachable; falling "
            "through to auto-detect.",
            file=sys.stderr,
        )

    candidates = ["podman", "docker"]

    for cmd in candidates:
        if shutil.which(cmd):
            try:
                result = subprocess.run(
                    [cmd, "version"], capture_output=True, text=True, timeout=15,
                )
                if result.returncode == 0:
                    return cmd
            except (subprocess.TimeoutExpired, OSError):
                continue
    return ""


def _container_runtime_reachable(container_cmd: str) -> bool:
    """Quick proactive check that the container daemon/socket is responsive.

    Used by `_start_services()` before compose-up to surface a
    cross-platform actionable hint when the runtime is installed but
    not running. Without this, compose-up takes 10-30s to fail with
    a cryptic stderr ("Cannot connect to the Docker daemon" or
    "Cannot connect to Podman socket"), which we then have to parse.

    Returns False if the runtime isn't on PATH OR `<runtime> info`
    fails. Returns True if the daemon/socket is responsive.

    Why `info` (not `version`): `version` only checks the client
    binary; `info` round-trips to the daemon/socket and exercises the
    same code path that compose-up needs. Catches stopped Docker
    Desktop on macOS, stopped podman.socket on Linux rootless,
    unstarted podman machine on Windows.
    """
    if not container_cmd or not shutil.which(container_cmd):
        return False
    try:
        result = subprocess.run(
            [container_cmd, "info"],
            capture_output=True, text=True, timeout=10,
        )
        return result.returncode == 0
    except (subprocess.TimeoutExpired, OSError):
        return False


def _podman_machine_auto_init_and_start() -> tuple[bool, str]:
    """v0.2.53 M-P1-2: auto-init then start Podman machine on macOS + Windows.

    Pre-v0.2.53 install.py asked the user to run `podman machine init`
    manually after seeing a "VM does not exist" error from `podman
    machine start`. This was friction for first-time installs.

    Sequence:
      1. `podman machine list --format json` — probe whether ANY
         machine exists. If none, run init.
      2. `podman machine init` (only when (1) showed empty list).
         This downloads ~500 MB of VM image; we use a 600s timeout.
      3. `podman machine start` — boots the VM.

    Returns (success, detail). Soft-fails on every error path; the
    caller decides whether to write a deferral.

    The init step is intentionally skipped if a machine already exists
    (we don't want to clobber a user's existing config; we just want to
    make sure SOMETHING is running). If init succeeds and start fails,
    we return the start failure rather than the init success.
    """
    # Probe: does a machine already exist?
    machine_exists = False
    try:
        list_result = subprocess.run(
            ["podman", "machine", "list", "--format", "json"],
            capture_output=True, text=True, timeout=15,
        )
        if list_result.returncode == 0:
            try:
                machines = json.loads(list_result.stdout or "[]")
                machine_exists = bool(machines and isinstance(machines, list))
            except (json.JSONDecodeError, TypeError):
                machine_exists = False
    except (subprocess.TimeoutExpired, OSError) as e:
        return False, f"podman machine list failed: {e}"

    if not machine_exists:
        # Run init. This is the long step (~500 MB download).
        print("  Podman machine not initialized; running "
              "`podman machine init` (this downloads ~500 MB; "
              "may take 2-5 min)...", flush=True)
        try:
            init_result = subprocess.run(
                ["podman", "machine", "init"],
                capture_output=True, text=True, timeout=600,
            )
        except subprocess.TimeoutExpired:
            return False, (
                "podman machine init timed out after 10 min; "
                "network down or VM image download blocked. "
                "Run `podman machine init` manually and re-run install.py."
            )
        except OSError as e:
            return False, f"podman machine init failed: {e}"
        if init_result.returncode != 0:
            return False, (
                f"podman machine init exited {init_result.returncode}: "
                f"{init_result.stderr.strip()[:300]}"
            )
        print("  Podman machine initialized.", flush=True)

    # Now start.
    try:
        start_result = subprocess.run(
            ["podman", "machine", "start"],
            capture_output=True, text=True, timeout=120,
        )
    except (subprocess.TimeoutExpired, OSError) as e:
        return False, f"podman machine start failed: {e}"
    if start_result.returncode != 0:
        # If machine is already running, that's success.
        stderr = (start_result.stderr or "").strip()[:300]
        if "already running" in stderr.lower():
            return True, "podman machine already running"
        return False, (
            f"podman machine start exited {start_result.returncode}: "
            f"{stderr}"
        )
    return True, "podman machine started"


def _try_start_podman_daemon() -> tuple[bool, str]:
    """v0.2.51 Bug G: auto-start the Podman daemon on a binary-present-but-
    daemon-stopped condition.

    Per-OS recipes:
      * Linux: ``systemctl --user start podman.socket`` (rootless). The
        --user scope mirrors the standard rootless Podman setup. Falls
        back to a no-op if systemctl is missing (e.g. distros without
        systemd: musl-based minimal images, Alpine on bare metal).
      * macOS: ``podman machine start``. Boots the QEMU VM that Podman
        runs containers in. First-time users need ``podman machine init``
        first — which we DON'T do automatically (downloads ~500 MB,
        consents to disk space; out of scope for an auto-start helper).
      * Windows: ``podman machine start``. Same as macOS (WSL2 VM).

    Returns:
        Tuple of ``(success, detail)``:
          * ``success=True``: daemon is now responsive to ``podman info``.
          * ``success=False``: start command failed or daemon never became
            responsive within the timeout. ``detail`` carries the failure
            reason (subprocess stderr or timeout description) for the
            caller's deferral entry.

    Soft-fails throughout: never raises. The 30-second
    post-start probe gives the socket time to bind without making the
    install hang indefinitely on a misconfigured machine.

    Why explicit start instead of waiting for compose-up to fail:
    compose-up's failure surface is a cryptic "Cannot connect to Podman
    socket" stderr that takes 10-30s to manifest. Surfacing the start +
    a clear deferral upfront saves 10-30s and gives the user an
    actionable next step.
    """
    os_name = platform.system()

    if not shutil.which("podman"):
        return False, "podman binary not on PATH"

    if os_name == "Linux":
        if not shutil.which("systemctl"):
            return False, "systemctl not on PATH (distro without systemd)"
        try:
            result = subprocess.run(
                ["systemctl", "--user", "start", "podman.socket"],
                capture_output=True, text=True, timeout=15,
            )
        except (subprocess.TimeoutExpired, OSError) as e:
            return False, f"systemctl invocation failed: {e}"
        if result.returncode != 0:
            return False, (
                f"systemctl --user start podman.socket exited "
                f"{result.returncode}: {result.stderr.strip()[:200]}"
            )
    elif os_name in ("Darwin", "Windows"):
        # v0.2.53 M-P1-2: auto-init then start on macOS + Windows.
        # Pre-v0.2.53 we asked the user to run `podman machine init`
        # themselves — but the recipe is well-documented and the typical
        # first-time install dropped to a deferral here, blocking
        # container setup until the user found the right command.
        # Now we run init→start automatically; the user only sees the
        # deferral if BOTH steps fail.
        ok, detail = _podman_machine_auto_init_and_start()
        if not ok:
            return False, detail
    else:
        return False, f"unsupported OS '{os_name}'"

    # Post-start probe: give the socket time to bind. systemctl --user
    # start returns immediately, but the socket may need a beat. Same
    # for podman machine start (the VM boot completes async).
    deadline = time.monotonic() + 30.0
    while time.monotonic() < deadline:
        if _container_runtime_reachable("podman"):
            return True, "daemon responsive"
        time.sleep(1.0)

    return False, "podman daemon did not become responsive within 30s"


def _try_start_docker_daemon() -> tuple[bool, str]:
    """v0.2.54 (container-scout C-RT-7): best-effort auto-start of the
    Docker daemon — closes the auto-heal asymmetry where Podman got
    socket auto-start (v0.2.51) + machine auto-init/start (v0.2.53)
    while Docker users only got a printed hint.

    OS matrix:
      - macOS:   ``open -a Docker`` — launches Docker Desktop. No sudo,
                 no GUI prompt beyond Docker Desktop's own startup.
      - Windows: shell-start ``Docker Desktop.exe`` from its canonical
                 install locations.
      - Linux:   NOT automated. ``sudo systemctl start docker`` needs an
                 interactive password we don't shoulder in a pre-flight
                 (same rationale as the original hint). Returns False
                 with the manual recipe.

    After a successful launch attempt, polls ``docker info`` for up to
    60s (Docker Desktop's VM boot is slow). Soft-fail throughout — the
    caller falls back to the printed hint.
    """
    os_name = platform.system()
    if not shutil.which("docker"):
        return False, "docker binary not on PATH"

    if os_name == "Darwin":
        try:
            result = subprocess.run(
                ["open", "-a", "Docker"],
                capture_output=True, text=True, timeout=15,
            )
        except (subprocess.TimeoutExpired, OSError) as e:
            return False, f"`open -a Docker` failed: {e}"
        if result.returncode != 0:
            return False, (
                f"`open -a Docker` exited {result.returncode}: "
                f"{(result.stderr or '').strip()[:200]}"
            )
    elif os_name == "Windows":
        candidates = [
            Path(os.environ.get("ProgramFiles", r"C:\Program Files"))
            / "Docker" / "Docker" / "Docker Desktop.exe",
            Path(os.environ.get("LOCALAPPDATA", "")) / "Docker" / "Docker Desktop.exe",
        ]
        exe = next((c for c in candidates if c.is_file()), None)
        if exe is None:
            return False, (
                "Docker Desktop.exe not found at the canonical install "
                "locations; start Docker Desktop from the Start Menu."
            )
        try:
            # Detached start — Docker Desktop is a GUI app; don't block.
            # Handle kept in _DETACHED_CHILDREN: suppresses the Popen
            # destructor's ResourceWarning for a child that outlives us.
            _DETACHED_CHILDREN.append(
                subprocess.Popen(
                    ["cmd", "/c", "start", "", str(exe)],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                )
            )
        except OSError as e:
            return False, f"could not launch Docker Desktop: {e}"
    else:
        return False, (
            "Docker daemon auto-start is not automated on Linux "
            "(requires sudo): run `sudo systemctl start docker`."
        )

    deadline = time.monotonic() + 60.0
    while time.monotonic() < deadline:
        if _container_runtime_reachable("docker"):
            return True, "daemon responsive"
        time.sleep(2.0)
    return False, "docker daemon did not become responsive within 60s"


def _emit_podman_daemon_start_failed_deferral(
    deferral_report: Any,
    *,
    detail: str,
) -> None:
    """v0.2.51 Bug G: write a deferral when auto-start of the Podman daemon
    fails.

    Mirrors the shape of :func:`_emit_launcher_restart_deferral` and other
    deferral emitters. The launcher GUI renders deferral entries as
    sticky banners in its post-install summary; this entry is the user's
    explicit signal that container setup cannot proceed until they start
    the daemon manually.

    Safe to call with ``deferral_report=None`` (no-op) so callers without
    a report in scope don't have to wire one through.
    """
    if deferral_report is None:
        return

    os_name = platform.system()
    if os_name == "Linux":
        manual_cmd = (
            "# Start the rootless Podman socket:\n"
            "systemctl --user start podman.socket\n"
            "# Verify it's responsive, then re-run:\n"
            "podman info >/dev/null && python install.py --update"
        )
    elif os_name == "Darwin":
        manual_cmd = (
            "# First time: initialize the Podman VM (~500 MB download):\n"
            "podman machine init\n"
            "# Then start it (~20-30s):\n"
            "podman machine start\n"
            "# Verify, then re-run:\n"
            "podman info >/dev/null && python install.py --update"
        )
    elif os_name == "Windows":
        manual_cmd = (
            "# Ensure WSL2 is installed first (one-time):\n"
            "wsl --install\n"
            "# First time: initialize the Podman machine:\n"
            "podman machine init\n"
            "# Then start it:\n"
            "podman machine start\n"
            "# Verify, then re-run:\n"
            "podman info; python install.py --update"
        )
    else:
        manual_cmd = (
            "# Start the Podman daemon for your platform, then re-run:\n"
            "podman info && python install.py --update"
        )

    try:
        entry = DeferralEntry(
            condition_id="podman_daemon_start_failed",
            title="Podman daemon could not be started automatically",
            detected=(
                f"install.py attempted to auto-start the Podman daemon "
                f"(per-OS recipe — systemctl --user start podman.socket on "
                f"Linux; podman machine start on macOS/Windows) but the "
                f"start command failed or the daemon never became "
                f"responsive. Detail: {detail}"
            ),
            why_deferred=(
                "Starting the Podman daemon requires either systemd-user "
                "(Linux) or an initialized podman machine (macOS/Windows). "
                "install.py won't run podman machine init unattended "
                "because it downloads a multi-hundred-MB VM image and the "
                "user should consent to the disk usage. After manual "
                "intervention, re-run install.py to complete container setup."
            ),
            command_to_apply=manual_cmd,
            severity="warning",
            kg_node_refs=[],
        )
        deferral_report.add_entry(entry)
    except Exception as exc:  # noqa: BLE001 — soft-fail by design
        _log_install_event(
            "container_runtime", "warn",
            f"could not emit podman_daemon_start_failed deferral: {exc}",
        )


def _detect_installed_runtime() -> str:
    """Lightweight presence check — returns the FIRST container-runtime
    binary on PATH regardless of whether its daemon is running.

    Honors `VCT_CONTAINER_RUNTIME=podman|docker|auto` env var (v0.2.14
    Bug #3 fix). If the explicit preference is installed (even if the
    daemon isn't responsive), it wins over the auto-detect order.

    Use case: `_detect_container_runtime()` returned "" (no working
    runtime) but we want to give a better message than "install Podman/
    Docker" if one IS installed, just stopped. On Windows specifically,
    Docker Desktop ships `docker.exe` on PATH but `docker version` fails
    until the user opens Docker Desktop from the Start Menu.

    Returns "" when neither binary is on PATH.
    """
    pref = _runtime_preference_from_env()
    if pref is not None and shutil.which(pref):
        return pref
    for cmd in ("podman", "docker"):
        if shutil.which(cmd):
            return cmd
    return ""


def _nvidia_container_toolkit_install_hint() -> str:
    """Return a pkgmgr-aware install hint for nvidia-container-toolkit.

    nvidia-container-toolkit is NOT in default repos for apt (Debian/Ubuntu),
    zypper (openSUSE), or apk (Alpine) — the user must add NVIDIA's
    libnvidia-container repo first. dnf (Fedora) and AUR (Arch) DO ship it
    directly. We surface the right command per-distro so the user can copy
    one line instead of paging through NVIDIA's install guide.

    Returns the formatted hint as a multi-line string (indented for
    embedding in the parent prompt), or an empty string when no
    recognised pkgmgr is on PATH (caller falls back to URL only).

    Refs: linux-comprehensive-audit-2026-06-10.md §P0-L7 / §P1-L4
    """
    if shutil.which("apt-get"):
        # apt: add NVIDIA's libnvidia-container repo first, then install.
        # We give the full curl|tee + apt-get sequence as one runnable
        # block — the user can paste it into a terminal.
        return (
            "      # apt (Debian/Ubuntu) — add NVIDIA's libnvidia-container repo first:\n"
            "      curl -fsSL https://nvidia.github.io/libnvidia-container/gpgkey | \\\n"
            "        sudo gpg --dearmor -o /usr/share/keyrings/nvidia-container-toolkit-keyring.gpg\n"
            "      curl -s -L https://nvidia.github.io/libnvidia-container/stable/deb/nvidia-container-toolkit.list | \\\n"
            "        sed 's#deb https://#deb [signed-by=/usr/share/keyrings/nvidia-container-toolkit-keyring.gpg] https://#g' | \\\n"
            "        sudo tee /etc/apt/sources.list.d/nvidia-container-toolkit.list\n"
            "      sudo apt-get update && sudo apt-get install -y nvidia-container-toolkit"
        )
    if shutil.which("dnf"):
        # dnf: nvidia-container-toolkit ships in Fedora's RPM Fusion
        # nonfree repo (already enabled if user installed nvidia-driver).
        # The NVIDIA libnvidia-container repo is also available for
        # RHEL/CentOS Stream.
        return (
            "      # dnf (Fedora / RHEL) — add NVIDIA's libnvidia-container repo if needed:\n"
            "      curl -s -L https://nvidia.github.io/libnvidia-container/stable/rpm/nvidia-container-toolkit.repo | \\\n"
            "        sudo tee /etc/yum.repos.d/nvidia-container-toolkit.repo\n"
            "      sudo dnf install -y nvidia-container-toolkit"
        )
    if shutil.which("pacman"):
        # Arch: nvidia-container-toolkit lives in the AUR. We point the
        # user at an AUR helper rather than pacman directly — the choice
        # of yay/paru/etc. is user preference, so we give the canonical
        # AUR URL too.
        return (
            "      # Arch — nvidia-container-toolkit is in the AUR:\n"
            "      yay -S nvidia-container-toolkit      # or paru -S, or manual makepkg\n"
            "      # AUR page: https://aur.archlinux.org/packages/nvidia-container-toolkit"
        )
    if shutil.which("zypper"):
        # openSUSE: add NVIDIA's libnvidia-container repo, then zypper
        # install. Same curl + tee shape as apt/dnf but using zypper's
        # repo file syntax.
        return (
            "      # zypper (openSUSE/SLES) — add NVIDIA's libnvidia-container repo:\n"
            "      sudo zypper ar -f https://nvidia.github.io/libnvidia-container/stable/rpm/nvidia-container-toolkit.repo\n"
            "      sudo zypper install -y nvidia-container-toolkit"
        )
    if shutil.which("apk"):
        # Alpine: nvidia-container-toolkit is in the testing repo. Most
        # NVIDIA-on-Alpine setups also need musl-compatible NVIDIA
        # libraries — point the user at the upstream docs for the
        # current procedure rather than risk giving stale advice.
        return (
            "      # apk (Alpine) — nvidia-container-toolkit is in the testing repo,\n"
            "      # and Alpine + NVIDIA needs musl-compatible drivers. See:\n"
            "      #   https://wiki.alpinelinux.org/wiki/Nvidia\n"
            "      sudo apk add --no-cache nvidia-container-toolkit"
        )
    return ""


def _ensure_nvidia_cdi_spec_for_podman() -> None:
    """Verify NVIDIA Container Toolkit's auto-refresh CDI service is active.

    Background (revised 2026-05-08):

    Earlier versions of this function wrote `/etc/cdi/nvidia.yaml` directly
    via `sudo nvidia-ctk cdi generate --output=/etc/cdi/nvidia.yaml`. That
    was the right advice for nvidia-container-toolkit < 1.18, but it's
    actively harmful in 2026:

      1. NVIDIA Container Toolkit ≥ 1.18.0 ships `nvidia-cdi-refresh.path`
         + `nvidia-cdi-refresh.service` systemd units that AUTO-regenerate
         the CDI spec on every driver install/upgrade. They write to
         `/var/run/cdi/nvidia.yaml` (a runtime tmpfs path).

      2. Podman reads `/etc/cdi/` BEFORE `/var/run/cdi/`. So a manually
         written `/etc/cdi/nvidia.yaml` SHADOWS the auto-refreshed one.

      3. After an apt/dnf-driven driver upgrade, the manual `/etc/cdi/`
         spec keeps referencing the OLD driver's library files (e.g.
         libEGL_nvidia.so.590.48.01). Those files were deleted by the
         driver upgrade. Result: every GPU container fails to start with
         `runc: failed to fulfil mount request: ... no such file`.

      4. We hit this exact bug on the dev machine 2026-05-07 — entire
         compose stack came down because ollama/code_embed couldn't mount
         a stale lib path. See `.claude/context/handoff-2026-05-08-*.md`.

    Correct behaviour now:
      - DO NOT write `/etc/cdi/nvidia.yaml` from this installer.
      - DELETE any pre-existing `/etc/cdi/nvidia.yaml` left over from prior
        installs of VCO (they are time-bombs).
      - Verify the system's auto-refresh service is present + enabled.
        If toolkit < 1.18 is installed (no auto-refresh units): warn user
        to upgrade. If units exist but are disabled: print the enable cmd.

    No /etc/cdi/ writes. Ever. The launcher's startup-time drift detector
    is the second line of defense if the user somehow re-creates a stale
    spec.
    """
    if platform.system() != "Linux":
        # macOS Podman runs in a VM; CDI generation happens inside
        # the VM via Podman Machine, not on the host. Skip for now.
        return

    if not shutil.which("nvidia-ctk"):
        # v0.2.53 (Track G2 / L-P0-7): surface a pkgmgr-aware install
        # hint when nvidia-container-toolkit is missing. Previously the
        # message pointed at NVIDIA's 4-page install-guide and left the
        # user to figure out the right apt/dnf line themselves.
        #
        # Note: nvidia-container-toolkit is NOT in distro default repos
        # for apt/zypper/apk — the user must add NVIDIA's libnvidia-
        # container repo first. dnf (Fedora) and pacman (AUR) DO ship it
        # directly in default repos. We mirror this in the hint so users
        # aren't told to run a command that will fail.
        print(
            "  [!] Podman + NVIDIA: `nvidia-ctk` not on PATH. Install the "
            "NVIDIA Container Toolkit (≥ 1.18.0 strongly recommended):"
        )
        hint = _nvidia_container_toolkit_install_hint()
        if hint:
            print(hint)
        print(
            "      Reference: https://docs.nvidia.com/datacenter/cloud-native/container-toolkit/install-guide.html\n"
            "      (then re-run install — compose-up will fail until CDI is set up)"
        )
        return

    # Step 1: surface + offer to delete any stale `/etc/cdi/nvidia.yaml`
    # left by a previous install of VCO or by a user following old docs.
    # Stale specs SHADOW the auto-refreshed `/var/run/cdi/nvidia.yaml`
    # and break GPU containers after every driver update.
    cdi_etc = Path("/etc/cdi/nvidia.yaml")
    if cdi_etc.exists():
        print(
            "  [!] Found stale /etc/cdi/nvidia.yaml — this shadows the\n"
            "      system's auto-refreshed /var/run/cdi/nvidia.yaml and\n"
            "      breaks GPU containers after driver updates. Remove with:\n"
            "          sudo rm /etc/cdi/nvidia.yaml\n"
            "      (run after install completes; the auto-refresh service\n"
            "      will keep /var/run/cdi/nvidia.yaml fresh from now on)"
        )

    # Step 2: verify nvidia-cdi-refresh.{path,service} exist + enabled.
    # systemctl `is-enabled` returns 0 only when the unit is active in the
    # boot manifest. Anything else means user needs to fix it.
    try:
        result = subprocess.run(
            ["systemctl", "is-enabled", "nvidia-cdi-refresh.path"],
            capture_output=True, text=True, timeout=5,
        )
        if result.returncode == 0:
            # Auto-refresh is on. Nothing more to do.
            print("    ✓ NVIDIA Container Toolkit auto-refresh active "
                  "(nvidia-cdi-refresh.path enabled)")
            return
    except (FileNotFoundError, subprocess.TimeoutExpired):
        # systemctl not on PATH (highly unusual on a Linux host with
        # podman) or hung. Fall through to install hint.
        pass

    print(
        "  [!] nvidia-cdi-refresh systemd units are not enabled. They ship\n"
        "      with NVIDIA Container Toolkit ≥ 1.18.0 and auto-regenerate\n"
        "      the CDI spec on every driver upgrade. To enable:\n"
        "          sudo systemctl enable --now nvidia-cdi-refresh.path\n"
        "          sudo systemctl enable --now nvidia-cdi-refresh.service\n"
        "      If your nvidia-container-toolkit version is < 1.18, upgrade\n"
        "      first. Without these units, you must manually regenerate the\n"
        "      CDI spec after every NVIDIA driver upgrade or GPU containers\n"
        "      will fail to start."
    )


# ---------------------------------------------------------------------------
# v0.2.53 L-P0-3: SELinux enforcement detection + :Z bind-mount label hint
# ---------------------------------------------------------------------------
def _detect_selinux_enforcing() -> bool:
    """Return True iff SELinux is currently in `Enforcing` mode.

    Detection chain (priority order):
      1. `getenforce` returns "Enforcing" — canonical signal on Fedora /
         RHEL / CentOS Stream / Rocky / Alma. Trusted when present.
      2. `/sys/fs/selinux/enforce` reads "1" — fallback for minimal
         containers / chrooted environments where `getenforce` may not
         be on PATH.
      3. Any failure (binary missing, sysfs unreadable, file is "0",
         non-Linux OS) → False (assume non-SELinux distro: Ubuntu, Arch,
         openSUSE without enforcement, etc.).

    The semantics are intentionally conservative: a False return is
    treated by callers as "no SELinux label fix needed". Only return
    True when we are certain SELinux is enforcing AND will reject bare
    bind mounts inside Podman/Docker.

    No subprocess on non-Linux. Best-effort soft-fail throughout.
    """
    if platform.system() != "Linux":
        return False

    # Step 1: getenforce (the canonical signal on Fedora/RHEL family).
    getenforce = shutil.which("getenforce")
    if getenforce:
        try:
            result = subprocess.run(
                [getenforce], capture_output=True, text=True, timeout=5,
            )
            if result.returncode == 0:
                # `getenforce` prints exactly one of: Enforcing, Permissive,
                # Disabled. Case sensitive on stock RHEL.
                return result.stdout.strip().lower() == "enforcing"
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError):
            pass  # Fall through to sysfs probe.

    # Step 2: sysfs fallback for minimal containers without selinux-utils.
    # /sys/fs/selinux/enforce is "1" when enforcing, "0" when permissive,
    # absent entirely when SELinux is not compiled into the kernel.
    try:
        enforce_path = Path("/sys/fs/selinux/enforce")
        if enforce_path.is_file():
            return enforce_path.read_text(encoding="utf-8").strip() == "1"
    except (OSError, UnicodeDecodeError):
        pass

    return False


def _print_selinux_bind_mount_hint() -> None:
    """Print the SELinux `:Z` / `:z` bind-mount remediation hint.

    Called from the GPU/container detection block when SELinux is
    detected as enforcing. Covers the most common Fedora/RHEL footgun:
    Podman starts containers cleanly, but any volume bind-mount fails
    with "Permission denied" inside the container because SELinux blocks
    cross-context access.

    The fix is one of:
      - `:Z` suffix on the host path (private label — recommended for
        single-container access).
      - `:z` suffix (shared label — only if multiple containers need
        access).

    We don't auto-rewrite compose files here because the launcher's
    volume migration (commands/volumes.rs) owns the bind-mount override
    surface; rewriting from install.py would race with launcher edits.
    Instead we print a clear pointer so the user can re-run the volume
    migration with SELinux awareness.

    Idempotent: no-op when called more than once in a single run
    (deduped by a module-level flag).
    """
    global _SELINUX_HINT_PRINTED  # noqa: PLW0603
    if globals().get("_SELINUX_HINT_PRINTED", False):
        return
    _SELINUX_HINT_PRINTED = True

    print(
        "  [!] SELinux detected as Enforcing (typical on Fedora / RHEL /\n"
        "      CentOS Stream / Rocky / Alma).\n"
        "      Podman + SELinux requires the `:Z` (or `:z`) label suffix\n"
        "      on every bind-mount volume, or the container sees\n"
        "      \"Permission denied\" on every file inside the mount.\n"
        "      Action — pick ONE:\n"
        "        (a) Use the orchestrator's NAMED-volume layout (the\n"
        "            install.py default): no bind mounts, no label\n"
        "            problem. Don't run the launcher's \"Migrate\n"
        "            volumes to bind-mount\" workflow.\n"
        "        (b) If you already migrated to bind-mounts: append\n"
        "            `:Z` to each `device:` host path in\n"
        "            `infrastructure/docker-compose.override.yml`, OR\n"
        "            relabel the host dirs with:\n"
        "                sudo chcon -Rt container_file_t \\\n"
        "                    ~/podman_volumes/weaviate \\\n"
        "                    ~/podman_volumes/ollama \\\n"
        "                    ~/podman_volumes/code_embed\n"
        "        (c) Temporarily set SELinux to permissive while testing:\n"
        "                sudo setenforce 0          # session-only\n"
        "                # /etc/selinux/config for permanent change.\n"
        "      Without one of these, podman compose-up will succeed but\n"
        "      the services will fail readiness checks with file-IO\n"
        "      errors on first access.")


# Module-level dedup flag for the SELinux hint printer.
_SELINUX_HINT_PRINTED: bool = False


# ---------------------------------------------------------------------------
# v0.2.53 L-P0-8: render / video group remediation hint
# ---------------------------------------------------------------------------
def _user_in_group(group_name: str) -> bool:
    """Return True iff the current user is a member of the given Unix
    group. Linux-only check; returns False on Windows and macOS (where
    the GPU permission model differs).

    Uses the `grp` stdlib module on POSIX (no subprocess needed). Soft-
    fails to False on any unexpected error — caller treats this as
    "needs hint", which is the safer default.
    """
    if platform.system() != "Linux":
        return False
    try:
        import grp  # POSIX-only stdlib module.
        gr = grp.getgrnam(group_name)
        user = os.environ.get("USER") or os.environ.get("LOGNAME") or ""
        if not user:
            try:
                import pwd  # noqa: PLC0415
                user = pwd.getpwuid(os.getuid()).pw_name
            except (KeyError, AttributeError, ImportError):
                return False
        return user in gr.gr_mem
    except (KeyError, ImportError, AttributeError, OSError):
        return False


def _print_render_video_group_hint() -> None:
    """Print the GPU-render-node group remediation hint.

    When the launcher's `webkit_preflight` runs and the user is missing
    `render` / `video` group membership, access to `/dev/dri/renderD128`
    (and friends) raises EACCES; the preflight silently skips GPU-
    accelerated WebKit and the user wonders why the launcher chrome is
    slow. The fix is one `usermod` + a re-login, but the user must KNOW
    that's the right knob.

    This helper is called from install.py's GPU detection step only on
    Linux when:
      - We detected an NVIDIA OR AMD OR Intel GPU on the box (lspci
        positive), AND
      - The current user is NOT in BOTH `render` and `video` groups.

    Idempotent (deduped by module flag) so repeated GPU probes don't
    spam the user.
    """
    global _RENDER_GROUP_HINT_PRINTED  # noqa: PLW0603
    if globals().get("_RENDER_GROUP_HINT_PRINTED", False):
        return
    _RENDER_GROUP_HINT_PRINTED = True

    in_render = _user_in_group("render")
    in_video = _user_in_group("video")

    if in_render and in_video:
        return  # Already in both — nothing to suggest.

    missing = []
    if not in_render:
        missing.append("render")
    if not in_video:
        missing.append("video")
    missing_csv = ",".join(missing)

    print(
        f"  [!] GPU detected, but your user is NOT in the `{missing_csv}`\n"
        f"      group{'s' if len(missing) > 1 else ''}. This blocks the launcher's WebKit GPU\n"
        f"      acceleration probe (EACCES on /dev/dri/renderD128) and any\n"
        f"      containerized GPU workload that re-bind-mounts the same\n"
        f"      device node. Fix:\n"
        f"          sudo usermod -aG {missing_csv} $USER\n"
        f"          newgrp {missing[0]}     # or log out + back in for it\n"
        f"                                # to take effect in your shell\n"
        f"      Without this, `webkit_preflight` will soft-skip and your\n"
        f"      launcher window may flicker / fall back to software\n"
        f"      rendering at boot.")


# Module-level dedup flag for the render/video group hint printer.
_RENDER_GROUP_HINT_PRINTED: bool = False


def _prompt_install_container_runtime(args: argparse.Namespace) -> bool:
    """Prompt the user to install Podman/Docker when neither is detected.

    Returns True iff an auto-install attempt completed successfully. Caller
    must re-detect afterward (PATH refresh, etc.).

    OS matrix:
      - Linux:   We CAN auto-install via apt/dnf/pacman. Prompt y/n;
                 on yes, run the package-manager command (sudo prompt
                 surfaces in the controlling terminal).
      - macOS:   URL only. Homebrew may not be present; Docker Desktop
                 needs kernel-extension consent on Apple Silicon. We
                 don't shoulder that.
      - Windows: URL only. winget on Podman requires WSL2 + admin
                 elevation; Docker Desktop installer is a separate
                 download. Print canonical URLs and exit.

    Honors `--yes` / non-TTY by skipping the prompt and printing
    instructions only (treated as a decline). This matches the spec's
    "fall back to manual install" rule for non-interactive runs.

    Refs:
      - Podman install:   https://podman.io/getting-started/installation
      - Docker Desktop:   https://www.docker.com/products/docker-desktop
      - Homebrew:         https://brew.sh
    """
    os_name = platform.system()

    # First: distinguish "not installed" from "installed but daemon
    # not running". On Windows in particular Docker Desktop installs
    # docker.exe on PATH but the daemon stays stopped until the user
    # opens Docker Desktop from the Start Menu / system tray; calling
    # `docker version` fails with the same exit code as truly-absent
    # docker, which made our earlier message misleading. Reported
    # 2026-04-28: "PC had docker, but not currently running".
    installed = _detect_installed_runtime()
    if installed:
        print(f"\n[!] {installed} is installed but its daemon isn't responding.")
        if os_name == "Windows" and installed == "docker":
            print("    Open Docker Desktop from the Start Menu or system tray,")
            print("    wait for the whale icon to settle (~30 seconds), then re-run install.")
        elif os_name == "Darwin" and installed == "docker":
            print("    Open Docker Desktop from /Applications, wait for the whale")
            print("    icon to settle (~30 seconds), then re-run install.")
        elif installed == "podman":
            print("    Start the Podman machine (Linux: systemctl --user start podman.socket;")
            print("    macOS / Windows: podman machine start), then re-run install.")
        else:
            print("    Start the Docker daemon (`sudo systemctl start docker` on Linux),")
            print("    then re-run install.")
        print("    Or re-run with --no-containers to skip container setup.")
        return False

    print("\n[!] No container runtime found. The orchestrator needs Podman or Docker.")

    non_interactive = bool(args.yes) or not sys.stdin.isatty() or bool(args.quiet)

    if os_name == "Linux":
        # Detect package manager first; we only prompt for managers we
        # can actually drive.
        #
        # v0.2.53 (Track G2 / L-P0-1): added zypper (openSUSE/SLES) +
        # apk (Alpine) branches. Previously, users on those distros got
        # "No supported package manager found" and had to install Podman
        # manually even though post-install-launcher.sh:288 already
        # advertised zypper+apk as detected — surface-level parity gap.
        if shutil.which("apt-get"):
            cmd = ["sudo", "apt-get", "install", "-y", "podman"]
            update_cmd = ["sudo", "apt-get", "update"]
            label = "apt (Debian/Ubuntu)"
        elif shutil.which("dnf"):
            cmd = ["sudo", "dnf", "install", "-y", "podman"]
            update_cmd = None
            label = "dnf (Fedora/RHEL)"
        elif shutil.which("pacman"):
            cmd = ["sudo", "pacman", "-S", "--noconfirm", "podman"]
            update_cmd = None
            label = "pacman (Arch)"
        elif shutil.which("zypper"):
            # `zypper install -y` is the non-interactive flag. SLES/Leap
            # ship podman in the standard repos.
            cmd = ["sudo", "zypper", "install", "-y", "podman"]
            update_cmd = None
            label = "zypper (openSUSE/SLES)"
        elif shutil.which("apk"):
            # Alpine: `apk add` is non-interactive by default. Podman
            # lives in the community repo; if it's not enabled, this
            # surfaces as `ERROR: unable to select packages: podman` —
            # acceptable failure mode.
            cmd = ["sudo", "apk", "add", "--no-cache", "podman"]
            update_cmd = ["sudo", "apk", "update"]
            label = "apk (Alpine)"
        else:
            print("    No supported package manager found "
                  "(apt/dnf/pacman/zypper/apk).")
            print("    Install Podman manually: https://podman.io/getting-started/installation")
            print("    Or Docker:               https://docs.docker.com/get-docker/")
            return False

        print(f"    Detected {label}. Will run:")
        if update_cmd:
            print(f"      {' '.join(update_cmd)}")
        print(f"      {' '.join(cmd)}")
        print("    (You'll be prompted for your sudo password.)")

        if non_interactive:
            print("    Non-interactive mode — skipping auto-install.")
            print("    Re-run interactively, or install manually then re-run install.py.")
            return False

        try:
            reply = input("    Install podman now? [Y/n] ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print("\n    Aborted.")
            return False
        if reply and reply[0] != "y":
            print("    Skipped. Install manually then re-run install.py.")
            return False

        try:
            if update_cmd:
                subprocess.run(update_cmd, check=True)
            subprocess.run(cmd, check=True)
        except subprocess.CalledProcessError as e:
            print(f"    Package install failed (exit {e.returncode}).")
            print("    Install manually: https://podman.io/getting-started/installation")
            return False
        except FileNotFoundError:
            print("    sudo not found. Install Podman manually:")
            print("      https://podman.io/getting-started/installation")
            return False
        return True

    if os_name == "Darwin":
        # Homebrew install requires Homebrew already present. Even with
        # brew, the user still needs `podman machine init && podman
        # machine start` (Podman runs in a VM on macOS). Don't try to
        # automate that — surface the canonical instructions.
        print("    Install one of (we recommend Podman):")
        print("      brew install podman                                     # if Homebrew is installed")
        print("      Then: podman machine init && podman machine start")
        print("    Or download:")
        print("      Podman:        https://podman.io/getting-started/installation")
        print("      Docker Desktop: https://www.docker.com/products/docker-desktop")
        print("      Homebrew:      https://brew.sh   (if not already installed)")
        return False

    if os_name == "Windows":
        # Podman on Windows requires WSL2 underneath; winget can install
        # the Podman binary but not the WSL2 prerequisite + admin
        # elevation. Docker Desktop is a separate installer. Manual.
        print("    Install one of (we recommend Podman):")
        print("      winget install RedHat.Podman                            # if winget is available")
        print("      Then: podman machine init && podman machine start")
        print("    Or download:")
        print("      Podman:         https://podman.io/getting-started/installation")
        print("      Docker Desktop: https://www.docker.com/products/docker-desktop")
        print("    Note: Podman on Windows requires WSL2.")
        print("      WSL2 setup:    https://learn.microsoft.com/windows/wsl/install")
        return False

    # Other / unknown OS — print generic guidance.
    print(f"    Unrecognized OS '{os_name}'. Install Podman or Docker manually:")
    print("      Podman:         https://podman.io/getting-started/installation")
    print("      Docker:         https://docs.docker.com/get-docker/")
    return False


def _print_system_info(sysinfo: SystemInfo) -> None:
    pass  # Already printed in _detect_system


def _find_lean_ctx_binary() -> str | None:
    """Locate lean-ctx beyond PATH (cross-OS).

    `shutil.which` only checks PATH, so users who installed lean-ctx via
    `cargo install lean-ctx` (lands at ~/.cargo/bin) but whose shell PATH
    doesn't include ~/.cargo/bin (cargo's installer adds it to ~/.profile
    but `bash first-install.sh` from a fresh terminal may not have sourced
    it yet) saw 'not installed' even though the binary is right there.
    Mirrors the known-binary-path probe pattern in
    post-install-launcher.sh's _ensure_path_for_tool helper.

    Cross-OS:
      * Linux/macOS: probes the cargo + brew + standard system paths.
      * Windows: probes the cargo install dir + scoop/chocolatey shims.
        Tries both ``lean-ctx`` and ``lean-ctx.exe`` since Windows
        cargo-installed binaries get the ``.exe`` suffix.
    """
    on_path = shutil.which("lean-ctx")
    if on_path:
        return on_path

    is_windows = sys.platform == "win32"
    home = Path.home()

    # Per-OS candidate list. Both forms are tried so a Linux user with a
    # weird WSL2 setup or a Windows user running this script under WSL2
    # still gets found.
    if is_windows:
        candidates: list[Path] = [
            home / ".cargo" / "bin" / "lean-ctx.exe",
            home / "scoop" / "shims" / "lean-ctx.exe",
            home / "scoop" / "apps" / "lean-ctx" / "current" / "lean-ctx.exe",
            Path(os.environ.get("ProgramData", r"C:\ProgramData"))
            / "chocolatey" / "bin" / "lean-ctx.exe",
            Path(os.environ.get("ProgramFiles", r"C:\Program Files"))
            / "lean-ctx" / "lean-ctx.exe",
        ]
    else:
        # D-11 (v0.2.73) CANONICAL POSIX candidate order. MUST MATCH the
        # fallback probe list in ``templates/hooks/lean-ctx-rewrite.sh``
        # (its `command -v lean-ctx` PATH check falls through to THESE same
        # paths, in this order). The two used to disagree — install could
        # conclude "installed" for a ``~/.cargo/bin`` binary that the
        # hook-shell PATH lacked, so compression silently never activated.
        # Keep the two lists identical; if you add/remove a path here, mirror
        # it in the hook (and vice-versa). Mirror-don't-fork (CLAUDE.md names
        # binary-discovery order as the canonical example).
        candidates = [
            home / ".cargo" / "bin" / "lean-ctx",
            home / ".local" / "bin" / "lean-ctx",
            Path("/usr/local/bin/lean-ctx"),
            Path("/usr/bin/lean-ctx"),
            # Homebrew on Apple Silicon vs Intel macOS:
            Path("/opt/homebrew/bin/lean-ctx"),
            Path("/home/linuxbrew/.linuxbrew/bin/lean-ctx"),
        ]

    for cand in candidates:
        try:
            # os.access(..., X_OK) is meaningful on POSIX. On Windows
            # there is no executable bit; is_file() is the relevant check.
            if cand.is_file() and (is_windows or os.access(cand, os.X_OK)):
                return str(cand)
        except OSError:
            # Hostile path (mount unavailable, permission denied at stat
            # time) — keep probing the rest.
            continue
    return None


def _resolve_vendored_lean_ctx() -> Path | None:
    """Look for a repo-vendored lean-ctx binary matching this host's
    arch. We ship prebuilts under `vendor/lean-ctx/<arch>/lean-ctx[.exe]`
    so users on Windows (where `cargo install lean-ctx` takes 5-10 min
    of cold Rust compile) can skip the build entirely. Mirrors the
    `launcher/dist/<arch>/` convention.

    Returns the absolute path to the vendored binary if it exists,
    None otherwise. Caller decides whether to copy it into a PATH
    location or run it in place.

    Vendor convention:
      vendor/lean-ctx/windows-x64/lean-ctx.exe   (Windows x86_64)
      vendor/lean-ctx/linux-x64/lean-ctx         (Linux x86_64)
      vendor/lean-ctx/experimental_macOS/lean-ctx (macOS, both archs)
    """
    os_name = platform.system()
    if os_name == "Windows":
        arch_dir = "windows-x64"
        bin_name = "lean-ctx.exe"
    elif os_name == "Darwin":
        arch_dir = "experimental_macOS"
        bin_name = "lean-ctx"
    elif os_name == "Linux":
        arch_dir = "linux-x64"
        bin_name = "lean-ctx"
    else:
        return None
    candidate = PROJECT_ROOT / "vendor" / "lean-ctx" / arch_dir / bin_name
    if candidate.is_file():
        return candidate
    return None


def _install_vendored_lean_ctx() -> str | None:
    """Copy the repo-vendored lean-ctx binary into a PATH-resolvable
    location so `shutil.which("lean-ctx")` picks it up post-install.

    Linux/macOS: target ~/.local/bin/lean-ctx (already on most users'
    PATH; rustup adds it if cargo is installed).
    Windows: target %USERPROFILE%\\.cargo\\bin\\lean-ctx.exe (cargo's
    canonical bin dir; cargo adds it to PATH; install.py's
    _resolve_lean_ctx already probes this dir as a fallback).

    Returns the destination path on success, None if no vendored
    prebuilt was found or the copy failed. Idempotent — re-copies
    even if a stale older version is already at the destination.
    """
    src = _resolve_vendored_lean_ctx()
    if src is None:
        return None
    os_name = platform.system()
    if os_name == "Windows":
        dest_dir = Path.home() / ".cargo" / "bin"
        dest = dest_dir / "lean-ctx.exe"
    else:
        dest_dir = Path.home() / ".local" / "bin"
        dest = dest_dir / "lean-ctx"
    try:
        dest_dir.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dest)
        if os_name != "Windows":
            os.chmod(dest, 0o755)
        return str(dest)
    except (OSError, shutil.Error) as e:
        print(f"  lean-ctx: failed to copy vendored prebuilt: {e}")
        return None


def _maybe_install_lean_ctx(args: argparse.Namespace) -> str | None:
    """Auto-install lean-ctx if a supported package manager is present.

    Order of attempts:
      1. Repo-vendored prebuilt (vendor/lean-ctx/<arch>/) — fastest
         path. Saves the ~5-10 min cargo build on Windows. Skipped if
         no prebuilt for this host arch.
      2. Homebrew tap (macOS / Linuxbrew).
      3. Cargo install (any host with rustup).
      4. AUR helpers (Arch Linux).

    Returns the resolved binary path on success, None otherwise.
    Auto-install runs in --yes / non-TTY contexts; real users get a
    prompt. lean-ctx project: https://github.com/yvgude/lean-ctx
    """
    # Step 1: try vendored prebuilt first. No prompt needed — the
    # binary is already in the repo, we just copy it. Silent on
    # failure (caller falls through to package-manager paths).
    vendored = _install_vendored_lean_ctx()
    if vendored:
        print(f"  lean-ctx: installed from vendored prebuilt → {vendored}")
        return vendored

    # T1 silent (with --yes / non-TTY). T3 prompt for interactive.
    silent = bool(args.yes or not sys.stdin.isatty())

    has_brew = shutil.which("brew") is not None
    has_cargo = shutil.which("cargo") is not None
    has_yay = shutil.which("yay") is not None
    has_paru = shutil.which("paru") is not None

    if not (has_brew or has_cargo or has_yay or has_paru):
        # No supported channel — fall through; caller prints the manual
        # install hints (rustup-then-cargo).
        return None

    method = None
    if has_brew:
        method = "brew"
    elif has_cargo:
        method = "cargo"
    elif has_yay:
        method = "yay"
    elif has_paru:
        method = "paru"

    if not silent:
        # Interactive: ask before installing. Default Y because the
        # benefit is large (~95% token savings) and the cost is small
        # (~one-time cargo build / brew tap).
        try:
            method_text = {
                "brew": "Homebrew (`brew tap yvgude/lean-ctx && brew install lean-ctx`)",
                "cargo": "Cargo (`cargo install lean-ctx`, ~2-5 min build)",
                "yay": "AUR (`yay -S lean-ctx-bin`)",
                "paru": "AUR (`paru -S lean-ctx-bin`)",
            }[method]
            ans = input(
                f"  lean-ctx: not installed. Install via {method_text}? [Y/n]: "
            ).strip().lower()
        except (EOFError, KeyboardInterrupt):
            print()
            return None
        if ans and ans not in {"y", "yes"}:
            return None

    print(f"  lean-ctx: installing via {method}...")
    try:
        if method == "brew":
            # `brew tap` is idempotent. Do tap + install in two steps so
            # an already-tapped tap doesn't error.
            subprocess.run(
                ["brew", "tap", "yvgude/lean-ctx"],
                check=False, timeout=120,
            )
            r = subprocess.run(
                ["brew", "install", "lean-ctx"],
                check=False, timeout=600,
            )
            if r.returncode != 0:
                print(f"  lean-ctx: brew install failed (exit {r.returncode}).")
                return None
        elif method == "cargo":
            r = subprocess.run(
                ["cargo", "install", "lean-ctx"],
                check=False, timeout=900,  # cargo build can be slow on small machines
            )
            if r.returncode != 0:
                print(f"  lean-ctx: cargo install failed (exit {r.returncode}).")
                return None
        elif method in {"yay", "paru"}:
            r = subprocess.run(
                [method, "-S", "--noconfirm", "lean-ctx-bin"],
                check=False, timeout=300,
            )
            if r.returncode != 0:
                # Fallback: try the source-built package name.
                r = subprocess.run(
                    [method, "-S", "--noconfirm", "lean-ctx"],
                    check=False, timeout=900,
                )
                if r.returncode != 0:
                    print(f"  lean-ctx: {method} install failed.")
                    return None
    except (subprocess.TimeoutExpired, OSError) as e:
        print(f"  lean-ctx: install raised {type(e).__name__}: {e}")
        return None

    # Re-detect — the just-installed binary should be findable now.
    return _find_lean_ctx_binary()


def _detect_optional_companions(args: argparse.Namespace) -> None:
    """Detect the optional lean-ctx companion (token-compression helper).

    lean-ctx (Rust binary at ~/.cargo/bin/) — the per-project PreToolUse hook
    delegates to it for command-output compression on Claude Code's Bash tool.
    Hint-only: an absent binary doesn't break anything.

    v0.2.73 (CG-3): the Joern (CFG/PDG) detection was removed — the code-graph
    analyzer no longer extracts `cfg_summary`/`data_flow_vars` (zero readers),
    so there is no Joern to probe, install, or gate `--cfg`/`--pdg` on.
    """
    print("\n[2b/10] Optional companions ...")
    _log_install_event("2b/10", "start", "probing optional companion tools")

    # lean-ctx (optional — the per-project PreToolUse hook
    # `.claude/hooks/lean-ctx-rewrite.sh` delegates to it for ~90-97%
    # command-output compression on Claude Code's Bash tool surface).
    # https://github.com/yvgude/lean-ctx
    #
    # 0.2.11 redesign: this step only DETECTS / OPTIONALLY INSTALLS the
    # binary. The legacy BASH_ENV shim wiring (which was fork-bomb-prone
    # on lean-ctx 3.x — see knowledge/concepts/lean-ctx-shim-disabled.md)
    # was removed; output compression now flows through the per-project
    # PreToolUse hook registered in templates/settings.json.*.template.
    # The hook no-ops gracefully if lean-ctx isn't on PATH, so an absent
    # binary doesn't break Bash for users without it.
    #
    # Detection: shutil.which checks PATH only. Many users have lean-ctx
    # installed via `cargo install lean-ctx` (canonical landing dir
    # ~/.cargo/bin/) but their non-interactive shell PATH doesn't include
    # ~/.cargo/bin (cargo's installer adds the line to ~/.profile but
    # `bash first-install.sh` from a fresh terminal may not have sourced
    # it yet). Probe known-binary locations as a fallback. Also auto-install
    # via cargo / brew when those are available.
    lean_ctx_path = _find_lean_ctx_binary()
    if not lean_ctx_path and not args.quiet and not args.no_lean_ctx:
        # Try auto-install via the most appropriate package manager.
        lean_ctx_path = _maybe_install_lean_ctx(args)
    if lean_ctx_path:
        print(
            f"  lean-ctx: detected at {lean_ctx_path} — PreToolUse hook "
            f".claude/hooks/lean-ctx-rewrite.sh will use it if registered "
            f"in settings"
        )
    else:
        print("  lean-ctx: not installed (optional, recommended for ~95% token savings on CLI output)")
        # OS-aware install hints. Use the canonical channels documented at
        # https://github.com/yvgude/lean-ctx — verified 2026-04-28.
        print("            Install via your preferred channel; the per-project")
        print("            PreToolUse hook will pick it up on the next session:")
        if shutil.which("brew"):
            print("              Homebrew:   brew tap yvgude/lean-ctx && brew install lean-ctx")
        if shutil.which("cargo"):
            print("              Cargo:      cargo install lean-ctx")
        if shutil.which("yay") or shutil.which("paru"):
            print("              AUR:        yay -S lean-ctx-bin   (or: yay -S lean-ctx)")
        if not (shutil.which("brew") or shutil.which("cargo") or shutil.which("yay") or shutil.which("paru")):
            # No supported package manager detected. Give the user a clear
            # path: install Cargo (Rust toolchain) and then lean-ctx.
            print("              No supported package manager detected.")
            print("              Easiest path: install Rust + Cargo, then `cargo install lean-ctx`:")
            print("                curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh")
            print("                source $HOME/.cargo/env && cargo install lean-ctx")
        print("            (Pass --no-lean-ctx to silence this hint.)")

# ---------------------------------------------------------------------------
# Step 3: Embedding configuration
# ---------------------------------------------------------------------------

# v0.2.54 (gpu-audit C-5): vector dimensionality per embedding model.
# Single source for the tier-override path so swapping a model can never
# leave the profile's stock `code_dims` / `text_dims` behind. Keep in
# lockstep with EMBEDDING_CONFIGS above and the per-model limits in
# claude_mcp_servers/weaviate_mcp/chunking.py.
_EMBEDDING_MODEL_DIMS = {
    "codesage-large-v2": 2048,
    "qwen3-embedding:0.6b": 1024,
    "unclemusclez/jina-embeddings-v2-base-code:latest": 768,
    "snowflake-arctic-embed2:latest": 1024,
    "openai-text-embedding-3-small": 1536,
    "text-embedding-3-small": 1536,
}

# ACTIVE_EMBEDDING named-vector slot per TEXT model — must match the
# slot mapping in weaviate_mcp/server.py::_get_search_vector. A text-
# model override that doesn't re-point this slot would write vectors
# from one model into a slot labelled for another (the 2026-04-30
# vector-audit bug class).
#
# This map is the model→profile half of the v0.2.71 T-B-emb active-embedding
# cascade. It MUST stay byte-identical to its mirrors (drift re-introduces the
# v0.2.68 Defect D bug — see project_env_settings.rs:78-87):
#   * launcher/src-tauri/src/commands/project_env_settings.rs
#       ::active_profile_for_model
#   * launcher/src-tauri/vct-hub/src/config_api.rs::hub_active_profile_for_model
#   * vco_lib/launcher_db_reader.py::_TEXT_MODEL_ACTIVE_EMBEDDING
_TEXT_MODEL_ACTIVE_EMBEDDING = {
    "qwen3-embedding:0.6b": "qwen3",
    "snowflake-arctic-embed2:latest": "arctic",
    "openai-text-embedding-3-small": "openai",
    "text-embedding-3-small": "openai",
}

# Models served via Ollama (must be in the pull list when selected).
_OLLAMA_SERVED_EMBEDDING_MODELS = {
    "qwen3-embedding:0.6b",
    "unclemusclez/jina-embeddings-v2-base-code:latest",
    "snowflake-arctic-embed2:latest",
}


def _apply_tier_overrides(config: dict, *, code_pick: str, kg_pick: str) -> None:
    """Shim over :func:`vco_lib.gpu_profile.apply_tier_overrides`.

    Passes install.py's module-level constants through to the shared
    helper. See `vco_lib/gpu_profile.py` for the canonical logic.
    """
    from vco_lib.gpu_profile import apply_tier_overrides
    apply_tier_overrides(
        config,
        code_pick=code_pick,
        kg_pick=kg_pick,
        model_dims=_EMBEDDING_MODEL_DIMS,
        text_model_active_embedding=_TEXT_MODEL_ACTIVE_EMBEDDING,
        ollama_served_models=_OLLAMA_SERVED_EMBEDDING_MODELS,
    )


def _choose_embedding_config(sysinfo: SystemInfo, args: argparse.Namespace) -> dict:
    # Explicit opt-ins win over auto-detection.
    #
    # Deliverable 2 (2026-04-28): persist the resolved choice so a
    # re-install with no CLI flags re-uses the same mode rather than
    # re-detecting GPU. Detection is normally fine but on machines
    # where nvidia-smi flapped or Ollama was unreachable at first
    # install, the user already picked a mode they want to stick.
    #
    # v0.2.23 C10 (2026-05-21): the auto-detection branch now consults
    # the three hardware-aware selectors (select_code_embedding_backend
    # / select_kg_embedding_backend / select_summary_backend) to pick
    # the right *profile* AND, when the profile's stock model isn't
    # the per-tier optimum, augment the returned dict with `text_model`
    # / `code_model` overrides. The explicit-opt-in branches (--openai,
    # --low-resource, --cpu-only) bypass the selectors entirely — the
    # user has stated a preference and we honour it byte-for-byte.
    if args.openai_key:
        config = dict(EMBEDDING_CONFIGS["openai"])
        config["openai_key"] = args.openai_key
        _record_install_choice("embedding_mode", "openai",
                               {"reason": "user passed --openai-key"})
        return config
    if args.low_resource:
        config = dict(EMBEDDING_CONFIGS["low_resource"])
        _record_install_choice("embedding_mode", "low_resource",
                               {"reason": "user passed --low-resource"})
        return config
    if args.cpu_only:
        config = dict(EMBEDDING_CONFIGS["cpu"])
        _record_install_choice("embedding_mode", "cpu",
                               {"reason": "user passed --cpu-only"})
        return config

    # Replay-eligible: no flag and we have a recent choice.
    prior_choices = _load_previous_choices()
    if "embedding_mode" in prior_choices:
        prior_value = prior_choices["embedding_mode"].get("value")
        if prior_value in EMBEDDING_CONFIGS:
            config = dict(EMBEDDING_CONFIGS[prior_value])
            _record_install_choice(
                "embedding_mode", prior_value,
                {"reason": "replayed from last install"},
            )
            return config

    # Auto-detection — v0.2.23 C10 tier-aware path.
    cores = _probe_cpu_cores()
    vram = float(sysinfo.vram_gb or 0.0)
    ram = float(sysinfo.ram_gb or 0.0)
    has_gpu = bool(sysinfo.has_gpu)

    code_pick = select_code_embedding_backend(
        gpu_vram_gb=vram,
        ram_gb=ram,
        cores=cores,
        openai_key_available=False,  # auto-detect never picks OpenAI
        prefer_openai=False,
    )
    kg_pick = select_kg_embedding_backend(
        gpu_vram_gb=vram,
        ram_gb=ram,
        cores=cores,
        openai_key_available=False,
        prefer_openai=False,
    )

    # v0.2.54 (gpu-audit C-2): CodeSage has no ROCm build path — the
    # code-embed container image is CPU-multi-arch by default with a
    # CUDA-only alternative (`Dockerfile.cuda`, emitted only for
    # gpu_vendor == "nvidia"). Pre-v0.2.54, an AMD host with >=12 GB
    # VRAM landed on the "gpu" profile labeled "GPU-accelerated ...
    # best quality" while CodeSage 1.3B silently ran on CPU inside the
    # container. Route AMD hosts to the Ollama-served qwen3 code model
    # instead: Ollama itself IS ROCm-accelerated (via the rocm compose
    # overlay), so code embeddings still run on the GPU — through the
    # backend that actually has a ROCm path. This also makes the
    # shipped claims true (CHANGELOG F7 + podman-compose.amd-rocm.yml:
    # "AMD users get the Ollama-based code embedding fallback").
    if has_gpu and code_pick == _CODE_BACKEND_CODESAGE and sysinfo.gpu_vendor == "amd":
        code_pick = _CODE_BACKEND_QWEN3

    # Map the per-tier picks back to a profile + overrides. The profile
    # determines the shape (active_embedding slot + which Ollama models
    # land in the pull list); the overrides surgically swap in the
    # tier-correct model when the profile's stock pick doesn't match.
    if has_gpu and code_pick == _CODE_BACKEND_CODESAGE:
        # Workstation-class GPU — gpu profile is the natural fit.
        profile_key = "gpu"
        reason = (f"auto-detected GPU (VRAM={vram:.1f} GB, RAM={ram:.1f} GB, "
                  f"cores={cores})")
    elif kg_pick == _KG_BACKEND_ARCTIC:
        # Mid- / low-resource path: arctic2 was selected for KG. The
        # low_resource profile already pairs arctic + Jina, which
        # matches the spec for this tier exactly.
        profile_key = "low_resource"
        reason = (f"auto-selected low_resource tier (VRAM={vram:.1f} GB, "
                  f"RAM={ram:.1f} GB, cores={cores})")
    else:
        # Capable CPU-only or sub-12 GB GPU: cpu profile (qwen3 + Jina).
        profile_key = "cpu"
        reason = (f"auto-selected cpu profile (VRAM={vram:.1f} GB, "
                  f"RAM={ram:.1f} GB, cores={cores})")

    config = dict(EMBEDDING_CONFIGS[profile_key])

    # Surgical overrides when the selector disagrees with the stock
    # profile model. v0.2.54 (gpu-audit C-5): extracted to
    # _apply_tier_overrides, which now keeps the DEPENDENT fields in
    # lockstep with the swapped model — pre-v0.2.54 only the model name
    # was replaced, so e.g. a 6-12 GB GPU host got the cpu profile with
    # code_model swapped to qwen3 (1024-dim) while code_dims stayed 768
    # and CODE_EMBED_DIMS=768 was written to .env for a 1024-dim model.
    _apply_tier_overrides(config, code_pick=code_pick, kg_pick=kg_pick)

    _record_install_choice("embedding_mode", profile_key, {"reason": reason})
    return config


# ---------------------------------------------------------------------------
# v0.2.18 Commit 10 — Preset defaults → launcher's app_state
#
# Goal: a brand-new project, on first launch after install, should see the
# KG/Codegraph dropdowns pre-populated with the embedding-model IDs that
# install.py actually configured. Without this, every new project starts
# blank and the user has to manually pick the same model `install.py`
# already pulled.
#
# The launcher's `app_state` is a generic key/value table (key TEXT,
# value TEXT, updated_at INTEGER) defined in
# `launcher/src-tauri/src/db/migrations/008_app_state.sql`. The keys we
# write are the same ones Wave A's `openai_cmd.rs` reads/writes:
#   - default_text_embedding
#   - default_code_embedding
# Canonical IDs are aligned with the Rust catalog
# (`launcher/src-tauri/src/commands/embedding_catalog.rs`) and Wave A's
# constants — OpenAI IDs use the `openai-` prefix; local Ollama IDs use
# the raw Ollama tag; CodeEmbed uses `codesage-large-v2`.
#
# DB path resolution mirrors the Rust resolver
# (`launcher/src-tauri/src/paths.rs::vct_root_dir`):
#   - `$VCT_STATE_DIR/launcher.db` if VCT_STATE_DIR is set (non-empty)
#   - `~/.vct/launcher.db` otherwise
# Cross-OS: same shape on Linux, macOS, Windows — `Path.home()` resolves
# correctly on all three. The launcher does NOT use Tauri's
# `app_data_dir()`; it pins to `~/.vct/` so dev/prod isolation (via
# VCT_STATE_DIR) works the same way on every platform.
#
# Ordering: install.py runs BEFORE the launcher may have ever been
# started (fresh install). When that's true, launcher.db does not exist
# on disk yet → we soft-fail with a skip log. The launcher creates the
# table on first boot via the schema migration, and the user's first
# manual selection in the GUI lands the rows (no defaults pre-populated
# in that case — acceptable: the user is configuring it themselves
# anyway). On --update runs (launcher.db exists), the rows are
# pre-populated.
#
# Idempotency: `INSERT OR IGNORE` only sets rows that are absent.
# Existing rows (= user's manual selections from a prior launcher
# session) are preserved.
# ---------------------------------------------------------------------------

# Canonical app_state keys. MUST stay in sync with:
#   launcher/src-tauri/src/commands/openai_cmd.rs::APP_STATE_DEFAULT_TEXT_EMBED
#   launcher/src-tauri/src/commands/openai_cmd.rs::APP_STATE_DEFAULT_CODE_EMBED
_APP_STATE_KEY_DEFAULT_TEXT_EMBED = "default_text_embedding"
_APP_STATE_KEY_DEFAULT_CODE_EMBED = "default_code_embedding"

# v0.2.42 CI-10: app_state keys that track the install-time embedding/collection
# context when the KG seed last ran successfully. Used by _seed_weaviate to
# decide whether a full sync or a content-hash diff-only sync is needed on
# --update runs. Documented in v0.2.17 fast-path CHANGELOG entry and this spec.
#
# IMPORTANT: "pay once, never again" — on fresh install or when any of these
# change (embedding model swap, collection rename), run a full sync. On
# subsequent --update runs with no change, compute a per-file content_hash diff
# and only sync the changed files. If the diff is empty → SKIP sync entirely.
#
# Semantics:
#   last_installed_active_embedding  — active embedding model at last seed run
#                                      (e.g. "qwen3", "arctic2", "openai")
#   last_installed_kg_collection     — KG_COLLECTION value at last seed run
#   last_installed_shared_kg_collection — SHARED_KG_COLLECTION at last seed run
#   last_kg_sync_at                  — ISO-8601 UTC timestamp of last sync
#   last_kg_sync_stats               — JSON: {"nodes_synced": N, "nodes_skipped": M}
_APP_STATE_KEY_LAST_ACTIVE_EMBEDDING = "last_installed_active_embedding"
_APP_STATE_KEY_LAST_KG_COLLECTION = "last_installed_kg_collection"
_APP_STATE_KEY_LAST_SHARED_KG_COLLECTION = "last_installed_shared_kg_collection"
_APP_STATE_KEY_LAST_KG_SYNC_AT = "last_kg_sync_at"

# v0.2.52 V52-AJ: app_state key that the launcher's Identity-tab embedding
# selector writes (mirrors Rust APP_STATE_KEY_ACTIVE_EMBEDDING in
# launcher/src-tauri/src/commands/project_env_settings.rs). Different from
# _APP_STATE_KEY_LAST_ACTIVE_EMBEDDING above: this one is the LIVE choice;
# the LAST_* one is the snapshot of what install.py used at the last
# successful KG seed. Both keys are present on the same launcher.db.
_APP_STATE_KEY_ACTIVE_EMBEDDING_LIVE = "embedding.active_profile"
_APP_STATE_KEY_LAST_KG_SYNC_STATS = "last_kg_sync_stats"

# Canonical OpenAI ID used by Wave A (with `openai-` prefix). MUST match:
#   launcher/src-tauri/src/commands/openai_cmd.rs::OPENAI_DEFAULT_TEXT_MODEL_ID
#   launcher/src-tauri/src/commands/embedding_catalog.rs (`id` field)
# As of the Commit 12 prefix-unification fix (v0.2.18),
# `EmbeddingService.discover_text_models` / `discover_code_models` ALSO
# emit the prefixed form for OpenAI models (via
# `vco_lib.embedding_service._to_openai_catalog_id`), so the catalog
# entry's `id` field round-trips byte-for-byte with what we write here
# and what `openai_cmd.rs::register_openai_api_key` writes. The HTTP
# call boundary (OpenAIAdapter.embed) strips the prefix back off via
# `_to_openai_api_model` because OpenAI's `/v1/embeddings` rejects the
# prefixed form with HTTP 400.
_OPENAI_PREFIXED_TEXT_MODEL_ID = "openai-text-embedding-3-small"


def _preset_to_default_models(
    embed_config: dict,
    openai_set_as_default: bool,
) -> tuple[str, str]:
    """Map an install-time embedding config dict to the (text, code) model
    IDs that the launcher's `app_state` should be seeded with.

    The source of truth is the chosen `EMBEDDING_CONFIGS` entry's
    `text_model` / `code_model` fields — i.e. exactly the models
    install.py just pulled into Ollama / configured for the GPU
    code-embed service. This guarantees the GUI's pre-populated default
    matches what the user's machine can actually serve.

    Special case: when the user passed `--openai-key` AND chose to set
    OpenAI as default (`openai_set_as_default=True`), the stored IDs
    use the `openai-` prefix to align with Wave A's
    `openai_cmd.rs::register_openai_api_key`, which writes the same
    prefixed form when the wizard's "set as default" checkbox is ticked.

    Args:
        embed_config: The dict returned by `_choose_embedding_config`.
            Keyed by `text_model`, `code_model`, `active_embedding`,
            optionally `openai_key` (presence indicates --openai-key).
        openai_set_as_default: True if the user explicitly opted to
            make OpenAI the default for this install (currently inferred
            from `embed_config["active_embedding"] == "openai"` —
            wizard-side this would flip per a checkbox, but install.py's
            `--openai-key` flag is an unambiguous opt-in).

    Returns:
        (text_model_id, code_model_id) — the strings to write into
        `app_state.default_text_embedding` and
        `app_state.default_code_embedding` respectively.
    """
    active = embed_config.get("active_embedding", "")

    if active == "openai" and openai_set_as_default:
        # Mirrors openai_cmd.rs constants. Both slots use the same model
        # today; the split exists for forward-compat when OpenAI ships
        # a code-specific embedder.
        return (_OPENAI_PREFIXED_TEXT_MODEL_ID, _OPENAI_PREFIXED_TEXT_MODEL_ID)

    # All non-OpenAI presets: use the IDs install.py pulled, verbatim.
    # These IDs match what `EmbeddingService.discover_*` surfaces in
    # the GUI catalog (Ollama tags / `codesage-large-v2`).
    text_model = str(embed_config.get("text_model") or "qwen3-embedding:0.6b")
    code_model = str(embed_config.get("code_model") or "qwen3-embedding:0.6b")
    return (text_model, code_model)


def _discover_app_state_db_path() -> Path:
    """Resolve the path to the launcher's SQLite state DB.

    Mirrors `launcher/src-tauri/src/db/mod.rs::db_path`, which itself
    delegates to `crate::paths::vct_root_dir`. Cross-OS:
      - Linux:   `~/.vct/launcher.db` (or `$VCT_STATE_DIR/launcher.db`)
      - macOS:   `~/.vct/launcher.db` (or `$VCT_STATE_DIR/launcher.db`)
      - Windows: `<USERPROFILE>\\.vct\\launcher.db`
                 (or `%VCT_STATE_DIR%\\launcher.db`)

    `Path.home()` resolves correctly on all three platforms; `os.environ`
    + `Path` join is portable. The launcher does NOT use Tauri's
    `app_data_dir()` here — it pins to `~/.vct/` so the same path works
    whether the launcher was installed via Tauri bundle, run from a
    cargo build, or hadn't started yet (path is predictable before any
    Tauri code has executed). VCT_STATE_DIR override is honoured for
    dev/prod isolation, same as the Rust side.

    Returns a `Path` whether or not the file exists on disk — caller is
    responsible for the `.is_file()` check and the soft-fail.

    v0.2.54: delegates to `vco_lib.paths.launcher_db_path` so the
    `VCT_LAUNCHER_DB_PATH` override is honoured uniformly (previously
    only `launcher_db_reader` honoured it — split-brain).
    """
    from vco_lib.paths import launcher_db_path
    return launcher_db_path()


def _write_preset_defaults_to_app_state(
    embed_config: dict,
    openai_set_as_default: bool,
) -> None:
    """Seed the launcher's `app_state` table with the install-time
    embedding-model defaults so the GUI dropdowns pre-populate for
    brand-new projects.

    Ordering constraint: if install.py runs BEFORE the launcher has
    ever been started (fresh first-install), the launcher.db file does
    not exist yet. The launcher creates it (with the `app_state` table)
    on first boot via `db::Db::open` → `migrations::apply`. In that
    case, we cannot pre-populate defaults — the user's first GUI action
    will land their explicit choice, which is functionally equivalent
    for the "what shows up in the dropdown" goal. We soft-fail with a
    `skip` log event.

    On --update runs (where launcher.db exists), the rows ARE
    pre-populated. Idempotency comes from `INSERT OR IGNORE`: rows the
    user explicitly set in a prior session are preserved.

    Soft-fail cases (all log a `skip`/`warn` and return without raising):
      - launcher.db file does not exist (fresh install, never booted)
      - `app_state` table does not exist (schema migration not applied
        — should not happen if file exists, but defense-in-depth)
      - Any `sqlite3.Error` (locked DB, permission denied, corruption)

    Never raises: install.py should not fail just because the GUI
    dropdowns won't pre-populate.

    DB-path resolution: `_discover_app_state_db_path` honours the
    `VCT_STATE_DIR` env override (the canonical pattern used by
    `vco_lib.paths.vct_root_dir`) — tests that need a custom DB
    location set `VCT_STATE_DIR` rather than threading a path
    parameter through this helper. The legacy `install_root`
    parameter (kept through v0.2.18 release prep as `noqa: ARG001`)
    was dropped here in the v0.2.18 cleanup commit.

    Args:
        embed_config: As returned by `_choose_embedding_config`.
        openai_set_as_default: True when `--openai-key` was passed (or,
            via the wizard, when the user ticked "set OpenAI as
            default").
    """
    db_path = _discover_app_state_db_path()
    if not db_path.is_file():
        _log_install_event(
            "preset_defaults", "skip",
            f"launcher.db not found at {db_path}; defaults will be set "
            f"by the launcher on first GUI use (no-op until then)",
            data={"db_path": str(db_path)},
        )
        return

    text_model, code_model = _preset_to_default_models(
        embed_config, openai_set_as_default,
    )

    # stdlib only — sqlite3 ships with every CPython >=3.11. No new
    # deps. Connection is opened with the default isolation level
    # (deferred) so the INSERT OR IGNOREs run inside an auto-managed
    # transaction.
    import sqlite3
    try:
        # v0.2.60: retry-with-backoff on a transient lock (was a single
        # no-timeout shot → instant fail-to-skip when the launcher held the
        # lock). The writes are `ON CONFLICT(key) DO NOTHING`, so a missed
        # write is benign (defaults already present), but riding out a
        # transient AV/indexer lock on Windows is strictly better.
        conn = _connect_launcher_db_with_retry(db_path, label="preset_defaults")
    except sqlite3.Error as e:
        _log_install_event(
            "preset_defaults", "warn",
            f"sqlite3.connect failed for {db_path}: {e}",
            data={"db_path": str(db_path), "error": str(e)},
        )
        return

    try:
        # `updated_at` is a NOT NULL column — provide unix-millis now.
        # ON CONFLICT(key) DO NOTHING preserves any prior value (user's
        # manual selection from an earlier launcher session). This is
        # the same idempotency semantic as `INSERT OR IGNORE`, written
        # explicitly so the intent is obvious to a future reader.
        import time as _time
        now_ms = int(_time.time() * 1000)
        cur = conn.cursor()
        try:
            cur.execute(
                "INSERT INTO app_state (key, value, updated_at) "
                "VALUES (?, ?, ?) "
                "ON CONFLICT(key) DO NOTHING",
                (_APP_STATE_KEY_DEFAULT_TEXT_EMBED, text_model, now_ms),
            )
            text_inserted = cur.rowcount > 0
            cur.execute(
                "INSERT INTO app_state (key, value, updated_at) "
                "VALUES (?, ?, ?) "
                "ON CONFLICT(key) DO NOTHING",
                (_APP_STATE_KEY_DEFAULT_CODE_EMBED, code_model, now_ms),
            )
            code_inserted = cur.rowcount > 0
            conn.commit()
        except sqlite3.OperationalError as e:
            # Most common: "no such table: app_state". The launcher
            # owns the schema — we should not auto-create it from here
            # (separation of concerns). Soft-fail with a clear log.
            _log_install_event(
                "preset_defaults", "skip",
                f"app_state table not present yet ({e}); the launcher "
                f"will create it on first boot",
                data={"db_path": str(db_path), "error": str(e)},
            )
            return

        active = embed_config.get("active_embedding", "unknown")
        _log_install_event(
            "preset_defaults", "ok",
            f"app_state defaults seeded "
            f"(active={active}, text={text_model}, code={code_model}, "
            f"text_inserted={text_inserted}, code_inserted={code_inserted})",
            data={
                "active_embedding": active,
                "default_text_embedding": text_model,
                "default_code_embedding": code_model,
                "text_inserted": text_inserted,
                "code_inserted": code_inserted,
                "db_path": str(db_path),
            },
        )
    except sqlite3.Error as e:
        _log_install_event(
            "preset_defaults", "warn",
            f"sqlite error writing preset defaults to {db_path}: {e}",
            data={"db_path": str(db_path), "error": str(e)},
        )
    finally:
        try:
            conn.close()
        except sqlite3.Error:
            pass


# ---------------------------------------------------------------------------
# v0.2.52 V52-AD — seed host-wide RL reranker disable on fresh installs
# ---------------------------------------------------------------------------
#
# User-stated 2026-06-09: "we don't have enough RL data, want to disable
# RL rerank by default until 500+ retrieval events accumulate". This is
# the install-time hook that lands that default: when launcher.db exists
# (= --update flow OR fresh install after the launcher has booted at
# least once) AND `rl_events` has fewer than 500 rows AND no global
# enable row already exists for vct-rl-reranker, write `enabled=false`
# at `(project_id IS NULL, vct-rl-reranker, enabled_for_project)`.
#
# Soft-fails identically to `_write_preset_defaults_to_app_state`:
#   - launcher.db absent → skip (launcher will create the table on first
#     boot; the user can then flip the toggle in Preferences → Modules).
#   - module_settings table absent → skip.
#   - Existing global row present → preserve user's prior choice (do
#     not overwrite).
#   - Existing rl_events count >= 500 → skip (training data already
#     accumulated; let the user decide via the GUI prompt).
#
# Idempotency: the helper exits early if a global row already exists,
# regardless of its value. Re-running install.py never resurrects a
# default the user has since flipped.

_RL_RERANKER_MODULE_ID = "vct-rl-reranker"
_MODULE_ENABLED_FOR_PROJECT_KEY = "enabled_for_project"
_RL_EVENTS_AUTO_ENABLE_THRESHOLD = 500


def _seed_rl_reranker_default_disabled() -> None:
    """Seed the launcher's `module_settings` table with a host-wide
    disable row for vct-rl-reranker when the install is fresh enough
    that the user hasn't accumulated training data yet.

    Mirror of `_write_preset_defaults_to_app_state` for an adjacent
    table. Soft-fail on every known error condition (see module-level
    comment).
    """
    db_path = _discover_app_state_db_path()
    if not db_path.is_file():
        _log_install_event(
            "rl_reranker_default", "skip",
            f"launcher.db not found at {db_path}; the launcher will "
            f"create the table on first boot. The user can flip the "
            f"default via Preferences → Modules in the GUI.",
            data={"db_path": str(db_path)},
        )
        return

    import sqlite3
    try:
        conn = sqlite3.connect(str(db_path))
    except sqlite3.Error as e:
        _log_install_event(
            "rl_reranker_default", "warn",
            f"sqlite3.connect failed for {db_path}: {e}",
            data={"db_path": str(db_path), "error": str(e)},
        )
        return

    try:
        cur = conn.cursor()

        # Step 1: probe the rl_events count. Soft-fail when the table
        # doesn't exist yet (pre-migration-025 launcher.db).
        try:
            row = cur.execute("SELECT COUNT(*) FROM rl_events").fetchone()
            rl_count = int(row[0]) if row else 0
        except sqlite3.OperationalError as e:
            _log_install_event(
                "rl_reranker_default", "skip",
                f"rl_events table not present yet ({e}); will write the "
                f"default disable row on next install run after the "
                f"launcher has booted at least once.",
                data={"db_path": str(db_path), "error": str(e)},
            )
            return

        # Step 2: if the user has already accumulated 500+ events, the
        # auto-enable path applies. Do NOT seed a disable here — let the
        # GUI prompt them to enable via Preferences → Modules.
        if rl_count >= _RL_EVENTS_AUTO_ENABLE_THRESHOLD:
            _log_install_event(
                "rl_reranker_default", "skip",
                f"rl_events already has {rl_count} rows "
                f"(>= {_RL_EVENTS_AUTO_ENABLE_THRESHOLD}); not seeding a "
                f"default disable row. The user can opt in / out via the "
                f"GUI.",
                data={
                    "rl_events_count": rl_count,
                    "threshold": _RL_EVENTS_AUTO_ENABLE_THRESHOLD,
                },
            )
            return

        # Step 3: probe for an existing global row. If present, the
        # user has already configured the default (either via the GUI
        # or a prior install.py run) — preserve their choice.
        try:
            existing = cur.execute(
                "SELECT setting_value FROM module_settings "
                " WHERE project_id IS NULL "
                "   AND module_id = ? "
                "   AND setting_key = ?",
                (_RL_RERANKER_MODULE_ID, _MODULE_ENABLED_FOR_PROJECT_KEY),
            ).fetchone()
        except sqlite3.OperationalError as e:
            # module_settings table missing OR project_id NOT NULL
            # (pre-034 schema). Either way we cannot land the global
            # default — soft-fail with a hint.
            _log_install_event(
                "rl_reranker_default", "skip",
                f"module_settings probe failed ({e}); the launcher's "
                f"migration 034 (v0.2.52) lands the nullable project_id "
                f"column. Re-run install.py after the launcher boots.",
                data={"db_path": str(db_path), "error": str(e)},
            )
            return

        if existing is not None:
            _log_install_event(
                "rl_reranker_default", "skip",
                f"global rl-reranker enable row already present "
                f"(value={existing[0]!r}); preserving user choice.",
                data={"existing_value": existing[0]},
            )
            return

        # Step 4: write the default disable row.
        try:
            cur.execute(
                "INSERT INTO module_settings "
                "  (project_id, module_id, setting_key, setting_value) "
                "VALUES (NULL, ?, ?, ?)",
                (
                    _RL_RERANKER_MODULE_ID,
                    _MODULE_ENABLED_FOR_PROJECT_KEY,
                    "false",  # JSON-encoded bool — matches the Rust
                              # setter's encoding so the cascade reader
                              # decodes it correctly.
                ),
            )
            conn.commit()
        except sqlite3.Error as e:
            _log_install_event(
                "rl_reranker_default", "warn",
                f"failed to seed default disable row: {e}",
                data={"error": str(e)},
            )
            return

        _log_install_event(
            "rl_reranker_default", "ok",
            f"seeded host-wide default: vct-rl-reranker disabled until "
            f"{_RL_EVENTS_AUTO_ENABLE_THRESHOLD}+ retrieval events "
            f"accumulate (currently {rl_count}). Override in "
            f"Preferences → Modules.",
            data={
                "module_id": _RL_RERANKER_MODULE_ID,
                "setting_key": _MODULE_ENABLED_FOR_PROJECT_KEY,
                "value": False,
                "rl_events_count": rl_count,
                "threshold": _RL_EVENTS_AUTO_ENABLE_THRESHOLD,
            },
        )
    except sqlite3.Error as e:
        _log_install_event(
            "rl_reranker_default", "warn",
            f"unexpected sqlite error: {e}",
            data={"error": str(e)},
        )
    finally:
        try:
            conn.close()
        except sqlite3.Error:
            pass


def _read_app_state_key(key: str) -> "str | None":
    """Read a single key from launcher.db's app_state table.

    Returns the string value, or None when the key is absent or any error
    occurs (soft-fail: callers use None as "unknown / first run").

    v0.2.53 DEDUP-4 / CORRECT-2: uses sqlite3 URI form
    ``file:<path>?mode=ro&immutable=1`` (the same readonly pattern
    used by :func:`vco_lib.launcher_db_reader._open_db_readonly`).
    The ro+immutable URI does NOT acquire a writer lock and never
    blocks regardless of what the launcher is doing.

    Pre-v0.2.53 this site used ``sqlite3.connect(timeout=5.0)`` which
    could block install.py for up to 5s on Windows when the launcher
    held a write lock — a perceived install-hang during the most
    performance-critical step.

    NOTE: we DO NOT route through ``launcher_db_reader.read_app_state_value``
    because that helper internally calls its own DB-path discovery
    (``VCT_LAUNCHER_DB_PATH`` env override → ``vct_root_dir() / launcher.db``).
    install.py needs to use its own ``_discover_app_state_db_path``
    so existing test mocks (which patch the install.py-local discoverer)
    continue to work. The cross-helper unification is a v0.2.54
    refactor; the readonly URI pattern below closes CORRECT-2 today.
    """
    import sqlite3
    db_path = _discover_app_state_db_path()
    if not db_path.is_file():
        return None
    try:
        uri = f"file:{db_path}?mode=ro&immutable=1"
        conn = sqlite3.connect(uri, uri=True, timeout=5.0)
        try:
            row = conn.execute(
                "SELECT value FROM app_state WHERE key = ?", (key,)
            ).fetchone()
            return row[0] if row else None
        finally:
            conn.close()
    except Exception:
        return None


def _model_id_for_active(active: str) -> str:
    """v0.2.52 V52-AJ: map an active-embedding profile to its model id.

    Used when threading ``EMBEDDING_MODEL`` into ``sync_knowledge_graph.py``
    subprocesses so the subprocess picks the same model the launcher chose,
    even when the user shell has no ``EMBEDDING_MODEL`` set.

    Profiles (case-insensitive):
      * ``arctic`` → ``snowflake-arctic-embed2:latest``
      * ``openai`` → ``text-embedding-3-small``
      * ``qwen3`` (or anything else) → ``qwen3-embedding:0.6b``

    Mirror of ``vco_lib.embedding_service._model_id_for_active``. Both
    functions intentionally duplicate the mapping (install.py runs from
    the bundled-script venv that may not have ``vco_lib`` on PYTHONPATH
    early in the bootstrap; the helper here keeps install.py self-contained).
    """
    normalised = (active or "").strip().lower()
    if normalised == "arctic":
        return "snowflake-arctic-embed2:latest"
    if normalised == "openai":
        return "text-embedding-3-small"
    return "qwen3-embedding:0.6b"


def _read_active_embedding_from_app_state() -> "str | None":
    """v0.2.52 V52-AJ: return the launcher's active embedding profile, or None.

    Reads ``app_state[embedding.active_profile]`` (canonical key written by
    the launcher's Identity-tab embedding selector + install.py's preset
    seeding). Returns ``None`` when:
      * launcher.db file is absent (free-tier install, no launcher), OR
      * the ``app_state`` table has not been created yet (fresh first
        boot pre-migration), OR
      * the key is unset, OR
      * the stored value is an empty/whitespace string, OR
      * any sqlite error fires.

    Soft-fail throughout — callers treat ``None`` as "use env or default".
    """
    raw = _read_app_state_key(_APP_STATE_KEY_ACTIVE_EMBEDDING_LIVE)
    if raw is None:
        return None
    stripped = raw.strip()
    return stripped if stripped else None


def _resolve_active_embedding_for_install() -> "str | None":
    """v0.2.52 V52-AJ: resolve the install-time active embedding profile.

    Resolution chain (matches ``EmbeddingService._resolve_active_embedding``):

      1. ``os.environ[ACTIVE_EMBEDDING]`` — explicit user override.
      2. ``launcher.db app_state[embedding.active_profile]`` — what the
         launcher's GUI / install.py preset chooser wrote.
      3. ``None`` — caller falls back to ``"qwen3"`` default (no
         destructive resolution here; the None sentinel lets callers
         distinguish "use default" from "explicit qwen3").

    Returned value (when not None) is lowercased + stripped.

    The chain intentionally mirrors the EmbeddingService side so both
    code paths arrive at the same answer for any given (env, db) pair.
    """
    env_value = os.environ.get("ACTIVE_EMBEDDING", "").strip().lower()
    if env_value:
        return env_value
    db_value = _read_active_embedding_from_app_state()
    if db_value:
        return db_value.lower()
    return None


# v0.2.61 (stale-embedding reconcile): the active_embedding profile slot
# (qwen3 / arctic / openai) that the KG-text writer corresponds to. Mirrors
# `_TEXT_MODEL_ACTIVE_EMBEDDING` but keyed by the KG-backend constant the
# hardware selector returns, so we can map a `select_kg_embedding_backend`
# result back to its active_embedding slot without going through the model id.
_KG_BACKEND_ACTIVE_EMBEDDING = {
    _KG_BACKEND_QWEN3: "qwen3",
    _KG_BACKEND_ARCTIC: "arctic",
    _KG_BACKEND_OPENAI: "openai",
}


def _decide_reconciled_active_embedding(
    env_active: "str | None",
    hardware_active: str,
    deliberate_choice: bool,
) -> "tuple[str, bool]":
    """Pure decision: reconcile a possibly-stale ACTIVE_EMBEDDING.

    v0.2.61 (stale-embedding reconcile). Background: a clone updated
    v0.2.51→v0.2.60 on a CPU / low-RAM box carried a STALE
    ``.claude/settings.json``/``.env`` ``ACTIVE_EMBEDDING=qwen3`` written by an
    OLD install (before the hardware-aware selectors existed). On that
    hardware ``select_kg_embedding_backend`` correctly picks arctic, but the
    stale ``qwen3`` value wins at priority #1 in
    ``_resolve_active_embedding_for_install`` and the settings/.env writers
    re-cement it on every update → KG sync times out (qwen3-embedding on
    CPU-only Ollama is ~30-60 s per embedding).

    Reconciliation is intentionally NARROW + conservative — it fires only on
    the exact known-failure shape so deliberate user choices and every other
    hardware tier are left byte-for-byte untouched:

    Decision table (first match wins):

      | # | condition                                          | result                  |
      |---|----------------------------------------------------|-------------------------|
      | 1 | deliberate_choice is True                           | (env_active or hw, NO)  |
      | 2 | env_active empty / None                              | (hardware_active, NO)   |
      | 3 | env_active == hardware_active                        | (env_active, NO)        |
      | 4 | env_active == "qwen3" AND hardware_active == "arctic"| (hardware_active, YES)  |
      | 5 | env_active != hardware_active (any other mismatch)   | (env_active, NO)        |

    Row 1 (deliberate): a CLI flag (``--openai-key`` / ``--low-resource`` /
    ``--cpu-only``) or a launcher.db ``embedding.active_profile`` value means
    the user stated a preference — honour it and NEVER reconcile. (When a
    deliberate choice exists with no env value, we fall back to the env value
    if present else the hardware pick, but the caller normally already
    threaded the deliberate value into the env.)

    Row 4 (the ONLY reconcile path): stale qwen3 on hardware whose selector
    says arctic. This is almost always a leftover from a pre-selector install
    and is the documented failure mode. We rewrite to the hardware pick.

    Row 5 (other mismatch): a NON-default explicit value (e.g. env=arctic but
    hw=qwen3, or env=openai) is honoured — the user (or a deliberate prior
    install) chose a value the current detector wouldn't, and that is a
    legitimate override we must not clobber.

    Args:
        env_active: ``os.environ["ACTIVE_EMBEDDING"]`` (lowercased / stripped
            by the caller, or None / "" when unset).
        hardware_active: the hardware-aware active_embedding slot, i.e.
            ``embed_config["active_embedding"]`` from ``_choose_embedding_config``
            (or a ``select_kg_embedding_backend`` result mapped via
            ``_KG_BACKEND_ACTIVE_EMBEDDING``).
        deliberate_choice: True when a CLI flag or launcher.db value pinned
            the embedding mode (see rows 1).

    Returns:
        ``(resolved_active_embedding, was_reconciled)``. ``was_reconciled`` is
        True only on row 4 — the caller uses it to emit the log notice +
        rewrite the env. Idempotent: once the env holds the hardware pick,
        row 3 short-circuits to (value, False) on the next run.
    """
    env = (env_active or "").strip().lower()
    hw = (hardware_active or "").strip().lower() or "qwen3"

    # Row 1: deliberate choice always wins, never reconciled.
    if deliberate_choice:
        return (env or hw, False)
    # Row 2: nothing stale to reconcile — use the hardware pick.
    if not env:
        return (hw, False)
    # Row 3: env already agrees with hardware — idempotent no-op.
    if env == hw:
        return (env, False)
    # Row 4: the ONE known-failure shape — stale qwen3 where hardware says
    # arctic (CPU / low-RAM host). Reconcile to the hardware pick.
    if env == "qwen3" and hw == "arctic":
        return (hw, True)
    # Row 5: any other explicit mismatch is a legitimate override — honour it.
    return (env, False)


def _reconcile_install_active_embedding(
    embed_config: dict,
    args: "argparse.Namespace",
) -> bool:
    """Make the hardware-aware embedding pick AUTHORITATIVE for the whole run.

    Single chokepoint for ACTIVE_EMBEDDING / EMBEDDING_MODEL. Called once from
    the main install flow right after ``_choose_embedding_config``. Whenever the
    user expressed NO deliberate choice and the resolved active embedding
    differs from whatever ``os.environ["ACTIVE_EMBEDDING"]`` currently holds, it
    writes ``os.environ["ACTIVE_EMBEDDING"]`` (and ``EMBEDDING_MODEL``) to the
    hardware pick so every downstream consumer is automatically correct:

      * ``_resolve_active_embedding_for_install`` (env is priority #1) → the
        ``_seed_weaviate_impl`` resolver + the ``_subprocess_env_with_embedding``
        threading helper embed with the hardware model, not the hard-coded
        ``"qwen3"`` fallback.
      * The ``.env`` / settings.json / env-template writers that read
        ``os.environ.get("ACTIVE_EMBEDDING", ...)`` → persist the hardware pick
        instead of re-cementing ``"qwen3"``.

    Two cases mutate ``os.environ`` (both gated on "no deliberate choice"):

      1. **Stale-reconcile** (v0.2.61): an inherited stale ``ACTIVE_EMBEDDING=qwen3``
         on hardware whose selector picked arctic (CPU / low-RAM box) — see
         ``_decide_reconciled_active_embedding`` row 4. Emits the "stale" notice.
      2. **Empty-env fill** (v0.2.67): NO inherited ``ACTIVE_EMBEDDING`` at all
         (the GUI install path: the launcher spawns ``install.py --update``
         without ACTIVE_EMBEDDING set, and there is no deliberate launcher.db
         ``embedding.active_profile``). Pre-v0.2.67 this early-returned, so the
         seed resolver fell through to ``"qwen3"`` and indexed the KG with qwen3
         even though the hardware selector picked arctic. Now the hardware pick
         from ``embed_config["active_embedding"]`` is persisted to the env so the
         single ``ACTIVE_EMBEDDING`` source of truth is correct everywhere. Emits
         a quieter "applied hardware pick" notice (it is not a stale value, just
         an unset one on a fresh box).

    Deliberate choices are never touched (see
    ``_decide_reconciled_active_embedding`` row 1): a CLI flag
    (``--openai-key`` / ``--low-resource`` / ``--cpu-only``) or a launcher.db
    ``embedding.active_profile`` value pins the mode and wins byte-for-byte. An
    explicit ``ACTIVE_EMBEDDING`` from the terminal (rows 3 + 5) is likewise
    honoured: row 3 already agrees with hardware (no write needed) and row 5 is a
    legitimate non-default override left verbatim.

    Idempotent: once the env holds the hardware pick, the resolved value equals
    the env value and nothing is rewritten on a second run.

    Returns:
        True iff ``os.environ`` was written (either stale-reconcile or empty-env
        fill) — callers may ignore the return; it exists for observability /
        tests.
    """
    hardware_active = str(embed_config.get("active_embedding") or "qwen3")

    # Deliberate-choice signals:
    #   (a) explicit CLI flags that bypass auto-detect in _choose_embedding_config
    cli_flag = bool(
        getattr(args, "openai_key", None)
        or getattr(args, "low_resource", False)
        or getattr(args, "cpu_only", False)
    )
    #   (b) a launcher.db embedding.active_profile value (GUI Identity tab)
    db_choice = _read_active_embedding_from_app_state()
    deliberate = cli_flag or bool(db_choice)

    env_active = os.environ.get("ACTIVE_EMBEDDING", "").strip().lower()

    resolved, was_reconciled = _decide_reconciled_active_embedding(
        env_active=env_active,
        hardware_active=hardware_active,
        deliberate_choice=deliberate,
    )

    # Decide whether to make the resolved pick authoritative in os.environ.
    #
    # A deliberate choice is never threaded here (the CLI flag value flows
    # through embed_config; the launcher.db value is read directly by the
    # resolver + EmbeddingService) — writing it would risk clobbering an
    # explicit terminal ACTIVE_EMBEDDING the user set alongside the flag.
    #
    # When NOT deliberate, persist whenever the resolved value diverges from
    # the current env. That covers exactly two cases:
    #   * resolved != "" and env_active == ""  → empty-env fill (GUI path).
    #   * resolved != env_active (both non-empty) → row-4 stale-reconcile.
    # Rows 3 + 5 leave resolved == env_active → no write (already authoritative).
    should_persist = (not deliberate) and bool(resolved) and (resolved != env_active)

    if not should_persist:
        return False

    # Make the hardware pick authoritative: rewrite the env so every downstream
    # reader (seed resolver + .env / settings writers + subprocess threader)
    # uses the same model.
    os.environ["ACTIVE_EMBEDDING"] = resolved
    os.environ["EMBEDDING_MODEL"] = _model_id_for_active(resolved)

    if was_reconciled:
        # Case 1: a stale inherited value was overridden.
        notice = (
            f"[embedding] settings.json ACTIVE_EMBEDDING={env_active} is stale for "
            f"this CPU hardware; auto-selected {resolved}. (Set it explicitly in "
            f"the launcher Identity tab to override.)"
        )
        print(f"  {notice}")
        _log_install_event(
            "3/10", "info", "stale ACTIVE_EMBEDDING reconciled",
            data={"stale": env_active, "reconciled_to": resolved,
                  "embedding_model": os.environ["EMBEDDING_MODEL"]},
        )
    else:
        # Case 2: empty-env fill — the GUI install path with no inherited env
        # and no deliberate launcher.db choice. Quieter notice: this is the
        # expected fresh-box default, not a stale-value correction.
        notice = (
            f"[embedding] no ACTIVE_EMBEDDING set; applied hardware-selected "
            f"{resolved} for this run. (Set it explicitly in the launcher "
            f"Identity tab to override.)"
        )
        print(f"  {notice}")
        _log_install_event(
            "3/10", "info", "hardware ACTIVE_EMBEDDING applied",
            data={"applied": resolved,
                  "embedding_model": os.environ["EMBEDDING_MODEL"]},
        )
    return True


def _subprocess_env_with_embedding(base_env: "dict[str, str] | None" = None) -> "dict[str, str]":
    """v0.2.52 V52-AJ: build a subprocess env dict with ACTIVE_EMBEDDING + EMBEDDING_MODEL threaded.

    Starts from ``base_env`` (defaults to ``os.environ.copy()``) and
    OVERLAYS the resolved values from
    :func:`_resolve_active_embedding_for_install`. The overlay rules:

      * If ``ACTIVE_EMBEDDING`` is already present in ``base_env`` with a
        non-empty value, leave it alone (env always wins).
      * Otherwise, if the launcher.db resolver returned a value, set it
        in the subprocess env.
      * If neither env nor launcher.db has a value, leave the env unset —
        the subprocess will fall back to its own ``"qwen3"`` default.

    Same rule applied to ``EMBEDDING_MODEL`` (derived via
    :func:`_model_id_for_active`).

    This is the WHOLE fix for the Windows + CPU-only stuck-at-40% install
    bug (reported 2026-06-09): the install.py subprocess inherited a
    bare ``os.environ.copy()`` that did not carry the launcher's
    ``arctic`` preference, so ``EmbeddingService.for_project()`` in
    the subprocess defaulted to qwen3 and ground for hours. With this
    helper, install.py threads the resolved values explicitly.

    v0.2.70 FIX B — per-chunk timeout pass-through:
        The maintainer-sanctioned cure for a "slow but healthy" seed is a
        *tunable per-chunk* bound (``VCT_EMBED_REQUEST_TIMEOUT_SECS``), NOT a
        process kill (the seed subprocess carries no per-process timeout —
        v0.2.69 FIX 3). For an operator's override to actually reach the
        ``sync_knowledge_graph.py`` subprocess (where EmbeddingService reads
        it), install.py must thread it through here. We propagate the value
        EXPLICITLY (not merely via the ``os.environ.copy()`` inheritance) so a
        future move to a curated env allow-list can't silently drop it — and
        we only set it when present in the install shell, so an unset var
        leaves the subprocess on its 180s default rather than being pinned.

    Args:
        base_env: starting env dict. Defaults to ``os.environ.copy()``.

    Returns:
        A new dict (never the caller's, never ``os.environ`` itself)
        with the embedding env vars threaded in.
    """
    sub_env = dict(base_env) if base_env is not None else os.environ.copy()

    # v0.2.70 FIX B: explicitly carry the per-embed-request (per-chunk) timeout
    # override into the subprocess env when set in the install shell. Resolve
    # from the live process env so a curated `base_env` that omitted it still
    # gets the operator's override. Unset → leave absent (subprocess default).
    _req_timeout = os.environ.get("VCT_EMBED_REQUEST_TIMEOUT_SECS", "").strip()
    if _req_timeout and not sub_env.get("VCT_EMBED_REQUEST_TIMEOUT_SECS", "").strip():
        sub_env["VCT_EMBED_REQUEST_TIMEOUT_SECS"] = _req_timeout

    existing_active = sub_env.get("ACTIVE_EMBEDDING", "").strip()
    if existing_active:
        # Env-explicit case — make sure EMBEDDING_MODEL is consistent if
        # absent (callers may have set ACTIVE_EMBEDDING without the model id).
        if not sub_env.get("EMBEDDING_MODEL", "").strip():
            sub_env["EMBEDDING_MODEL"] = _model_id_for_active(existing_active)
        return sub_env
    # Env empty — consult launcher.db.
    resolved = _resolve_active_embedding_for_install()
    if resolved:
        sub_env["ACTIVE_EMBEDDING"] = resolved
        if not sub_env.get("EMBEDDING_MODEL", "").strip():
            sub_env["EMBEDDING_MODEL"] = _model_id_for_active(resolved)
    return sub_env


def _write_app_state_key(key: str, value: str) -> None:
    """Write/overwrite a single key in launcher.db's app_state table.

    Soft-fail: any sqlite error is silently swallowed (callers use this
    for telemetry / cache; a missed write just means the next run re-scans).
    """
    import sqlite3
    db_path = _discover_app_state_db_path()
    if not db_path.is_file():
        return
    try:
        now_ms = int(time.time() * 1000)
        conn = sqlite3.connect(str(db_path), timeout=5.0)
        try:
            conn.execute(
                "INSERT INTO app_state (key, value, updated_at) VALUES (?, ?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value = excluded.value, "
                "updated_at = excluded.updated_at",
                (key, value, now_ms),
            )
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass


