# ---------------------------------------------------------------------------
# Step 4: Virtual environment
# ---------------------------------------------------------------------------

def _create_venv(project_root: Path) -> Path:
    print("\n[3/10] Creating virtual environment ... ", end="", flush=True)
    _log_install_event("3/10", "start", "creating venv")
    venv_dir = project_root / ".venv"

    if platform.system() == "Windows":
        venv_python = venv_dir / "Scripts" / "python.exe"
    else:
        venv_python = venv_dir / "bin" / "python"

    if venv_python.exists():
        # Verification beats log signal: even if resume says ok, the
        # venv-python file is what matters. If it's gone, fall through to
        # re-create. Resume log is a hint, not a contract.
        print("already exists")
        _log_install_event(
            "3/10", "skip",
            "venv already present",
            data={"venv_python": str(venv_python)},
        )
        return venv_python

    # Don't use check=True with capture_output — we want to surface stderr on failure.
    result = subprocess.run(
        [sys.executable, "-m", "venv", str(venv_dir)],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        print("FAIL")
        print("  Failed to create venv. stderr:")
        for line in (result.stderr or "").strip().splitlines()[-20:]:
            print(f"    {line}")
        print()
        print("  Common causes:")
        if platform.system() == "Linux":
            print("    - Missing python3-venv: sudo apt install python3-venv  (Debian/Ubuntu)")
            print("                            sudo dnf install python3-venv  (Fedora)")
        print("    - Disk full or no write permission to:")
        print(f"      {venv_dir}")
        _log_install_event(
            "3/10", "error",
            f"venv creation failed (exit {result.returncode})",
            data={"exit_code": result.returncode,
                  "stderr_tail": (result.stderr or "").strip()[-400:]},
        )
        sys.exit(1)
    print("OK")
    _log_install_event(
        "3/10", "ok",
        "venv created",
        data={"venv_python": str(venv_python)},
    )
    return venv_python


# ---------------------------------------------------------------------------
# Step 5: Install dependencies
# ---------------------------------------------------------------------------

def _pip_subprocess_env() -> dict[str, str]:
    """v0.2.46 Part-1.5 H2: env for pip subprocess calls with PYTHONPATH scrubbed.

    The user's shell PYTHONPATH leaks into venv pip subprocesses by default
    (subprocess.run inherits os.environ unless told otherwise). With a non-empty
    PYTHONPATH, pip resolves imports against sibling-project paths during the
    install, occasionally shadowing the freshly-installed venv packages. This
    is rare in practice but unboundedly weird when it bites.

    Empty-string PYTHONPATH is preserved (vs deletion) so any child of the pip
    subprocess that probes PYTHONPATH sees a defined-but-empty value rather
    than inherited-from-parent semantics.

    v0.2.53 M-P1-3: also threads pip-quality-of-life env vars so the user
    doesn't get "A new release of pip is available" noise mid-install and
    doesn't get blocked by interactive prompts in non-TTY runs:
      * PIP_DISABLE_PIP_VERSION_CHECK=1 — suppresses the pip-version
        suggestion banner. This banner is decorative for install.py
        (we don't auto-upgrade based on it) and consumes a network
        round-trip per pip call.
      * PIP_NO_INPUT=1 — refuses any pip prompt (e.g. "y/n: proceed
        with install of pre-release?"). Defends against pip hangs in
        CI when stdin is /dev/null but pip thinks it has a terminal.

    pip retry/timeout/prefer-binary flags are passed at the argv level
    by callers that need them (e.g. _install_requirements) rather than
    set via env, because pip's env-var equivalents
    (PIP_DEFAULT_TIMEOUT etc) are per-version inconsistent.

    Audit finding 2026-06-03 (venv-runtime-adversarial S6) +
    docs/INSTALL_ARCHITECTURE_v2.md per-track table M-P1-3.
    """
    env = os.environ.copy()
    env["PYTHONPATH"] = ""
    env["PIP_DISABLE_PIP_VERSION_CHECK"] = "1"
    env["PIP_NO_INPUT"] = "1"
    return env


def _pip_install_flags() -> list[str]:
    """v0.2.53 M-P1-3: shared pip install flags for robustness.

    Returns a list of argv tokens to splice into ``[python, "-m", "pip",
    "install", ...]`` calls:
      * ``--timeout 60``: per-request network timeout. pip's default
        is 15s which is too short for slow networks (corporate proxies,
        OCI image-layer downloads, etc.). 60s is a good compromise.
      * ``--retries 5``: pip's default is 5 already in modern versions
        but we set it explicitly so install.py's behavior is
        independent of the pip version on PATH.
      * ``--prefer-binary``: when both a wheel and an sdist exist for a
        dep, prefer the wheel. Avoids accidental source builds when
        wheels are present.

    Callers splice these flags into the argv:

        cmd = [py, "-m", "pip", "install", *_pip_install_flags(),
               "-r", "requirements.txt"]

    Not bundled into _pip_subprocess_env() because not every pip
    invocation accepts these flags (pip --version doesn't, for
    example).
    """
    return [
        "--timeout", "60",
        "--retries", "5",
        "--prefer-binary",
    ]


# ---------------------------------------------------------------------------
# v0.2.53 DEDUP-1: _run_logged_subprocess
#
# Single helper for the ~40 `subprocess.run(capture_output=True, text=True,
# timeout=N)` callsites that follow the same boilerplate:
#
#   result = subprocess.run([...], capture_output=True, text=True, timeout=N)
#   if result.returncode != 0:
#       print(FAIL)
#       for line in result.stderr.splitlines()[-N:]:
#           print(line)
#       _log_install_event(..., 'error', ..., data={'stderr_tail': ...})
#       sys.exit(1)
#
# WHY consolidate (closes M-P0-4):
# * Single place to add dot-cycle animation (M-P1-7) so users see
#   long-running pip/npm/playwright steps are alive, not hung.
# * Uniform stderr-tail length + uniform timeout policy.
# * Uniform env-scrub (today only pip uses _pip_subprocess_env(); the
#   helper makes it opt-in once at the callsite).
# * Single place to add retry-with-backoff if/when needed.
#
# Sites covered in v0.2.53 (the 8 silent-hang sites per audit):
#   - _install_requirements: pip upgrade, pip install -r, pip install -e
#     (root), pip install -e (claude_mcp_servers)  [4 sites]
#   - _install_pinned_npm: npm install -g                                [1]
#   - _install_playwright_browsers: npx + playwright install             [2]
#   - _compile_python_modules: python -m compileall                      [1]
#
# Other ~30 sites can migrate incrementally in v0.2.54+ as they're touched
# for other reasons. The dot-cycle behavior is opt-in via
# `show_dots_after_seconds`, so non-migrated callsites stay silent (which
# is fine — they were silent before too).
# ---------------------------------------------------------------------------


def _run_logged_subprocess(
    cmd: list[str],
    *,
    step: str,
    phase_label: str,
    timeout: int,
    env: Optional[dict[str, str]] = None,
    cwd: Optional[str] = None,
    stderr_tail_lines: int = 15,
    on_failure: str = "exit",
    show_dots_after_seconds: Optional[float] = 3.0,
    fail_message: Optional[str] = None,
    user_hint_lines: Optional[list[str]] = None,
) -> "subprocess.CompletedProcess[str]":
    """Run a subprocess with uniform logging, dot-cycle animation, and stderr tail.

    Args:
        cmd: Argv list to run.
        step: Install-step label for _log_install_event (e.g. "4/10").
        phase_label: Short label for the log data (e.g. "pip-upgrade").
        timeout: Subprocess timeout in seconds.
        env: Optional env override; if None uses inherited environ.
        cwd: Optional working directory.
        stderr_tail_lines: Number of stderr lines to surface on failure.
        on_failure: One of:
            - "exit": print FAIL + tail + log error + sys.exit(1).
            - "return": print FAIL + tail + log warn; return the result.
            - "raise": re-raise CalledProcessError (for callers that
              want to handle the failure themselves).
        show_dots_after_seconds: If not None, start a dot-cycle
            background thread after this many seconds with no output.
            Set None to disable (e.g. for short probes).
        fail_message: Optional one-line message to print before tail
            when failure occurs. Default: f"FAIL ({phase_label})".
        user_hint_lines: Optional list of follow-up hint lines printed
            after the stderr tail (e.g. "check your network").

    Returns:
        subprocess.CompletedProcess[str] when on_failure="return" OR
        the command succeeded. For on_failure="exit" the function does
        not return on failure (calls sys.exit(1)).

    Raises:
        subprocess.CalledProcessError: only when on_failure="raise" AND
            the command returned non-zero.
        subprocess.TimeoutExpired: propagated when the subprocess times
            out (no on_failure branch covers timeout intentionally —
            timeout is a logic bug in the caller's `timeout` arg).
    """
    if on_failure not in ("exit", "return", "raise"):
        raise ValueError(
            f"on_failure must be 'exit'|'return'|'raise', got {on_failure!r}"
        )

    # Dot-cycle animation: in a separate thread to avoid blocking the
    # subprocess. We poll the subprocess by spawning it ourselves rather
    # than via subprocess.run, so the animation can be cancelled cleanly
    # when the subprocess exits.
    proc = subprocess.Popen(
        cmd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        env=env,
        cwd=cwd,
    )

    dots_stop = False
    dots_thread = None

    def _dot_cycle() -> None:
        # Display "[12s] ..." style elapsed counter + cycling dots.
        # The leading carriage-return overwrites the line each tick.
        # First dot appears after `show_dots_after_seconds` of no output.
        if show_dots_after_seconds is None:
            return
        time.sleep(show_dots_after_seconds)
        start = time.monotonic()
        dot_state = 0
        while not dots_stop and proc.poll() is None:
            elapsed = int(time.monotonic() - start) + int(show_dots_after_seconds)
            dots = "." * ((dot_state % 4) + 1)  # 1, 2, 3, 4 dots
            try:
                sys.stdout.write(f"\r  [{elapsed:>3}s] {phase_label} {dots:<4}")
                sys.stdout.flush()
            except (OSError, ValueError):
                # Detached / closed stdout — just stop animating.
                break
            dot_state += 1
            time.sleep(1.0)
        # Clear the line so the next print starts fresh.
        try:
            sys.stdout.write("\r" + " " * 60 + "\r")
            sys.stdout.flush()
        except (OSError, ValueError):
            pass

    if show_dots_after_seconds is not None and sys.stdout.isatty():
        import threading
        dots_thread = threading.Thread(target=_dot_cycle, daemon=True)
        dots_thread.start()

    try:
        stdout_text, stderr_text = proc.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        dots_stop = True
        try:
            proc.kill()
            proc.communicate(timeout=5)
        except (subprocess.TimeoutExpired, OSError):
            pass
        if dots_thread is not None:
            dots_thread.join(timeout=2)
        _log_install_event(
            step, "error",
            f"{phase_label} timed out after {timeout}s",
            data={"phase": phase_label, "timeout": timeout},
        )
        if on_failure == "exit":
            print(f"FAIL ({phase_label} timed out after {timeout}s)")
            sys.exit(1)
        raise
    finally:
        dots_stop = True
        if dots_thread is not None:
            dots_thread.join(timeout=2)

    result = subprocess.CompletedProcess(
        args=cmd, returncode=proc.returncode,
        stdout=stdout_text, stderr=stderr_text,
    )

    if result.returncode == 0:
        return result

    # Failure path. Empty `fail_message=""` means "suppress the header
    # line"; the caller is summarising errors itself (e.g. compileall
    # loops over multiple dirs and prints one final summary).
    msg = fail_message if fail_message is not None else f"FAIL ({phase_label})"
    if msg:
        print(msg)
    tail = (result.stderr or "").strip().splitlines()[-stderr_tail_lines:]
    if msg:
        for line in tail:
            print(f"  {line}")
    if user_hint_lines:
        print()
        for line in user_hint_lines:
            print(f"  {line}")
    _log_install_event(
        step, "error" if on_failure == "exit" else "warn",
        f"{phase_label} failed (exit {result.returncode})",
        data={
            "phase": phase_label,
            "exit_code": result.returncode,
            "stderr_tail": (result.stderr or "").strip()[-400:],
        },
    )
    if on_failure == "exit":
        sys.exit(1)
    if on_failure == "raise":
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=cmd,
            output=stdout_text,
            stderr=stderr_text,
        )
    return result  # on_failure == "return"


def _install_requirements(venv_python: Path, *, dev: bool) -> None:
    label = "with dev extras" if dev else "production"
    print(f"[4/10] Installing dependencies ({label}) ... ", flush=True)
    _log_install_event(
        "4/10", "start",
        f"pip install ({label})",
        data={"dev": dev},
    )

    # Upgrade pip — surface errors instead of swallowing them via check=True.
    # v0.2.53 DEDUP-1 (M-P0-4 silent-hang fix): _run_logged_subprocess adds
    # dot-cycle animation after 3s so the user can see pip is alive during
    # the typical 30–90s upgrade.
    # v0.2.53 M-P1-3: pip's own self-upgrade benefits from the same
    # robustness flags (--timeout, --retries, --prefer-binary). pip
    # is happy to receive flags from its own command line.
    _run_logged_subprocess(
        [str(venv_python), "-m", "pip", "install",
         *_pip_install_flags(),
         "--upgrade", "pip"],
        step="4/10", phase_label="pip-upgrade",
        timeout=300, env=_pip_subprocess_env(),
        fail_message="  FAIL (pip upgrade)",
        user_hint_lines=[
            "Hint: check your network connection and PyPI availability.",
            "      If behind a corporate proxy, set http_proxy/https_proxy.",
        ],
    )

    # Install requirements
    req_file = PROJECT_ROOT / "requirements.txt"
    if not req_file.exists():
        print("  WARNING: requirements.txt not found, skipping pip install")
        _log_install_event(
            "4/10", "warn",
            "requirements.txt missing",
            data={"requirements": str(req_file)},
        )
        return

    # v0.2.53 M-P1-3: thread pip robustness flags into install argv.
    cmd = [str(venv_python), "-m", "pip", "install",
           *_pip_install_flags(),
           "-r", str(req_file)]
    if dev:
        req_dev = PROJECT_ROOT / "requirements-dev.txt"
        if req_dev.exists():
            cmd = [str(venv_python), "-m", "pip", "install",
                   *_pip_install_flags(),
                   "-r", str(req_file), "-r", str(req_dev)]

    # v0.2.53 DEDUP-1: M-P0-4 silent-hang fix at the longest-running pip
    # call in the install. Was the dominant user-reported "install
    # appears hung" complaint pre-v0.2.53.
    _run_logged_subprocess(
        cmd,
        step="4/10", phase_label="pip-install",
        timeout=1800, env=_pip_subprocess_env(),
        fail_message="  FAIL",
        stderr_tail_lines=30,
    )
    print("  OK")
    _log_install_event("4/10", "ok", "pip install completed")

    # Editable-install the orchestrator's own Python distribution so the
    # `vco` console-script lands on PATH inside `.venv/bin/` (cross-OS:
    # hatchling generates `vco.exe` on Windows). Replaces the
    # `scripts/vco{,.ps1}` shim wrappers from Phase 0.C.
    #
    # Gated on pyproject.toml's existence so older clones (pre-0.2.34) or
    # exotic install paths that strip pyproject.toml don't fail loudly —
    # they just don't get the `vco` entry point (shim wrappers were the
    # previous answer; we don't ship them anymore).
    pyproject = PROJECT_ROOT / "pyproject.toml"
    if not pyproject.exists():
        _log_install_event(
            "4/10", "skip",
            "pyproject.toml missing; skipping editable install of vco CLI",
            data={"pyproject_path": str(pyproject)},
        )
        return

    print("[4/10] Installing vco CLI (editable) ... ", end="", flush=True)
    _log_install_event("4/10", "start", "pip install -e . (vco CLI)")
    # v0.2.53 DEDUP-1: silent-hang fix. Soft-fail (on_failure="return")
    # because the CLI entry point is best-effort; sys.path fallback works.
    editable_result = _run_logged_subprocess(
        [str(venv_python), "-m", "pip", "install",
         *_pip_install_flags(),
         "-e", "."],
        step="4/10", phase_label="pip-install-editable-vco",
        timeout=600,
        cwd=str(PROJECT_ROOT),
        env=_pip_subprocess_env(),
        on_failure="return",
        fail_message="FAIL",
        user_hint_lines=[
            "The orchestrator install completed, but the `vco` CLI entry "
            "point did NOT register. You can still invoke it via",
            "`python -m vco_lib.cli <subcommand>` until this is resolved.",
        ],
    )
    if editable_result.returncode != 0:
        # Soft-fail: don't kill the whole install over the CLI entry
        # point. `python -m vco_lib.cli` keeps working regardless.
        return
    print("OK")
    _log_install_event("4/10", "ok", "vco CLI editable install completed")

    # A1 (v0.2.38): pip-install weaviate_mcp as an editable package so all
    # consumer scripts can `from weaviate_mcp.chunking import Chunker` (etc.)
    # without sys.path hacks.  Runs AFTER the root `pip install -e .` so the
    # venv already has all shared deps (mcp, weaviate-client, aiohttp, …) and
    # hatchling can satisfy them without a network hit.
    #
    # Gated on the sub-package's pyproject.toml so older clones (pre-0.2.38)
    # or exotic paths that strip that file don't fail loudly — they just keep
    # using sys.path-based resolution.
    mcp_pyproject = PROJECT_ROOT / "claude_mcp_servers" / "pyproject.toml"
    if not mcp_pyproject.exists():
        _log_install_event(
            "4/10", "skip",
            "claude_mcp_servers/pyproject.toml missing; skipping weaviate_mcp editable install",
            data={"mcp_pyproject_path": str(mcp_pyproject)},
        )
        return

    print("[4/10] Installing weaviate_mcp (editable) ... ", end="", flush=True)
    _log_install_event("4/10", "start", "pip install -e claude_mcp_servers/ (weaviate_mcp)")
    # v0.2.53 DEDUP-1: silent-hang fix. Soft-fail (on_failure="return")
    # because sys.path fallback keeps consumer scripts working.
    mcp_editable_result = _run_logged_subprocess(
        [str(venv_python), "-m", "pip", "install",
         *_pip_install_flags(),
         "-e", str(PROJECT_ROOT / "claude_mcp_servers")],
        step="4/10", phase_label="pip-install-editable-weaviate_mcp",
        timeout=600,
        cwd=str(PROJECT_ROOT),
        env=_pip_subprocess_env(),
        on_failure="return",
        fail_message="FAIL",
        user_hint_lines=[
            "The orchestrator install completed, but weaviate_mcp is not pip-installed.",
            "Consumer scripts fall back to sys.path resolution automatically.",
        ],
    )
    if mcp_editable_result.returncode != 0:
        # Soft-fail: don't kill the whole install — sys.path fallbacks still work.
        return
    print("OK")
    _log_install_event("4/10", "ok", "weaviate_mcp editable install completed")


# ---------------------------------------------------------------------------
# Step 5b: Materialize orchestrator-self .claude/ from templates
#
# PR-39 (v0.2.12, 2026-05-16). Before this PR the public repo shipped:
#   1. 50 .claude/hooks/*.{sh,ps1} files byte-identical with templates/hooks/*
#      (CI gate check_template_drift.py enforced parity — pure duplication).
#   2. 36 .claude/scripts/*.py files where templates were NEWER (post commit
#      c209261 per-project portability fix never reached the active copies).
#   3. .claude/settings.json — bash-flavored Linux/macOS-only assembled
#      artifact that would break on Windows installs without bash.
#
# User direction (2026-05-16): "anything that is or will be generated from a
# template at install time should NOT ship in the public repo. Only ship the
# template itself." Templates are now the single source of truth; this
# function renders the orchestrator-self's runtime .claude/ from them at
# install time (and on every --update). Downstream user projects already
# went through this template-driven render via vco_lib.project_init —
# orchestrator-self now uses the same pipeline.
# ---------------------------------------------------------------------------

def _load_self_materialize_prior_hashes(install_root: Path) -> dict:
    """Read the prior-shipped hashes from
    ``<install_root>/.claude/.vco-manifest.json`` (the V0243-4 manifest
    rewritten by :func:`_refresh_orchestrator_self_vco_manifest` after
    every materialize run).

    Returns ``{".claude/hooks/<name>": "<sha256>", ...}``. Missing or
    corrupt manifest → empty dict (the git-history heal in
    ``_self_materialize_file_action`` covers pre-manifest installs).
    """
    target = install_root / ".claude" / ".vco-manifest.json"
    try:
        data = json.loads(target.read_text(encoding="utf-8"))
        files = data.get("files") if isinstance(data, dict) else None
        if isinstance(files, dict):
            return {
                k: (v or {}).get("sha256", "")
                for k, v in files.items()
                if isinstance(v, dict)
            }
    except (OSError, json.JSONDecodeError):
        pass
    return {}


def _self_materialize_file_action(
    src: Path,
    target: Path,
    prior_hash: str,
    install_root: Path,
) -> tuple[str, bytes]:
    """Per-file decision for the orchestrator-self materialize — the
    v0.2.54 Track D backport of ``vco_lib.project_init._file_action``'s
    bundle-path semantics (hash-compare + preserve, instead of the
    pre-fix unconditional overwrite that silently destroyed runtime-copy
    edits like the 118-line agent-skill-keyword-match divergence observed
    in the field).

    Returns (action, source_bytes) where action is one of:
      "create"    — target missing.
      "noop"      — target identical to the current template.
      "overwrite" — target matches the prior-shipped hash (manifest) OR
                    any historical shipped version (git-history heal,
                    v0.2.31 pattern) → user untouched, safe to update.
      "preserve"  — target diverges from every shipped version → user-
                    modified; skip + defer.
    """
    source_bytes = src.read_bytes()
    if not target.exists():
        return ("create", source_bytes)
    installed_hash = _project_init._file_sha256(target)
    new_hash = _project_init._bytes_sha256(source_bytes)
    if installed_hash == new_hash:
        return ("noop", source_bytes)
    if prior_hash and installed_hash == prior_hash:
        return ("overwrite", source_bytes)
    # Pre-manifest installs (every install before v0.2.54) have no
    # prior_hash. Walk the template's git history: installed content
    # matching ANY shipped version = "VCO-shipped, just stale" → safe
    # to overwrite. Genuinely user-edited content matches nothing →
    # preserve. (Same discipline as project_init._file_action's
    # v0.2.31 heal — without it, the first post-v0.2.54 update would
    # freeze every stale-but-untouched runtime copy forever.)
    if _project_init._installed_matches_template_history(
        src, installed_hash, install_root,
    ):
        return ("overwrite", source_bytes)
    return ("preserve", source_bytes)


def _emit_self_materialize_preserved_deferral(
    deferral_report: "DeferralReport | None",
    preserved: list,
    install_root: Path,
) -> None:
    """Emit ``orchestrator_self_user_modified_preserved``: the
    orchestrator-self materialize found runtime copies in
    ``.claude/{hooks,scripts}`` that diverge from every shipped template
    version and left them in place."""
    if deferral_report is None or not preserved:
        return
    try:
        file_list = _project_init._format_file_list_md(
            [f".claude/{p}" for p in preserved],
        )
        deferral_report.add_entry(
            DeferralEntry(
                condition_id="orchestrator_self_user_modified_preserved",
                title=(
                    f"{len(preserved)} user-modified .claude/ file(s) "
                    "preserved during materialize"
                ),
                detected=(
                    "While rendering the orchestrator's runtime .claude/ "
                    "from templates/, these files diverged from every "
                    "version VCO ever shipped (manifest hash + git-history "
                    "walk) and were PRESERVED on disk:\n" + file_list
                ),
                why_deferred=(
                    "Pre-v0.2.54 this step silently overwrote runtime "
                    "copies, destroying local edits (dogfooded features, "
                    "hotfixes applied directly to .claude/scripts/). The "
                    "preserved files may now LAG the shipped templates — "
                    "diff them and either port your changes INTO "
                    "templates/ (so they ship) or accept the template "
                    "versions."
                ),
                command_to_apply=(
                    "# Compare each preserved file against its template:\n"
                    "#   diff .claude/scripts/<name> templates/scripts/<name>\n"
                    "# Accept the template versions for ALL preserved files:\n"
                    "python install.py --update --force-materialize-claude-dir"
                ),
                severity="warning",
                kg_node_refs=[],
            )
        )
    except Exception as exc:  # noqa: BLE001 — soft-fail by design
        _log_install_event(
            "4b/10", "warn",
            f"could not emit orchestrator_self_user_modified_preserved "
            f"deferral: {exc}",
        )


def _materialize_orchestrator_self_claude_dir(
    install_root: Path,
    deferral_report: "DeferralReport | None" = None,
    force_overwrite: bool = False,
) -> None:
    """Render the orchestrator-self's runtime .claude/ contents from templates.

    Copies ``templates/hooks/*`` → ``<install_root>/.claude/hooks/`` and
    ``templates/scripts/*`` → ``<install_root>/.claude/scripts/`` preserving
    executable bits, then renders the OS-appropriate
    ``templates/settings.json.{linux,windows}.template`` to
    ``<install_root>/.claude/settings.json``.

    v0.2.54 Track D (Theme 5): per-file hash-compare with preserve-and-
    defer semantics, backported from the per-project bundle path
    (``project_init._file_action``). A runtime copy that diverges from
    every shipped template version (self-manifest hash + git-history
    heal) is PRESERVED and listed in an
    ``orchestrator_self_user_modified_preserved`` deferral entry instead
    of silently overwritten. ``--force-materialize-claude-dir`` accepts
    the template versions. ``hooks/_lib`` subdirs remain always-
    overwrite (not user-customisable — same contract as the bundle
    path). Prior-shipped hashes come from ``.claude/.vco-manifest.json``
    (rewritten with template hashes by
    ``_refresh_orchestrator_self_vco_manifest`` right after this
    function runs).

    Idempotent: re-running converges on the current templates for every
    file the user hasn't touched. Users running ``install.py --update``
    after a ``git pull`` get the latest hook/script/settings content
    automatically.

    Soft-fail: if any individual template file is missing for some reason,
    a warning is logged and the install continues — a partial hook set
    is better than aborting an entire install over a single file. The
    settings.json render is also soft-fail (skipped with warning) so a
    missing OS template doesn't kill the install on an unexpected
    platform.

    v0.2.46 V47-B (Gap B): if ``.claude/`` (or ``.claude/hooks/`` /
    ``.claude/scripts/``) is a symlink, VCO writes its content to a
    sibling ``.vco-new`` path and emits a deferral entry. The original
    symlink is preserved. Symlinks at individual file targets are also
    caught — the symlinked file is left alone and VCO's content lands
    at the sibling.

    Honors ``--skip-materialize-claude-dir`` for tests / special-case
    installs targeting a pre-populated .claude/ directory.
    """
    claude_dir = install_root / ".claude"
    templates_dir = install_root / "templates"

    print("[4b/10] Materializing orchestrator .claude/ from templates ... ",
          end="", flush=True)
    _log_install_event("4b/10", "start",
                       "rendering .claude/{hooks,scripts,settings.json}")

    copied_hooks = 0
    copied_scripts = 0
    warnings: list[str] = []
    # v0.2.70 FIX-3 (Stream B sibling): accumulate every (symlink, .vco-new)
    # redirect pair across the materialize so we can emit ONE consolidated
    # deferral via emit_symlink_deferral_multi. Calling the single-pair
    # emit_symlink_deferral once per redirect would silently DROP all but the
    # last (DeferralReport.add_entry is last-write-wins per condition_id, and
    # all 8 redirects share SYMLINK_PRESERVED_CONDITION_ID) -- the exact bug
    # class Stream B fixed for the bundle path.
    symlink_events: list[tuple[Path, Path]] = []
    # v0.2.54 Track D: hash-compare bookkeeping. Prior-shipped hashes
    # come from .claude/.vco-manifest.json (rewritten with TEMPLATE
    # hashes by _refresh_orchestrator_self_vco_manifest after this
    # function). `preserved` collects ".claude/"-relative paths (e.g.
    # "scripts/foo.py") left in place because they diverge from every
    # shipped version.
    prior_hashes = _load_self_materialize_prior_hashes(install_root)
    preserved: list = []

    # v0.2.46 V47-B (Gap B): if .claude/ itself is a symlink, redirect
    # the entire materialization to a sibling .vco-new tree. This catches
    # the symlinked-claude-dir case where the user pointed .claude at a
    # shared workflow tree — VCO refuses to touch it.
    if is_symlink_blocking(claude_dir):
        vco_new_claude = compute_vco_new_path(claude_dir)
        symlink_events.append((claude_dir, vco_new_claude))
        warnings.append(
            f".claude/ is a symlink — materializing into "
            f"{vco_new_claude.name} instead (see UPDATE_DEFERRED.md)"
        )
        claude_dir = vco_new_claude

    # 1. Hooks: templates/hooks/* → .claude/hooks/* preserving exec bit.
    hooks_src = templates_dir / "hooks"
    hooks_dst = claude_dir / "hooks"
    if not hooks_src.is_dir():
        warnings.append(f"templates/hooks/ missing at {hooks_src}")
    else:
        # v0.2.46 V47-B: symlinked .claude/hooks/ → redirect to sibling.
        if is_symlink_blocking(hooks_dst):
            vco_new_hooks = compute_vco_new_path(hooks_dst)
            symlink_events.append((hooks_dst, vco_new_hooks))
            warnings.append(
                f".claude/hooks is a symlink — writing into "
                f"{vco_new_hooks.name} instead"
            )
            hooks_dst = vco_new_hooks

        hooks_dst.mkdir(parents=True, exist_ok=True)
        # v0.2.54 Track G (G-4): filter by the shared hook-flavour globs.
        # Pre-G-4 this loop copied every file via iterdir() — which DID
        # ship both .sh + .ps1 flavours, but by accident rather than
        # policy, and would also have shipped any stray non-hook file
        # someone dropped into templates/hooks/. Now the both-flavours
        # policy is explicit and shared with Step 9b + project_init.
        from vco_lib.bundle_globs import hook_globs as _hook_globs
        from fnmatch import fnmatch as _fnmatch
        for src in hooks_src.iterdir():
            if not src.is_file():
                continue  # Skip _lib/ and other subdirs; handled below.
            if not any(_fnmatch(src.name, g) for g in _hook_globs()):
                continue  # Not a hook flavour we ship (.sh / .ps1 only).
            target = hooks_dst / src.name
            # v0.2.46 V47-B: individual hook file is a symlink → skip
            # the in-place copy; land VCO's version at the sibling.
            if is_symlink_blocking(target):
                vco_new_file = compute_vco_new_path(target)
                symlink_events.append((target, vco_new_file))
                try:
                    shutil.copy2(src, vco_new_file)
                except OSError as e:
                    warnings.append(
                        f"failed to copy {src.name} to .vco-new sibling: {e}"
                    )
                continue
            try:
                # v0.2.54 Track D: hash-compare instead of unconditional
                # overwrite. User-modified runtime copies are preserved
                # + deferred (see _self_materialize_file_action).
                prior_hash = prior_hashes.get(
                    str(Path(".claude") / "hooks" / src.name), "",
                )
                action, _source_bytes = _self_materialize_file_action(
                    src, target, prior_hash, install_root,
                )
                if action == "preserve" and not force_overwrite:
                    preserved.append(f"hooks/{src.name}")
                    continue
                if action != "noop":
                    shutil.copy2(src, target)
                # v0.2.53 belt-and-braces: install.py's pre-existing test
                # `test_install_into_fresh_target_linux` caught 3 v0.2.52
                # hooks shipped with mode 664 (no exec bit). Without exec
                # bit, Claude Code refuses to fire the hook on POSIX. Defend
                # by force-setting 0o755 on every .sh hook target — copy2
                # preserves source mode, so any contributor who commits a
                # 664-mode hook silently disables it without this fix.
                if src.suffix == ".sh":
                    try:
                        os.chmod(target, 0o755)
                    except OSError as chmod_e:
                        warnings.append(
                            f"failed to chmod 755 {src.name}: {chmod_e}"
                        )
                copied_hooks += 1
            except OSError as e:
                warnings.append(f"failed to copy {src.name}: {e}")
        # Also copy nested helper dirs (e.g. _lib/) that ship alongside.
        for sub in hooks_src.iterdir():
            if sub.is_dir():
                dst_sub = hooks_dst / sub.name
                # v0.2.46 V47-B: never rmtree a symlinked subdir; land
                # at sibling instead.
                if is_symlink_blocking(dst_sub):
                    vco_new_sub = compute_vco_new_path(dst_sub)
                    symlink_events.append((dst_sub, vco_new_sub))
                    try:
                        shutil.copytree(sub, vco_new_sub)
                    except OSError as e:
                        warnings.append(
                            f"failed to copy hooks subdir "
                            f"{sub.name} to .vco-new sibling: {e}"
                        )
                    continue
                if os.path.lexists(os.fspath(dst_sub)):
                    shutil.rmtree(dst_sub)
                try:
                    shutil.copytree(sub, dst_sub)
                except OSError as e:
                    warnings.append(f"failed to copy hooks subdir {sub.name}: {e}")

    # 2. Scripts: same pattern.
    scripts_src = templates_dir / "scripts"
    scripts_dst = claude_dir / "scripts"
    if not scripts_src.is_dir():
        warnings.append(f"templates/scripts/ missing at {scripts_src}")
    else:
        # v0.2.46 V47-B: symlinked .claude/scripts/ → redirect to sibling.
        if is_symlink_blocking(scripts_dst):
            vco_new_scripts = compute_vco_new_path(scripts_dst)
            symlink_events.append((scripts_dst, vco_new_scripts))
            warnings.append(
                f".claude/scripts is a symlink — writing into "
                f"{vco_new_scripts.name} instead"
            )
            scripts_dst = vco_new_scripts

        scripts_dst.mkdir(parents=True, exist_ok=True)
        for src in scripts_src.iterdir():
            if not src.is_file():
                continue
            target = scripts_dst / src.name
            # v0.2.46 V47-B: individual script file is a symlink → skip.
            if is_symlink_blocking(target):
                vco_new_file = compute_vco_new_path(target)
                symlink_events.append((target, vco_new_file))
                try:
                    shutil.copy2(src, vco_new_file)
                except OSError as e:
                    warnings.append(
                        f"failed to copy {src.name} to .vco-new sibling: {e}"
                    )
                continue
            try:
                # v0.2.54 Track D: same hash-compare contract as hooks.
                prior_hash = prior_hashes.get(
                    str(Path(".claude") / "scripts" / src.name), "",
                )
                action, _source_bytes = _self_materialize_file_action(
                    src, target, prior_hash, install_root,
                )
                if action == "preserve" and not force_overwrite:
                    preserved.append(f"scripts/{src.name}")
                    continue
                if action != "noop":
                    shutil.copy2(src, target)
                copied_scripts += 1
            except OSError as e:
                warnings.append(f"failed to copy {src.name}: {e}")

    # 3. settings.json: OS-dispatch + render.
    if platform.system() == "Windows":
        settings_template = templates_dir / "settings.json.windows.template"
    else:
        settings_template = templates_dir / "settings.json.linux.template"
    if not settings_template.is_file():
        warnings.append(f"settings template missing at {settings_template}")
    else:
        try:
            settings_dst = claude_dir / "settings.json"
            settings_dst.parent.mkdir(parents=True, exist_ok=True)

            # v0.2.46 V47-B (Gap B): symlinked settings.json → write to
            # sibling. Catches the case where the user symlinks
            # settings.json to a shared config tree across projects.
            if is_symlink_blocking(settings_dst):
                vco_new_settings = compute_vco_new_path(settings_dst)
                symlink_events.append((settings_dst, vco_new_settings))
                warnings.append(
                    f".claude/settings.json is a symlink — writing into "
                    f"{vco_new_settings.name} instead"
                )
                settings_dst = vco_new_settings

            # v0.2.30 fix: preserve existing settings.json's `env` block on
            # re-render. Pre-v0.2.30 this code unconditionally overwrote
            # settings.json with the rendered template — which has NO env
            # block. Result: any user-customized `env.KG_COLLECTION` (e.g.
            # a per-project override pointing at the project's legacy
            # collection name) was silently wiped on every
            # `install.py --update` run, then the downstream
            # `_backfill_kg_collection_env_in_project` step re-derived a
            # default that didn't match what the user had set. Symptom:
            # `hybrid_search` returns 0 results because the MCP queries
            # the wrong collection. Now: when settings.json already
            # exists, merge the template's hooks/permissions block in but
            # PRESERVE the user's env, _comment, and any other top-level
            # keys. Fresh installs see no change (template wins).
            rendered = settings_template.read_text(encoding="utf-8")
            # Placeholder substitution (no-op today: the OS templates are
            # fully concrete and ship without `{{PROJECT_NAME}}` markers).
            rendered = rendered.replace("{{PROJECT_NAME}}",
                                        "VibeCoded Orchestrator")

            if settings_dst.is_file():
                # Existing settings.json — merge additively. Preserve
                # any top-level key the template doesn't declare (in
                # particular `env`, `_comment`, `_env_comment`), and
                # take the template's version for keys it does declare
                # (`hooks`, `permissions`, `$schema`, `_template_origin`).
                try:
                    existing = json.loads(
                        settings_dst.read_text(encoding="utf-8")
                    )
                    rendered_obj = json.loads(rendered)
                    if isinstance(existing, dict) and isinstance(
                        rendered_obj, dict
                    ):
                        merged = dict(existing)  # start with user state
                        for k, v in rendered_obj.items():
                            # Template wins for hook/permission/schema
                            # keys (those are the "shipped contract").
                            # User wins for env-shaped keys (preserved
                            # via NOT overwriting from template). The
                            # rendered template has no `env` key, so
                            # `existing.env` survives by construction —
                            # this is the load-bearing invariant.
                            merged[k] = v
                        settings_dst.write_text(
                            json.dumps(merged, indent=2) + "\n",
                            encoding="utf-8",
                        )
                    else:
                        # User had unparseable JSON — refuse to clobber.
                        warnings.append(
                            "settings.json present but unparseable; left untouched"
                        )
                except (OSError, json.JSONDecodeError) as e:
                    warnings.append(
                        f"settings.json merge failed ({e}); left untouched"
                    )
            else:
                # Fresh install — write the template as-is. The
                # downstream `_backfill_code_graph_project_env` +
                # `_backfill_kg_collection_env_in_project` steps add
                # the env block.
                settings_dst.write_text(rendered, encoding="utf-8")
        except OSError as e:
            warnings.append(f"failed to render settings.json: {e}")

    # v0.2.70 FIX-3: emit ONE consolidated symlink deferral covering every
    # (symlink, .vco-new) redirect this run hit. Replaces the 8 single-pair
    # emits that collapsed to last-write-wins under the shared condition_id.
    if symlink_events and deferral_report is not None:
        emit_symlink_deferral_multi(
            deferral_report, symlink_events, install_root=install_root,
        )

    # v0.2.54 Track D: surface preserved (user-modified) runtime copies.
    # Informational, not a failure — but they must be visible: the
    # preserved files now LAG the shipped templates until the user diffs
    # + reconciles (or re-runs with --force-materialize-claude-dir).
    if preserved:
        _emit_self_materialize_preserved_deferral(
            deferral_report, preserved, install_root,
        )
        warnings.append(
            f"{len(preserved)} user-modified file(s) preserved (not "
            f"overwritten): {', '.join(sorted(preserved)[:10])}"
            + (" ..." if len(preserved) > 10 else "")
            + " — see UPDATE_DEFERRED.md"
        )
        _log_install_event(
            "4b/10", "info",
            f"preserved {len(preserved)} user-modified .claude/ file(s)",
            data={"preserved": sorted(preserved)},
        )

    if warnings:
        print("PARTIAL")
        for w in warnings:
            print(f"  ! {w}")
        _log_install_event(
            "4b/10", "warn",
            f"materialized {copied_hooks} hooks + {copied_scripts} scripts "
            f"with {len(warnings)} warnings",
            data={"warnings": warnings,
                  "copied_hooks": copied_hooks,
                  "copied_scripts": copied_scripts},
        )
    else:
        print(f"OK ({copied_hooks} hooks, {copied_scripts} scripts)")
        _log_install_event(
            "4b/10", "ok",
            f"materialized {copied_hooks} hooks + {copied_scripts} scripts",
            data={"copied_hooks": copied_hooks,
                  "copied_scripts": copied_scripts},
        )

    # V0243-4: on orchestrator-root installs, refresh .vco-manifest.json
    # with current shipped-file SHA256s + bump vco_version. Only runs after
    # templates have been copied (so hashes reflect the latest on-disk state).
    if _is_orchestrator_root_install():
        _refresh_orchestrator_self_vco_manifest(install_root)

    # v0.2.50 Track A: also materialize the orchestrator's own CLAUDE.md
    # from templates/ORCHESTRATOR-CLAUDE.md.template. Idempotent — runs on
    # every install + --update. Preserves user content outside the AUTO
    # markers; replaces the AUTO block with freshly rendered template.
    _materialize_orchestrator_self_claude_md(install_root)


def _materialize_orchestrator_self_claude_md(install_root: Path) -> None:
    """v0.2.50 Track A: render templates/ORCHESTRATOR-CLAUDE.md.template
    to ``<install_root>/CLAUDE.md``.

    The template uses ``{{ORCHESTRATOR_ROOT}}`` for the resolved install
    root path. The rendered content is wrapped in HTML comment markers
    (``<!-- BEGIN: AUTO -->`` / ``<!-- END: AUTO -->``) so that on
    ``--update`` re-runs, only the AUTO block is replaced — user-added
    content OUTSIDE those markers is preserved.

    Idempotent:
    - First run (no CLAUDE.md or CLAUDE.md without AUTO markers): writes
      the rendered template as the entire file.
    - Subsequent runs (CLAUDE.md has AUTO markers): replaces only the
      block between BEGIN/END AUTO; preserves content before/after.

    Soft-fail: any error here is logged but does not abort the install.
    A missing CLAUDE.md is not fatal — the orchestrator still runs.
    """
    template_path = install_root / "templates" / "ORCHESTRATOR-CLAUDE.md.template"
    target_path = install_root / "CLAUDE.md"

    print("[4c/10] Materializing orchestrator CLAUDE.md from template ... ",
          end="", flush=True)
    _log_install_event("4c/10", "start",
                       "rendering CLAUDE.md from ORCHESTRATOR-CLAUDE.md.template")

    if not template_path.is_file():
        print("SKIP (template missing)")
        _log_install_event(
            "4c/10", "skip",
            f"template not found at {template_path}",
        )
        return

    try:
        rendered = template_path.read_text(encoding="utf-8")
        # Placeholder substitution.
        rendered = rendered.replace("{{ORCHESTRATOR_ROOT}}", str(install_root))

        if target_path.is_file():
            existing = target_path.read_text(encoding="utf-8")
            begin_marker = "<!-- BEGIN: AUTO"
            end_marker = "<!-- END: AUTO -->"
            begin_idx = existing.find(begin_marker)
            end_idx = existing.find(end_marker)
            if begin_idx >= 0 and end_idx > begin_idx:
                # Preserve content outside AUTO markers; replace AUTO block.
                prefix = existing[:begin_idx]
                suffix = existing[end_idx + len(end_marker):]
                merged = prefix + rendered.rstrip() + suffix
                # Avoid no-op writes that would still bump mtime.
                if merged != existing:
                    target_path.write_text(merged, encoding="utf-8")
                print("OK (AUTO block updated)")
                _log_install_event(
                    "4c/10", "ok",
                    "CLAUDE.md AUTO block updated; user content preserved",
                )
            else:
                # No AUTO markers in existing file — write rendered as-is.
                # (Existing content is replaced because the AUTO markers are
                # the contract for "preserve me"; without them, the template
                # is the source of truth.)
                target_path.write_text(rendered, encoding="utf-8")
                print("OK (full rewrite — no AUTO markers found)")
                _log_install_event(
                    "4c/10", "ok",
                    "CLAUDE.md fully rewritten (no AUTO markers in prior version)",
                )
        else:
            # Fresh install — write rendered as-is.
            target_path.write_text(rendered, encoding="utf-8")
            print("OK (created)")
            _log_install_event(
                "4c/10", "ok",
                "CLAUDE.md created from template",
            )
    except OSError as e:
        print(f"FAILED ({e})")
        _log_install_event(
            "4c/10", "warn",
            f"failed to materialize CLAUDE.md: {e}",
        )


def _materialize_vct_secrets_shared_readme(install_root: Path) -> None:
    """v0.2.54 S-3: install-side wrapper around
    :func:`vco_lib.secrets_bootstrap.materialize_shared_readme`.

    Translates the shared helper's :class:`MaterializeReadmeResult`
    into the phase-prefixed install-event stream and the user-visible
    print line. Soft-fail: secrets-store problems never abort an
    install.
    """
    from vco_lib.secrets_bootstrap import materialize_shared_readme
    result = materialize_shared_readme(install_root)
    if result.status == "template_missing":
        _log_install_event(
            "5c/10", "skip",
            f"vct-secrets readme template missing: {result.message}",
        )
    elif result.status == "preserved":
        _log_install_event(
            "5c/10", "skip",
            "~/.vct-secrets/shared/_README.md already exists (user copy preserved)",
        )
    elif result.status == "materialized":
        print("[5c/10] Materialized ~/.vct-secrets/shared/_README.md "
              "(agent-facing key schema)")
        _log_install_event(
            "5c/10", "ok", f"materialized {result.target}",
        )
    elif result.status == "error":
        _log_install_event(
            "5c/10", "warn",
            f"failed to materialize vct-secrets shared _README.md: {result.message}",
        )


def _refresh_orchestrator_self_vco_manifest(install_root: Path) -> None:
    """V0243-4: rewrite `<install_root>/.claude/.vco-manifest.json` with
    current shipped-file SHA256 hashes + bump `vco_version` to the current
    HEAD commit from ``_read_git_rev()[0]``.

    Only called from the orchestrator-root install path (after templates are
    copied by ``_materialize_orchestrator_self_claude_dir``).  Per-project
    installs have their manifest written by
    ``vco_lib.project_init.install_project_bundle``.

    The manifest tracks every file that install.py copies from
    ``templates/`` to ``.claude/`` — hooks, scripts, and the rendered
    settings.json.  Agents and skills are NOT included because their
    source-of-truth is ``templates/{agents,skills}/`` and they are written
    by the per-project bundle path, not by the orchestrator-self path.

    Soft-fail throughout: any OSError is logged but does not abort the
    install.  A missing or stale manifest is only a cosmetic issue (the
    launcher's bundle-update flow will notice the drift on the next
    per-project update pass).
    """
    import hashlib as _hashlib
    import datetime as _dt

    claude_dir = install_root / ".claude"
    manifest_path = claude_dir / ".vco-manifest.json"

    # Collect shipped files that were just materialised.
    file_entries: dict[str, dict] = {}
    templates_dir = install_root / "templates"

    def _sha256_file(p: Path) -> str:
        h = _hashlib.sha256()
        try:
            with open(p, "rb") as fh:
                for chunk in iter(lambda: fh.read(65536), b""):
                    h.update(chunk)
        except OSError:
            return ""
        return h.hexdigest()

    # Hooks (top-level files only — _lib/ sub-tree handled below).
    #
    # v0.2.54 Track D: hash the TEMPLATE source, not the destination.
    # The manifest's `sha256` is the prior-SHIPPED hash consumed by both
    # the per-project bundle `_file_action` and the orchestrator-self
    # materialize's hash-compare. Pre-fix the two were identical (the
    # materialize overwrote unconditionally, so dst == src); with
    # preserve-and-defer semantics a user-modified dst can diverge —
    # recording the dst hash would make the NEXT run see
    # installed == prior-shipped and overwrite the very file the
    # previous run preserved.
    hooks_src = templates_dir / "hooks"
    if hooks_src.is_dir():
        for src in hooks_src.iterdir():
            if not src.is_file():
                continue
            rel = str(Path(".claude") / "hooks" / src.name)
            src_rel = str(src.relative_to(install_root))
            file_entries[rel] = {
                "sha256": _sha256_file(src),
                "source": src_rel,
            }
        # _lib/ subdirectory.
        lib_src = hooks_src / "_lib"
        if lib_src.is_dir():
            for src in lib_src.iterdir():
                if not src.is_file():
                    continue
                rel = str(Path(".claude") / "hooks" / "_lib" / src.name)
                src_rel = str(src.relative_to(install_root))
                file_entries[rel] = {
                    "sha256": _sha256_file(src),
                    "source": src_rel,
                }

    # Scripts.
    scripts_src = templates_dir / "scripts"
    if scripts_src.is_dir():
        for src in scripts_src.iterdir():
            if not src.is_file():
                continue
            rel = str(Path(".claude") / "scripts" / src.name)
            src_rel = str(src.relative_to(install_root))
            # v0.2.54 Track D: template hash (= prior-shipped), not dst.
            # See the hooks comment above for why this is load-bearing.
            file_entries[rel] = {
                "sha256": _sha256_file(src),
                "source": src_rel,
            }

    # settings.json (rendered from template — hash the on-disk result).
    settings_dst = claude_dir / "settings.json"
    if platform.system() == "Windows":
        settings_src_name = "settings.json.windows.template"
    else:
        settings_src_name = "settings.json.linux.template"
    settings_src = templates_dir / settings_src_name
    if settings_src.is_file():
        rel = str(Path(".claude") / "settings.json")
        file_entries[rel] = {
            "sha256": _sha256_file(
                settings_dst if settings_dst.exists() else settings_src
            ),
            "source": str(settings_src.relative_to(install_root)),
        }

    # Determine vco_version.
    commit, _ = _read_git_rev()
    vco_version = commit or "unknown"

    now_str = _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    # Read existing manifest to preserve preserved_files section.
    existing: dict = {}
    if manifest_path.is_file():
        try:
            existing = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception:
            existing = {}

    manifest_payload = {
        "schema_version": 2,
        "vco_version": vco_version,
        "installed_at": existing.get("installed_at", now_str),
        "updated_at": now_str,
        "files": file_entries,
        "preserved_files": existing.get("preserved_files", {}),
    }

    try:
        # v0.2.46 V47-B (Gap B): if .claude/ itself is a symlink, write
        # the manifest to a sibling .vco-new tree. os.replace() on a
        # symlinked DESTINATION would replace the symlink itself on POSIX
        # (silently destroying the user's link); on Windows it errors.
        # Either is unacceptable per the hard rule.
        target_claude = claude_dir
        if is_symlink_blocking(target_claude):
            target_claude = compute_vco_new_path(target_claude)
            target_claude.mkdir(parents=True, exist_ok=True)
            manifest_path_effective = target_claude / ".vco-manifest.json"
        else:
            claude_dir.mkdir(parents=True, exist_ok=True)
            manifest_path_effective = manifest_path

        # v0.2.46 V47-B: also guard the manifest file itself.
        if is_symlink_blocking(manifest_path_effective):
            manifest_path_effective = compute_vco_new_path(
                manifest_path_effective
            )

        payload_bytes = (json.dumps(manifest_payload, indent=2, sort_keys=True) + "\n")
        # Atomic write via tempfile + replace.
        import tempfile as _tf
        fd, tmp_path = _tf.mkstemp(
            dir=str(manifest_path_effective.parent),
            suffix=".tmp", prefix=".vco-manifest-",
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                fh.write(payload_bytes)
            os.replace(tmp_path, str(manifest_path_effective))
        except Exception:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise
        _log_install_event(
            "4b/10", "ok",
            f"V0243-4: refreshed .vco-manifest.json "
            f"({len(file_entries)} files, vco_version={vco_version!r})",
            data={"file_count": len(file_entries), "vco_version": vco_version},
        )
    except OSError as exc:
        _log_install_event(
            "4b/10", "warn",
            f"V0243-4: could not write .vco-manifest.json: {exc}",
        )


# ---------------------------------------------------------------------------
# Step 6: Container services
# ---------------------------------------------------------------------------

def _probe_http(url: str, timeout: float = 2.0) -> str | None:
    """Probe a URL with HEAD/GET. Returns the URL if reachable + status<400, else None.

    Used to detect already-running shared services (Weaviate / Ollama / code_embed)
    so we don't try to start a duplicate container that would bind-conflict on the
    same host port.
    """
    try:
        resp = urllib.request.urlopen(url, timeout=timeout)
        if resp.status < 400:
            return url
    except Exception:
        pass
    return None


def _detect_existing_services(weaviate_port: int = DEFAULT_WEAVIATE_PORT,
                              ollama_port: int = DEFAULT_OLLAMA_PORT,
                              code_embed_port: int = DEFAULT_CODE_EMBED_PORT) -> dict:
    """Probe the three default service endpoints. Returns a dict with the URL
    on success (str) or None when not reachable, for each of weaviate / ollama /
    code_embed."""
    return {
        "weaviate_url": _probe_http(
            f"http://localhost:{weaviate_port}/v1/.well-known/ready"
        ),
        "ollama_url": _probe_http(
            f"http://localhost:{ollama_port}/api/tags"
        ),
        "code_embed_url": _probe_http(
            f"http://localhost:{code_embed_port}/health"
        ),
    }


# ---------------------------------------------------------------------------
# Step 5b: Safe-by-default service detection
# ---------------------------------------------------------------------------
#
# Goal: install.py must NOT touch a Weaviate / Ollama / code-embed service
# that wasn't started by us, EVEN IF it's running on our canonical port. The
# old behavior — blindly POSTing to localhost:8081 — would pollute a foreign
# user-owned Weaviate with our collections (`KnowledgeGraph` etc.) and could
# even bind-conflict the compose `up -d` against it.
#
# Detection is content-based, not name-based: we probe the port and
# fingerprint the response. A container called `weaviate` is irrelevant —
# what matters is "did WE start whatever's responding here?".
#
# Decision matrix:
#
#   probe state    | default action             | non-interactive override
#   ---------------+----------------------------+------------------------
#   not-running    | start our compose service  | (none — no conflict)
#   vct-managed    | adopt (skip compose start) | (none — auto-handled)
#   foreign        | alt-port (free port)       | --on-conflict
#   incompatible   | abort                      | (cannot override)
#
# State persistence: the chosen action is recorded in
# `~/.vct/services.toml`, the SAME file the launcher's
# `services::adoption` reads/writes (commit 8b1890f). install.py and the
# launcher therefore see consistent state. Schema is the launcher's
# `AdoptionState` (rust serde) but expressed as flat TOML so plain Python
# can produce it without depending on the `tomli_w` package.

# Canonical service identifiers used in services.toml. Match the launcher's
# launcher::services::adoption canonical names.
_CANONICAL_SERVICES = ("weaviate", "ollama", "code_embed")

# Default ports per service. Mirrors the DEFAULT_*_PORT constants above but
# keyed by canonical name for table-driven loops.
_DEFAULT_PORTS = {
    "weaviate": DEFAULT_WEAVIATE_PORT,
    "ollama": DEFAULT_OLLAMA_PORT,
    "code_embed": DEFAULT_CODE_EMBED_PORT,
}

# Health-probe paths per service. GET / 2xx-3xx ⇒ "something is listening";
# we then fingerprint the body to decide vct-managed vs. foreign.
_HEALTH_PATHS = {
    "weaviate": "/v1/.well-known/ready",
    "ollama": "/api/tags",
    "code_embed": "/health",
}


def _services_toml_path() -> Path:
    """Path to `<VCT_STATE_DIR or ~/.vct>/services.toml` — shared with
    launcher::services::adoption (Rust). Both sides honour ``VCT_STATE_DIR``
    so a dev launcher's state stays isolated from production state."""
    from vco_lib.paths import vct_root_dir
    return vct_root_dir() / "services.toml"


def _read_services_toml() -> dict:
    """Parse `~/.vct/services.toml` into a list-of-tables dict.

    Returns `{"services": [{name, mode, external_url, parallel_port}, ...]}`.
    Empty dict on missing file. Empty `services` list on parse error — we'd
    rather treat the file as missing than crash mid-install on a corrupted
    TOML the user might have hand-edited.
    """
    path = _services_toml_path()
    if not path.exists():
        return {"services": []}
    try:
        # tomllib is stdlib in Python 3.11+; install.py already requires 3.11.
        import tomllib  # noqa: PLC0415
        return tomllib.loads(path.read_text(encoding="utf-8"))
    except Exception as e:
        print(f"  ! services.toml unreadable ({e}); treating as empty")
        return {"services": []}


def _write_services_toml(state: dict) -> None:
    """Serialize `{services: [...]}` to `~/.vct/services.toml`.

    Hand-rolled TOML serializer because `tomli_w` isn't in the install-time
    venv (we run BEFORE `pip install -r requirements.txt`). The schema is
    a flat array of tables — the rust launcher's `AdoptionState` shape —
    so a hand-rolled writer is trivial and avoids a chicken-and-egg
    dependency. Atomic via temp-file + rename so a crashed install never
    leaves a half-written services.toml.
    """
    path = _services_toml_path()
    path.parent.mkdir(parents=True, exist_ok=True)

    lines: list[str] = []
    for entry in state.get("services", []):
        lines.append("[[services]]")
        # Order: name, mode (always present), then optional fields.
        lines.append(f'name = "{_toml_escape(entry["name"])}"')
        lines.append(f'mode = "{_toml_escape(entry["mode"])}"')
        if entry.get("external_url"):
            lines.append(f'external_url = "{_toml_escape(entry["external_url"])}"')
        if entry.get("parallel_port") is not None:
            lines.append(f'parallel_port = {int(entry["parallel_port"])}')
        lines.append("")  # blank line between tables

    body = "\n".join(lines).rstrip() + "\n"
    tmp = path.with_suffix(".toml.tmp")
    tmp.write_text(body, encoding="utf-8")
    os.replace(tmp, path)  # atomic on POSIX + Windows


def _toml_escape(s: str) -> str:
    """Minimal TOML basic-string escaping (backslash + double-quote).

    Sufficient for our payloads — service names, mode tokens, and URLs.
    No newlines, no control chars in any value we ever write here.
    """
    return s.replace("\\", "\\\\").replace('"', '\\"')


# ProbeResult and ProbeAction — emulated as string constants for stdlib-only
# install.py. `enum` would work but adds import noise without buying us
# anything; the action set is small and string-comparable.
PROBE_NOT_RUNNING = "not-running"   # port free; we'll start compose
PROBE_VCT_MANAGED = "vct-managed"   # our prior install — adopt seamlessly
PROBE_FOREIGN = "foreign"           # someone else's service — DO NOT TOUCH
PROBE_INCOMPATIBLE = "incompatible" # protocol mismatch — abort

ACTION_START = "start"      # bring up the compose service on default port
ACTION_ADOPT = "adopt"      # reuse the existing service as-is (skip compose)
ACTION_ALT_PORT = "alt-port"  # bring up compose on an alternate free port
ACTION_ABORT = "abort"      # bail the install


def _classify_service_compose_action(action: str, probe: str) -> str:
    """Pure: map a per-service (action, probe) decision to a compose disposition.

    v0.2.61 (FINDING-1): returns one of:
      * "start"    — bring the service up (it's not running / needs alt-port).
      * "recreate" — the service is an adopt WE OWN (probe == vct-managed) whose
        compose config may have changed (e.g. the Weaviate write-amp env
        tuning); `compose up -d --force-recreate <svc>` rebuilds it from the new
        config (the named data volume is preserved). This is the fix for "an
        adopt skips compose, so a changed env never applies on --update."
      * "skip"     — leave the service running untouched. Critically this covers
        a FOREIGN adopt (probe == foreign, only via explicit --on-conflict
        adopt): we must NEVER recreate a service we don't own.

    Keeping this a pure function makes the start-vs-recreate-vs-skip rule
    unit-testable without driving the whole `_start_services` subprocess path.
    """
    if action in (ACTION_START, ACTION_ALT_PORT):
        return "start"
    if action == ACTION_ADOPT and probe == PROBE_VCT_MANAGED:
        return "recreate"
    return "skip"


def _should_check_weaviate_reclaim_drift(
    decisions: dict, services_to_start: list, services_to_recreate: list,
) -> bool:
    """Pure: may the R2 reclaim-env drift check run for weaviate this pass?

    v0.2.74 (Fable-review F3). True ONLY when ALL hold:
      * the safety probe classified weaviate as VCT-MANAGED — the v0.2.61
        invariant ("a FOREIGN adopt is NEVER recreated — we must not touch a
        service we don't own") is enforced by the disposition loop, but the
        drift check runs precisely on the "skip" disposition, which INCLUDES a
        foreign adopt. Without this gate a foreign weaviate on 8081 whose env
        lacks our tuning keys ("absent IS drift") would get force-recreated
        (port-conflict failure), and a STOPPED stale vco_weaviate next to a
        running foreign service could be resurrected into the same conflict.
        Probe missing/unknown → False (conservative; the reclaim converges on
        a later run once the probe resolves).
      * weaviate is NOT already being started or recreated this pass (those
        paths apply the fresh compose config anyway).
    Kept pure so the ownership rule is unit-testable without driving the whole
    ``_start_services`` subprocess path (mirrors
    ``_classify_service_compose_action``).
    """
    probe = ((decisions or {}).get("weaviate", {}) or {}).get("probe", "")
    if probe != PROBE_VCT_MANAGED:
        return False
    return (
        "weaviate" not in services_to_recreate
        and "weaviate" not in services_to_start
    )


#: v0.2.74 (R2): perf/reclaim env vars whose value MUST match the compose file
#: on the RUNNING Weaviate container. Drift on ANY of these means the container
#: predates the current compose config and its dead LSM segments cannot compact
#: (the 136GB-never-reclaims bug: the running container was stuck at
#: PERSISTENCE_LSM_MAX_SEGMENT_SIZE=500MiB while compose shipped 2GiB, because a
#: running-and-ours container is "reused" and never recreated). When any drift
#: is detected we force a `--force-recreate` (data-safe: the named volume
#: survives). Keys mirror the `environment:` blocks in both compose files.
_WEAVIATE_RECLAIM_ENV_KEYS: tuple = (
    "PERSISTENCE_LSM_MAX_SEGMENT_SIZE",
    "TOMBSTONE_DELETION_MIN_PER_CYCLE",
    "TOMBSTONE_DELETION_MAX_PER_CYCLE",
    "TOMBSTONE_DELETION_CONCURRENCY",
)


def _parse_compose_weaviate_reclaim_env(compose_text: str) -> dict:
    """Extract the reclaim env values (see `_WEAVIATE_RECLAIM_ENV_KEYS`) from a
    compose file's text. Pure/regex — avoids a YAML dep on the install path.

    Matches `KEY: value` (with optional quotes) anywhere in the file; the
    reclaim keys are unique across services so a flat scan is unambiguous.
    Returns a dict of only the keys found, values stripped of quotes/whitespace.
    """
    found: dict = {}
    for key in _WEAVIATE_RECLAIM_ENV_KEYS:
        m = re.search(
            rf'^\s*{re.escape(key)}\s*:\s*["\']?([^"\'\n#]+?)["\']?\s*(?:#.*)?$',
            compose_text,
            re.MULTILINE,
        )
        if m:
            found[key] = m.group(1).strip()
    return found


def _running_container_reclaim_env(container_cmd: str, container_ref: str) -> "Optional[dict]":
    """Inspect the RUNNING Weaviate container's reclaim env values.

    Returns a dict of the `_WEAVIATE_RECLAIM_ENV_KEYS` actually set on the live
    container (via `<runtime> inspect`), or ``None`` when the inspect can't run /
    parse (unknown → the caller treats "can't determine" as "do NOT force a
    recreate" — conservative: never recreate on uncertainty, mirroring the
    best-effort-soft-fail rule).
    """
    if not container_cmd or not container_ref:
        return None
    try:
        proc = subprocess.run(
            [container_cmd, "inspect", "--format", "{{json .Config.Env}}", container_ref],
            capture_output=True, text=True, timeout=10,
        )
        if proc.returncode != 0 or not proc.stdout.strip():
            return None
        env_list = json.loads(proc.stdout.strip())
        if not isinstance(env_list, list):
            return None
    except Exception:  # noqa: BLE001 — inspect/parse failure → unknown → None
        return None
    wanted = set(_WEAVIATE_RECLAIM_ENV_KEYS)
    live: dict = {}
    for item in env_list:
        if not isinstance(item, str) or "=" not in item:
            continue
        k, _, v = item.partition("=")
        if k in wanted:
            live[k] = v.strip()
    return live


def _weaviate_reclaim_env_drifted(
    container_cmd: str, container_ref: str, compose_text: str,
) -> tuple[bool, list]:
    """True when the RUNNING Weaviate container's reclaim env DIFFERS from the
    compose file (→ it must be `--force-recreate`d to apply the reclaim tuning).

    Returns ``(drifted, details)`` where ``details`` is a list of
    ``(key, live_value, compose_value)`` tuples for the mismatches (for logging).
    Conservative: when the live env can't be inspected (``None``) we return
    ``(False, [])`` — never recreate on uncertainty. A key present in compose but
    ABSENT on the live container IS drift (the container predates the key).
    """
    compose_vals = _parse_compose_weaviate_reclaim_env(compose_text)
    if not compose_vals:
        return False, []
    live = _running_container_reclaim_env(container_cmd, container_ref)
    if live is None:
        return False, []  # can't determine → don't recreate (conservative)
    details: list = []
    for key, want in compose_vals.items():
        have = live.get(key)
        if have != want:
            details.append((key, have, want))
    return (len(details) > 0), details


def _probe_service_identity(name: str, port: int) -> tuple[str, str]:
    """Content-fingerprint whatever is listening on `localhost:<port>`.

    Returns (probe_result, evidence) where:
      - probe_result is one of PROBE_*
      - evidence is a short human-readable string (URL, schema-class name,
        etc.) used for log lines and the interactive prompt

    Heuristic per service:
      - weaviate: GET /v1/.well-known/ready; if 200, GET /v1/schema and
        look for our canonical collections (KnowledgeGraph,
        VibeCodedOrchestrator_KnowledgeGraph — the v0.2.23 B1 capital-C
        casing, plus the lowercase-c v0.2.12–v0.2.22 variant
        VibecodedOrchestrator_KnowledgeGraph, plus the pre-v0.2.12 PR-26
        legacy VibeCodedTools_KnowledgeGraph). Any present ⇒ vct-managed.
        Empty schema + no services.toml record ⇒ foreign (we don't claim
        bare instances).
      - ollama: GET /api/tags; if 200, look for our pinned embedding model
        (qwen3-embedding:0.6b OR snowflake-arctic-embed2:latest) AS WELL AS
        the services.toml record. Either signal present ⇒ vct-managed.
        Empty tags or no signal ⇒ foreign.
      - code_embed: GET /health; if 200 + body matches CodeSage/Ollama
        backend marker, vct-managed. Otherwise foreign.

    The services.toml lock is the strongest signal — it survives a Weaviate
    that we previously cleared. Content fingerprints are the secondary
    signal so we can recognise our own data even when the lock file was
    deleted (rare; user wiped ~/.vct/).
    """
    path = _HEALTH_PATHS.get(name)
    if path is None:
        return PROBE_INCOMPATIBLE, f"unknown service '{name}'"

    base = f"http://localhost:{port}"

    # Step 1: liveness probe
    try:
        resp = urllib.request.urlopen(f"{base}{path}", timeout=2)
        if resp.status >= 400:
            return PROBE_NOT_RUNNING, f"{base}{path} → HTTP {resp.status}"
    except Exception:
        return PROBE_NOT_RUNNING, f"{base}{path} unreachable"

    # Step 2: services.toml lookup (strongest signal — explicit prior claim).
    state = _read_services_toml()
    locked = next(
        (s for s in state.get("services", []) if s.get("name") == name),
        None,
    )
    if locked and locked.get("mode") in ("adopt", "parallel", "refuse"):
        # We previously decided how to handle this port. Consider it
        # "ours" in the sense that subsequent installs should not re-prompt.
        return PROBE_VCT_MANAGED, f"prior decision: {locked['mode']}"

    # Step 3: content fingerprint per service.
    if name == "weaviate":
        try:
            schema_resp = urllib.request.urlopen(f"{base}/v1/schema", timeout=3)
            schema = json.loads(schema_resp.read())
            classes = {
                c.get("class") for c in schema.get("classes", [])
                if isinstance(c, dict)
            }
            # Two recognition modes for vct ownership of a Weaviate:
            # 1. Exact canonical names (single-tenant install).
            # 2. Suffix-pattern names (multi-project orchestrator setup
            #    where each project namespaces its collections — e.g.
            #    `MyProject_CodeFunction`, `ClaudeKnowledgeGraph`,
            #    `OtherProject_KnowledgeGraph`). The `_KnowledgeGraph` /
            #    `_CodeFunction` / `_CodeClass` / `_CodeModule` suffixes
            #    are ours by construction and don't appear in foreign
            #    Weaviates.
            # Legacy-detection: the canonical post-v0.2.23-B1 capital-C name,
            # the lowercase-c v0.2.12–v0.2.22 variant, AND the pre-v0.2.12
            # "VibeCodedTools_KnowledgeGraph" are markers of a vct-managed
            # Weaviate (the v0.2.23 B1 case-flip is the canonical-name change
            # only — install.py's case-insensitive adoption keeps the on-disk
            # class unchanged so pre-flip installs still have the lowercase-c
            # class on disk; same applies to pre-v0.2.12 installs with the
            # VibeCodedTools name).
            exact_markers = {"KnowledgeGraph",
                             "VibeCodedOrchestrator_KnowledgeGraph",
                             # v0.2.12–v0.2.22 lowercase-c variant.
                             "VibecodedOrchestrator_KnowledgeGraph",
                             # Pre-v0.2.12 name (PR-26 rename predecessor).
                             "VibeCodedTools_KnowledgeGraph",
                             "Development", "CodeFunction", "CodeClass",
                             "CodeModule", "CodeAPI", "CodeInteraction"}
            # `_conversations` is a legacy marker (collection deprecated
            # 2026-04-30) — kept here for detection of old installs only.
            # New installs do NOT create the conversations collection.
            suffix_markers = ("_KnowledgeGraph", "_Development",
                              "_CodeFunction", "_CodeClass", "_CodeModule",
                              "_conversations", "_development")
            exact_hits = classes & exact_markers
            suffix_hits = {c for c in classes if c and any(c.endswith(s) for s in suffix_markers)}
            hits = exact_hits | suffix_hits
            if hits:
                return PROBE_VCT_MANAGED, f"weaviate has vct collections: {sorted(hits)[:3]}"
            # Weaviate alive but no vct markers — could be empty (fresh user
            # install) or could be foreign + populated. Either way, not ours.
            return PROBE_FOREIGN, f"weaviate alive at {base} (classes: {sorted(classes)[:3] or 'none'})"
        except Exception as e:
            return PROBE_INCOMPATIBLE, f"weaviate at {base} but /v1/schema failed: {e}"

    if name == "ollama":
        try:
            tags_resp = urllib.request.urlopen(f"{base}/api/tags", timeout=3)
            tags = json.loads(tags_resp.read())
            model_names = {m.get("name", "") for m in tags.get("models", [])}
            vct_markers = {"qwen3-embedding:0.6b",
                           "snowflake-arctic-embed2:latest",
                           "unclemusclez/jina-embeddings-v2-base-code:latest",
                           "qwen3.5:0.8b"}
            if model_names & vct_markers:
                return PROBE_VCT_MANAGED, f"ollama has vct models: {sorted(model_names & vct_markers)}"
            return PROBE_FOREIGN, f"ollama alive at {base} (models: {sorted(model_names)[:3] or 'none'})"
        except Exception as e:
            return PROBE_INCOMPATIBLE, f"ollama at {base} but /api/tags failed: {e}"

    if name == "code_embed":
        # Our service responds to /health with JSON {"status": "ok",
        # "model": "codesage-large-v2", ...}. Foreign FastAPIs may also
        # respond 200 to /health but not produce that body.
        try:
            health_resp = urllib.request.urlopen(f"{base}/health", timeout=3)
            body = health_resp.read().decode("utf-8", errors="replace")
            if "codesage" in body.lower() or "code_embed" in body.lower():
                return PROBE_VCT_MANAGED, f"code_embed responds with vct fingerprint"
            return PROBE_FOREIGN, f"port {port} responds to /health but is not our code_embed"
        except Exception as e:
            return PROBE_INCOMPATIBLE, f"code_embed at {base} unrecognised: {e}"

    return PROBE_INCOMPATIBLE, f"no fingerprint logic for '{name}'"


def _find_free_port(start: int, end: int = 65000) -> int | None:
    """Return the first free TCP port in [start, end] on 127.0.0.1.

    Used when a foreign service holds the canonical port and the user
    chose `alt-port`. We bind-and-close to test, which is racy with a
    process spawning a millisecond later — but for install-time it's
    fine; the compose `up -d` happens within the same install run.
    """
    import socket  # noqa: PLC0415 — lazy import; rare path
    for port in range(start, end + 1):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                s.bind(("127.0.0.1", port))
                return port
        except OSError:
            continue
    return None


def _decide_action(name: str, probe: str, evidence: str,
                   args: argparse.Namespace) -> str:
    """Resolve a probe result into a concrete action.

    Honors:
      1. `--on-conflict` flag (non-interactive override for `foreign`)
      2. `--yes` / non-TTY (defaults to alt-port for foreign, abort for incompatible)
      3. interactive prompt
    """
    if probe == PROBE_NOT_RUNNING:
        return ACTION_START
    if probe == PROBE_VCT_MANAGED:
        return ACTION_ADOPT
    if probe == PROBE_INCOMPATIBLE:
        return ACTION_ABORT

    # Foreign — the interesting case.
    if args.on_conflict == "alt-port":
        return ACTION_ALT_PORT
    if args.on_conflict == "adopt":
        return ACTION_ADOPT
    if args.on_conflict == "abort":
        return ACTION_ABORT

    # Non-interactive default: alt-port. Prevents pollution; never adopts
    # someone else's service without explicit consent.
    if args.yes or not sys.stdin.isatty() or args.quiet:
        print(f"  [{name}] foreign service detected ({evidence})")
        print(f"  [{name}] non-interactive mode → using alt-port "
              f"(override: --on-conflict adopt|abort)")
        return ACTION_ALT_PORT

    # Interactive prompt
    print()
    print(f"  Detected a foreign {name} on port {_DEFAULT_PORTS[name]}.")
    print(f"  Evidence: {evidence}")
    print()
    print(f"  Options:")
    print(f"    [1] alt-port  — pick a free port and run our own {name} alongside it (safe, default)")
    print(f"    [2] adopt     — reuse the existing {name}; WILL write our collections into it")
    print(f"    [3] abort     — stop installation")
    try:
        ans = input(f"  Choice for {name} [1/2/3, default 1]: ").strip()
    except (EOFError, KeyboardInterrupt):
        print()
        return ACTION_ALT_PORT
    if ans in ("2", "adopt"):
        return ACTION_ADOPT
    if ans in ("3", "abort"):
        return ACTION_ABORT
    return ACTION_ALT_PORT


def _scan_foreign_compose_files(
    project_root: Path,
    max_depth: int = 3,
) -> list[Path]:
    """Return relative paths of non-VCO compose files under *project_root*.

    Scans up to *max_depth* levels deep for files matching:
        docker-compose*.yml / docker-compose*.yaml
        compose*.yml / compose*.yaml
        podman-compose*.yml / podman-compose*.yaml

    Excludes files owned by VCO:
        - anything under ``infrastructure/``
        - anything under ``claude_mcp_servers/``

    Returns a list of ``Path`` objects relative to *project_root*,
    sorted for stable output. Never raises; returns an empty list on I/O
    errors.

    Performance: bounded O(n) walk at depth ≤ 3 — fast even for large
    repos because the depth limit prevents full-tree traversal.
    """
    _VCO_OWNED_PREFIXES: tuple[str, ...] = ("infrastructure", "claude_mcp_servers")
    _COMPOSE_STEMS: tuple[str, ...] = (
        "docker-compose",
        "compose",
        "podman-compose",
    )
    _COMPOSE_SUFFIXES: tuple[str, ...] = (".yml", ".yaml")

    def _is_vco_owned(rel: Path) -> bool:
        """Return True if *rel* is under a VCO-managed subtree."""
        parts = rel.parts
        return len(parts) > 0 and parts[0] in _VCO_OWNED_PREFIXES

    def _is_compose_filename(name: str) -> bool:
        """Return True if *name* matches any of the compose file patterns."""
        lower = name.lower()
        for suffix in _COMPOSE_SUFFIXES:
            if lower.endswith(suffix):
                stem = lower[: -len(suffix)]  # e.g. "docker-compose.dev"
                for prefix in _COMPOSE_STEMS:
                    if stem == prefix or stem.startswith(prefix + "."):
                        return True
        return False

    results: list[Path] = []
    try:
        for entry in project_root.iterdir():
            _walk(entry, project_root, current_depth=1, max_depth=max_depth,
                  results=results, check_fn=_is_compose_filename,
                  vco_owned_fn=_is_vco_owned)
    except OSError:
        pass

    results.sort()
    return results


def _walk(
    path: Path,
    root: Path,
    current_depth: int,
    max_depth: int,
    results: list[Path],
    check_fn: "Callable[[str], bool]",
    vco_owned_fn: "Callable[[Path], bool]",
) -> None:
    """Recursive helper for :func:`_scan_foreign_compose_files`."""
    try:
        rel = path.relative_to(root)
    except ValueError:
        return

    if vco_owned_fn(rel):
        return

    if path.is_file() and not path.is_symlink():
        if check_fn(path.name):
            results.append(rel)
        return

    if path.is_dir() and not path.is_symlink() and current_depth <= max_depth:
        try:
            for child in path.iterdir():
                _walk(child, root, current_depth + 1, max_depth,
                      results, check_fn, vco_owned_fn)
        except OSError:
            pass


def _resolve_service_safety(args: argparse.Namespace) -> dict:
    """Probe Weaviate / Ollama / code_embed and pick a safe action per service.

    Returns a dict shaped:
        {
          "weaviate":  {"action": ACTION_*, "port": int, "probe": PROBE_*, "evidence": str},
          "ollama":    {...},
          "code_embed":{...},
        }

    Side effects:
      - When alt-port is chosen: sets the corresponding env var
        (WEAVIATE_PORT / OLLAMA_PORT / CODE_EMBED_PORT) for the rest of
        the install. Compose reads these from the env via
        `${WEAVIATE_PORT:-8081}` substitutions.
      - Persists the resolution to `~/.vct/services.toml` so the
        launcher and subsequent installs see it.

    Design note: probing happens BEFORE compose `up -d`. That's the whole
    point — we never start a container against an occupied port without
    explicit consent.
    """
    print(f"\n[5b/10] Probing existing services (content-based detection) ...")

    decisions: dict = {}
    state = _read_services_toml()
    services_list = state.get("services", []) or []
    services_by_name = {s.get("name"): s for s in services_list}
    state_dirty = False

    for name in _CANONICAL_SERVICES:
        port = _DEFAULT_PORTS[name]
        # Honor explicit env-var override (advanced users / CI).
        env_port_name = {
            "weaviate": "WEAVIATE_PORT",
            "ollama": "OLLAMA_PORT",
            "code_embed": "CODE_EMBED_PORT",
        }[name]
        explicit_port = os.environ.get(env_port_name)
        if explicit_port:
            try:
                port = int(explicit_port)
            except ValueError:
                pass

        probe, evidence = _probe_service_identity(name, port)
        action = _decide_action(name, probe, evidence, args)

        chosen_port = port
        if action == ACTION_ALT_PORT:
            free = _find_free_port(port + 1)
            if free is None:
                print(f"  [{name}] FAIL: no free port in [{port + 1}, 65000]; aborting")
                action = ACTION_ABORT
            else:
                chosen_port = free
                # Propagate to env so all downstream code (compose, env
                # writers, MCP settings) picks up the override.
                os.environ[env_port_name] = str(chosen_port)
                if name == "weaviate":
                    # gRPC port also moves; offset matches the default gap (50052 vs 8081 → +41971).
                    # Simpler: just shift by the same delta from default.
                    delta = chosen_port - DEFAULT_WEAVIATE_PORT
                    grpc_port = DEFAULT_WEAVIATE_GRPC_PORT + delta
                    free_grpc = _find_free_port(grpc_port)
                    if free_grpc is not None:
                        os.environ["WEAVIATE_GRPC_PORT"] = str(free_grpc)

        decisions[name] = {
            "action": action,
            "port": chosen_port,
            "default_port": port,
            "probe": probe,
            "evidence": evidence,
        }

        # Print the decision summary line
        if action == ACTION_START:
            print(f"  [{name}] not running → will start on port {chosen_port}")
        elif action == ACTION_ADOPT:
            print(f"  [{name}] adopting existing service on port {chosen_port} ({evidence})")
        elif action == ACTION_ALT_PORT:
            print(f"  [{name}] foreign on {port} → starting our copy on alt port {chosen_port}")
        elif action == ACTION_ABORT:
            print(f"  [{name}] ABORT: {evidence}")
            return decisions  # caller must check for any ABORT

        # Persist to services.toml. Mode mapping mirrors the launcher's
        # AdoptionMode enum exactly (adoption.rs):
        #   unresolved | adopt | parallel | refuse  (snake_case in TOML)
        # ACTION_START → "unresolved" because there is no foreign service to
        # adopt or run parallel to; "unresolved" tells the launcher "no
        # conflict was seen" so it doesn't re-prompt. ACTION_ABORT also
        # maps to "unresolved" — the install bailed before persisting a
        # decision, so the next install should re-probe from scratch.
        mode_map = {
            ACTION_START: "unresolved",     # no conflict; launcher won't re-prompt
            ACTION_ADOPT: "adopt",
            ACTION_ALT_PORT: "parallel",
            ACTION_ABORT: "unresolved",
        }
        new_entry = {
            "name": name,
            "mode": mode_map[action],
            "external_url": f"http://localhost:{port}" if probe != PROBE_NOT_RUNNING else None,
            "parallel_port": chosen_port if action == ACTION_ALT_PORT else None,
        }
        # Only update if changed (idempotency: re-running install on a fully
        # adopted machine touches nothing).
        existing = services_by_name.get(name)
        if existing != new_entry:
            services_by_name[name] = new_entry
            state_dirty = True

    if state_dirty:
        new_state = {"services": list(services_by_name.values())}
        try:
            _write_services_toml(new_state)
        except OSError as e:
            print(f"  ! could not persist {_services_toml_path()}: {e}")

    # If any service decision was alt-port, write a compose override.
    alt_ports = {n: d for n, d in decisions.items()
                 if d["action"] == ACTION_ALT_PORT}
    if alt_ports:
        _write_compose_override(alt_ports)

    # Windows reserved-range check (v0.2.64). The probe loop above classifies
    # a conflict by "is something listening?" — but a WinNAT/Hyper-V reserved
    # TCP range INVERTS that: nothing listens (probe → not-running → we'd
    # `compose up`), yet the OS refuses the host bind. So detect-foreign→
    # alt-port never fires for this class. Check the *resolved* per-service
    # ports (after any alt-port shift) against the OS's own excluded ranges and
    # either auto-reserve (admin) or warn with the exact fix. Clean no-op on
    # Linux/macOS; soft-fail on any probe error.
    _check_windows_reserved_ports(decisions)

    return decisions


def _check_windows_reserved_ports(decisions: dict) -> None:
    """Warn (or auto-reserve when elevated) if any resolved service port falls
    inside a Windows reserved TCP range. Single concern, delegated to the
    shared ``vco_lib.windows_reserved_ports`` helper so install.py and the
    session-start hook apply the SAME rule.

    No-op on non-Windows. Soft-fail: any import/probe error is logged and
    swallowed — a reserved-port probe must never abort an install.
    """
    try:
        from vco_lib.windows_reserved_ports import check_ports, is_windows  # noqa: PLC0415
    except Exception:
        return
    if not is_windows():
        return
    # Only the local-bind services matter here. Weaviate's gRPC port shifts in
    # lockstep with its HTTP port, but the reserved-range bug is reported for
    # the embedding ports (ollama / code_embed); include weaviate's resolved
    # HTTP port too since it binds the same way.
    ports: list[tuple[str, int]] = []
    for name in ("weaviate", "ollama", "code_embed"):
        d = decisions.get(name)
        if d and isinstance(d.get("port"), int):
            ports.append((name, d["port"]))
    if not ports:
        return
    try:
        check_ports(ports)
    except Exception as e:  # pragma: no cover - defensive soft-fail
        print(f"  ! reserved-port check skipped ({e})")


def _write_compose_override(alt_ports: dict) -> None:
    """Generate `infrastructure/docker-compose.override.yml` with alternate ports.

    The override is per-machine state (not source-controlled) and is
    already covered by `.gitignore` (Bug 31 contract). We append rather
    than overwrite when a previous override exists from the launcher's
    volume migration — the override file at this path is read-merged by
    docker compose, so two concurrent override files can't safely coexist
    on the same path. Strategy: read existing, splice in our port section
    if absent, write back.

    Rather than YAML-parse without PyYAML in the pre-pip phase, we write
    a fresh file with both the volume-migration block AND our port
    overrides. If the launcher had an override there already, we preserve
    its non-port content via simple text concatenation. In practice, the
    user paths that hit alt-port (foreign service) and the volume-migration
    path (existing volumes) are disjoint enough that this is fine — the
    launcher writes the volume override, and install.py only writes here
    if no launcher override exists.
    """
    infra_dir = PROJECT_ROOT / "infrastructure"
    override_path = infra_dir / "docker-compose.override.yml"

    if override_path.exists():
        # Don't clobber a launcher-written volume override. Surface the
        # collision and rely on env-var port overrides alone — compose
        # WILL honor the env vars without needing an override file
        # (infrastructure/docker-compose.yml uses ${WEAVIATE_PORT:-8081}).
        print(f"  [override] {override_path} already exists; relying on env-var port overrides instead.")
        return

    # Compose v3 schema. Each alt-port service overrides only its `ports`
    # mapping; all other config from the base file (image, volumes, env)
    # is inherited.
    lines = [
        "# Auto-generated by install.py — alt-port mappings for foreign-service coexistence",
        "# Safe to delete + regenerate by re-running `python install.py`.",
        "# Tracked in ~/.vct/services.toml.",
        "services:",
    ]
    for name, dec in alt_ports.items():
        host_port = dec["port"]
        if name == "weaviate":
            grpc = os.environ.get("WEAVIATE_GRPC_PORT", str(DEFAULT_WEAVIATE_GRPC_PORT))
            lines.extend([
                "  weaviate:",
                "    ports:",
                f'      - "{host_port}:8080"',
                f'      - "{grpc}:50051"',
            ])
        elif name == "ollama":
            lines.extend([
                "  ollama:",
                "    ports:",
                f'      - "{host_port}:11434"',
            ])
        elif name == "code_embed":
            lines.extend([
                "  code_embed:",
                "    ports:",
                f'      - "{host_port}:11440"',
            ])

    override_path.parent.mkdir(parents=True, exist_ok=True)
    override_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"  [override] wrote {override_path}")


def _build_orchestrator_volume_names() -> tuple[str, ...]:
    """Volume names this install knows about — canonical first, then the
    historical container-name aliases from vco_lib.containers (which now
    centralises the maintainer-machine-leak fix from v0.2.15).

    The list below intentionally returns only canonical and centrally-
    tracked historical aliases. Multi-project orchestrator setups that
    historically used per-project suffix names (e.g. `weaviate_<proj>`,
    `ollama_<proj>`) are detected dynamically via the
    `HISTORICAL_ALIASES` list in `vco_lib.containers` rather than
    hard-coded here.
    """
    from vco_lib.containers import HISTORICAL_ALIASES

    canonical = ("weaviate_data", "ollama_data", "code_embed_cache")
    historical: list[str] = []
    for service in ("weaviate", "ollama", "code_embed"):
        historical.extend(HISTORICAL_ALIASES[service])
    # Per-project-suffix volume names (used by some multi-project
    # orchestrator setups). The list is intentionally empty here:
    # downstream callers detect such names dynamically when they hit
    # the storage-config picker rather than relying on a hard-coded
    # allowlist.
    sibling_legacy: tuple[str, ...] = ()

    seen: set[str] = set()
    out: list[str] = []
    for name in (*canonical, *historical, *sibling_legacy):
        if name in seen:
            continue
        seen.add(name)
        out.append(name)
    return tuple(out)


_ORCHESTRATOR_VOLUME_NAMES = _build_orchestrator_volume_names()


def _detect_existing_volume_paths() -> dict:
    """Bug 31: read-only probe for existing orchestrator volumes.

    Mirrors the Rust `detect_existing_volumes` in
    launcher/src-tauri/src/commands/installer.rs — both the launcher and
    the headless install.py honor the same Bug 32 contract: when
    existing volumes are detected, do NOT generate a bind-mount override.

    Returns a dict mapping volume_name -> {"mountpoint": str,
    "size_gb": float | None}. Empty dict when no runtime is installed
    or no orchestrator volumes are found.

    Calls only `<runtime> volume inspect <name>` which is read-only.
    Never invokes `volume rm` / `volume prune` / `compose down`.
    """
    volumes: dict[str, dict] = {}
    runtime = None
    for cmd in ("podman", "docker"):
        if shutil.which(cmd):
            runtime = cmd
            break
    if runtime is None:
        return volumes
    for name in _ORCHESTRATOR_VOLUME_NAMES:
        try:
            r = subprocess.run(
                [runtime, "volume", "inspect", name],
                capture_output=True,
                text=True,
                timeout=5,
            )
        except (FileNotFoundError, subprocess.TimeoutExpired):
            continue
        if r.returncode != 0:
            continue
        try:
            data = json.loads(r.stdout or "[]")
        except json.JSONDecodeError:
            continue
        if not data or "Mountpoint" not in data[0]:
            continue
        mountpoint = data[0]["Mountpoint"]
        # Best-effort size probe via `du -sk` (kibibytes). Failure is fine.
        size_gb: float | None = None
        try:
            du = subprocess.run(
                ["du", "-sk", mountpoint],
                capture_output=True,
                text=True,
                timeout=20,
            )
            if du.returncode == 0:
                kb_str = du.stdout.split()[0]
                size_gb = int(kb_str) / (1024 * 1024)
        except (FileNotFoundError, subprocess.TimeoutExpired, ValueError, IndexError):
            pass
        volumes[name] = {"mountpoint": mountpoint, "size_gb": size_gb}
    return volumes


def _compose_substitution_env(embed_config: dict) -> dict[str, str]:
    """Shim over :func:`vco_lib.compose_env.compose_substitution_env`."""
    from vco_lib.compose_env import compose_substitution_env
    return compose_substitution_env(embed_config)


def _write_infrastructure_env(embed_config: dict) -> None:
    """Shim over :func:`vco_lib.compose_env.write_infrastructure_env`.

    Soft-fail on I/O errors: the explicit process-env pass-through in
    ``_start_services`` still covers the in-flight install.
    """
    from vco_lib.compose_env import write_infrastructure_env
    ok, msg = write_infrastructure_env(
        PROJECT_ROOT / "infrastructure", embed_config
    )
    if not ok:
        print(f"  WARNING: could not write infrastructure/.env: {msg}")


def _start_services(
    sysinfo: SystemInfo,
    args: argparse.Namespace,
    embed_config: dict,
    decisions: dict | None = None,
    deferral_report: "DeferralReport | None" = None,
) -> None:
    print(f"\n[5/10] Starting services via {sysinfo.container_cmd} ... ", flush=True)
    _log_install_event(
        "5/10", "start",
        f"compose up via {sysinfo.container_cmd}",
        data={"runtime": sysinfo.container_cmd},
    )

    infra_dir = PROJECT_ROOT / "infrastructure"
    compose_file = infra_dir / "docker-compose.yml"

    if not compose_file.exists():
        print(f"  WARNING: {compose_file} not found, skipping.")
        print("  Start Weaviate and Ollama manually.")
        _log_install_event(
            "5/10", "warn",
            "docker-compose.yml missing",
            data={"compose_file": str(compose_file)},
        )
        return

    # Bug 31 contract: when existing orchestrator volumes are detected,
    # we surface them so the user knows their data will be reused, and
    # we do NOT (re)generate any bind-mount override. The launcher GUI
    # is the only path that may generate a docker-compose.override.yml;
    # headless install.py keeps things conservative.
    existing_volumes = _detect_existing_volume_paths()
    if existing_volumes:
        print(f"  Existing orchestrator volumes detected — keeping in place:")
        for name, info in existing_volumes.items():
            size = (
                f" ({info['size_gb']:.1f} GB)" if info.get("size_gb") is not None else ""
            )
            print(f"    [reuse] {name} -> {info['mountpoint']}{size}")

    # Bug 29: shared containers across installs.
    # Before running `compose up -d` (which would bind to host ports), probe
    # the default ports. If a service is already up, reuse it — installs share
    # one Weaviate / Ollama / code_embed per machine. Per-install isolation
    # comes from KG_COLLECTION namespacing inside the shared Weaviate.
    #
    # Escape hatch: VCT_FORCE_SEPARATE_CONTAINERS=1 forces a full `up -d`
    # regardless of what's already running (advanced — caller is responsible
    # for resolving port conflicts via WEAVIATE_PORT/OLLAMA_PORT overrides).
    weaviate_port = int(os.environ.get("WEAVIATE_PORT", DEFAULT_WEAVIATE_PORT))
    ollama_port = int(os.environ.get("OLLAMA_PORT", DEFAULT_OLLAMA_PORT))
    code_embed_port = int(os.environ.get("CODE_EMBED_PORT", DEFAULT_CODE_EMBED_PORT))

    force_separate = os.environ.get("VCT_FORCE_SEPARATE_CONTAINERS") == "1"
    detected = _detect_existing_services(weaviate_port, ollama_port, code_embed_port)

    if not force_separate:
        any_detected = any(v is not None for v in detected.values())
        if any_detected:
            print("  Detected already-running services:")
            for label, url in (
                ("Weaviate", detected["weaviate_url"]),
                ("Ollama", detected["ollama_url"]),
                ("code_embed", detected["code_embed_url"]),
            ):
                if url:
                    print(f"    [reuse] {label}: {url}")
                else:
                    print(f"    [start] {label}: not detected")

    # Determine which compose services need to start.
    # If --gpu, we additionally bring up code_embed (gated on the gpu profile +
    # overlay file). On CPU-only setups the service uses Ollama as code embed
    # backend and code_embed is intentionally skipped.
    services_to_start: list[str] = []
    # v0.2.61: services we OWN (vct-managed adopt) that may have a changed
    # compose config (e.g. the Weaviate write-amplification env tuning). An
    # adopt skips `compose up` entirely (the service is already running), so a
    # changed `environment:` block never reaches compose → the new config
    # silently never applies on `--update`. We force-recreate ONLY our own
    # vct-managed adopts (probe == PROBE_VCT_MANAGED) so the new config lands;
    # the named data volume is preserved across `--force-recreate` (it rm's the
    # container, not the volume). FOREIGN adopts (someone else's container,
    # probe == PROBE_FOREIGN, only via explicit --on-conflict adopt) are NEVER
    # recreated — we must not touch a service we don't own.
    services_to_recreate: list[str] = []
    if force_separate:
        # No detection — bring everything compose declares up.
        services_to_start = []  # empty list => `up -d` with no service args
    elif decisions:
        # Decision-driven: only bring up services where the action is start
        # or alt-port. Adopted services (vct-managed reuse, foreign adopt)
        # do NOT get a compose START — but a vct-managed adopt DOES get a
        # force-recreate so a changed compose config is applied (v0.2.61).
        for svc in ("weaviate", "ollama", "code_embed"):
            if svc == "code_embed" and not sysinfo.has_gpu:
                continue
            d = decisions.get(svc, {})
            disposition = _classify_service_compose_action(
                d.get("action", ""), d.get("probe", "")
            )
            if disposition == "start":
                services_to_start.append(svc)
            elif disposition == "recreate":
                services_to_recreate.append(svc)
            # "skip" → leave running untouched (incl. a foreign adopt).

        # ── v0.2.74 (R2): Weaviate reclaim-env DRIFT recreate ────────────────
        # The adopt-recreate above only fires when THIS run classifies Weaviate
        # as a fresh vct-managed ADOPT. But a running-and-ours Weaviate is often
        # classified "reuse/skip" — so a compose env change (the 2GiB LSM cap +
        # tombstone brake that let the 136GB dead segments compact) NEVER reached
        # the live container, which stayed at the old 500MiB cap and could never
        # reclaim. Independently INSPECT the running container's reclaim env and,
        # if it drifts from compose, force a `--force-recreate` regardless of the
        # adopt/skip classification. Data-safe: the named volume survives a
        # recreate. Runs BEFORE the schema-migration 6_to_7 purge + the codegraph
        # resync (both later in the update flow at the call site), so that heavy
        # write activity lands under the 2GiB cap and compaction can collapse the
        # backlog (HIGH-1 sequencing). Conservative: an un-inspectable container
        # → no drift reported → no recreate (never recreate on uncertainty).
        #
        # v0.2.74 (Fable-review F3): additionally gated on the safety probe
        # having classified weaviate as VCT-MANAGED (pure predicate below —
        # see _should_check_weaviate_reclaim_drift for the full rationale).
        if _should_check_weaviate_reclaim_drift(
            decisions, services_to_start, services_to_recreate
        ):
            try:
                from vco_lib.containers import find_existing_container
                _wv_ref = find_existing_container("weaviate") or "vco_weaviate"
            except Exception:  # noqa: BLE001 — resolver import/probe soft-fail
                _wv_ref = "vco_weaviate"
            try:
                _compose_text = compose_file.read_text(encoding="utf-8")
            except Exception:  # noqa: BLE001
                _compose_text = ""
            if _compose_text:
                _drifted, _drift_details = _weaviate_reclaim_env_drifted(
                    sysinfo.container_cmd, _wv_ref, _compose_text,
                )
                if _drifted:
                    services_to_recreate.append("weaviate")
                    print(
                        "  [recreate] Weaviate: reclaim-env drift detected "
                        "(running container predates the current compose tuning) "
                        "— forcing --force-recreate so the LSM/compaction config "
                        "applies. The named data volume is preserved."
                    )
                    for _k, _have, _want in _drift_details:
                        print(f"      {_k}: running={_have!r} → compose={_want!r}")
                    _log_install_event(
                        "5/10", "recreate",
                        "weaviate reclaim-env drift → force-recreate",
                        data={"drift": [list(d) for d in _drift_details]},
                    )
    else:
        # Legacy path (no safety probe ran — should not happen in normal
        # install but kept for callers that pass decisions=None).
        if not detected["weaviate_url"]:
            services_to_start.append("weaviate")
        if not detected["ollama_url"]:
            services_to_start.append("ollama")
        if sysinfo.has_gpu and not detected["code_embed_url"]:
            services_to_start.append("code_embed")

    # All required services already up AND none needs a config-recreate —
    # nothing to do. (v0.2.61: a vct-managed adopt with a changed compose
    # config lands in services_to_recreate, so we must NOT early-return when
    # that list is non-empty — the recreate below applies the new config.)
    if not force_separate and not services_to_start and not services_to_recreate:
        print("  All required services already running — reusing them.")
        print("  (Set VCT_FORCE_SEPARATE_CONTAINERS=1 for separate per-install containers.)")
        return

    # Proactive runtime-reachability check (2026-05-08). Catches "daemon
    # not running" / "rootless socket not started" BEFORE we attempt
    # compose-up — without this we used to wait for compose-up to fail
    # with cryptic stderr ("Cannot connect to the Docker daemon" /
    # "Cannot connect to Podman socket"), parse it, and emit a hint. Now
    # we surface the actionable hint upfront with the OS-correct
    # recovery command, saving 10-30s and giving the user a clearer
    # signal.
    #
    # v0.2.51 Bug G: for Podman, ATTEMPT to start the daemon before
    # giving up. systemctl --user start podman.socket on Linux is safe
    # to call on a healthy machine (no-op if already started) and
    # eliminates the most common "binary present but daemon stopped"
    # failure mode. On macOS/Windows we try `podman machine start` — if
    # the VM hasn't been initialized yet (first-time user), we emit a
    # deferral with the manual `podman machine init` recipe rather than
    # auto-downloading a multi-hundred-MB VM image unattended.
    # Docker daemon start is NOT automated here — Docker Desktop on
    # macOS/Windows requires GUI interaction; `sudo systemctl start
    # docker` on Linux needs sudo+interactive password, which we don't
    # shoulder for a non-blocking pre-flight check.
    if not _container_runtime_reachable(sysinfo.container_cmd):
        if sysinfo.container_cmd == "podman":
            print(
                "  [!] podman is installed but its daemon/socket isn't "
                "responding to `podman info`. Attempting auto-start..."
            )
            ok, detail = _try_start_podman_daemon()
            if ok:
                print("      [OK] Podman daemon is now responsive.")
            else:
                print(f"      [!] Auto-start failed: {detail}")
                _emit_podman_daemon_start_failed_deferral(
                    deferral_report, detail=detail,
                )
                print(
                    "      A deferral entry has been written to "
                    "UPDATE_DEFERRED.md with the manual recovery recipe."
                )
                print(
                    "      compose-up below may fail; re-run install.py "
                    "after starting the daemon manually."
                )
        elif sysinfo.container_cmd == "docker" and platform.system() in ("Darwin", "Windows"):
            # v0.2.54 (C-RT-7): docker auto-heal sibling of the podman
            # branch above — `open -a Docker` (macOS) / shell-start of
            # Docker Desktop (Windows) + 60s `docker info` poll. Linux
            # stays manual (sudo systemctl needs an interactive password
            # we don't shoulder in a pre-flight) and takes the hint
            # branch below.
            print(
                "  [!] docker is installed but its daemon isn't responding "
                "to `docker info`. Attempting to start Docker Desktop..."
            )
            ok, detail = _try_start_docker_daemon()
            if ok:
                print("      [OK] Docker daemon is now responsive.")
            else:
                print(f"      [!] Auto-start failed: {detail}")
                print(
                    "      compose-up below may fail; start Docker Desktop "
                    "manually and re-run install.py once it settles."
                )
        else:
            print(
                f"  [!] {sysinfo.container_cmd} is installed but its daemon/socket\n"
                f"      isn't responding to `{sysinfo.container_cmd} info`. The compose-up\n"
                f"      below will fail. Most common fixes:"
            )
            if sysinfo.container_cmd == "docker":
                print("        Linux:   sudo systemctl start docker")
                print("        macOS:   open Docker Desktop and wait for it to start")
                print("        Windows: start Docker Desktop")
            else:
                print("        Linux:   systemctl --user start podman.socket")
                print("        macOS:   podman machine start")
                print("        Windows: podman machine start")
            print(
                "      Re-run install.py once the runtime is reachable. (Skipping the\n"
                "      compose-up below would leave the install in a partial state.)"
            )

    compose_cmd = _get_compose_command(sysinfo.container_cmd)

    # v0.2.54 (gpu-audit C-4): persist + export the compose-substitution
    # keys (CODE_EMBED_BACKEND / CODE_EMBED_DOCKERFILE) so the build
    # actually receives them. infrastructure/.env covers every later
    # compose invocation (boot wrapper, hooks, manual up); the explicit
    # process-env merge below covers THIS invocation.
    _write_infrastructure_env(embed_config)
    compose_env = {**os.environ, **_compose_substitution_env(embed_config)}

    cmd = [*compose_cmd, "-f", str(compose_file)]

    # GPU overlay + code_embed profile.
    # NVIDIA → docker-compose.gpu.yml (deploy.resources NVIDIA driver).
    # AMD ROCm → docker-compose.amd-rocm.yml (Ollama ROCm image + /dev/kfd
    # + /dev/dri device passthrough). The two are mutually exclusive —
    # picking the wrong one means Ollama silently runs CPU-only despite
    # has_gpu=True. Distinguished via sysinfo.gpu_vendor.
    #
    # Podman vs Docker: each engine needs a different compose overlay
    # because the device-passthrough syntax differs (Docker reads
    # `deploy.resources.reservations.devices`; Podman uses CDI form
    # `devices: [nvidia.com/gpu=all]`). Pick by `sysinfo.container_cmd`.
    is_podman = "podman" in (sysinfo.container_cmd or "").lower()

    # Compose-overlay ambiguity check: if both the NVIDIA overlay file and
    # the AMD ROCm overlay file exist, and both GPU tools respond, we cannot
    # safely pick the right one without user input. Emit a deferral so the
    # user can resolve explicitly (e.g. by passing --gpu or --cpu-only).
    if sysinfo.has_gpu and deferral_report is not None:
        _nvidia_file = infra_dir / ("podman-compose.gpu.yml" if is_podman else "docker-compose.gpu.yml")
        # v0.2.20: probe BOTH the canonical short name AND the legacy
        # `amd-rocm.yml` name. Either being on disk counts as "AMD
        # overlay available" for the purpose of the ambiguity check.
        _amd_short = infra_dir / ("podman-compose.rocm.yml" if is_podman else "docker-compose.rocm.yml")
        _amd_legacy = infra_dir / ("podman-compose.amd-rocm.yml" if is_podman else "docker-compose.amd-rocm.yml")
        _amd_file_exists = _amd_short.exists() or _amd_legacy.exists()
        _amd_file = _amd_short if _amd_short.exists() else _amd_legacy
        if _nvidia_file.exists() and _amd_file_exists:
            # Both overlay files present. Probe GPU tools to see if both are
            # live. A tool that isn't installed (no rocm-smi on a pure-NVIDIA
            # box, the common case; or either tool on a non-GPU machine) or
            # that hangs past the timeout means "not live" — it must NOT crash
            # the install. See _gpu_tool_reports_live (v0.2.62 fix): pre-fix
            # these two calls invoked subprocess.run unguarded and aborted the
            # whole install/update with FileNotFoundError on any box missing a
            # tool.
            _nvidia_live = _gpu_tool_reports_live("nvidia-smi", ["-L"])
            _amd_live = _gpu_tool_reports_live("rocm-smi", ["--showid"])
            if _nvidia_live and _amd_live:
                deferral_report.add_entry(
                    DeferralEntry(
                        condition_id="compose_overlay_ambiguous",
                        title="Compose GPU overlay ambiguous",
                        detected=(
                            "Both nvidia-smi and rocm-smi report a live GPU, and "
                            "both NVIDIA and AMD ROCm compose overlay files exist. "
                            "Cannot safely pick an overlay automatically."
                        ),
                        why_deferred=(
                            "Picking the wrong overlay causes Ollama to silently "
                            "run CPU-only. User must specify the GPU vendor."
                        ),
                        command_to_apply=(
                            "# For NVIDIA:\n"
                            "VCT_GPU_VENDOR=nvidia python install.py --gpu --update\n"
                            "# For AMD ROCm:\n"
                            "VCT_GPU_VENDOR=amd python install.py --gpu --update"
                        ),
                        severity="warning",
                        kg_node_refs=[],
                    )
                )

    if sysinfo.has_gpu:
        if sysinfo.gpu_vendor == "amd":
            # v0.2.20: prefer `docker-compose.rocm.yml` (canonical short
            # name) over the legacy `docker-compose.amd-rocm.yml`. Both
            # are valid; the short name is what new docs reference.
            # Podman uses its own variant filename because the device-
            # passthrough syntax can differ. Probe both.
            rocm_candidates = []
            if is_podman:
                rocm_candidates.extend([
                    "podman-compose.rocm.yml",
                    "podman-compose.amd-rocm.yml",
                ])
            else:
                rocm_candidates.extend([
                    "docker-compose.rocm.yml",
                    "docker-compose.amd-rocm.yml",
                ])
            rocm_file_name = None
            rocm_file = None
            for candidate in rocm_candidates:
                p = infra_dir / candidate
                if p.exists():
                    rocm_file_name = candidate
                    rocm_file = p
                    break
            if rocm_file is not None:
                cmd.extend(["-f", str(rocm_file), "--profile", "gpu"])
                engine = "Podman" if is_podman else "Docker"
                print(f"  GPU overlay: AMD ROCm ({engine}: {rocm_file_name})")
            else:
                # Neither overlay file present — fall back to CPU.
                tried = ", ".join(rocm_candidates)
                print(f"  WARNING: AMD ROCm overlay not found (tried: {tried}), running CPU-only")
        else:
            # Default to NVIDIA overlay for has_gpu=True with vendor
            # unset or "nvidia" (back-compat with --gpu flag).
            gpu_file_name = "podman-compose.gpu.yml" if is_podman else "docker-compose.gpu.yml"
            gpu_file = infra_dir / gpu_file_name
            if gpu_file.exists():
                # Podman + NVIDIA prerequisite: nvidia-ctk CDI spec must
                # exist on the host. install.py runs the generator once
                # before compose-up so compose can reference
                # `nvidia.com/gpu=all` without manual setup.
                if is_podman:
                    _ensure_nvidia_cdi_spec_for_podman()
                cmd.extend(["-f", str(gpu_file), "--profile", "gpu"])
                engine = "Podman" if is_podman else "Docker"
                print(f"  GPU overlay: NVIDIA ({engine}: includes code_embed container)")
            else:
                print(f"  WARNING: GPU overlay {gpu_file_name} not found, running CPU-only")

    cmd.extend(["up", "-d"])
    # v0.2.61 (FINDING-1 fix): when a vct-managed service we OWN was adopted
    # but its compose config changed (e.g. the Weaviate write-amp env tuning),
    # it lands in services_to_recreate and we add `--force-recreate` + name the
    # exact services so compose REBUILDS them from the new config. We pass the
    # explicit service list (start ∪ recreate) so compose touches ONLY those —
    # `--force-recreate` then recreates the named ones (no-op'ing any already
    # at the desired config) and leaves every unnamed service (incl. a FOREIGN
    # adopt we must not touch) running untouched. The named DATA VOLUME is
    # preserved across `--force-recreate` (it rm's the container, not the
    # volume) — collections survive. Without naming services, a bare
    # `--force-recreate` would recreate the WHOLE stack, including foreign
    # adopts; naming keeps it surgical.
    explicit_services = services_to_start + [
        s for s in services_to_recreate if s not in services_to_start
    ]
    if services_to_recreate:
        cmd.append("--force-recreate")
        cmd.extend(explicit_services)
        print(
            f"  Recreating (config changed): {', '.join(services_to_recreate)}"
            + (f"; starting: {', '.join(services_to_start)}" if services_to_start else "")
        )
    elif services_to_start:
        # When subset detection said only some services are missing, pass them
        # explicitly so compose doesn't try to recreate already-running ones.
        cmd.extend(services_to_start)
        print(f"  Starting only: {', '.join(services_to_start)}")

    # 15 min default cap: first-run pulls of weaviate + ollama images can
    # take a while on slow links, but a hung daemon should not block us
    # forever. Configurable via VCT_INSTALL_DOCKER_TIMEOUT (seconds) — bump
    # for slow domestic links + cold cache (2026-05-23 observed: weaviate
    # 1.28.4 pull alone is ~250MB and can hit the 15min wall on residential
    # DSL while the daemon is still healthy and pulling in the background).
    docker_timeout = 900
    timeout_env = os.environ.get("VCT_INSTALL_DOCKER_TIMEOUT", "").strip()
    if timeout_env:
        try:
            docker_timeout = max(60, int(timeout_env))
        except ValueError:
            pass
    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, cwd=str(infra_dir), timeout=docker_timeout,
            env=compose_env,
        )
    except subprocess.TimeoutExpired:
        timeout_min = docker_timeout // 60
        print(f"  FAIL (timed out after {timeout_min} min)")
        print(f"  Container daemon may be hung. Try manually:")
        print(f"    cd {infra_dir}")
        print(f"    {' '.join(compose_cmd)} up -d")
        print(f"  Or bump the timeout: VCT_INSTALL_DOCKER_TIMEOUT=1800 python install.py ...")
        _log_install_event(
            "5/10", "error",
            f"compose up timed out after {timeout_min} min",
            data={"runtime": sysinfo.container_cmd, "timeout_sec": docker_timeout},
        )
        sys.exit(1)
    if result.returncode != 0:
        print("  FAIL")
        for line in (result.stderr or "").strip().splitlines()[-10:]:
            print(f"  {line}")
        print("\n  Try starting manually:")
        print(f"    cd {infra_dir}")
        print(f"    {' '.join(compose_cmd)} up -d")
        # Common cause: daemon not running. Surface it.
        stderr_lower = (result.stderr or "").lower()
        if "cannot connect" in stderr_lower or "daemon" in stderr_lower:
            print("\n  Hint: container daemon not running.")
            if sysinfo.container_cmd == "docker":
                print("    Linux:  sudo systemctl start docker")
                print("    macOS:  open Docker Desktop")
                print("    Windows: start Docker Desktop")
            else:
                print("    Linux:  systemctl --user start podman.socket")
        # Common cause: bind: address already in use → user already has a
        # service on this port that we somehow didn't probe (different
        # protocol, late startup, …). Tell them about the escape hatch.
        if "address already in use" in stderr_lower or "bind" in stderr_lower:
            print("\n  Hint: a host port is already in use.")
            print("    Either stop the conflicting process, or set")
            print("    VCT_FORCE_SEPARATE_CONTAINERS=1 + override WEAVIATE_PORT /")
            print("    OLLAMA_PORT / CODE_EMBED_PORT to use distinct ports.")
        _log_install_event(
            "5/10", "error",
            f"compose up failed (exit {result.returncode})",
            data={"runtime": sysinfo.container_cmd,
                  "exit_code": result.returncode,
                  "stderr_tail": (result.stderr or "").strip()[-400:]},
        )
        sys.exit(1)
    print("  OK")
    _log_install_event("5/10", "ok", "compose up completed")


def _get_compose_command(container_cmd: str) -> list[str]:
    """Return the compose command as a list of args."""
    if container_cmd == "podman":
        # Prefer standalone podman-compose if present
        if shutil.which("podman-compose"):
            return ["podman-compose"]
        # Try `podman compose` plugin
        try:
            result = subprocess.run(
                ["podman", "compose", "version"],
                capture_output=True, text=True, timeout=10,
            )
            if result.returncode == 0:
                return ["podman", "compose"]
        except (subprocess.TimeoutExpired, OSError):
            pass
        # Last-resort fallback (user will see error if neither works)
        return ["podman", "compose"]

    # Docker: try v2 plugin first, then standalone
    try:
        result = subprocess.run(
            ["docker", "compose", "version"],
            capture_output=True, text=True, timeout=10,
        )
        if result.returncode == 0:
            return ["docker", "compose"]
    except (subprocess.TimeoutExpired, OSError):
        pass

    if shutil.which("docker-compose"):
        return ["docker-compose"]
    return ["docker", "compose"]


def _wait_for_ollama() -> None:
    """Wait for Ollama to be ready."""
    print("[6/10] Waiting for Ollama ... ", end="", flush=True)
    _log_install_event("6/10", "start", "waiting for Ollama")
    port = os.environ.get("OLLAMA_PORT", str(DEFAULT_OLLAMA_PORT))
    url = f"http://localhost:{port}/api/tags"
    deadline = time.monotonic() + HEALTH_TIMEOUT

    while time.monotonic() < deadline:
        try:
            resp = urllib.request.urlopen(url, timeout=3)
            if resp.status == 200:
                print("OK")
                _log_install_event(
                    "6/10", "ok",
                    "Ollama is ready",
                    data={"url": url},
                )
                return
        except (urllib.error.URLError, OSError):
            pass
        time.sleep(2)

    print("TIMEOUT")
    print(f"  Ollama not ready after {HEALTH_TIMEOUT}s at {url}")
    print("  Check container logs.")
    _log_install_event(
        "6/10", "error",
        f"Ollama not ready after {HEALTH_TIMEOUT}s",
        data={"url": url, "timeout_s": HEALTH_TIMEOUT},
    )


class EmbeddingModelPullError(RuntimeError):
    """Raised when a load-bearing embedding-model pull fails.

    v0.2.49 Bug I: pre-fix ``_pull_ollama_models`` logged-then-continued on
    every failure. Embedding models are load-bearing — without the active
    embedding model in the local Ollama cache, KG sync silently breaks.
    The function now classifies each model as embedding (fail-fast) or
    other (best-effort) and raises this exception when one or more
    load-bearing models fail to pull.
    """


def _pull_ollama_models(
    models: list[str],
    embedding_models: set[str] | None = None,
) -> None:
    """Pull required Ollama models.

    v0.2.49 Bug I: ``embedding_models`` names the subset of ``models`` that
    are load-bearing (the active text/code embedding models). If any of
    them fail to pull, this function raises
    :class:`EmbeddingModelPullError` AFTER attempting all remaining pulls
    so the user gets the full picture in one shot rather than a per-model
    interactive bail. Non-embedding models (summary/chat tiers) remain
    best-effort and only emit a WARN log + manual-pull hint on failure.

    Backward-compat: callers that don't pass ``embedding_models`` get a
    heuristic fallback — any model name containing ``"embed"`` in
    lowercase is treated as load-bearing. Callers that DO pass the set
    get a precise answer; the heuristic is the safety net.
    """
    print("[7/10] Pulling Ollama models ... ", flush=True)
    _log_install_event(
        "7/10", "start",
        f"pulling {len(models)} Ollama model(s)",
        data={"models": list(models)},
    )
    port = os.environ.get("OLLAMA_PORT", str(DEFAULT_OLLAMA_PORT))

    if embedding_models is None:
        # Heuristic fallback for callers that don't pass the precise set
        # (back-compat). Embedding-model names canonically contain
        # "embed" in lowercase: qwen3-embedding, snowflake-arctic-embed2,
        # text-embedding-3-small, unclemusclez/jina-embeddings-v2-base-code.
        embedding_models = {
            m for m in models
            if "embed" in m.lower()
        }

    failed: list[str] = []
    failed_embedding: list[str] = []
    for model in models:
        print(f"  Pulling {model} ... ", end="", flush=True)
        try:
            data = json.dumps({"name": model}).encode()
            req = urllib.request.Request(
                f"http://localhost:{port}/api/pull",
                data=data,
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            resp = urllib.request.urlopen(req, timeout=600)
            # Read streaming response to completion
            while True:
                chunk = resp.read(4096)
                if not chunk:
                    break
            print("OK")
        except (urllib.error.URLError, OSError) as e:
            print(f"WARN ({e})")
            print(f"    Pull manually: curl -X POST "
                  f"http://localhost:{port}/api/pull "
                  f"-d '{{\"name\": \"{model}\"}}'")
            failed.append(model)
            if model in embedding_models:
                failed_embedding.append(model)

    if failed_embedding:
        _log_install_event(
            "7/10", "error",
            f"{len(failed_embedding)} load-bearing embedding-model pull(s) "
            f"failed; KG sync will be broken until resolved",
            data={
                "failed_embedding": failed_embedding,
                "failed_all": failed,
            },
        )
        raise EmbeddingModelPullError(
            "Load-bearing embedding model pull(s) failed: "
            f"{', '.join(failed_embedding)}. The Knowledge Graph cannot "
            "function without these models — install aborted. Resolve "
            "manually (curl -X POST http://localhost:" + port + "/api/pull "
            "-d '{\"name\": \"<model>\"}') then re-run install."
        )
    if failed:
        _log_install_event(
            "7/10", "warn",
            f"{len(failed)} non-load-bearing model pull(s) failed",
            data={"failed": failed},
        )
    else:
        _log_install_event("7/10", "ok", "all Ollama models pulled")


def _probe_dual_ollama_instances(
    canonical_port: int = DEFAULT_OLLAMA_PORT,
    alternate_port: int = 11434,
    timeout_s: float = 1.0,
) -> tuple[int, int] | None:
    """Detect when two separate Ollama daemons are reachable on this host.

    v0.2.49 Bug J: users with personal Ollama installs (default port
    11434) running alongside the launcher's containerized Ollama (port
    11435) hit "where did my model go?" confusion because the two
    instances have independent model caches. This probe returns
    ``(alternate_port, canonical_port)`` when BOTH respond to
    ``/api/tags`` within ``timeout_s`` seconds; the caller can then emit
    a UPDATE_DEFERRED.md warning so the user sees the divergence at
    install-time AND post-install (the deferral file persists).

    Returns ``None`` when only one or neither responds. Soft-fails on
    any unexpected error (network stack quirks, IPv6/IPv4 oddities,
    etc.) — a probe failure must never block install.
    """

    def _port_responds(port: int) -> bool:
        try:
            req = urllib.request.Request(
                f"http://localhost:{port}/api/tags",
                method="GET",
            )
            with urllib.request.urlopen(req, timeout=timeout_s) as resp:
                # Drain a few bytes so the socket closes cleanly. We
                # don't care about the body — any 2xx response means
                # there's a live Ollama on this port.
                _ = resp.read(64)
                return 200 <= getattr(resp, "status", 200) < 300
        except Exception:
            return False

    try:
        canonical_alive = _port_responds(canonical_port)
        alternate_alive = _port_responds(alternate_port)
    except Exception:
        return None

    if canonical_alive and alternate_alive and canonical_port != alternate_port:
        # Order: alternate first (the "surprise" instance), canonical
        # second. Tests assert this exact shape.
        return (alternate_port, canonical_port)
    return None


def _emit_dual_ollama_deferral(
    deferral_report: "DeferralReport",
    canonical_port: int = DEFAULT_OLLAMA_PORT,
    alternate_port: int = 11434,
) -> None:
    """v0.2.49 Bug J: emit an info-severity deferral when both Ollama
    instances respond.

    Mirrors the shape of :func:`_emit_orchestrator_root_schema_deferrals`
    — soft-fail throughout, idempotent on re-runs (the deferral writer
    deduplicates by ``condition_id``).
    """
    try:
        result = _probe_dual_ollama_instances(
            canonical_port=canonical_port,
            alternate_port=alternate_port,
        )
    except Exception:
        return
    if result is None:
        return

    alt, canon = result
    try:
        deferral_report.add_entry(
            DeferralEntry(
                condition_id="dual_ollama_detected",
                title=(
                    f"Two Ollama instances reachable "
                    f"(:{alt} + :{canon})"
                ),
                detected=(
                    f"Both `http://localhost:{alt}` (default Ollama "
                    f"port) and `http://localhost:{canon}` "
                    f"(launcher-managed Ollama container) responded to "
                    f"`/api/tags`.  These are two independent daemons "
                    f"with separate model caches — a model pulled into "
                    f"one is NOT visible from the other."
                ),
                why_deferred=(
                    "Cannot auto-resolve: we don't know which instance "
                    "the user intends as canonical.  Stopping the "
                    "user's personal Ollama daemon would risk breaking "
                    "their other tooling; stopping the launcher's "
                    "container would break VCO.  The user must choose "
                    "and reconcile."
                ),
                command_to_apply=(
                    f"# VCO uses :{canon} (the launcher-managed "
                    f"container) as canonical.\n"
                    f"# If you want VCO to use your personal Ollama "
                    f"instead, set OLLAMA_PORT={alt} in .claude/env and "
                    f"re-run install.\n"
                    f"# If you want to stop the personal instance:\n"
                    f"#   systemctl --user stop ollama   # Linux\n"
                    f"#   killall ollama                 # macOS / generic\n"
                    f"# Then re-run install.py --update to reseed."
                ),
                severity="info",
                kg_node_refs=[],
            )
        )
        _log_install_event(
            "7/10", "info",
            f"Bug J: dual-Ollama detected (:{alt} + :{canon}); "
            f"deferral emitted",
        )
    except Exception:
        # Defensive: never let a deferral emit failure block install.
        return


# ---------------------------------------------------------------------------
# Step 6c: Weaviate collection bootstrap (shared-container aware)
# ---------------------------------------------------------------------------

# Minimal Weaviate class definitions for the collections this install needs.
# Vectorizer is "none" — we feed pre-computed vectors from Ollama / CodeSage.
# These are intentionally property-light: the MCP server (server.py) uses the
# v4 client `client.collections.get(name)` which doesn't require a strict
# property list to insert; richer schemas can be added later without
# re-creating the class.
# Moved to vco_lib.project_init in PR 2 — kept as shim for existing callers;
# will be removed in PR 9 (cleanup). The old underscored names are exported
# below for back-compat with tests and other modules.
_named_vector_config = _project_init._named_vector_config
_kg_class_definition = _project_init._kg_class_definition
_development_class_definition = _project_init._development_class_definition
_SAFE_CLASS_RE = _project_init._SAFE_CLASS_RE
_derive_project_kg_name = _project_init._derive_project_kg_name
_derive_project_dev_name = _project_init._derive_project_dev_name
# fix/a1-indexing-pipeline (2026-05-25) — path-based Diagrams name
# derivation, matching the KG / Dev helper shape so _ensure_collections
# can include the diagrams class in its bootstrap pass.
_derive_project_diagrams_name = _project_init._derive_project_diagrams_name
_diagrams_class_definition = _project_init._diagrams_class_definition


def _derive_orchestrator_project_name() -> str:
    """Resolve the orchestrator's own project name for env propagation.

    PR-7 (v0.2.11): pre-v0.2.11 the orchestrator's `.claude/settings.json`
    env block omitted `PROJECT_NAME` and `CODE_GRAPH_PROJECT`. As a result,
    every hook in every project that derived a fallback ended up sharing the
    legacy `ClaudeOrchestrator` hardcode. We now write both keys at install
    time so the orchestrator's own hooks resolve a stable, project-specific
    name.

    Resolution priority:
      1. `vct-module.json::name` (canonical — shipped with every release).
         Sanitized to a Weaviate-safe class basename (same sanitizer as the
         per-project derivation in `vco_lib.project_init`).
      2. Hardcoded fallback `"VibeCodedOrchestrator"` — matches what
         `_install_kg_class_definition`'s naming convention would produce
         for "VibeCoded Orchestrator" and never collides with a real
         per-project derivation.

    Returns:
        A Weaviate-class-safe (PascalCase, alphanum-only) project name.
    """
    manifest = PROJECT_ROOT / "vct-module.json"
    if manifest.is_file():
        try:
            with manifest.open("r", encoding="utf-8") as f:
                data = json.load(f)
            raw = data.get("name") or ""
            if raw:
                sanitized = _project_init.sanitize_for_weaviate_class(str(raw))
                if sanitized and sanitized != _project_init._FALLBACK_PREFIX:
                    return sanitized
        except (OSError, json.JSONDecodeError):
            pass
    return "VibeCodedOrchestrator"


def _backfill_vscode_excludes(settings_file: Path | None = None) -> dict:
    """Orchestrator-side mirror of
    `vco_lib.project_init._backfill_vscode_excludes_in_project`.

    PR-7 / addendum-4 (v0.2.11): the orchestrator's own `.vscode/settings.json`
    benefits from the same watcher / search / Pylance exclude defaults as
    every project the launcher registers. Without these:
      - VS Code's file watcher saturates on cargo target/ (~33 GB churn).
      - Pylance indexes site-packages, blowing memory budget.
      - OOM kills (verified live 2026-05-16 on multiple workspaces).

    Idempotency contract matches the per-project version: only ADDS
    missing keys, never overwrites. Returns the same dict shape.

    Args:
        settings_file: path to `.vscode/settings.json`. Defaults to
            `<PROJECT_ROOT>/.vscode/settings.json`.
    """
    if settings_file is None:
        settings_file = PROJECT_ROOT / ".vscode" / "settings.json"

    # Delegate to the project_init helper using the parent folder of
    # `.vscode/`. This keeps the canonical exclude block in ONE place
    # (project_init._VSCODE_EXCLUDE_DEFAULTS) so the orchestrator and
    # per-project surfaces never drift.
    if settings_file.parent.name == ".vscode":
        parent = settings_file.parent.parent
    else:
        # Caller passed a non-canonical path; fall back to the raw
        # parent. Still safe — the project_init helper looks for
        # `<parent>/.vscode/settings.json` and would create that path
        # rather than touching the caller's custom file.
        parent = settings_file.parent
    return _project_init._backfill_vscode_excludes_in_project(parent)


def _backfill_code_graph_project_env(settings_file: Path | None = None) -> dict:
    """Project canonical env (incl. PROJECT_NAME + CODE_GRAPH_PROJECT) into
    the orchestrator-root project's `.claude/settings.json::env` block.

    Phase 0.B Part 2 (2026-05-25): this helper now delegates to
    `vco_lib.config_projection.apply_project_env`. The legacy
    add-only-missing-keys path (PR-7 / v0.2.11) is GONE; canonical keys
    are now always OVERWRITTEN with the DB-resolved value because the
    launcher's `launcher.db` is the single source of truth per the
    Phase 0.B contract. User-set values for canonical keys are no
    longer preserved — users who want a non-default KG_COLLECTION /
    CODE_GRAPH_PROJECT should change the binding in the launcher GUI
    instead of hand-editing the settings file.

    Non-canonical user-added env keys ARE preserved (the contract's
    deep-merge semantics — see `vco_lib/config_projection.py`).

    Idempotency contract (post-Phase-0.B-Part-2):
      - Missing settings file → the contract writes a fresh one.
      - launcher.db unreachable (fresh install before first launcher
        boot) → `action="db_unreachable"`, no-op.
      - orchestrator-root project not yet registered in launcher.db
        → `action="orchestrator_not_registered"`, no-op.
      - Successful project_env → `action="applied"` with the list of
        canonical keys written.

    Args:
        settings_file: path to `.claude/settings.json`. Defaults to
            `<PROJECT_ROOT>/.claude/settings.json` — the Orchestrator
            Project's own settings file. The parent of this path is the
            orchestrator-root project folder; the resolver looks up its
            project_id by folder match.

    Returns:
        `{"action": str, "added_keys": [str, ...], "path": str}` so callers
        can log a precise outcome. `added_keys` lists the canonical keys
        that landed on disk this run (sorted).
    """
    if settings_file is None:
        settings_file = PROJECT_ROOT / ".claude" / "settings.json"

    result: dict = {
        "action": "missing",
        "added_keys": [],
        "path": str(settings_file),
    }

    project_folder = settings_file.parent.parent

    # Resolve the orchestrator-root project_id by matching folder_path
    # in launcher.db. Soft-fail to no-op on any DB issue (matches the
    # legacy helper's "best-effort" discipline — install-bundle --update
    # must not crash on a missing / not-yet-initialised launcher).
    project_id = _resolve_project_id_by_folder(project_folder)
    if project_id is None:
        result["action"] = "orchestrator_not_registered"
        return result

    try:
        from vco_lib.config_projection import (
            apply_project_env,
            project_env_from_db,
            DbUnreachable,
            ProjectNotFound,
        )
        bundle = project_env_from_db(project_id)
        report = apply_project_env(bundle)
    except DbUnreachable:
        result["action"] = "db_unreachable"
        return result
    except ProjectNotFound:
        # The folder-match resolver said the project exists, but
        # project_env_from_db disagrees — DB rewrite mid-run. Re-classify
        # as orchestrator_not_registered for consistency.
        result["action"] = "orchestrator_not_registered"
        return result
    except Exception as e:
        result["action"] = f"apply_failed:{type(e).__name__}:{e}"
        return result

    # The contract reports per-surface lists; flatten to a unique sorted
    # list for the existing log-event consumer's shape.
    keys_written: set[str] = set()
    for _surface, keys in report.items():
        keys_written.update(keys)
    result["action"] = "applied"
    result["added_keys"] = sorted(keys_written)
    return result


def _emit_orchestrator_root_env_keys(install_root: Path) -> None:
    """V0243-5: write VCT_ORCHESTRATOR_ROOT, VCT_INFRASTRUCTURE_DIR, and
    KG_BASE_DIR into ``<install_root>/.claude/env`` managed block.

    These three portability keys are load-bearing for every hook and MCP
    that references the orchestrator root at runtime.  They were previously
    emitted only via ``apply_project_env`` (which requires launcher.db with
    a registered project row), leaving fresh installs — where the launcher
    has never started — without these keys until the first launcher boot.

    This helper writes the 3 keys directly, bypassing the DB requirement.
    It merges into the managed block via
    ``vco_lib.config_projection._write_shell_env_managed_block`` (same
    mechanism the launcher uses) so a subsequent ``apply_project_env`` call
    that writes the full canonical set will overwrite these 3 keys in-place
    without duplication.

    Soft-fail: any error is logged but never raises.
    """
    try:
        from vco_lib.config_projection import _write_shell_env_managed_block
    except ImportError:
        # vco_lib not yet on sys.path on a very early fresh install; skip —
        # the launcher's first-boot env-projection will fill the gap.
        _log_install_event(
            "4b/10", "skip",
            "V0243-5: vco_lib.config_projection not importable; "
            "orchestrator-root env keys deferred to launcher boot",
        )
        return

    infra_dir = install_root / "infrastructure"
    keys: dict[str, str] = {
        "VCT_ORCHESTRATOR_ROOT": str(install_root.resolve()),
        "VCT_INFRASTRUCTURE_DIR": str(infra_dir.resolve()),
        "KG_BASE_DIR": str(install_root.resolve()),
    }

    # v0.2.49 SB1: seed VCT_PROJECT_ID alongside the portability keys
    # so the Phase-8 access-matrix WRITE gate has a project identifier
    # from the moment .claude/env is written. The gate's empty-PID
    # branch (claude_mcp_servers/weaviate_mcp/server.py L5995-6049 and
    # the templates/hooks/post-file-edit.{sh,ps1} _kg_write_allowed
    # helpers) is the silent-bypass surface that SB1 closes — emitting
    # VCT_PROJECT_ID here means hooks + the MCP have the identifier
    # available from install time, not just after the first launcher
    # boot's apply_project_env pass.
    #
    # Resolution is best-effort: if launcher.db isn't there yet (fresh
    # install, never opened the launcher), we just skip this key — the
    # gate's empty-PID branch will fire on the first WRITE attempt and
    # the deferral / metric surfaces guide the user to re-register.
    # Once they do, the next apply_project_env pass (driven by the
    # launcher) backfills VCT_PROJECT_ID via the canonical contract.
    try:
        pid = _resolve_project_id_by_folder(install_root)
    except Exception:
        pid = None
    if pid:
        keys["VCT_PROJECT_ID"] = pid

    claude_env_path = install_root / ".claude" / "env"
    try:
        written = _write_shell_env_managed_block(claude_env_path, keys)
        _log_install_event(
            "4b/10", "ok",
            f"V0243-5: emitted orchestrator-root env keys to .claude/env: "
            f"{', '.join(written)}",
            data={"keys": written, "path": str(claude_env_path)},
        )
    except Exception as exc:
        _log_install_event(
            "4b/10", "warn",
            f"V0243-5: could not write orchestrator-root env keys to "
            f".claude/env: {exc}",
        )


def _resolve_project_id_by_folder(folder: Path) -> str | None:
    """Look up the project_id for a given folder_path in launcher.db.

    Mirrors the soft-fail discipline of
    `vco_lib.project_init._read_kg_binding_override`: read-only DB
    open, return None on any failure (DB missing, file locked, no
    matching row). On a fresh install where the launcher has never
    started, `~/.vct/launcher.db` doesn't exist and the function
    returns None — the caller treats this as "no-op, don't backfill".

    Honours `$VCT_STATE_DIR` so the launcher's per-launcher state
    isolation works (multi-launcher dev setups) — delegates to
    `vco_lib.paths.launcher_db_path` (canonical resolver, v0.2.40 F5).
    """
    from vco_lib.paths import launcher_db_path
    db_path = launcher_db_path()
    if not db_path.is_file():
        return None
    try:
        folder_canonical = folder.resolve()
    except (OSError, RuntimeError):
        return None
    import sqlite3 as _sqlite3
    try:
        conn = _sqlite3.connect(
            f"file:{db_path}?mode=ro", uri=True, timeout=2.0
        )
    except _sqlite3.Error:
        return None
    try:
        cur = conn.cursor()
        try:
            cur.execute("SELECT id, folder_path FROM projects")
            rows = cur.fetchall()
        except _sqlite3.Error:
            return None
        for row_id, row_folder in rows:
            try:
                row_canonical = Path(row_folder or "").resolve()
            except (OSError, RuntimeError):
                continue
            if row_canonical == folder_canonical:
                return str(row_id)
        return None
    finally:
        try:
            conn.close()
        except _sqlite3.Error:
            pass


def _ensure_collections(embed_config: dict,
                        decisions: dict | None = None,
                        args: argparse.Namespace | None = None) -> None:
    """Detect existing Weaviate collections and create only the ones missing.

    Code-graph collections (CodeModule / CodeClass / CodeFunction / CodeAPI /
    CodeInteraction) are SHARED across all projects on this machine — they
    carry a `project_name` field that separates rows. Don't recreate them
    per-install: the MCP server creates them lazily on first write.

    Adopt-mode safety (the user's Weaviate already exists):
      - Per-project KG / Development names are derived from the project
        basename so we never write bare top-level `KnowledgeGraph` /
        `Development` into a host that uses per-project namespacing.
      - vco always creates its OWN collections; we deliberately do NOT
        adopt cross-project KGs from other installs. Reason: the
        orchestrator's orphan-prune sync would delete entries whose
        `file_path` no longer exists in this install.
      - In adopt mode, every proposed creation is announced; with `--yes`
        the install proceeds non-interactively, otherwise the user is
        prompted to confirm.
      - `--skip-seed` and `--skip-collections` short-circuit the whole
        step (collections get created lazily by the MCP server).

    The resolved per-project / shared names are propagated back to
    `os.environ` so `_write_env_config` writes them into `.env`.
    """
    # Honor --skip-seed / --skip-collections: if the user opted out of
    # seeding, they almost certainly don't want us mutating schema either.
    if args is not None and (
        getattr(args, "skip_collections", False)
        or getattr(args, "skip_seed", False)
    ):
        print("[7b/10] Skipping Weaviate collection bootstrap "
              "(--skip-seed / --skip-collections).")
        print("  Run `kg-sync --all` later to seed; the MCP server creates "
              "missing collections lazily on first write.")
        _log_install_event(
            "7b/10", "skip",
            "collection bootstrap skipped via flag",
            data={"skip_collections": getattr(args, "skip_collections", False),
                  "skip_seed": getattr(args, "skip_seed", False)},
        )
        return

    weaviate_port = os.environ.get("WEAVIATE_PORT", str(DEFAULT_WEAVIATE_PORT))
    weaviate_url = f"http://localhost:{weaviate_port}"

    # Detect adopt mode: install is reusing a Weaviate it didn't bring up.
    weaviate_decision = (decisions or {}).get("weaviate", {})
    adopt_mode = weaviate_decision.get("action") == ACTION_ADOPT

    # Per-project KG name. Resolution order:
    #   1. KG_COLLECTION env var (Claude Code workspace override)
    #   2. Adopt mode: derive from project basename (don't pollute with
    #      bare `KnowledgeGraph`)
    #   3. Otherwise: derive from PROJECT_ROOT basename. Pre-2026-05-01 this
    #      branch hardcoded bare `"KnowledgeGraph"` / `"Development"`, which
    #      collided with sibling installs and silently routed writes to
    #      collections shared across every vco install on the same Weaviate.
    env_kg = os.environ.get("KG_COLLECTION")
    if env_kg:
        kg_name = env_kg
    else:
        kg_name = _derive_project_kg_name(PROJECT_ROOT)

    # Per-project Development collection: same logic.
    env_dev = os.environ.get("DEVELOPMENT_COLLECTION")
    if env_dev:
        dev_name = env_dev
    else:
        dev_name = _derive_project_dev_name(PROJECT_ROOT)

    # Per-project Diagrams collection (Phase 1.5 — fix/a1-indexing-
    # pipeline 2026-05-25). Resolution mirrors KG / Dev: env var
    # overrides, else path-based derivation.
    env_diagrams = os.environ.get("DIAGRAMS_COLLECTION")
    if env_diagrams:
        diagrams_name = env_diagrams
    else:
        diagrams_name = _derive_project_diagrams_name(PROJECT_ROOT)

    # Cross-project shared KG. All vibecoded installs read from the same shared
    # collection name (default "VibeCodedOrchestrator_KnowledgeGraph" since
    # v0.2.23 B1 — was lowercase-c "VibecodedOrchestrator_KnowledgeGraph"
    # v0.2.12–v0.2.22, itself renamed from "VibeCodedTools_KnowledgeGraph"
    # pre-v0.2.12); the projects only differ in their per-project KG.
    # Bootstrapped once per Weaviate instance — re-runs are no-ops thanks
    # to the existing-class detection (which is case-insensitive since
    # v0.2.23 B1, so the lowercase-c class on existing installs is adopted
    # in place without recreate).
    shared_name = os.environ.get(
        "SHARED_KG_COLLECTION", "VibeCodedOrchestrator_KnowledgeGraph"
    ) or ""

    print(f"[7b/10] Checking Weaviate collections at {weaviate_url} "
          f"({'adopt' if adopt_mode else 'self-managed'} mode) ... ",
          flush=True)
    _log_install_event(
        "7b/10", "start",
        f"checking Weaviate collections ({'adopt' if adopt_mode else 'self-managed'})",
        data={"weaviate_url": weaviate_url, "adopt_mode": adopt_mode},
    )

    # 1. Read existing schema.
    try:
        resp = urllib.request.urlopen(f"{weaviate_url}/v1/schema", timeout=10)
        schema = json.loads(resp.read())
    except Exception as e:
        print(f"  WARN: couldn't read schema ({e}). Skipping bootstrap.")
        print("  MCP server will create collections lazily on first write.")
        _log_install_event(
            "7b/10", "warn",
            f"schema read failed: {type(e).__name__}",
            data={"error": str(e)[:200]},
        )
        return

    existing = {
        c.get("class") for c in schema.get("classes", [])
        if isinstance(c, dict) and c.get("class")
    }

    # v0.2.23 B1 (2026-05-21): case-insensitive adoption.
    #
    # Weaviate class names are case-SENSITIVE at the storage layer, so a
    # naive strict-equality check would treat the v0.2.12–v0.2.22
    # lowercase-c "VibecodedOrchestrator_KnowledgeGraph" class as MISSING
    # when the new canonical default is capital-C
    # "VibeCodedOrchestrator_KnowledgeGraph" — and would attempt to CREATE
    # the capital-C variant alongside it, leaving the user with two
    # divergent shared-KG classes (a regression of the same shape the
    # PR-26 rename introduced when it landed without case-insensitive
    # lookup).
    #
    # Strategy: build a `lower(name) -> actual_name` map of every
    # existing class, then look up each required collection by its
    # lowercased name. When a case-different sibling is found, rebind
    # the required name to the live class so:
    #   (a) we DON'T POST a new schema (idempotent w.r.t. casing),
    #   (b) downstream env-write paths see the on-disk casing (so the
    #       per-project binding row in launcher.db points at what
    #       actually exists, not what _we_ thought we'd create),
    #   (c) the `--update` self-heal step (`_self_heal_kg_bindings_on_update`
    #       below) auto-resolves any pre-flip binding rows.
    #
    # The lowercase-c → capital-C transition is the one this fix targets,
    # but the logic is generic: any future case-mismatch on any of the
    # three required collections (per-project KG, per-project Dev, shared
    # KG) will adopt the on-disk casing rather than recreate.
    existing_by_lower: dict[str, str] = {
        name.lower(): name for name in existing if name
    }

    def _find_existing_case_insensitive(name: str) -> str | None:
        """Return the actual-case existing class name when *name* matches
        case-insensitively, or None when no class exists by that lowered key.
        """
        return existing_by_lower.get(name.lower())

    # Resolve each required name to its on-disk casing (when present).
    # `case_rebinds` tracks names that changed casing during resolution so
    # we can announce them differently in adopt-mode (D21 prompt-phrasing).
    case_rebinds: list[tuple[str, str]] = []  # (requested, adopted)

    def _resolve_existing_casing(name: str) -> str:
        actual = _find_existing_case_insensitive(name)
        if actual is not None and actual != name:
            case_rebinds.append((name, actual))
            return actual
        return name

    kg_name = _resolve_existing_casing(kg_name)
    dev_name = _resolve_existing_casing(dev_name)
    diagrams_name = _resolve_existing_casing(diagrams_name)
    if shared_name:
        shared_name = _resolve_existing_casing(shared_name)

    # Note: we deliberately do NOT auto-adopt existing cross-project KGs
    # (e.g. `ClaudeKnowledgeGraph` from another install). The orchestrator
    # runs an orphan-prune sync cycle that would delete entries whose
    # `file_path` no longer exists in this install — silently destroying
    # the other install's KG. vco always gets its own collections;
    # existing collections from other projects are left untouched.

    # Propagate resolved names back to env so .env / settings.json pick
    # them up. This is the tri-write source of truth for downstream steps.
    # CRUCIAL: after case-rebind above, these env values carry the on-disk
    # casing so .env writes and binding rows match what Weaviate actually has.
    os.environ["KG_COLLECTION"] = kg_name
    os.environ["DEVELOPMENT_COLLECTION"] = dev_name
    os.environ["DIAGRAMS_COLLECTION"] = diagrams_name
    if shared_name:
        os.environ["SHARED_KG_COLLECTION"] = shared_name

    # 2. Required for THIS project install. Code-graph collections excluded
    #    on purpose — they're shared and created on demand.
    required: list[tuple[str, "callable"]] = [
        (kg_name, _kg_class_definition),
        (dev_name, _development_class_definition),
        # fix/a1-indexing-pipeline (2026-05-25): include the Diagrams
        # class in the self-install bootstrap so the orchestrator clone
        # has somewhere to write when the user starts saving .mmd /
        # .excalidraw files. Symmetric with project_init.bootstrap_collections.
        (diagrams_name, _diagrams_class_definition),
    ]
    # Shared cross-project KG. Same schema as the per-project KG (the MCP
    # server reads them with the same shape). Created once per Weaviate
    # instance — the existing-class check above means concurrent installs
    # don't double-create. Skip if shared_name resolved to an existing class
    # (we already adopted it above).
    if shared_name and shared_name != kg_name:
        required.append((shared_name, _kg_class_definition))

    # NOTE: do NOT skip our `_development` collection just because other
    # projects on the host have their own. Each project's docs live in
    # its own per-project `<Project>_development` namespace — they are
    # NOT shared like the cross-project KG. Creating ours is required
    # for Step 7c to seed `docs/` content. Earlier code skipped it on
    # the false assumption that one Development class served all
    # projects, which left vco's docs unseeded (Step 7c then exited 1).

    # `existing` is the schema-snapshot set; after case-rebind every
    # `required` name uses the on-disk casing so strict equality below
    # still works (the rebind happens BEFORE this comparison).
    missing = [(n, b) for (n, b) in required if n not in existing]
    skipped_existing = [n for (n, _) in required if n in existing]
    if not missing:
        if case_rebinds:
            print(f"  All collections present (case-adopted "
                  f"{len(case_rebinds)} class(es): "
                  f"{', '.join(f'{r}→{a}' for r, a in case_rebinds)}).")
        else:
            print(f"  All collections present (reusing {len(required)} shared classes).")
        _log_install_event(
            "7b/10", "ok",
            "all required collections already present",
            data={"existing": skipped_existing,
                  "kg": kg_name, "dev": dev_name, "shared": shared_name,
                  "case_rebinds": [
                      {"requested": r, "adopted": a} for r, a in case_rebinds
                  ]},
        )
        return

    # In adopt mode, announce what we're about to do and confirm. With
    # --yes / non-TTY we proceed non-interactively (the user already
    # consented to adoption upstream).
    if adopt_mode:
        print(f"  Existing classes ({len(existing)}): "
              f"{', '.join(sorted(list(existing))[:6])}"
              + (" ..." if len(existing) > 6 else ""))
        if skipped_existing:
            # Split skipped into pure-case-adopted (case-rebind sibling
            # was found) and exact-match (already present, unchanged).
            # The case-adopted ones get the more informative "ADOPT
            # (case-different)" phrasing.
            rebind_targets = {a for _, a in case_rebinds}
            adopted_case_different = [
                n for n in skipped_existing if n in rebind_targets
            ]
            adopted_exact = [
                n for n in skipped_existing if n not in rebind_targets
            ]
            if adopted_exact:
                print(f"  Will SKIP (already present): "
                      f"{', '.join(adopted_exact)}")
            if adopted_case_different:
                # For each case-rebind, find the original requested name
                # so the user sees what casing we asked for vs what's
                # on disk.
                pairs = [(req, adp) for req, adp in case_rebinds
                         if adp in adopted_case_different]
                pair_strs = [
                    f"`{adp}` (requested `{req}`)" for req, adp in pairs
                ]
                print(f"  Will ADOPT (existing case-different class): "
                      f"{', '.join(pair_strs)}")
        if missing:
            print(f"  Will CREATE: "
                  f"{', '.join(n for (n, _) in missing)}"
                  + (" (no case-variant found)"
                     if not case_rebinds and not skipped_existing else ""))
        interactive = (
            args is not None
            and not getattr(args, "yes", False)
            and not getattr(args, "quiet", False)
            and sys.stdin.isatty()
        )
        if interactive:
            try:
                ans = input("  Proceed with creating these classes? "
                            "[Y/n]: ").strip().lower()
            except (EOFError, KeyboardInterrupt):
                ans = ""
            if ans in ("n", "no"):
                print("  → user declined; skipping collection creation.")
                print("    (MCP server will create lazily on first write.)")
                _log_install_event(
                    "7b/10", "skip",
                    "user declined collection creation in adopt mode",
                )
                return

    # 3. POST each missing class definition.
    created: list[str] = []
    failed: list[tuple[str, str]] = []
    for name, builder in missing:
        body = json.dumps(builder(name)).encode()
        req = urllib.request.Request(
            f"{weaviate_url}/v1/schema",
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            urllib.request.urlopen(req, timeout=15)
            created.append(name)
        except urllib.error.HTTPError as e:
            err_body = e.read().decode("utf-8", errors="replace")[:200]
            # 422 with "already exists" is benign on race with another install.
            if e.code == 422 and "already exists" in err_body.lower():
                created.append(f"{name} (already)")
            else:
                failed.append((name, f"HTTP {e.code}: {err_body}"))
        except Exception as e:
            failed.append((name, str(e)))

    for c in created:
        print(f"  + created collection {c}")
    for n, err in failed:
        print(f"  ! failed to create {n}: {err}")
    if not failed:
        print("  OK")
        _log_install_event(
            "7b/10", "ok",
            f"created {len(created)} collection(s)",
            data={"created": created, "skipped_existing": skipped_existing},
        )
    else:
        _log_install_event(
            "7b/10", "error",
            f"{len(failed)} collection(s) failed to create",
            data={"created": created,
                  "failed": [{"name": n, "error": e[:200]} for n, e in failed]},
        )

    # V0243-18: warn when the Diagrams collection was just created (or
    # already existed) but no .mmd / .excalidraw sources are present in
    # the project. Users won't get useful results from describe_excalidraw
    # or diagram-search skills until diagrams exist on disk.
    _warn_if_diagrams_empty(diagrams_name, weaviate_url)


def _warn_if_diagrams_empty(diagrams_name: str, weaviate_url: str) -> None:
    """V0243-18 — Emit an install-log warning when the Diagrams collection
    has been bootstrapped but contains 0 rows and no .mmd / .excalidraw
    source files exist under ``.claude/diagrams/``.

    Skills like ``describe_excalidraw`` and diagram-search will return
    nothing until diagrams are created. The warning surfaces this so the
    user understands why the feature appears "empty" on a fresh install.

    Soft-fail throughout: transport errors, missing collection, or a
    Weaviate count-query failure are all treated as "unknown" and the
    warning is suppressed (we don't want false positives).

    Idempotent: emits only a log line (no deferral entry — this is
    informational, not actionable in the same way as a schema drift).
    """
    if not diagrams_name:
        return

    # Count .mmd + .excalidraw files under .claude/diagrams/.
    diagrams_dir = PROJECT_ROOT / ".claude" / "diagrams"
    source_count = 0
    if diagrams_dir.is_dir():
        for ext in ("*.mmd", "*.excalidraw"):
            source_count += len(list(diagrams_dir.rglob(ext)))

    if source_count > 0:
        # Sources exist — collection will be populated; no warning needed.
        _log_install_event(
            "7b/10", "info",
            f"diagrams_empty_check: {source_count} source file(s) found under "
            f".claude/diagrams/ — no empty-collection warning",
            data={"diagrams_collection": diagrams_name,
                  "source_count": source_count},
        )
        return

    # No sources. Try to get the Weaviate object count to distinguish
    # "just created / genuinely empty" from "creation failed" (failed →
    # count unknown → skip warning).
    from vco_lib.project_init import _http_count_objects
    count = _http_count_objects(diagrams_name, weaviate_url=weaviate_url)

    if count is None:
        # Unknown — Weaviate unreachable or collection absent; skip.
        return

    if count > 0:
        # Has objects but no on-disk sources (e.g. reinstall after manual
        # diagram creation). Not a problem — no warning.
        return

    # count == 0 AND no on-disk sources → user hasn't created diagrams yet.
    print(
        f"  WARN [7b/10] Diagrams collection `{diagrams_name}` is empty: "
        f"no .mmd / .excalidraw sources found under .claude/diagrams/. "
        f"Skills like describe_excalidraw will return nothing until you "
        f"save diagrams there (via the mermaid or excalidraw MCP tools)."
    )
    _log_install_event(
        "7b/10", "warn",
        f"Diagrams collection empty: no .mmd sources found",
        data={"diagrams_collection": diagrams_name,
              "source_count": 0,
              "weaviate_count": 0},
    )


# ---------------------------------------------------------------------------
# Step 7c: Seed Weaviate with bundled knowledge/ + docs/
# ---------------------------------------------------------------------------
#
# Without this step, a fresh install leaves the Weaviate collections empty
# and `hybrid_search` returns nothing until the user manually runs
# `kg-sync --all`. That's exactly the friction-y workaround that
# undermines the orchestrator's "search just works" promise. Seed at
# install time so it's invisible to adopters.
#
# Soft-fail policy: if Weaviate or Ollama isn't yet reachable (timing
# race on first-boot pulls), print a clear hint and continue. The
# install itself succeeds; the user can re-run seeding later via
#   .claude/scripts/kg-sync --all       (handles knowledge/ + docs/)
#
# The script is idempotent so re-runs are safe.

# Moved to vco_lib.project_init in PR 2 — kept as shim for existing callers;
# will be removed in PR 9 (cleanup).
_detect_kg_schema_drift = _project_init._detect_kg_schema_drift


def _maybe_prompt_rebuild_collections(
    args: argparse.Namespace,
    deferral_report: "DeferralReport | None" = None,
) -> bool:
    """During --update, detect schema drift and prompt the user.

    When *deferral_report* is provided, a ``schema_drift_rebuild_required``
    entry is added to it whenever the rebuild is deferred (non-interactive
    shell without ``--yes``, or ``--skip-rebuild-prompt``).

    Returns True iff the rebuild should run. Exits silently with False
    on:
      - install (not update) mode — schema is fresh by definition
      - --skip-rebuild-prompt — explicit defer
      - --rebuild-collections — explicit opt-in (returns True directly)
      - non-interactive shell with no --yes — fail safe; no destructive
        action without confirmation
    """
    if not args.update:
        return False
    if args.rebuild_collections:
        # Explicit opt-in. No prompt needed.
        return True
    if args.skip_rebuild_prompt:
        return False

    # Detect drift on the running KG collection.
    weaviate_url = os.environ.get("WEAVIATE_URL", f"http://localhost:{DEFAULT_WEAVIATE_PORT}")
    kg_collection = os.environ.get("KG_COLLECTION", "")
    if not kg_collection:
        # No KG collection configured — first install probably; let
        # _ensure_collections + _seed_weaviate handle it.
        return False

    drift, missing = _detect_kg_schema_drift(weaviate_url, kg_collection)
    if not drift:
        return False

    print()
    print("=" * 70)
    print("SCHEMA REBUILD REQUIRED")
    print("=" * 70)
    print()
    print(f"The running KG collection ({kg_collection}) is on an older schema:")
    for feat in missing:
        print(f"  - missing: {feat}")
    print()
    print("Today's code requires these invariants. Weaviate <=1.30 doesn't")
    print("allow adding them via Reconfigure -- but most cases can be fixed")
    print("by COPYING with vectors (no Ollama re-embed). PR 3 smart migrate")
    print("will pick: noop / patch_props / copy-with-vectors / rebuild per")
    print("collection.")
    print()
    print("What gets touched:")
    print("  + Weaviate collections (rebuilt with copy-with-vectors when possible)")
    print("  - Your .md source files in knowledge/ and docs/  (untouched)")
    print("  - .env / .vscode/settings.json / .claude/settings.json (untouched)")
    print("  - The launcher's project bindings (untouched)")
    print()
    print("Estimated time: ~30-60s for copy path (vs 3-5min for legacy rebuild).")
    print("Pass --force-rebuild to bypass smart path and drop+re-embed instead.")
    print()

    def _emit_drift_deferral(missing_feats: list) -> None:
        """Emit a deferral entry for schema drift when deferral_report given."""
        if deferral_report is None:
            return
        missing_str = ", ".join(missing_feats) if missing_feats else "unknown"
        deferral_report.add_entry(
            DeferralEntry(
                condition_id="schema_drift_rebuild_required",
                title="Schema rebuild required",
                detected=(
                    f"KG_COLLECTION `{kg_collection}` schema is on an older "
                    f"version. Missing: {missing_str}."
                ),
                why_deferred=(
                    "Schema rebuild touches Weaviate state -- non-interactive "
                    "shells without --yes defer to avoid silent data churn."
                ),
                command_to_apply="python install.py --update --rebuild-collections",
                severity="warning",
                # HIGH-3 fix (2026-05-01): kg_node_refs now points at the
                # actual schema-port research report. Path is relative to the
                # claude-orchestrator project root (the meta-project that owns
                # research reports), not VCO. Cross-repo reference is intentional.
                kg_node_refs=[
                    ".claude/context/weaviate-schema-port-research-2026-05-01.md",
                ],
            )
        )

    # Non-interactive flow: respect --yes; otherwise refuse to nuke data.
    if not sys.stdin.isatty():
        if getattr(args, "yes", False):
            print("(non-interactive --yes: proceeding with rebuild)")
            return True
        print("Non-interactive shell + no --yes -- DEFERRING rebuild.")
        print("DEFERRED -- re-run with `install.py --update --rebuild-collections` to apply.")
        print("Note: search may misbehave until rebuild completes.")
        _emit_drift_deferral(list(missing))
        return False

    answer = input("Proceed with rebuild? [y/N]: ").strip().lower()
    if answer not in ("y", "yes"):
        _emit_drift_deferral(list(missing))
        return False
    return True


# Moved to vco_lib.project_init in PR 2 — kept as shim for existing callers;
# will be removed in PR 9 (cleanup). PR 3 will replace the underlying
# implementation with `migrate_collections` (smart copy/patch/rebuild
# dispatch) but keep this entry-point name for back-compat.
def _rebuild_collections(args: argparse.Namespace) -> None:
    """Shim — delegates to vco_lib.project_init.rebuild_collections.

    Passes the install.py-local `_log_install_event` so forensic logs
    continue to land in the same JSONL stream.
    """
    _project_init.rebuild_collections(args, log_event=_log_install_event)


def _is_orchestrator_root_install() -> bool:
    """Return True iff PROJECT_ROOT is an orchestrator clone (not a per-project install).

    Detection: PROJECT_ROOT contains ALL THREE of:
      - vct-module.json  (orchestrator identity marker)
      - install.py       (orchestrator entry-point)
      - vco_lib/         (orchestrator library package)

    Per-project installs have `.vco-manifest.json` and no install.py.
    Orchestrator self-installs have all three markers above.  Never raises.
    """
    return (
        (PROJECT_ROOT / "vct-module.json").is_file()
        and (PROJECT_ROOT / "install.py").is_file()
        and (PROJECT_ROOT / "vco_lib").is_dir()
    )


def _check_dual_clone() -> Optional[tuple]:
    """v0.2.44 V44-G2: detect dual-clone hazard.

    Returns ``(registered_folder_path, current_project_root)`` tuple if
    ``launcher.db``'s orchestrator-root ``project_id`` points at a DIFFERENT
    folder than ``PROJECT_ROOT``. Returns ``None`` when there's no conflict
    or when the DB is unavailable.

    Background: ``_is_orchestrator_root_install()`` returns True from any
    on-disk clone that has the three file markers (vct-module.json,
    install.py, vco_lib/). The DB row ``projects.host='orchestrator_root'``
    is the single authoritative pointer to which clone is "the" orchestrator
    root for this user. If a user accidentally has two clones on disk and
    runs install.py from the WRONG one, the install would rebind the OTHER
    project's bindings to this clone's identity — silent cross-clone state
    corruption.

    This helper surfaces the deviation so install.py can WARN before
    proceeding. The install is not blocked (per user directive
    2026-06-01: "warn but proceed; user is expected to have one VCO root").

    v0.2.44 V44-I: skip the dual-clone check when the launcher.db is
    owned by a different uid than the current process (POSIX) — common
    in sudo / docker exec / Codespaces scenarios where ~/.vct/ resolves
    to a homedir we don't own. Avoids a confusing WARN that points at
    a folder the user has never seen. On Windows, use os.access(db_path,
    os.W_OK) as a write-access proxy for the uid check.
    """
    try:
        from vco_lib.launcher_db_reader import (
            get_orchestrator_root_project_id,
            _discover_db_path,
        )
        pid = get_orchestrator_root_project_id()
        if not pid:
            return None
        db_path = _discover_db_path()
        if not db_path:
            return None

        # v0.2.44 V44-I: uid ownership check BEFORE reading the DB.
        # If the DB file isn't ours, this isn't the launcher.db we
        # should be reconciling against — silently return None rather
        # than emitting a spurious dual-clone WARN.
        try:
            if sys.platform != "win32":
                if db_path.stat().st_uid != os.getuid():
                    return None  # not our launcher.db
            else:
                # Windows: best-effort write-access check as a uid proxy.
                if not os.access(str(db_path), os.W_OK):
                    return None
        except Exception:
            # uid check is best-effort; on failure fall through to the
            # normal read path rather than incorrectly suppressing the
            # warning.
            pass

        import sqlite3
        try:
            conn = sqlite3.connect(
                f"file:{db_path}?mode=ro", uri=True, timeout=5.0
            )
            try:
                row = conn.execute(
                    "SELECT folder_path FROM projects WHERE id = ? LIMIT 1",
                    (pid,),
                ).fetchone()
                if not row:
                    return None
                registered = str(row[0])
                current = str(PROJECT_ROOT.resolve())
                # Resolve registered too — handle symlinks consistently. If
                # the registered path no longer exists on disk, fall back
                # to the raw value (comparison still triggers the warning).
                try:
                    registered_resolved = str(Path(registered).resolve())
                except Exception:
                    registered_resolved = registered
                if registered_resolved != current:
                    return (registered, current)
                return None
            finally:
                conn.close()
        except Exception:
            return None
    except Exception:
        return None


def _rebind_orchestrator_root_to_canonical(canonical: str) -> list[str]:
    """v0.2.44 V44-A: rebind orchestrator-root pointers to canonical KG name.

    Updates (all soft-fail; collected errors returned as list):
      1. project_kg_bindings rows (role='primary' AND role='shared') for the
         orchestrator-root project_id. Uses a writable sqlite3 connection
         to ~/.vct/launcher.db (env override: VCT_LAUNCHER_DB_PATH). The
         launcher.db is the SOURCE OF TRUTH for canonical env values per
         the Phase 0.B config-projection contract; this UPDATE is the
         authoritative state change.
      2. Env-surface projection (.claude/settings.json + .claude/env)
         routed through ``vco_lib.config_projection.apply_project_env``
         — the SINGLE legal writer of those surfaces per the Phase 0.B
         contract. Bundle is built via ``project_env_from_db(pid)`` so
         the env files pick up the canonical name we just UPDATEd into
         the bindings plus all other canonical keys derived from the DB.

    v0.2.44 V44-E: env-surface writes were previously direct
    ``.write_text`` calls on settings.json and ``.claude/env``, which
    violated ``tests/test_config_projection_single_writer``. Refactored
    to delegate to ``apply_project_env`` (the canonical single writer).
    The DB-unreachable branch is now best-effort — without the launcher
    DB we can't safely build a full bundle (the deep-merge contract would
    DELETE canonical keys not present in a minimal bundle), so we soft-
    fail and rely on the launcher's first-boot env-refresh to reconcile.

    Returns empty list on full success, otherwise list of error strings.
    Never raises — every operation is wrapped.
    """
    errors: list[str] = []
    # v0.2.44 V44-H/H5: dual-clone short-circuit. When _seed_weaviate
    # detected that launcher.db's orchestrator_root project_id points at
    # a DIFFERENT folder than PROJECT_ROOT, running the rebind UPDATEs
    # would corrupt the registered clone's bindings (the launcher would
    # then point at the wrong on-disk root). Skip both the DB UPDATE and
    # the env projection here. The "(skipped — ...)" tail is recognized
    # by V44-F's seed_errors deferral discriminator so this does NOT
    # escalate to a "warn" audit-log entry (the warn already fired
    # at the dual-clone detection site via V44-H/H6).
    #
    # v0.2.44 V44-I: read-and-reset the module flag so it doesn't leak
    # across _seed_weaviate invocations within the same process (pytest
    # tests share the imported install module; an earlier test that set
    # the flag would otherwise mis-trigger the short-circuit in a later
    # test that exercises a legitimate rebind).
    global _DUAL_CLONE_DETECTED_THIS_RUN
    _dual_clone_was_set = _DUAL_CLONE_DETECTED_THIS_RUN
    _DUAL_CLONE_DETECTED_THIS_RUN = False
    if _dual_clone_was_set:
        errors.append(
            "dual-clone detected: skipping rebind to avoid corrupting "
            "registered clone's bindings (skipped — re-run install.py from "
            "the registered folder to commit)"
        )
        return errors

    # v0.2.44 V44-I: acquire the cross-OS advisory lock around the
    # install-state mutation block. Both the launcher.db UPDATE below
    # AND the apply_project_env() call (settings.json + .claude/env)
    # are mutating shared state — without the lock, two install.py
    # processes can interleave writes across the two surfaces and
    # produce a split-brain. Soft-fails to WARNING if the lock can't
    # be acquired; never blocks.
    with _install_advisory_lock(timeout_seconds=60.0):
        return _rebind_orchestrator_root_to_canonical_locked(canonical, errors)


def _rebind_orchestrator_root_to_canonical_locked(
    canonical: str, errors: list[str]
) -> list[str]:
    """v0.2.44 V44-I: the actual rebind work, called under the advisory
    lock from _rebind_orchestrator_root_to_canonical. Split out so the
    lock scope is a single `with` block at the call site rather than
    an indented body in the original function (keeps the diff small
    and the surrounding docstring + dual-clone guard intact).
    """
    # 1. launcher.db rebind — the authoritative state change. NOT an env
    #    surface, so not in the Phase 0.B single-writer contract's scope.
    pid: str | None = None
    db_path: Path | None = None
    try:
        from vco_lib.launcher_db_reader import (
            get_orchestrator_root_project_id, _discover_db_path,
        )
        pid = get_orchestrator_root_project_id()
        db_path = _discover_db_path()
        if pid and db_path:
            import sqlite3
            try:
                conn = sqlite3.connect(str(db_path), timeout=5.0)
                try:
                    import time
                    now_ms = int(time.time() * 1000)
                    cur = conn.cursor()
                    # X-1 (v0.2.73): route the primary+shared rebind through
                    # the single-writer home so this file holds no inline
                    # project_kg_bindings mutation SQL.
                    from vco_lib.kg_binding_heal import (
                        rebind_orchestrator_root_bindings,
                    )
                    rebind_orchestrator_root_bindings(
                        cur, project_id=pid, canonical=canonical, now_ms=now_ms,
                    )
                    conn.commit()
                    print(f"    → launcher.db: rebound primary+shared bindings → {canonical}")
                finally:
                    conn.close()
            except Exception as e:
                errors.append(f"launcher.db UPDATE failed: {e}")
        elif not pid:
            errors.append("launcher.db: no orchestrator-root project row found (skipped)")
        elif not db_path:
            errors.append("launcher.db: file not found (skipped)")
    except Exception as e:
        errors.append(f"launcher_db_reader import/use failed: {e}")

    # 2. Env-surface projection — routed through the single legal writer.
    #    We re-resolve project_id via the folder-based resolver too, so
    #    if get_orchestrator_root_project_id() returned None (e.g. host
    #    column wasn't populated), the folder-match path may still succeed.
    try:
        from vco_lib.config_projection import (
            apply_project_env,
            project_env_from_db,
            DbUnreachable,
            ProjectNotFound,
        )
        # Resolve project_id for the env projection — prefer the host-tag
        # lookup (already done above as `pid`); fall back to folder match
        # when the host column is empty.
        proj_id_for_env = pid or _resolve_project_id_by_folder(PROJECT_ROOT)
        if proj_id_for_env is None:
            errors.append(
                "config_projection: orchestrator-root project_id not "
                "resolvable; env files will be reconciled on next launcher boot"
            )
        else:
            try:
                bundle = project_env_from_db(proj_id_for_env)
                report = apply_project_env(bundle)
                print(
                    "    → env surfaces (settings.json + .claude/env): "
                    f"KG/SHARED = {canonical} "
                    f"(via apply_project_env, {sum(len(v) for v in report.values())} keys total)"
                )
            except DbUnreachable as e:
                # Launcher DB went away between the rebind UPDATE above and
                # the bundle build here — extremely rare race. Soft-fail;
                # the launcher's next boot will reconcile env surfaces.
                errors.append(
                    f"config_projection: launcher.db unreachable for env "
                    f"projection ({e}); env files will be reconciled on next "
                    f"launcher boot"
                )
            except ProjectNotFound as e:
                errors.append(
                    f"config_projection: project_id {proj_id_for_env} not "
                    f"found in launcher.db ({e})"
                )
    except Exception as e:
        errors.append(f"config_projection apply failed: {e}")

    return errors


def _seed_weaviate_shared_kg_only(
    *,
    args: "argparse.Namespace",
    venv_py: "Path",
    sync_kg: "Path",
    weaviate_url: str,
    current_shared_kg: str,
    current_kg_collection: str = "",
    orphan_candidate_kg: "Optional[str]" = None,
    rebind_deferred: bool = False,
    rebind_deferred_rationale: str = "",
) -> "list[str]":
    """Run the shared-KG seed step only (no per-project KG sync).

    v0.2.42 CI-10: extracted from ``_seed_weaviate`` so the diff-gate
    skip path can still run the shared KG seed without the full per-project
    sync. Returns a list of error strings (empty = success).

    v0.2.43 V0243-0: on orchestrator-root installs where
    ``current_shared_kg == current_kg_collection`` (the per-project KG IS
    the shared KG — typical when both env vars point at the same collection),
    skip the shared seed to avoid a redundant double-sync and record the
    skip in ``app_state.last_installed_shared_kg_collection``.
    """
    seed_errors: list[str] = []
    shared_write_disabled = (
        os.environ.get("SHARED_KG_WRITE_DISABLED")
        or os.environ.get("SHARED_KG_OPT_OUT", "")
    ).lower() in ("1", "true", "yes")
    if shared_write_disabled:
        print("  → shared KG seed: skipped (SHARED_KG_WRITE_DISABLED=true)")
        return seed_errors
    if not current_shared_kg:
        print("  → shared KG seed: skipped (SHARED_KG_COLLECTION empty)")
        return seed_errors

    # v0.2.44 V44-A: orchestrator-root adopt-and-route.
    #
    # When this is the orchestrator clone itself, the per-project KG and the
    # shared KG are the same logical collection. Names can legitimately differ
    # due to legacy migrations (e.g. the maintainer install's
    # `VCODev_KnowledgeGraph` survives from an older migration while
    # SHARED_KG_COLLECTION points at
    # the canonical VibeCodedOrchestrator_KnowledgeGraph).
    #
    # Strategy: pick SHARED_KG_COLLECTION as canonical (predictable, matches
    # public-shipping convention). Rebind both project_kg_bindings rows
    # (primary + shared) and both env keys (KG_COLLECTION + SHARED_KG_COLLECTION)
    # to that canonical name. Skip the shared-seed sync step — one collection
    # serves both roles.
    #
    # No re-embedding. No re-syncing. No collection renaming. Just rebind
    # pointers + update app_state.
    if _is_orchestrator_root_install():
        canonical = current_shared_kg or current_kg_collection
        if not canonical:
            print("  → shared KG seed: skipped (orchestrator-root, "
                  "no KG_COLLECTION or SHARED_KG_COLLECTION set)")
            return seed_errors

        # v0.2.44 V44-H/H2: orphan-detection must compare the PRE-resolution
        # KG name (the one this install replaced) against canonical, NOT the
        # post-V44-G1 reassigned current_kg_collection. Otherwise once G1
        # picks the same value for both env and resolved, the orphan check
        # always sees canonical == current_kg_collection and the notice is
        # silently masked (Reader-4 FN1 against the maintainer install's actual state).
        orphan_kg = orphan_candidate_kg or current_kg_collection

        # Diagnostic: report row counts on both physical collections.
        try:
            primary_count = _count_weaviate_class_objects(
                weaviate_url, orphan_kg
            ) if orphan_kg else 0
        except Exception:
            primary_count = -1
        try:
            shared_count = _count_weaviate_class_objects(
                weaviate_url, current_shared_kg
            ) if current_shared_kg else 0
        except Exception:
            shared_count = -1
        print(
            f"  → orchestrator-root adopt-and-route: "
            f"primary={orphan_kg or '(unset)'}={primary_count} rows, "
            f"shared={current_shared_kg or '(unset)'}={shared_count} rows"
        )
        # v0.2.44 V44-H/H8: removed misleading "(SHARED_KG_COLLECTION wins)"
        # tail. The V44-G1 hybrid-SoT rationale line printed upstream already
        # names the actual decision source — appending an unconditional
        # "SHARED wins" was a lie when G1 picked via Weaviate-existence or
        # the first-install heuristic.
        print(f"  → canonical = {canonical}")

        # v0.2.44 fix-now-3 (+ V44-H/H2): notify user about orphan collection
        # retention. When the canonical-loser collection still has rows, those
        # rows survive in Weaviate but no longer have a binding. User may
        # want to clean up. Compares against orphan_kg (pre-resolution name).
        if (
            orphan_kg
            and canonical != orphan_kg
            and isinstance(primary_count, int) and primary_count > 0
        ):
            print(
                f"  ⚠ Orphan collection '{orphan_kg}' retains "
                f"{primary_count} rows after rebind. The orchestrator-root install "
                f"now uses '{canonical}'. To free up Weaviate storage, drop the "
                f"orphan collection manually (REST: DELETE /v1/schema/"
                f"{orphan_kg}) or via the launcher's Weaviate panel."
            )

        # v0.2.44 V44-H/H1: when the hybrid resolver returned a deferred
        # rationale (Weaviate unreachable for ALL candidates), DO NOT touch
        # launcher.db or env surfaces — the resolver had no authoritative
        # signal and would clobber last-known-good bindings with possibly-
        # stale env values. Print the deferral and return without
        # rebinding or writing app_state.
        if rebind_deferred:
            print(f"  ⏸ Rebind deferred: {rebind_deferred_rationale}")
            print("  → shared KG seed: skipped (orchestrator-root, "
                  "canonical collection serves both roles)")
            return seed_errors

        # Rebind launcher.db (if available) and both env keys to canonical.
        rebind_errors = _rebind_orchestrator_root_to_canonical(canonical)
        if rebind_errors:
            for e in rebind_errors:
                print(f"    ! rebind: {e}")
            # v0.2.44 fix-now-2: propagate the "definitely broken" tier so
            # the audit-log "warn" entry fires on real DB write failures or
            # import errors. Two error classes stay non-propagated and
            # preserve V44-A/V44-E's soft-fail discipline:
            #   - Deferrals: "(skipped)", "reconciled on next launcher boot"
            #     — these are legitimate first-boot reconciliation signals.
            #   - "config_projection apply failed:" — V44-E documents env
            #     projection as best-effort; failures here also defer to
            #     the launcher's env-refresh, so they stay print-only.
            for e in rebind_errors:
                is_deferral = (
                    "(skipped)" in e
                    or "(skipped —" in e  # V44-H/H5 dual-clone short-circuit
                    or "reconciled on next launcher boot" in e
                    or "config_projection apply failed" in e
                )
                if not is_deferral:
                    seed_errors.append(e)

        _write_app_state_key(_APP_STATE_KEY_LAST_KG_COLLECTION, canonical)
        _write_app_state_key(_APP_STATE_KEY_LAST_SHARED_KG_COLLECTION, canonical)

        print("  → shared KG seed: skipped (orchestrator-root, "
              "canonical collection serves both roles)")
        return seed_errors
    if not sync_kg.exists():
        return seed_errors
    print(f"  → knowledge/ → {current_shared_kg} (shared) ...", flush=True)
    # v0.2.52 V52-AJ: same env-threading rationale as the per-project KG
    # seed above. Build the base env via _subprocess_env_with_embedding()
    # (threads ACTIVE_EMBEDDING + EMBEDDING_MODEL from env-or-launcher.db),
    # then overlay the shared-KG-specific KG_COLLECTION + KG_BASE_DIR.
    seed_env = _subprocess_env_with_embedding()
    seed_env["KG_COLLECTION"] = current_shared_kg
    seed_env["KG_BASE_DIR"] = str(PROJECT_ROOT)
    # v0.2.69 FIX 3: no per-process timeout here. A legitimate slow re-embed
    # (e.g. arctic on a cold CPU over the full shared KG) can run well past
    # any wall-clock cap we'd pick, and killing it mid-seed strands the user
    # exactly where they don't want to be. The right granularity is a
    # per-embed-REQUEST timeout, which now lives inside EmbeddingService's
    # adapters (VCT_EMBED_REQUEST_TIMEOUT_SECS) — a genuinely-wedged embedder
    # fails fast per chunk; a slow-but-progressing one runs to completion.
    try:
        subprocess.run(
            [str(venv_py), str(sync_kg), "--all"],
            check=True,
            cwd=str(PROJECT_ROOT),
            env=seed_env,
        )
    except subprocess.CalledProcessError as e:
        print(f"    ! shared KG seed exited {e.returncode} — re-run later with "
              f"`KG_COLLECTION={current_shared_kg} kg-sync --all`")
        seed_errors.append(f"shared-kg exit {e.returncode}")
    except FileNotFoundError as e:
        print(f"    ! shared KG seed failed: {e}")
        seed_errors.append(f"shared-kg FileNotFound: {e}")
    return seed_errors


def _resolve_orchestrator_root_canonical(
    env_kg: str,
    env_shared: str,
    db_primary: "Optional[str]",
    db_shared: "Optional[str]",
    weaviate_url: str,
) -> "tuple[str, str, str]":
    """v0.2.44 V44-G1: hybrid env-vs-DB conflict resolution.

    User directive (2026-06-01): when env and DB disagree on the canonical
    KG collection name for orchestrator-root, resolve via this priority chain:

      1. CHECK WEAVIATE first. If exactly ONE candidate collection actually
         exists, pick it (preferring an extant-with-data candidate over an
         extant-empty one when only one of each kind exists).
      2. If MULTIPLE candidates exist (true tie), apply the first-install
         heuristic: env wins on fresh install (``app_state.last_installed_
         kg_collection`` unset), DB wins on subsequent update (key SET).
      3. If NEITHER candidate exists, env wins (bootstrap case — nothing
         in Weaviate to anchor on).

    Replaces V44-F's silent "env-wins / DB-wins via WARNING print" behavior
    with an explicit, observable decision logged via the returned rationale.

    Args:
        env_kg: KG_COLLECTION from process env (may be empty).
        env_shared: SHARED_KG_COLLECTION from process env (may be empty).
        db_primary: launcher.db primary binding for orchestrator-root (or None).
        db_shared: launcher.db shared binding for orchestrator-root (or None).
        weaviate_url: Weaviate base URL for existence checks.

    Returns:
        (canonical_kg, canonical_shared, rationale)
        rationale is a short human-readable string naming which branch fired.
        Suitable for direct ``print()`` into install logs.

        v0.2.44 V44-H: when ``rationale.startswith("deferred:")`` the caller
        MUST NOT trigger ``_rebind_orchestrator_root_to_canonical`` — the
        resolver was unable to obtain authoritative existence signals (e.g.
        Weaviate unreachable) and the returned values are the existing
        bindings unchanged. Rebinding on a deferred signal would clobber
        the last-known-good state with possibly-stale env values. See H1.
    """
    # v0.2.44 V44-H/H4: all-empty guard. When none of the four inputs are set
    # we have nothing to resolve — this is a true bootstrap before any env or
    # DB binding has been recorded. Returning empty strings here is correct
    # (downstream callers already handle the empty-collection case) but we
    # tag the rationale so observers can distinguish "bootstrap" from
    # "no-conflict-empty".
    if not (env_kg or env_shared or db_primary or db_shared):
        return "", "", "no canonical resolvable; bootstrap path"

    # No-conflict fast path: when env and DB agree (or DB has no value),
    # fill empties from DB and preserve env where set. This matches the
    # pre-V44-G1 V44-B "fill empties only" behavior.
    env_disagreement_kg = bool(db_primary and env_kg and db_primary != env_kg)
    env_disagreement_shared = bool(db_shared and env_shared and db_shared != env_shared)
    if not env_disagreement_kg and not env_disagreement_shared:
        out_kg = env_kg or (db_primary or "")
        out_shared = env_shared or (db_shared or "")
        return out_kg, out_shared, "no conflict (env wins when set, DB fills empties)"

    # Disagreement — apply hybrid algorithm.
    # Step 1: Weaviate existence check. Build the candidate set from all four
    # values (env_kg, env_shared, db_primary, db_shared), excluding empties.
    candidates = {env_kg, env_shared, db_primary or "", db_shared or ""} - {""}
    counts: "dict[str, Optional[int]]" = {}
    for c in candidates:
        try:
            n = _count_weaviate_class_objects(weaviate_url, c)
            # n is int (>=0) on success, None on error/nonexistent.
            counts[c] = n if isinstance(n, int) and n >= 0 else None
        except Exception:
            counts[c] = None  # treat as nonexistent on any error
    extant_with_data = [c for c, n in counts.items() if n is not None and n > 0]
    extant_any = [c for c, n in counts.items() if n is not None]
    # v0.2.44 V44-H/H1: distinguish "all unreachable" (every count is None,
    # i.e. Weaviate down or transient failure on every candidate) from
    # "all empty" (every count is 0, candidates exist but have no rows).
    # When unreachable, we have NO authoritative signal — rebinding would
    # gamble the last-known-good state on a transient outage. Return a
    # deferred rationale and prefer the DB-recorded names (last known good)
    # so the caller can short-circuit the rebind.
    all_unreachable = bool(counts) and all(c is None for c in counts.values())
    if all_unreachable and candidates:
        return (
            (db_primary or env_kg),
            (db_shared or env_shared),
            "deferred: Weaviate unreachable; preserving existing bindings",
        )

    if len(extant_with_data) == 1:
        winner = extant_with_data[0]
        return winner, winner, (
            f"weaviate (only '{winner}' has rows; counts={counts})"
        )
    if len(extant_any) == 1:
        winner = extant_any[0]
        return winner, winner, (
            f"weaviate (only '{winner}' exists; rowcount=0)"
        )
    if len(extant_any) == 0:
        # Neither exists in Weaviate (and we DID get reachable answers, so this
        # isn't a transient outage) → genuine bootstrap; env wins.
        return env_kg, env_shared, "env (no candidates exist in Weaviate yet)"

    # Step 2: multiple candidates exist (true tie). Apply first-install heuristic.
    try:
        last_kg = _read_app_state_key(_APP_STATE_KEY_LAST_KG_COLLECTION)
    except Exception:
        last_kg = None
    if not last_kg:
        return env_kg, env_shared, (
            "env (fresh install; app_state.last_installed_kg_collection unset)"
        )
    # Subsequent update → DB wins (bindings are authoritative once recorded).
    return (
        (db_primary or env_kg),
        (db_shared or env_shared),
        "db (subsequent update; bindings authoritative)",
    )


def _seed_weaviate(args: argparse.Namespace) -> None:
    """v0.2.44 V44-I: thin wrapper around :func:`_seed_weaviate_impl`
    that guarantees the ``_DUAL_CLONE_DETECTED_THIS_RUN`` module-level
    flag is reset to False after the call returns (even if the impl
    raises). The flag is intended to live for ONE _seed_weaviate
    invocation; without this wrapper, pytest tests sharing the imported
    install module would see leaked True values from earlier tests,
    causing legitimate rebind paths to short-circuit incorrectly.

    Production callers invoke _seed_weaviate once per process so the
    cleanup is a no-op in normal operation.
    """
    global _DUAL_CLONE_DETECTED_THIS_RUN
    try:
        _DUAL_CLONE_DETECTED_THIS_RUN = False
        return _seed_weaviate_impl(args)
    finally:
        _DUAL_CLONE_DETECTED_THIS_RUN = False


def _seed_weaviate_impl(args: argparse.Namespace) -> None:
    """Seed Weaviate with bundled knowledge/ + docs/.

    v0.2.42 CI-10: on ``--update`` runs (not fresh install), gate the sync
    on a per-file content-hash diff instead of unconditionally running
    ``sync_knowledge_graph.py --all``.  "Pay once, never again" — see
    v0.2.17 fast-path CHANGELOG entry and the v0.2.42 user-spec.

    Gate algorithm for ``--update``:
      a. Read ``app_state`` keys ``last_installed_active_embedding``,
         ``last_installed_kg_collection``, ``last_installed_shared_kg_collection``.
      b. If ANY differ from current env → full sync (model swap / collection
         rename detected; re-embed everything).
      c. Else compute on-disk ``content_hash`` per file in ``knowledge/``
         (using ``_content_signature_excluding_updated``, the same function
         ``sync_knowledge_graph.py`` uses). Batch-query Weaviate for stored
         ``content_hash`` per ``file_path``. Compute diff set.
         - Empty diff → SKIP sync entirely (all hashes match).
         - Non-empty diff → invoke ``sync_knowledge_graph.py`` passing just
           the diff list as positional args (NOT ``--all``).
      d. After successful sync, UPSERT the ``app_state`` keys with current
         values. Audit-log run stats: ``nodes_synced``, ``nodes_skipped``.

    On fresh install (no ``--update`` flag): full sync, no change.

    Replaces the old ``knowledge_md5 changed → re-run sync_knowledge_graph.py``
    approach (line ~873 comment in ``_compute_drift``) with per-file content-hash
    diff: instead of a single md5 of the whole tree we now compare per-object
    hashes already stored in Weaviate, avoiding the false-positive where a single
    file change would force re-embedding of the entire tree.
    """
    print("[7c/10] Seeding Weaviate with bundled knowledge/ + docs/ ... ", flush=True)
    _log_install_event("7c/10", "start", "seeding Weaviate")

    # Guard: if user passed --skip-seed, honor it (useful for CI / tests).
    if getattr(args, "skip_seed", False):
        print("  Skipped (--skip-seed).")
        _log_install_event("7c/10", "skip", "seed skipped via --skip-seed")
        return

    # We must use the venv's Python so weaviate-client + weaviate_mcp.chunking
    # import correctly. Step 4 creates the venv at PROJECT_ROOT/.venv (NOT
    # at claude_mcp_servers/.venv — that's a stale legacy path).
    if os.name == "nt":
        venv_py = PROJECT_ROOT / ".venv" / "Scripts" / "python.exe"
    else:
        venv_py = PROJECT_ROOT / ".venv" / "bin" / "python"
    if not venv_py.exists():
        # Legacy fallback: some older installs put the venv inside claude_mcp_servers/
        legacy = PROJECT_ROOT / "claude_mcp_servers" / ".venv" / (
            "Scripts/python.exe" if os.name == "nt" else "bin/python"
        )
        if legacy.exists():
            venv_py = legacy
        else:
            print(f"  ! venv python not found at {venv_py} — skipping seed (run Step 4 first)")
            _log_install_event(
                "7c/10", "error",
                "venv python missing — Step 4 must run first",
                data={"venv_py": str(venv_py)},
            )
            return

    scripts_dir = PROJECT_ROOT / ".claude" / "scripts"
    sync_kg = scripts_dir / "sync_knowledge_graph.py"

    # ── CI-10: content-hash diff gate for --update runs ───────────────────
    #
    # On fresh install (args.update is False): full sync unconditionally.
    # On --update: detect whether a full sync or a diff-only sync (or skip)
    # is needed. See function docstring for full algorithm.
    is_update = getattr(args, "update", False)
    _sync_all = True          # default: run --all (set False for diff path)
    _diff_files: "list[str]" = []  # set when doing a partial sync
    _nodes_skipped = 0
    _nodes_synced = 0

    # v0.2.52 V52-AJ: resolve active embedding via the same chain the
    # subprocess will use (env → launcher.db → "qwen3"). This guarantees
    # the CI-10 diff gate's "stored vs current" comparison uses the SAME
    # value that the subprocess EmbeddingService will resolve to —
    # otherwise install.py could write last_installed_active_embedding=arctic
    # while the subprocess silently embedded with qwen3, and the next
    # --update's diff gate would short-circuit on the wrong premise.
    current_active_embedding = _resolve_active_embedding_for_install() or "qwen3"
    current_kg_collection = os.environ.get("KG_COLLECTION", "") or ""
    current_shared_kg = os.environ.get("SHARED_KG_COLLECTION", "") or ""
    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )

    # v0.2.44 V44-G1: hybrid env-vs-DB SoT resolution (replaces V44-B fill-only
    # + V44-F disagreement-WARNING). Per user directive (2026-06-01): when env
    # and DB disagree, check Weaviate first (pick the collection that actually
    # exists), then fall back to "env wins on fresh install / DB wins on
    # subsequent update". See _resolve_orchestrator_root_canonical for the full
    # priority chain.
    try:
        from vco_lib.launcher_db_reader import get_orchestrator_root_bindings
        _db_primary, _db_shared = get_orchestrator_root_bindings()
    except Exception:
        _db_primary, _db_shared = (None, None)

    # v0.2.44 V44-G2: dual-clone WARNING. Fires when launcher.db's
    # orchestrator-root project_id points at a folder different from
    # PROJECT_ROOT. User directive 2026-06-01: warn but proceed; the
    # supported configuration is "one VCO root project per user".
    if _is_orchestrator_root_install():
        dual_clone = _check_dual_clone()
        if dual_clone is not None:
            registered, current = dual_clone
            print(
                f"  ⚠ DUAL-CLONE WARNING: this install ({current}) has all "
                f"orchestrator-root file markers, but launcher.db's "
                f"orchestrator_root project_id points at a DIFFERENT folder: "
                f"{registered}. The install will proceed but the rebind step "
                f"will be SKIPPED to avoid corrupting the registered clone's "
                f"bindings. To commit a rebind, re-run install.py from "
                f"{registered} instead, or update the launcher's project "
                f"registry to point at the current location."
            )
            # v0.2.44 V44-H/H5: signal to _rebind_orchestrator_root_to_canonical
            # that it must not run for this install — otherwise the rebind
            # UPDATEs would corrupt the OTHER registered clone's bindings.
            global _DUAL_CLONE_DETECTED_THIS_RUN
            _DUAL_CLONE_DETECTED_THIS_RUN = True
            # v0.2.44 V44-H/H6: dual-clone WARNING also lands in install.jsonl
            # as a "warn"-level audit entry so post-run audits can see it.
            _log_install_event(
                "7c/10", "warn", "dual-clone detected",
                data={"registered": registered, "current": current},
            )

    # v0.2.44 V44-H/H2: capture pre-resolution KG name BEFORE the G1
    # reassignment below. Used downstream by the orphan-collection notice
    # in _seed_weaviate_shared_kg_only so the warning fires against the
    # collection this install actually replaced (not against the
    # post-reassignment value, which would mask the notice).
    _pre_resolution_kg = current_kg_collection
    # v0.2.44 V44-H/H1: track whether the hybrid resolver punted on the
    # rebind decision (Weaviate unreachable). The caller below must honor
    # the deferral by skipping _rebind_orchestrator_root_to_canonical.
    _rebind_deferred = False
    _rebind_deferred_rationale = ""

    if _is_orchestrator_root_install():
        if _db_primary or _db_shared:
            resolved_kg, resolved_shared, rationale = (
                _resolve_orchestrator_root_canonical(
                    env_kg=current_kg_collection,
                    env_shared=current_shared_kg,
                    db_primary=_db_primary,
                    db_shared=_db_shared,
                    weaviate_url=weaviate_url,
                )
            )
            if rationale.startswith("deferred:"):
                _rebind_deferred = True
                _rebind_deferred_rationale = rationale
            if (
                resolved_kg != current_kg_collection
                or resolved_shared != current_shared_kg
            ):
                print(
                    f"  → hybrid SoT resolution: KG={resolved_kg!r}, "
                    f"SHARED={resolved_shared!r} ({rationale})"
                )
                current_kg_collection = resolved_kg
                current_shared_kg = resolved_shared
            else:
                print(f"  → hybrid SoT: no disagreement ({rationale})")
        else:
            print("  WARNING: orchestrator-root install but launcher.db unavailable; "
                  "falling back to env for KG collection resolution")

    if is_update and sync_kg.exists():
        stored_embedding = _read_app_state_key(_APP_STATE_KEY_LAST_ACTIVE_EMBEDDING)
        stored_kg = _read_app_state_key(_APP_STATE_KEY_LAST_KG_COLLECTION)
        stored_shared_kg = _read_app_state_key(_APP_STATE_KEY_LAST_SHARED_KG_COLLECTION)

        # Check for model-swap / collection-rename: if ANY key differs, fall
        # back to full sync (we cannot trust the stored hashes).
        context_changed = (
            stored_embedding != current_active_embedding
            or stored_kg != current_kg_collection
            or stored_shared_kg != current_shared_kg
        )

        if context_changed:
            # Full sync required — context changed since last run.
            reason = (
                f"embedding={stored_embedding!r}→{current_active_embedding!r}, "
                f"kg={stored_kg!r}→{current_kg_collection!r}, "
                f"shared_kg={stored_shared_kg!r}→{current_shared_kg!r}"
            )
            print(f"  CI-10: context changed ({reason}) → full sync")
            _log_install_event(
                "7c/10", "info",
                f"CI-10: full sync (context change: {reason})",
                data={"reason": "context_change"},
            )
            _sync_all = True
        elif not current_kg_collection:
            # No KG_COLLECTION configured — can't query Weaviate for diff.
            # Fall back to full sync to be safe.
            _sync_all = True
        else:
            # Context unchanged — attempt per-file content-hash diff.
            knowledge_root = PROJECT_ROOT / "knowledge"
            on_disk = _compute_on_disk_content_hashes(knowledge_root)
            stored_hashes = _batch_query_weaviate_content_hashes(
                current_kg_collection, weaviate_url,
            )

            # Build diff: files whose on-disk hash differs from stored
            # (or whose stored hash is missing / empty).
            diff_files: list[str] = []
            for file_path_str, disk_hash in on_disk.items():
                # Match stored hash by absolute path OR by file_path relative
                # forms. Weaviate stores file_path as written by sync_kg (may
                # be absolute or relative depending on KG_BASE_DIR).
                stored_hash = stored_hashes.get(file_path_str, "")
                if not stored_hash:
                    # Try relative path form as fallback.
                    try:
                        rel = str(Path(file_path_str).relative_to(PROJECT_ROOT))
                        stored_hash = stored_hashes.get(rel, "")
                    except ValueError:
                        pass
                if disk_hash != stored_hash:
                    diff_files.append(file_path_str)

            total_files = len(on_disk)
            _nodes_skipped = total_files - len(diff_files)

            if not diff_files:
                # All hashes match → skip sync entirely.
                print(
                    f"  CI-10: all {total_files} knowledge/ file(s) unchanged "
                    f"(content-hash diff empty) → skipping KG sync"
                )
                _log_install_event(
                    "7c/10", "skip",
                    f"CI-10: diff-only gate: all {total_files} file(s) match "
                    f"stored hashes → sync skipped",
                    data={"total": total_files, "changed": 0, "skipped": _nodes_skipped},
                )
                # Still update the app_state sync timestamp.
                _write_app_state_key(_APP_STATE_KEY_LAST_ACTIVE_EMBEDDING, current_active_embedding)
                _write_app_state_key(_APP_STATE_KEY_LAST_KG_COLLECTION, current_kg_collection)
                _write_app_state_key(_APP_STATE_KEY_LAST_SHARED_KG_COLLECTION, current_shared_kg)
                import datetime as _dt
                _write_app_state_key(
                    _APP_STATE_KEY_LAST_KG_SYNC_AT,
                    _dt.datetime.now(_dt.timezone.utc).isoformat(),
                )
                _write_app_state_key(
                    _APP_STATE_KEY_LAST_KG_SYNC_STATS,
                    json.dumps({"nodes_synced": 0, "nodes_skipped": _nodes_skipped}),
                )
                # Skip directly to shared KG section (no per-project sync).
                _seed_weaviate_shared_kg_only(
                    args=args,
                    venv_py=venv_py,
                    sync_kg=sync_kg,
                    weaviate_url=weaviate_url,
                    current_shared_kg=current_shared_kg,
                    current_kg_collection=current_kg_collection,
                    orphan_candidate_kg=_pre_resolution_kg,
                    rebind_deferred=_rebind_deferred,
                    rebind_deferred_rationale=_rebind_deferred_rationale,
                )
                _log_install_event("7c/10", "ok", "CI-10: diff-gate skip complete")
                return

            # Non-empty diff — sync only the changed files.
            _sync_all = False
            _diff_files = diff_files
            _nodes_synced = len(diff_files)
            print(
                f"  CI-10: {len(diff_files)}/{total_files} knowledge/ file(s) changed "
                f"→ partial sync"
            )
            _log_install_event(
                "7c/10", "info",
                f"CI-10: diff-only sync: {len(diff_files)}/{total_files} file(s)",
                data={"changed": len(diff_files), "skipped": _nodes_skipped},
            )

    seed_errors: list[str] = []

    # V0243-10: on the full-sync branch, record the on-disk file count as the
    # upper-bound nodes_synced BEFORE subprocess.run so the stat is captured
    # even on non-zero exit.  (Previously _nodes_synced was left at 0 for
    # full-sync runs, recording 0/0 in last_kg_sync_stats.)
    if _sync_all and current_kg_collection:
        _knowledge_root_for_count = PROJECT_ROOT / "knowledge"
        _full_sync_count = len(
            _compute_on_disk_content_hashes(_knowledge_root_for_count)
        )
        _nodes_synced = _full_sync_count

    # `sync_knowledge_graph.py` now handles both KG (knowledge/) and dev
    # docs (docs/) ingest paths — it routes by the file's location.
    # Old upload_docs.py was retired 2026-04-30 (audit cleanup); the
    # `--all` flag below seeds knowledge/ AND docs/ in one pass.
    #
    # CI-10 diff gate: when _sync_all=False, pass explicit file list
    # instead of --all (only syncs changed files).
    # SEG-1 (v0.2.73): track whether the sync subprocess actually EXECUTED
    # (regardless of exit code), as distinct from "never ran" (script missing
    # or failed to launch). The context-triple app_state persist below is gated
    # on this flag — NOT on `seed_errors` — because a run where the subprocess
    # ran and embedded 2589/2590 nodes DID (re)embed the collection against the
    # current context, even if one node failed. Gating the persist on
    # `seed_errors` meant a single transient node failure (e.g. one oversize
    # chunk → sync_knowledge_graph.py exits 1) left last_installed_active_embedding
    # at None forever, forcing a full ~2590-node re-embed on EVERY subsequent
    # --update (CI-10 "pay once" defeated). See the persist block below.
    sync_subprocess_ran = False
    if sync_kg.exists():
        if _sync_all:
            cmd_args = ["--all"]
            desc = "knowledge/ + docs/"
        else:
            cmd_args = _diff_files  # explicit list of changed files
            desc = f"{len(_diff_files)} changed file(s)"
        print(f"  → {desc} → KG + Development collections ...", flush=True)
        # v0.2.52 V52-AJ: thread ACTIVE_EMBEDDING + EMBEDDING_MODEL into the
        # subprocess env. Without this, install.py's bare os.environ.copy()
        # would mask the launcher's app_state[embedding.active_profile]
        # choice, and EmbeddingService.for_project() inside the subprocess
        # would silently fall back to qwen3 (the hard-coded default). On
        # Windows + CPU + 24 GB RAM with the launcher having stored
        # active=arctic, that fallback meant ~30 s per chunk and the user
        # stuck at 40-50% for hours (reported 2026-06-09).
        # v0.2.69 FIX 3: no per-process timeout — see the matching note in
        # the shared-KG seed above. A slow re-embed over a large knowledge/
        # + docs/ tree on a cold CPU can legitimately exceed any wall-clock
        # cap; the per-embed-REQUEST guard inside EmbeddingService
        # (VCT_EMBED_REQUEST_TIMEOUT_SECS) is the correct granularity for
        # catching a wedged embedder without aborting a healthy slow seed.
        try:
            subprocess.run(
                [str(venv_py), str(sync_kg)] + cmd_args,
                check=True,
                cwd=str(PROJECT_ROOT),
                env=_subprocess_env_with_embedding(),
            )
            # Subprocess executed AND exited 0 — clean sync.
            sync_subprocess_ran = True
        except subprocess.CalledProcessError as e:
            # Subprocess EXECUTED but exited non-zero — e.g. 1/2590 nodes failed
            # (oversize chunk, transient embed error). The other 2589 WERE
            # embedded against current_active_embedding, so the collection now
            # reflects the current context. We record seed_errors (so the KG
            # PRUNE below stays conservatively skipped) but STILL mark the
            # subprocess as having run — the context-persist keys off this, not
            # off seed_errors. The next --update's content-hash diff re-picks-up
            # only the failed node(s) (their Weaviate content_hash won't match
            # on-disk), re-embedding them alone in seconds. (SEG-1 fix.)
            print(f"    ! kg/docs sync exited {e.returncode} — re-run later with `kg-sync --all`")
            seed_errors.append(f"kg-sync exit {e.returncode}")
            sync_subprocess_ran = True
        except FileNotFoundError as e:
            # Subprocess FAILED TO LAUNCH (venv python / script path bad) —
            # nothing was embedded. Leave sync_subprocess_ran False so we do
            # NOT record a false "collection embedded against current context".
            print(f"    ! kg/docs sync failed: {e}")
            seed_errors.append(f"kg-sync FileNotFound: {e}")
    else:
        # Sync script missing — the subprocess never ran, nothing embedded.
        # sync_subprocess_ran stays False → context triple is NOT persisted.
        print(f"  ! sync_knowledge_graph.py not found at {sync_kg}")
        seed_errors.append("sync_knowledge_graph.py missing")

    # SEG-1 (v0.2.73): persist the CONTEXT TRIPLE
    # (last_installed_active_embedding / _kg_collection / _shared_kg_collection)
    # whenever the sync subprocess ACTUALLY RAN — even if it exited non-zero
    # with ≥1 failed node. Rationale: this triple records WHAT CONTEXT the
    # collection was last embedded against, which is TRUE for the 2589/2590
    # nodes that succeeded; the next --update's content-hash diff will re-embed
    # exactly the node(s) that failed (seconds), instead of full-re-embedding
    # all 2590 (~70 min) because the key was stuck at None. We gate on
    # `sync_subprocess_ran`, NOT `seed_errors`, so a launch failure / missing
    # script (nothing embedded) still correctly skips the persist.
    #
    # The sync-AT timestamp + sync-STATS are persisted on the same condition:
    # they record "we last attempted a sync at T, embedding N/K nodes" — reality
    # regardless of the one failed node — so they belong with the context triple,
    # not under a stricter success check.
    if sync_subprocess_ran:
        _write_app_state_key(_APP_STATE_KEY_LAST_ACTIVE_EMBEDDING, current_active_embedding)
        _write_app_state_key(_APP_STATE_KEY_LAST_KG_COLLECTION, current_kg_collection)
        _write_app_state_key(_APP_STATE_KEY_LAST_SHARED_KG_COLLECTION, current_shared_kg)
        import datetime as _dt
        _write_app_state_key(
            _APP_STATE_KEY_LAST_KG_SYNC_AT,
            _dt.datetime.now(_dt.timezone.utc).isoformat(),
        )
        _write_app_state_key(
            _APP_STATE_KEY_LAST_KG_SYNC_STATS,
            json.dumps({"nodes_synced": _nodes_synced or 0, "nodes_skipped": _nodes_skipped}),
        )

    # v0.2.44 V44-A: always prune on --update.
    #
    # Previous version gated on _sync_all=True out of fear that partial-sync
    # would mark "deliberately skipped" files as orphans. But the prune compares
    # Weaviate file_path entries to on-disk presence — files that don't exist
    # on disk at all are always safe to remove regardless of the partial-sync
    # changelist. The _sync_all gate caused the 192 orphan accumulation on
    # the maintainer install's KG (v0.2.43 post-update audit).
    if not seed_errors and current_kg_collection:
        _prune_stale_kg_rows(current_kg_collection, weaviate_url)

    # 3. Cross-project shared KG seed (Step 7d).
    #
    # Re-runs sync_knowledge_graph.py against the SHARED collection so
    # vibecoded-orchestrator/knowledge/ is also persisted into
    # VibeCodedOrchestrator_KnowledgeGraph (since v0.2.23 B1; was lowercase-c
    # VibecodedOrchestrator_KnowledgeGraph v0.2.12–v0.2.22, itself renamed
    # from VibeCodedTools_KnowledgeGraph in v0.2.12 PR-26 / Group E). All
    # projects on this machine then read from this shared collection in
    # addition to their per-project KG (see weaviate_mcp/server.py:
    # SHARED_KG_COLLECTION).
    #
    # Idempotency: sync_knowledge_graph.py upserts per file (delete+insert
    # by file_path), so re-running on unchanged content yields the same
    # collection state. The cost on a 50-node tree is ~30s on warm Ollama.
    #
    # Honor SHARED_KG_WRITE_DISABLED=true at install time too (skip seeding)
    # so power-users who explicitly gated shared-KG writes don't get the
    # collection re-populated by a subsequent install / update.
    # v0.2.42 CI-10: extracted to _seed_weaviate_shared_kg_only helper.
    shared_errors = _seed_weaviate_shared_kg_only(
        args=args,
        venv_py=venv_py,
        sync_kg=sync_kg,
        weaviate_url=weaviate_url,
        current_shared_kg=current_shared_kg,
        current_kg_collection=current_kg_collection,
        orphan_candidate_kg=_pre_resolution_kg,
        rebind_deferred=_rebind_deferred,
        rebind_deferred_rationale=_rebind_deferred_rationale,
    )
    seed_errors.extend(shared_errors)

    print("  OK (seed step complete; per-script errors are non-fatal — see hints above)")
    if seed_errors:
        # Soft-fail: still log as warn, not error. Step is non-fatal by
        # design — users can re-run `kg-sync --all` later. The
        # downstream resume-decider treats "warn" as still-eligible-to-skip
        # so a partial seed doesn't block install completion.
        _log_install_event(
            "7c/10", "warn",
            f"{len(seed_errors)} seed sub-step(s) had errors (non-fatal)",
            data={"errors": seed_errors},
        )
    else:
        _log_install_event("7c/10", "ok", "all seed sub-steps completed")


# ---------------------------------------------------------------------------
# Schema-correctness migrations (PR-24, v0.2.12, 2026-05-16)
# ---------------------------------------------------------------------------


def _run_schema_migration_scripts(deferral_report: "DeferralReport") -> None:
    """Version-gated schema migrations (v0.2.60 — thin shim over the runner).

    Historically this ran TWO hardcoded ``scripts/migrate-*.{sh,ps1}`` scripts
    UNCONDITIONALLY on every install/update. v0.2.60 folds that into ONE
    version-gated runner (``vco_lib.schema_migration_runner``) driven by the
    existing ``artifact_schema_versions`` registry, so a FUTURE schema-changing
    release can drop a single ``migrations/<type>/<from>_to_<to>.<ext>`` edge
    that runs only when the DB-recorded version is behind canonical. The runner
    ships as a verified NO-OP today (``migrations/`` is empty).

    This shim:
      1. Calls ``run_schema_migrations(...)`` (the per-artifact version gate +
         the DERIVED-collection binding policy).
      2. Translates the returned ``MigrationRunReport`` into the EXISTING
         ``DeferralEntry`` shape (condition_ids: ``schema_migration_failed_*``,
         ``schema_migration_refuse_downgrade``,
         ``schema_regenerate_or_defer_<artifact>`` /
         ``schema_migration_needs_choice``, ``schema_migration_script_missing``)
         — the same family install.py emitted before.
      3. KEEPS the safe ADDITIVE script (``migrate-development-temporal-props``)
         running UNCONDITIONALLY (SPEC §3.1 / R1 Option A): it is idempotent,
         in-place, always exit 0 — zero risk, and ``detect_kg_schema_drift``
         does NOT yet check the temporal props, so the live-drift net would
         miss a pre-V52-I collection missing them. Only the DESTRUCTIVE
         shared-KG recreate moved under version+policy gating (it was already
         guarded, so no safety regression — strictly safer now).
      4. Still calls ``_migrate_kg_named_vector_slots`` +
         ``_emit_lowercase_codegraph_cleanup_deferrals`` after the runner —
         unchanged.

    Soft-fail throughout: a runner exception never aborts install.py.
    """
    print("[7d/10] Running schema-correctness migrations ... ", flush=True)
    _log_install_event("7d/10", "start", "version-gated schema migrations")

    # --- (3) Option A: keep the safe additive props script unconditional. ---
    # SPEC §3.1 / R1: in-place, idempotent, always exit 0. Run it directly
    # here (NOT through the version gate) so its current "always run, no-op
    # when present" semantics are preserved exactly and remain auditable.
    _run_additive_temporal_props_migration(deferral_report)

    # --- (1) The version-gated runner (no-op today). ---
    # STRUCTURAL (2026-06-16): this is the ROOT (orchestrator self-)update path.
    # It migrates the ROOT project's own per-project collections (keyed by the
    # root's REAL project_id) AND the orchestrator-wide artifacts (shared KG +
    # Layer-5 shapes, keyed project_id=NULL) — hence include_orchestrator_wide
    # = True. A NON-root project's collections are migrated by ITS OWN
    # per-project bundle update (launcher → apply_post_bundle_steps →
    # `migrate-schema --project-id <that-project>`), NOT here.
    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )
    # Resolve the ROOT (base-host) project's real id so per-project collection
    # artifacts (KG / Development / Diagrams / Codegraph) are keyed correctly.
    # Falls back to VCT_PROJECT_ID env then None (orchestrator-wide only) when
    # the launcher.db row isn't resolvable.
    root_project_id = None
    try:
        from vco_lib.launcher_db_reader import get_orchestrator_root_project_id
        root_project_id = get_orchestrator_root_project_id()
    except Exception:
        root_project_id = None
    # NIT-A (2026-06-16): when neither the launcher.db orchestrator_root row nor
    # VCT_PROJECT_ID resolves (free-tier / launcher-less install, or before the
    # row exists), project_id is None → ONLY the orchestrator-wide artifacts
    # (shared KG + Layer-5 shapes, keyed NULL) get registered this run. The
    # ROOT's OWN per-project collections (its KG/Development/Diagrams/Codegraph)
    # are NOT seeded into the registry until the first launcher-attached update
    # resolves the root project_id. Harmless today (no-op: empty migrations/ →
    # those artifacts are simply registered later at the then-current canonical,
    # which is correct since a fresh collection is born at canonical); a future
    # schema bump shipped during this window would be seen as NEVER_MATERIALIZED
    # on the first launcher-attached run and registered straight to the new
    # canonical (no spurious recreate). Documented consequence, not a bug.
    project_id = root_project_id or (os.environ.get("VCT_PROJECT_ID") or None)
    _launcher_db = _project_init._launcher_db_path()
    try:
        from vco_lib import schema_migration_runner as smr

        # A1 (v0.2.74 migration delivery): the install.py process env has NO
        # CODE_GRAPH_PROJECT / PROJECT_NAME, so the runner's env-only codegraph
        # resolution returns None → the codegraph migration loop iterates ZERO
        # times, silently, and v0.2.73's .claude/state purge + add-property
        # ladder never reach existing users. Resolve the codegraph prefix from
        # the SSOT (launcher.db project_codegraph_bindings, RO-URI) and pass
        # EXPLICIT artifact_names + an AUGMENTED env (CODE_GRAPH_PROJECT set) so
        # (a) the loop iterates and (b) each edge subprocess resolves the same
        # prefix (closing the second-order false-advance trap).
        _cg_artifact_names, _cg_env, _cg_prefix = (
            smr.resolve_codegraph_migration_inputs(
                os.environ,
                db_path=_launcher_db,
                project_id=project_id,
                project_name=os.environ.get("PROJECT_NAME"),
            )
        )
        if _cg_prefix:
            _log_install_event(
                "7d/10", "ok",
                f"codegraph migration prefix resolved: {_cg_prefix}",
            )
        else:
            _log_install_event(
                "7d/10", "warn",
                "codegraph migration prefix UNRESOLVED (no binding / env); "
                "codegraph edges will no-op this pass (A3 reconcile retries)",
            )

        run_report = smr.run_schema_migrations(
            db_path=_launcher_db,
            project_id=project_id,
            migrations_dir=PROJECT_ROOT / "migrations",
            deferral_report=deferral_report,
            weaviate_url=weaviate_url,
            env=_cg_env,
            check=False,
            artifact_names=_cg_artifact_names or None,
            project_root=PROJECT_ROOT,
            include_orchestrator_wide=True,
        )
    except Exception as exc:  # never abort install on a runner fault
        print(f"  [migrate:runner] runner failed (non-fatal): {exc}")
        _log_install_event(
            "7d/10", "error", f"schema_migration_runner failed: {exc}",
        )
        run_report = None

    if run_report is not None:
        _translate_migration_report_to_deferrals(run_report, deferral_report)
        _log_install_event(
            "7d/10", "ok",
            "version-gated runner completed",
            data={
                "registered": len(run_report.registered),
                "up_to_date": len(run_report.up_to_date),
                "applied": len(run_report.applied),
                "refused": len(run_report.refused),
                "errors": len(run_report.errors),
                "pending_regenerate": len(run_report.pending_regenerate),
            },
        )

    _log_install_event("7d/10", "ok", "schema migrations completed")

    # A3 (v0.2.74): one-time code-graph registry reconcile. The main runner
    # above migrates the ROOT project's codegraph; this sweep carries EVERY
    # registered project (including non-root existing projects installed at any
    # prior version) whose codegraph collection EXISTS WITH DATA but whose
    # registry row is stale/missing to a correct state, by replaying the
    # idempotent-from-earliest edge ladder. Soft-fail: any error becomes a log
    # line + deferral, never crashes install.py --update.
    try:
        from vco_lib import codegraph_registry_reconcile as cgrr

        cgrr.reconcile_codegraph_registry(
            deferral_report,
            db_path=_launcher_db,
            weaviate_url=weaviate_url,
            migrations_dir=PROJECT_ROOT / "migrations",
            project_root=PROJECT_ROOT,
            env=os.environ,
            log_event=_log_install_event,
            deferral_entry_cls=DeferralEntry,
        )
    except Exception as exc:  # never abort install on a reconcile fault
        print(f"  [migrate:reconcile] codegraph reconcile failed (non-fatal): {exc}")
        _log_install_event(
            "7d/10", "warn", f"codegraph_registry_reconcile failed: {exc}",
        )

    # V0243-2: additive named-vector slot migration for per-project KG +
    # Development collections. Runs after the runner so the collections are
    # guaranteed to exist before we attempt slot adds.
    _migrate_kg_named_vector_slots(deferral_report)

    # V0243-14: emit deferred cleanup suggestions for residual lowercase
    # legacy code-graph collections. Idempotent; never auto-drops.
    _emit_lowercase_codegraph_cleanup_deferrals(deferral_report)


def _trigger_codegraph_embed_resync(deferral_report: "DeferralReport") -> None:
    """v0.2.72 (P7) thin shim: trigger the revision-gated code-graph resync.

    All real logic lives in ``vco_lib.codegraph_resync`` (install.py is a
    mega-file — per the modularity rule, >50-line additions go to a helper
    module). This shim only:
      1. resolves the orchestrator's own code-graph project name,
      2. calls ``spawn_background_resync`` (background, non-blocking, no global
         timeout; R-6: gated on the owed-probe — fires only when stale rows
         exist; self-degrades when the code-embed service is down),
      3. records the returned ``DeferralEntry`` when the resync was deferred,
      4. resolves the pending ``codegraph_embed_resync_pending`` ledger entry
         when the probe POSITIVELY confirms zero stale rows (``not_owed``).

    Soft-fail throughout: any error here converts to a log line, never a crash —
    the resync is a best-effort background refresh, not a gating step.
    """
    try:
        from vco_lib.codegraph_resync import spawn_background_resync
    except Exception as exc:  # noqa: BLE001 — missing helper must not wedge update
        _log_install_event(
            "codegraph_resync", "warn",
            f"codegraph_resync helper unavailable: {exc}",
        )
        return

    project_name = _derive_orchestrator_project_name()
    venv_python = None
    try:
        # Prefer the orchestrator venv python (has weaviate-client + vco_lib)
        # so the spawned analyze can import its deps. Fall back to sys.executable
        # inside the helper when this is None.
        _vp_posix = PROJECT_ROOT / ".venv" / "bin" / "python"
        _vp_win = PROJECT_ROOT / ".venv" / "Scripts" / "python.exe"
        if _vp_posix.is_file():
            venv_python = str(_vp_posix)
        elif _vp_win.is_file():
            venv_python = str(_vp_win)
    except Exception:  # noqa: BLE001
        venv_python = None

    try:
        result = spawn_background_resync(
            PROJECT_ROOT,
            project_name,
            python_exe=venv_python,
        )
    except Exception as exc:  # noqa: BLE001 — never crash the update
        _log_install_event(
            "codegraph_resync", "warn",
            f"codegraph resync trigger raised: {exc}",
        )
        return

    if result.status == "launched":
        print(f"  → code-graph resync (P7) launched in background (pid {result.pid})")
        _log_install_event(
            "codegraph_resync", "ok",
            f"background resync launched for {project_name} (pid {result.pid})",
        )
    elif result.status == "not_owed":
        # R-6 (v0.2.73): the owed-probe POSITIVELY confirmed zero stale rows.
        # Resolve any pending resync ledger entry — this is the ONLY way that
        # (deliberately FOREIGN, A-2) entry clears: explicit positive
        # confirmation, never drop-when-absent.
        print("  → code-graph resync not owed (all rows at current embed revision)")
        try:
            deferral_report.mark_resolved("codegraph_embed_resync_pending")
        except Exception as exc:  # noqa: BLE001
            _log_install_event(
                "codegraph_resync", "warn",
                f"could not resolve resync deferral: {exc}",
            )
        _log_install_event(
            "codegraph_resync", "ok",
            f"no resync owed for {project_name}: {result.message}",
        )
    elif result.status == "deferred":
        print(f"  ! code-graph resync deferred: {result.message}")
        if result.deferral is not None:
            try:
                deferral_report.add_entry(result.deferral)
            except Exception as exc:  # noqa: BLE001
                _log_install_event(
                    "codegraph_resync", "warn",
                    f"could not record resync deferral: {exc}",
                )
        _log_install_event(
            "codegraph_resync", "warn",
            f"resync deferred for {project_name}: {result.message}",
        )
    else:  # skipped
        _log_install_event(
            "codegraph_resync", "warn",
            f"resync skipped for {project_name}: {result.message}",
        )


def _run_additive_temporal_props_migration(
    deferral_report: "DeferralReport",
) -> None:
    """Run the safe, additive ``migrate-development-temporal-props`` script
    UNCONDITIONALLY (SPEC §3.1 / R1 Option A).

    Adds the 4 temporal date props to existing ``*_Development`` /
    ``*_KnowledgeGraph`` / ``*_Diagrams`` collections via the v1 REST schema
    API. In-place, per-property presence-checked → idempotent; always exit 0.
    A spawn failure / non-zero exit converts to a ``schema_migration_failed_*``
    deferral (same family as before) and never aborts install.py.
    """
    script_ext = ".ps1" if sys.platform == "win32" else ".sh"
    script_name = f"migrate-development-temporal-props{script_ext}"
    migration_id = "development_temporal_props"
    script_path = PROJECT_ROOT / "scripts" / script_name

    if not script_path.exists():
        print(f"  [migrate:{migration_id}] {script_name} not found; skipping.")
        _log_install_event(
            "7d/10", "skip",
            f"{migration_id}: script not present at {script_path}",
        )
        return

    if sys.platform == "win32":
        cmd = [
            "powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass",
            "-File", str(script_path),
        ]
    else:
        cmd = ["bash", str(script_path)]

    print(f"  [migrate:{migration_id}] Add temporal properties to existing "
          f"Development / KnowledgeGraph / Diagrams collections (additive).")
    try:
        rc = subprocess.call(cmd, cwd=str(PROJECT_ROOT), timeout=300)
    except (OSError, subprocess.TimeoutExpired) as e:
        print(f"  [migrate:{migration_id}] spawn failed: {e}")
        _log_install_event(
            "7d/10", "error", f"{migration_id}: spawn failed: {e}",
        )
        deferral_report.add_entry(
            DeferralEntry(
                condition_id=f"schema_migration_failed_{migration_id}",
                title=f"Schema migration failed: {migration_id}",
                detected=(
                    f"Migration script `scripts/{script_name}` failed to "
                    f"launch: {e}"
                ),
                why_deferred=(
                    "The additive temporal-props migration could not be "
                    "invoked. Search and stale-data filtering may misbehave "
                    "until it is applied manually."
                ),
                command_to_apply=(
                    f"{'powershell.exe -File ' if sys.platform == 'win32' else 'bash '}"
                    f"scripts/{script_name}"
                ),
                severity="warning",
                kg_node_refs=[],
            )
        )
        return

    if rc != 0:
        print(f"  [migrate:{migration_id}] exit rc={rc} (non-fatal)")
        _log_install_event(
            "7d/10", "warn", f"{migration_id}: exit rc={rc}",
            data={"rc": rc, "script": str(script_path)},
        )
        deferral_report.add_entry(
            DeferralEntry(
                condition_id=f"schema_migration_failed_{migration_id}",
                title=f"Schema migration failed: {migration_id}",
                detected=(
                    f"Migration script `scripts/{script_name}` exited with "
                    f"non-zero status (rc={rc})."
                ),
                why_deferred=(
                    "Search and stale-data filtering may misbehave on the "
                    "affected collections until the migration is applied "
                    "successfully. Re-run the script manually after "
                    "addressing the underlying cause (e.g. Weaviate not "
                    "running, missing jq, etc.)."
                ),
                command_to_apply=(
                    f"{'powershell.exe -File ' if sys.platform == 'win32' else 'bash '}"
                    f"scripts/{script_name}"
                ),
                severity="warning",
                kg_node_refs=[],
            )
        )
        return

    _log_install_event(
        "7d/10", "ok", f"{migration_id}: additive migration completed",
    )


def _translate_migration_report_to_deferrals(
    run_report: "object", deferral_report: "DeferralReport",
) -> None:
    """Add a ``MigrationRunReport``'s findings to the run-scoped DeferralReport.

    Thin wrapper over the SINGLE-SOURCE-OF-TRUTH builder
    ``schema_migration_runner.build_deferral_entries`` (shared with the
    per-project CLI surface in ``project_init._cmd_migrate_schema`` so both
    paths emit identical condition_ids). The runner never writes deferrals
    itself; this is the ROOT-update sink for its findings.
    """
    from vco_lib import schema_migration_runner as smr

    for entry in smr.build_deferral_entries(run_report):
        deferral_report.add_entry(entry)


def _migrate_kg_named_vector_slots(deferral_report: "DeferralReport") -> None:
    """V0243-2 — Ensure $KG_COLLECTION and $DEVELOPMENT_COLLECTION carry all
    5 named-vector slots from the v0.2.18 catalog.

    Background: collections created before v0.2.18 were built with 3 slots
    (qwen3_embed, ollama_embed, openai_embed). v0.2.18 added arctic2_embed +
    openai_text_embed. The drift-detector intentionally does NOT fire on the
    two new slots (so basic search still works), but every install/update
    should silently patch them in when missing.

    Strategy: additive patch_props (UNION) — vector slots can be added
    without re-embedding existing data. The new slots start empty; the
    embedding-enrichment step (commit 9 / EmbeddingService) fills them
    lazily as the user runs sync or queries.

    Idempotent: running twice produces 0 additions on the second pass
    (every slot present → all Skipped).

    Soft-fail: Weaviate unreachable or collection missing → skip silently
    (those are existing deferred conditions upstream). Any per-slot error
    is captured as a deferral entry and does NOT abort install.

    Scope: per-project KG ($KG_COLLECTION) + per-project Development
    ($DEVELOPMENT_COLLECTION). Shared KG and code-graph collections are
    handled separately by `migrate_collections_to_v0218_schema`.
    """
    from vco_lib.weaviate_schema import (
        KG_NAMED_VECTORS,
        migrate_collection_to_target,
    )

    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )
    kg_coll = os.environ.get("KG_COLLECTION", "")
    dev_coll = os.environ.get("DEVELOPMENT_COLLECTION", "")

    targets = [(n, "kg") for n in [kg_coll] if n] + [
        (n, "dev") for n in [dev_coll] if n
    ]

    if not targets:
        _log_install_event(
            "7d/10", "skip",
            "kg_named_vector_slots: no KG_COLLECTION/DEVELOPMENT_COLLECTION set",
        )
        return

    print("[7d/10] Migrating KG named-vector slots (V0243-2) ... ", flush=True)
    _log_install_event(
        "7d/10", "start",
        "kg_named_vector_slots: ensuring 5-slot catalog on KG + Dev",
        data={"kg": kg_coll, "dev": dev_coll, "weaviate_url": weaviate_url},
    )

    all_ok = True
    for coll_name, coll_type in targets:
        try:
            report = migrate_collection_to_target(
                coll_name,
                KG_NAMED_VECTORS,
                weaviate_url=weaviate_url,
            )
        except Exception as exc:
            # Transport failure, missing collection, etc. — skip silently.
            print(f"  [kg_named_vector_slots] {coll_name}: skipped ({exc})")
            _log_install_event(
                "7d/10", "warn",
                f"kg_named_vector_slots: {coll_name} skipped: {type(exc).__name__}",
                data={"collection": coll_name, "error": str(exc)[:200]},
            )
            continue

        if report.added_slots:
            print(f"  [kg_named_vector_slots] {coll_name}: "
                  f"added {report.added_slots}")
        elif report.skipped_slots:
            print(f"  [kg_named_vector_slots] {coll_name}: "
                  f"all slots present (noop)")
        if report.errors:
            all_ok = False
            for err in report.errors:
                slot = err.get("slot", "?")
                reason = err.get("reason", "?")
                print(f"  [kg_named_vector_slots] {coll_name}: "
                      f"slot {slot} error: {reason}")
                deferral_report.add_entry(
                    DeferralEntry(
                        condition_id=f"kg_named_vector_slot_error_{coll_name}_{slot}",
                        title=(
                            f"Named-vector slot migration failed: "
                            f"{coll_name}/{slot}"
                        ),
                        detected=(
                            f"Migration of vector slot `{slot}` on collection "
                            f"`{coll_name}` failed during install step 7d: "
                            f"{reason}"
                        ),
                        why_deferred=(
                            "Adding a vector slot failed. The collection will "
                            "continue to work with the existing slots, but new "
                            "embedding backends (arctic2_embed / "
                            "openai_text_embed) will not be available until "
                            "the migration succeeds."
                        ),
                        command_to_apply=(
                            f"python -m vco_lib.project_init "
                            f"migrate-collections --name "
                            f"{os.environ.get('PROJECT_NAME', 'YourProject')} "
                            f"--json"
                        ),
                        severity="warning",
                        kg_node_refs=[],
                    )
                )
        _log_install_event(
            "7d/10",
            "ok" if not report.errors else "warn",
            f"kg_named_vector_slots: {coll_name} done",
            data={
                "collection": coll_name,
                "added": report.added_slots,
                "skipped": report.skipped_slots,
                "errors": report.errors,
            },
        )

    if all_ok:
        print("  [kg_named_vector_slots] OK")
    _log_install_event(
        "7d/10",
        "ok" if all_ok else "warn",
        "kg_named_vector_slots: migration pass completed",
    )


def _emit_lowercase_codegraph_cleanup_deferrals(
    deferral_report: "DeferralReport",
) -> None:
    """V0243-14 — Emit deferred cleanup suggestions for residual lowercase
    legacy code-graph collections.

    Background: early orchestrator versions wrote code-graph collections
    with lowercase prefixes (e.g. ``myproject_CodeFunction`` instead of the
    canonical ``MyProject_CodeFunction``). These can linger alongside the
    correctly-cased collections, wasting Weaviate memory and causing
    confusing duplicate search results.

    Strategy:
      * For each canonical CodeXxx suffix, detect any Weaviate class whose
        name ends in that suffix AND whose FULL name (prefix included) is a
        pure-lowercase form of an existing canonical-cased class.
      * If the lowercase variant has fewer than 100 objects it is
        "clearly residual" — safe to drop.
      * We NEVER auto-drop. Instead, one deferral entry per qualifying
        collection is emitted to UPDATE_DEFERRED.md with an explicit
        `python -m vco_lib.project_init drop-collection …` command.

    Idempotent — runs every update; already-absent collections produce no
    entries (the check re-reads the live schema each run).

    Soft-fail: Weaviate unreachable → skip silently.
    """
    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )

    # Read live schema (soft-fail on transport errors).
    try:
        resp = urllib.request.urlopen(
            f"{weaviate_url}/v1/schema", timeout=8,
        )
        schema = json.loads(resp.read())
    except Exception:
        return  # Weaviate down — skip silently, upstream already deferred this.

    all_classes: list[str] = [
        c.get("class", "") for c in schema.get("classes", [])
        if isinstance(c, dict) and c.get("class")
    ]
    # Build a lookup: lower(name) -> set of canonical names sharing that key.
    from_lower: dict[str, list[str]] = {}
    for cls in all_classes:
        key = cls.lower()
        from_lower.setdefault(key, []).append(cls)

    # Code collection suffixes from the canonical catalog.
    from vco_lib.weaviate_schema import _CODE_COLLECTION_SUFFIXES

    residual: list[str] = []
    for cls in all_classes:
        # Skip already-canonical: class is its own lone lower-representative.
        key = cls.lower()
        siblings = from_lower.get(key, [])
        # Must have a case-different sibling to qualify as residual.
        canonical_siblings = [s for s in siblings if s != cls]
        if not canonical_siblings:
            continue
        # Must end in a code-graph suffix.
        if not any(cls.endswith(sfx) for sfx in _CODE_COLLECTION_SUFFIXES):
            continue
        # Must be the LOWERCASE variant (i.e. cls == key → all lower).
        if cls != cls.lower():
            continue
        residual.append(cls)

    if not residual:
        _log_install_event(
            "7d/10", "ok",
            "lowercase_codegraph_cleanup: no residual lowercase collections",
        )
        return

    # Count objects in each residual collection (< 100 = clearly residual).
    from vco_lib.project_init import _http_count_objects

    for cls in residual:
        count = _http_count_objects(cls, weaviate_url=weaviate_url)
        if count is None:
            # Unknown count — don't defer a drop (could be data-bearing).
            _log_install_event(
                "7d/10", "warn",
                f"lowercase_codegraph_cleanup: {cls} count unknown; skipping",
                data={"collection": cls},
            )
            continue
        if count >= 100:
            # Plausibly real data — skip.
            _log_install_event(
                "7d/10", "info",
                f"lowercase_codegraph_cleanup: {cls} has {count} rows (>=100); skipping",
                data={"collection": cls, "count": count},
            )
            continue

        # Qualify as residual: lowercase + case-sibling + < 100 rows.
        canonical_siblings = [s for s in from_lower.get(cls.lower(), []) if s != cls]
        canonical_str = ", ".join(f"`{s}`" for s in sorted(canonical_siblings))
        deferral_report.add_entry(
            DeferralEntry(
                condition_id=f"lowercase_codegraph_residual_{cls}",
                title=f"Residual lowercase code-graph collection: {cls}",
                detected=(
                    f"Collection `{cls}` ({count} objects) appears to be a "
                    f"residual lowercase variant of the canonical "
                    f"{canonical_str}. It was likely created by an older "
                    f"version of the orchestrator and can be safely dropped."
                ),
                why_deferred=(
                    "The orchestrator never auto-drops populated collections "
                    "(even with < 100 rows) to avoid accidental data loss. "
                    "Inspect `{cls}` with the Weaviate console or the CLI, "
                    "then drop it manually when confident the data is "
                    "captured in the canonical collection."
                ),
                command_to_apply=(
                    f"python -m vco_lib.project_init drop-collection "
                    f"--name {cls} --yes"
                ),
                severity="info",
                kg_node_refs=[],
            )
        )
        _log_install_event(
            "7d/10", "info",
            f"lowercase_codegraph_cleanup: deferred drop for {cls} ({count} rows)",
            data={"collection": cls, "count": count,
                  "canonical_siblings": canonical_siblings},
        )

    _log_install_event(
        "7d/10", "ok",
        f"lowercase_codegraph_cleanup: {len(residual)} candidate(s) processed",
    )


def _detect_legacy_shared_kg_class(deferral_report: "DeferralReport") -> None:
    """PR-34 (v0.2.12, Group M) — soft-fail migration deferral.

    When `python install.py --update` runs against a Weaviate that still
    carries the pre-rename `VibeCodedTools_KnowledgeGraph` class (created
    by an install <v0.2.12), emit a `legacy_shared_kg_class_present`
    deferral entry pointing the user at the launcher's "Manage shared KG
    collection" picker. We NEVER auto-rename or auto-drop the class —
    that is destructive (would lose any cross-project KG content the user
    has written) and the picker is the consent mechanism.

    Idempotent + soft-fail:
      * Weaviate unreachable → skip silently (the schema-rebuild flow
        upstream already emits a `weaviate_unreachable` deferral).
      * Legacy class absent → no-op.
      * Legacy class present → one deferral entry, severity=info.

    The picker (launcher Settings → Identity → "Manage shared KG
    collection") handles three resolution paths: (a) accept the new
    canonical and migrate content, (b) keep the legacy name as the
    per-project shared-KG override, (c) ignore (dismissable).
    """
    # Resolve Weaviate URL: prefer env, fall back to canonical default.
    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )
    try:
        resp = urllib.request.urlopen(  # noqa: S310 (localhost only)
            f"{weaviate_url}/v1/schema", timeout=5,
        )
        schema = json.loads(resp.read())
    except Exception:
        # Soft-fail: skip silently. Other code paths already deferral
        # on Weaviate unreachability.
        return

    classes = {c.get("class", "") for c in schema.get("classes", [])}
    legacy_name = "VibeCodedTools_KnowledgeGraph"
    canonical_name = "VibeCodedOrchestrator_KnowledgeGraph"
    # v0.2.23 B1: also recognise the lowercase-c v0.2.12–v0.2.22 default
    # as "canonical-present" (case-insensitive) so a user upgrading from
    # that range doesn't get a spurious "canonical not yet created"
    # message when their on-disk class is the lowercase-c variant.
    legacy_lowercase_c = "VibecodedOrchestrator_KnowledgeGraph"

    if legacy_name not in classes:
        return  # No legacy class — nothing to migrate.

    canonical_present = (
        canonical_name in classes or legacy_lowercase_c in classes
    )
    detected_msg = (
        f"Weaviate at {weaviate_url} still carries the pre-v0.2.12 "
        f"shared-KG class `{legacy_name}`. The post-rename canonical "
        f"name is `{canonical_name}` "
        f"({'already present' if canonical_present else 'not yet created'})."
    )

    deferral_report.add_entry(
        DeferralEntry(
            condition_id="legacy_shared_kg_class_present",
            title="Legacy shared-KG class still on disk (pre-v0.2.12 PR-26)",
            detected=detected_msg,
            why_deferred=(
                "The shared cross-project KG class was renamed from "
                f"`{legacy_name}` to `{canonical_name}` in v0.2.12 PR-26. "
                "The legacy class is still on disk because the rename is "
                "metadata-only; install.py does NOT auto-rename or "
                "auto-drop a populated class (destructive — would lose "
                "any cross-project KG content). Resolve via the "
                "launcher's Settings → Identity → \"Manage shared KG "
                "collection\" picker, which lets you pick which class "
                "becomes the active shared KG for each project."
            ),
            command_to_apply=(
                "Open the launcher (`./vct-launcher`), pick a project, "
                "go to Settings → Identity, click \"Manage shared KG "
                "collection\", and select either the legacy "
                f"`{legacy_name}` or the canonical "
                f"`{canonical_name}` as the shared KG for that project."
            ),
            severity="info",
            kg_node_refs=[],
        )
    )
    _log_install_event(
        "7d/10", "info",
        "legacy shared-KG class detected; deferral emitted",
        data={"legacy_class": legacy_name,
              "canonical_present": canonical_present},
    )


def _emit_orchestrator_root_schema_deferrals(
    deferral_report: "DeferralReport",
) -> None:
    """V0243-13: emit UPDATE_DEFERRED.md entries for known orchestrator-root
    schema drift items that require explicit user consent to fix.

    Currently covers two items:

    (a) **Orphan VibeCodedOrchestrator_Development collection** — the
        orchestrator's own Development collection has no callers and 0 rows.
        It was created by early install.py versions before the "docs/" sync
        moved exclusively into per-project Development collections. Dropping
        it is non-destructive (0 rows) but we still require explicit consent.

    (b) **linksTo property drift** — old shared-KG collections may carry a
        stale ``linksTo`` property (array of object refs) whose schema has
        drifted from the current ``typed_links``/``links`` property contract.
        Fixing requires a schema PATCH or collection recreate; emitting a
        deferral so the user can run the migration script at a chosen time.

    Both deferrals are severity="info" and idempotent (re-emitting the same
    ``condition_id`` on successive ``--update`` runs is harmless — the
    deferral-report writer deduplicates by ``condition_id``).

    Soft-fail throughout: any error is logged but never raises.
    """
    weaviate_url = (
        os.environ.get("WEAVIATE_URL")
        or f"http://localhost:{os.environ.get('WEAVIATE_PORT', '8081')}"
    )

    # Fetch current schema to probe both conditions.
    try:
        resp = urllib.request.urlopen(  # noqa: S310 (localhost only)
            f"{weaviate_url}/v1/schema", timeout=5,
        )
        schema = json.loads(resp.read())
        classes_list = schema.get("classes", [])
    except Exception:
        # Weaviate unreachable — skip silently.
        return

    class_map: dict[str, dict] = {
        c.get("class", ""): c
        for c in classes_list
        if isinstance(c, dict) and c.get("class")
    }

    # ── (a) Orphan VibeCodedOrchestrator_Development ──────────────────────
    # v0.2.46 post-adversarial: gate the "orphan" claim on the collection
    # NOT being the current project's canonical Development collection.
    # On an orchestrator-clone install (.claude/env sets
    # DEVELOPMENT_COLLECTION=VibeCodedOrchestrator_Development) this IS
    # the canonical dev collection — install.py creates it via the dev-
    # collection bootstrap, then the per-project Development hooks
    # populate it. Pre-fix, the install would create the collection,
    # then this detector would re-emit the orphan deferral every run,
    # causing an apply-deferred infinite loop that blocked the
    # no-deferred-fixes rule at tag time.
    orphan_dev = "VibeCodedOrchestrator_Development"
    _current_dev_collection = os.environ.get("DEVELOPMENT_COLLECTION", "")
    if orphan_dev in class_map and orphan_dev != _current_dev_collection:
        # Only emit if the collection appears to have 0 or very few rows.
        row_count = _count_weaviate_class_objects(weaviate_url, orphan_dev)
        if row_count is not None and row_count == 0:
            deferral_report.add_entry(
                DeferralEntry(
                    condition_id="orphan_orchestrator_development_collection",
                    title=(
                        f"Orphan Weaviate collection `{orphan_dev}` "
                        f"has 0 rows and no callers"
                    ),
                    detected=(
                        f"The Weaviate collection `{orphan_dev}` exists at "
                        f"{weaviate_url} with 0 stored objects.  It was "
                        f"created by older install.py versions and is no "
                        f"longer populated (all docs/ sync now targets "
                        f"per-project Development collections).  Dropping "
                        f"it is safe."
                    ),
                    why_deferred=(
                        "DROP is a destructive Weaviate operation even when "
                        "the collection is empty — it cannot be undone without "
                        "a full re-seed.  User consent required."
                    ),
                    command_to_apply=(
                        f"# Delete the orphan collection via the Weaviate REST API:\n"
                        f"curl -X DELETE "
                        f"{weaviate_url}/v1/schema/{orphan_dev}\n"
                        f"# Or open the Weaviate console at {weaviate_url} "
                        f"and delete the class from the Schema tab."
                    ),
                    severity="info",
                    kg_node_refs=[],
                )
            )
            _log_install_event(
                "7e/10", "info",
                f"V0243-13(a): orphan {orphan_dev!r} deferral emitted (0 rows)",
            )

    # ── (b) linksTo property drift ─────────────────────────────────────────
    shared_kg = os.environ.get("SHARED_KG_COLLECTION", "") or ""
    _links_to_drift_classes: list[str] = []
    for class_name, class_def in class_map.items():
        # Only check KG-shaped collections (shared KG + per-project KG).
        if not class_name.endswith("_KnowledgeGraph"):
            continue
        props = class_def.get("properties") or []
        prop_names = {p.get("name", "") for p in props if isinstance(p, dict)}
        # Stale schema has "linksTo" but lacks the current "typed_links" property.
        if "linksTo" in prop_names and "typed_links" not in prop_names:
            _links_to_drift_classes.append(class_name)

    if _links_to_drift_classes:
        classes_str = ", ".join(f"`{c}`" for c in sorted(_links_to_drift_classes))
        deferral_report.add_entry(
            DeferralEntry(
                condition_id="links_to_property_schema_drift",
                title=(
                    f"KG collection(s) have stale `linksTo` property "
                    f"(missing `typed_links`): {classes_str}"
                ),
                detected=(
                    f"The following Weaviate collection(s) carry a stale "
                    f"`linksTo` array-of-object-refs property introduced by "
                    f"an older orchestrator version: {classes_str}.  The "
                    f"current schema uses `typed_links` (text property) and "
                    f"`links` (text array).  KG search still works but "
                    f"graph-traversal features (`semantic_graph_search`) "
                    f"cannot resolve wiki-links on these collections."
                ),
                why_deferred=(
                    "Fixing requires either a Weaviate schema PATCH (add "
                    "`typed_links` + `links` properties additively) or a "
                    "full DROP + recreate + re-seed (if the schema is too "
                    "old to accept the additive patch).  Both operations "
                    "require manual consent."
                ),
                command_to_apply=(
                    "# Option 1 — additive PATCH (preserves existing data):\n"
                    "python install.py --update  "
                    "# run migrate-shared-kg-schema.sh if it detects the gap\n"
                    "# Option 2 — full recreate + re-seed:\n"
                    "python -m vco_lib.project_init migrate-collections "
                    f"--name <collection>  "
                    "# opens a consent prompt, then re-syncs"
                ),
                severity="info",
                kg_node_refs=[],
            )
        )
        _log_install_event(
            "7e/10", "info",
            f"V0243-13(b): linksTo drift deferral emitted for "
            f"{len(_links_to_drift_classes)} collection(s)",
            data={"classes": _links_to_drift_classes},
        )


